import base64, hashlib, hmac, struct, time, os, json, socket

NODES_CONFIG_FILE = f"{BASE}/nodes.json"

_NODES_LOCK = threading.Lock()

def get_nodes():
    if os.path.exists(NODES_CONFIG_FILE):
        try:
            with open(NODES_CONFIG_FILE, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    return []

def save_nodes(nodes):
    # содержит токены нод — только 0600
    _save(NODES_CONFIG_FILE, nodes)

# Поля, которые опрос нод ИЗМЕРЯЕТ сам. Всё остальное в записи (token, name,
# порт, тип) принадлежит владельцу панели, и фоновый цикл на него не имеет права.
_NODE_OBSERVED = ("online", "err", "remote_version", "node_clients", "node_online",
                  "node_xray", "node_caps", "agent_params", "pin", "last_check",
                  "status_cache")

def _nodes_merge_observed(observed):
    """observed: {"хост": {поле: значение}} — наложить измерения поверх ТОГО файла,
    который на диске сейчас.

    Раньше опрос делал так: снял nodes.json, 45 секунд ходил по нодам (каждый
    запрос — до 8 секунд), потом вернул СВОЙ снимок целиком. Заявка ноды по SSH,
    добавление или удаление ноды в эти секунды исчезало вместе с снимком — нода
    либо пропадала, либо возвращалась живой, хотя её удалили.»"""
    with _NODES_LOCK:
        nodes = get_nodes()
        touched = False
        for n in nodes:
            f = observed.get(n.get("host") or "")
            if not f:
                continue
            for k in _NODE_OBSERVED:
                if k in f and n.get(k) != f[k]:
                    n[k] = f[k]
                    touched = True
        if touched:
            save_nodes(nodes)
        return touched

def generate_totp(secret_key, interval=30):
    try:
        key = base64.b32decode(secret_key.upper() + "=" * ((8 - len(secret_key)) % 8))
    except Exception:
        key = secret_key.encode('utf-8')
    counter = int(time.time() // interval)
    msg = struct.pack(">Q", counter)
    digest = hmac.new(key, msg, hashlib.sha1).digest()
    o = digest[19] & 15
    code_int = (struct.unpack(">I", digest[o:o+4])[0] & 0x7fffffff) % 1000000
    return f"{code_int:06d}"

def verify_totp(secret_key, code):
    if not secret_key:
        return True
    interval = 30
    for offset in [-interval, 0, interval]:
        if generate_totp(secret_key, interval) == str(code).strip():
            return True
    return False

def get_system_metrics():
    metrics = {"cpu_percent": 0.0, "ram_percent": 0.0, "net_rx": 0, "net_tx": 0}
    try:
        with open("/proc/stat", "r") as f:
            line = f.readline()
            parts = [int(x) for x in line.split()[1:]]
            idle = parts[3]
            total = sum(parts)
            metrics["cpu_percent"] = round(100.0 * (1.0 - idle / max(1, total)), 1)
    except Exception:
        pass
    try:
        meminfo = {}
        with open("/proc/meminfo", "r") as f:
            for line in f:
                parts = line.split(":")
                if len(parts) == 2:
                    meminfo[parts[0].strip()] = int(parts[1].split()[0])
        total_mem = meminfo.get("MemTotal", 1)
        avail_mem = meminfo.get("MemAvailable", total_mem)
        metrics["ram_percent"] = round(100.0 * (1.0 - avail_mem / max(1, total_mem)), 1)
    except Exception:
        pass
    try:
        metrics["load1"] = round(os.getloadavg()[0], 2)
    except Exception:
        pass
    try:
        du = shutil.disk_usage("/")
        metrics["disk_used_percent"] = round(100.0 * du.used / du.total, 1)
        metrics["disk_free_gb"] = round(du.free / (1024**3), 1)
    except Exception:
        pass
    try:
        metrics["xray_running"] = _unit_active("xray")
    except Exception:
        metrics["xray_running"] = False
    try:
        st = _load(STATE, {}) or {}
        ps = {}
        for proto, inb in _inb_entries(st):
            port = inb.get("port")
            if isinstance(port, int):
                ps[str(port)] = not _port_free(port)
        metrics["ports_status"] = ps
    except Exception:
        metrics["ports_status"] = {}
    return metrics

def run_protocol_self_test():
    results = {}
    checks = [(8443, "Панель (TCP)")]
    try:
        st = _load(STATE, {}) or {}
        for proto, inb in _inb_entries(st):
            p = inb.get("port")
            if isinstance(p, int):
                is_udp = proto in ("wireguard", "amneziawg", "hysteria2") or inb.get("net") == "udp"
                checks.append((p, f"{proto} ({'UDP' if is_udp else 'TCP'})"))
    except Exception:
        pass

    for port, label in checks:
        is_udp = "UDP" in label
        if is_udp:
            bound = not _port_free(port)
            results[str(port)] = {"label": label, "status": "OK (слушает)" if bound else "FAIL: свободен"}
        else:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(1.0)
            try:
                s.connect(("127.0.0.1", port))
                results[str(port)] = {"label": label, "status": "OK"}
            except Exception:
                if not _port_free(port):
                    results[str(port)] = {"label": label, "status": "OK (занят)"}
                else:
                    results[str(port)] = {"label": label, "status": "FAIL: закрыт"}
            finally:
                s.close()
    # «не висит ли панель» раньше можно было только угадать. Теперь честно показываем,
    # сколько соединений она обслуживает прямо сейчас и где её потолок: упёрся в
    # максимум — значит пришли сканеры/шторм подписчиков и новым честно 503.
    results["_panel"] = {"label": "Панель: живых обработчиков",
                         "status": f"{_veil_busy}/{_veil_max_workers}",
                         "busy": _veil_busy, "max": _veil_max_workers,
                         "refused": _veil_rejects}
    # Фоновый тик ждёт замок. Секунды — норма, десятки секунд — чужая ручка
    # держит его сквозь сеть, и подписчик в это время не может ни добавить
    # клиента, ни получить предупреждение о трафике.
    results["_tick"] = {"label": "Тик: ожидание замка (макс)",
                        "status": "%.1f с (%.1f с), держал %.1f с" % (
                            _TICK["wait"], _TICK["wait_max"], _TICK["hold"]),
                        "wait": _TICK["wait"], "wait_max": _TICK["wait_max"],
                        "hold": _TICK["hold"], "hold_max": _TICK["hold_max"],
                        "ts": _TICK["ts"]}
    # Молчаливый Telegram больше не вешает панель (письма уходят в очередь), но
    # из-за этого может переполниться сама очередь. Потерянное предупреждение —
    # это подписчик, который не узнал, что остался без лимита: цифра должна быть
    # на экране диагностики, а не зарыта в audit.json.
    results["_notify"] = {"label": "Очередь уведомлений: ждёт / потеряно",
                          "status": "%d / %d" % (_notify_q.qsize(), _notify_lost),
                          "queued": _notify_q.qsize(), "dropped": _notify_lost,
                          "max": _NOTIFY_QUEUE_MAX}
    return results

