def _load_audit():
    global AUDIT
    try:
        d = json.load(open(AUDIT_FILE)) or []
        if isinstance(d, list):
            AUDIT = d[-AUDIT_LIMIT:]
    except Exception:
        AUDIT = []

def _save_audit():
    try:
        _save(AUDIT_FILE, AUDIT[-AUDIT_LIMIT:])
    except Exception:
        pass

# Имена полей, чьё значение — секрет или bearer-креденциал. Аудит читается
# через /api/audit человеком с правом «security», и раньше туда попадали живые
# подписочные токены и API-ключи: этой галки хватало, чтобы получить чужую подписку.
# `uuid` — из того же класса (#70): для VLESS это и есть пароль входа, а право
# «security» выдаётся оператору отдельно от «clients», так что журнал был вторым,
# неочевидным способом прочитать чужой доступ. Плюс `_ai_audit` (`recent_audit`)
# уносит эти же строки наружу, на внешний AI-хост. Сам credential при этом не
# теряется для разбора: отпечаток стабилен, то есть «та же ли это подписка»
# остаётся вопросом с ответом, а `name`/`ip`/`node` в событии не скрыты.
_SECRET_KEYS = {"token", "tok", "sub", "secret", "password", "passwd", "pass",
                "psk", "salt", "hash", "otp", "totp", "key", "cookie",
                "authorization", "private", "private_key", "privkey", "priv_pem",
                "api_key", "apikey", "session", "sid", "pin", "cvv", "token_hint",
                "client_private_key", "cert_pem", "sub_token", "sub_path", "uuid"}
_SECRET_SUFFIX = ("_token", "_secret", "_password", "_passwd", "_psk",
                  "_private_key", "_api_key", "_apikey", "_hash", "_salt", "_key",
                  "_uuid", "_uuids")

# Два разделителя между словом-атрибутом и значением — не придирка к вкусу, а
# разница в поверхности. `_AUDIT_SECRET_RE` исторический (#72): он режет ТЕЛО
# события, где структура уже есть и `key` — это имя поля. `_LOG_SECRET_RE` — для
# СВОБОДНОГО текста чужого журнала (ручка «Логи», #91): там тот же шаблон с
# пробелом в разделителе срабатывает на прозу, и на живой машине широкий вариант
# сворачивал бы `42 033` из `170 140` строк ротации `syslog.4.gz` (24.70 %) —
# `Asymmetric key parser 'x509' registered`, `Forward Password Requests to
# Plymouth`, `key management` внутри телеметовских INFO. Требование `=` или `:`
# стоит того же закрытия: на всём корпусе (`2 536 005` строк из `5` файлов)
# широкий вариант меняет `330 683` строки (13.04 %), строгий — `480` (0.019 %),
# а все `42` строки `telemt … secret=` на текущем `/var/log/syslog` (и `460` по
# всем ротациям) вычищают оба.
_AUDIT_SECRET_RE = re.compile(r"(tok|token|secret|key|password|psk)[=\"\s:]+[A-Za-z0-9_.+\-/]{6,}",
                              re.I)
_LOG_SECRET_RE = re.compile(r"(tok|token|secret|key|password|psk)[\"'\s]*[=:][\"'\s]*"
                            r"[A-Za-z0-9_.+\-/]{6,}", re.I)
# ссылки подписчика: scheme://<пароль или id>@host — секрет лежит до `@`, он один
# на обеих поверхностях (и в теле события, и в свободном тексте), поэтому
# вынесен в константу, а не переписывается в двух местах
_AUDIT_URL_RE = re.compile(r"((?:vless|vmess|trojan|ss|hy2|hysteria2|wireguard|amneziawg)://"
                           r")[^@]+@", re.I)

# форма идентификаторов, а не их значения: образец в журнале описывает мусор, но
# не выдаёт подписчика (#68)
_SAMPLE_UUID_RE = re.compile(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
                             r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")
_SAMPLE_MAIL_RE = re.compile(r"[A-Za-z0-9._%+\-]+@")

def _secret_key(k):
    kl = str(k).lower()
    return kl in _SECRET_KEYS or kl.endswith(_SECRET_SUFFIX)

def _audit_redact(v, strict_sep=False):
    """Скрывает секреты в строке; внутри dict/list идёт рекурсивно (события
    передают словари: тело запроса, конфиг, срез состояния).

    `strict_sep=True` — для свободного текста (журнал чужого процесса): разделитель
    обязан быть `=` или `:`, иначе маска съедает прозу. См. комментарий у
    `_LOG_SECRET_RE` — там измеренная цена широкого варианта."""
    if isinstance(v, dict):
        return {k: ("sha1:" + hashlib.sha1(str(val).encode("utf-8", "replace")).hexdigest()[:10]
                    if isinstance(val, str) and _secret_key(k) else _audit_redact(val, strict_sep))
                for k, val in v.items()}
    if isinstance(v, (list, tuple)):
        return [_audit_redact(x, strict_sep) for x in v]
    if isinstance(v, str):
        v = (_LOG_SECRET_RE if strict_sep else _AUDIT_SECRET_RE).sub(r"\1=***", v)
        # ссылки подписчика: scheme://<пароль или id>@host — секрет до @
        v = _AUDIT_URL_RE.sub(r"\1***@", v)
    return v

def _audit_val(k, v):
    if isinstance(v, str) and _secret_key(k):
        return "sha1:" + hashlib.sha1(v.encode("utf-8", "replace")).hexdigest()[:10]
    return _audit_redact(v)

# Путь запроса — это не только маршрут. На части адресов следующий сегмент и есть
# чужой credential: `/sub/<tok>`, `/p/<tok>`, `/sb/<tok>`, `/api/wgconf/<tok>` и
# `/api/awgconf/<tok>` отдают подписочный `sub_token` (или `uuid`), `/pay/buy/<tok>`
# принимает то же самое, а `/pay/i/<id>` — bearer-номер чужого счёта (#72). Обрыв
# соединения на странице подписки и любая 500-ка на этих маршрутах писали путь в
# журнал как есть, а `_audit_redact` бьёт по ИМЕНИ ключа: `path` в списке
# защищённых не лежит, потому что остальные пути оператору нужны целиком
# (`/api/clients/add`). Сворачивается только токен — форма пути и его продолжение
# (`/p/<tok>/family/adopt`) остаются читаемыми, а отпечаток остаётся ответом на
# «та же ли это подписка».
_AUDIT_TOK_ROUTES = ("sub", "sb", "p", "api/wgconf", "api/awgconf", "pay/buy", "pay/i")
_AUDIT_TOK_PATH_RE = re.compile(
    "(^|/)(" + "|".join(re.escape(x) for x in _AUDIT_TOK_ROUTES) +
    r")/([A-Za-z0-9_\-]{8,64})")


def _audit_path(p):
    """Форма пути для журнала: сегмент-credential — отпечатком, остальное как есть."""
    def _one(m):
        return (m.group(1) + m.group(2) + "/sha1:"
                + hashlib.sha1(m.group(3).encode("utf-8", "replace")).hexdigest()[:10])
    return _AUDIT_TOK_PATH_RE.sub(_one, str(p or ""))


def _sample_ident(body):
    """Чистит образцы идентификаторов в ГОТОВОЙ форме (#68).

    `_audit_redact` режет секреты по ключам структуры и по двум шаблонам — `tok=`
    и `scheme://`; здесь ни того, ни другого уже нет: мусорный вход это голый
    `uuid` или адрес почты, записанные как скаляр. Маска съедает только сам
    идентификатор: `***@host.example.test` по-прежнему говорит, кто и откуда, —
    но не что именно.
    """
    body = _SAMPLE_UUID_RE.sub("***", body)
    return _SAMPLE_MAIL_RE.sub("***@", body)

def _audit_sample(v, limit=60):
    """ФОРМА подозреваемой записи для журнала, без её значений (#68).

    Прежний `str(v)[:60]` клал в `audit.json` кусок боевого состояния: на срезе в
    шестьдесят символов умещались `uuid` подписчика и его имя. Журнал отдаётся
    админке, переживает любой объём правок и попадает в резервные копии, а
    `_audit_redact` тут бессилен — он режет секреты по КЛЮЧАМ структуры, а в
    строку-выжимку структура уже превратилась (и обрезана посреди значения).

    Оператору при отказе нужно другое: чем именно не словарь этот вход, сколько
    в нём записей и тот ли это мусор, что час назад. Первое дают ключи и длина,
    второе — отпечаток исходного объекта: он неотделим от формы, но по нему
    нельзя восстановить идентификатор, в отличие от превью.

    Скаляры при этом остаются собой: число или строка вроде «мусор» не прячут
    структуру, а после выброса их уже никто не прочитает. Словари и списки — это
    как раз форма боевого состояния, от них остаются ключи, длина и отпечаток.

    Строку режет не только `_audit_redact`: он работает по КЛЮЧАМ структуры, а здесь
    ключей уже нет. Голый `uuid` и адрес почты в список-мусор кладутся как есть, ни
    `tok=`, ни `scheme://` перед ними не стоят, поэтому образец проходит вторую
    чистку: последовательность вида uuid и локальная часть адреса до `@` становятся
    `***`. Хост и длина при этом остаются читаемыми — по ним отказ и различается, а
    `***@host` говорит оператору «вот этот подписчик», не выдавая его адрес.

    Длина записана контрактом: содержательная часть не больше `limit`, целиком
    строка не больше `limit + 14` (хвост `sha8=` ровно столько и стоит). Иначе
    «обрезано до 60» превращается в «обрезано как получится», ровно так же, как
    это случилось в #65 с перечнем путей в журнале ремонта.
    """
    try:
        raw = repr(v)
    except Exception:
        raw = "<не разбирается>"
    if isinstance(v, dict):
        keys = ",".join(sorted(str(k) for k in v))
        body = "dict n=%d keys=[%s]" % (len(v), keys)
    elif isinstance(v, (list, tuple)):
        body = "%s n=%d kinds=%s" % (type(v).__name__, len(v),
                                     ",".join(sorted({type(x).__name__ for x in v})))
    elif isinstance(v, str):
        body = "str len=%d %r" % (len(v), _audit_redact(v))
    else:
        # только `raw`: второй вызов `repr` здесь (`%r`) у объекта с кривым
        # `__repr__` бросил бы из хелпера, который вызван ИЗ `except`
        body = "%s %s" % (type(v).__name__, raw)
    return _sample_ident(body)[:limit] + " sha8=" + hashlib.sha256(
        raw.encode("utf-8", "replace")).hexdigest()[:8]

def _audit(ev, **kw):
    """Запись в аудит-журнал. ev — событие, kw — детали (имя клиента, uuid, ip и т.п.)."""
    entry = {"ts": _now_iso(), "ev": ev}
    entry.update({k: _audit_val(k, v) for k, v in kw.items() if v is not None})
    AUDIT.append(entry)
    if len(AUDIT) > AUDIT_LIMIT + 64:
        del AUDIT[: len(AUDIT) - AUDIT_LIMIT]
    try:
        _save_audit()
    except Exception:
        pass

def _audit_throttled(ev, gap=300, **kw):
    """Журнал событий, которые может вызвать кто угодно и без пароля (вебхук
    Telegram, чужие токены). Писать на каждое — значит дать незнакомцу стирать
    журнал целиком: у него потолок 2000 записей, а мусорных POSTов бесконечно
    много. Пишем не чаще одной записи в `gap` секунд на событие, но то, сколько
    их накопилось, показываем в той же строке."""
    now = time.time()
    with _AUDIT_THROTTLE_LK:
        last, n = _AUDIT_THROTTLE.get(ev) or (0.0, 0)
        if now - last < gap:
            _AUDIT_THROTTLE[ev] = (last, n + 1)
            return False
        _AUDIT_THROTTLE[ev] = (now, 0)
        if n:
            kw["suppressed"] = n
    _audit(ev, **kw)
    return True

def _login_history(ev, ip=None, ua=None, user=None, ok=True, err=None):
    entry = {"ts": _now_iso(), "ev": ev, "ip": ip, "ua": (ua or "")[:256],
             "user": user, "ok": bool(ok), "err": err}
    _LOGIN_HIST.append(entry)
    if len(_LOGIN_HIST) > LOGIN_HIST_LIMIT + 32:
        del _LOGIN_HIST[: len(_LOGIN_HIST) - LOGIN_HIST_LIMIT]
    try:
        _save(LOGIN_HIST_FILE, _LOGIN_HIST[-LOGIN_HIST_LIMIT:])
    except Exception:
        pass
    _audit("login_" + ev, ip=ip, ua=(ua or "")[:256], user=user, **({"err": err} if err else {}))

