def _read_raw(path):
    try:
        with open(path, "rb") as f: return f.read()
    except Exception:
        return None

def _restore_raw(path, data):
    """Вернуть файл к снимку байтов (или удалить, если файла не было)."""
    try:
        if data is None:
            if os.path.exists(path): os.unlink(path)
            return
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "wb") as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        # Без прежнего исключения для XRAY (`0o644 if path == XRAY`): возвращая
        # байты конфига ядра, оно возвращало и право читать их всеми.
        os.chmod(path, 0o600)
    except Exception as e:
        print("restore " + path + ": " + str(e), flush=True)

def _js(v):
    """JSON для вставки прямо в <script>. Обычный json.dumps не спасает от </script:
    имя подписчика попадает в JS-строку, а `</` раньше времени закрывает элемент, и
    браузер читает всё, что после него, как HTML — то есть чужой код на странице
    человека, который открыл свою ссылку. Экранируем <, >, & и JS-переносы строк."""
    return (json.dumps(v, ensure_ascii=False)
            .replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
            .replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))

def _wg_addr(inb, default):
    """Первый свободный /32 в /24-пулу туннеля.

    Прежний счётчик next_address только рос: после 253 выдач (даже если клиентов
    удаляли) адрес стал бы 10.10.0.256 — невалидный, и ядро отвергло бы весь
    конфиг, то есть одна лишняя кнопка «создать» роняла бы VPN целиком. Здесь
    освободившийся адрес возвращается в оборот, а когда пул правда заполнен,
    слышно честное «не осталось свободных», а не молчаливую ерунду."""
    used = set()
    for c in (inb.get("clients") or []):
        a = str(c.get("address") or "").split("/")[0]
        if a:
            used.add(a)
        for x in str(c.get("allowed_ips") or "").split(","):
            b = x.strip().split("/")[0]
            if b:
                used.add(b)
    pre = (str(inb.get("address") or "").split("/")[0].rsplit(".", 1)[0] + "."
           or default.rsplit(".", 2)[0] + ".")
    try:
        start = int(inb.get("next_address") or 2)
    except Exception:
        start = 2
    for k in range(2, 254):
        i = 2 + ((start - 2 + k) % 252)
        cand = pre + str(i)
        if cand not in used:
            inb["next_address"] = i + 1
            return cand
    raise RuntimeError("в пуле туннеля " + pre + "x/24 не осталось свободных адресов — "
                       "расширьте подсеть входа")

# Единственный предел имени подписчика. Число живёт здесь, а не в головах
# вызывающих мест: до #94 создание подписчика не знало никакого предела, а
# переименование резало молча — то есть у одного поля было два правила.
_NAME_MAX = 40


def _client_name(name):
    """Имя подписчика: строка с непробельным содержимым, иначе None.
    Ничего не придумывает и не обрезает — решение за вызывающим местом: оно знает,
    чем отвечать (400, пропуск с предупреждением, ошибка бота). None в `_new_client`
    превращается в отказ, поэтому ни одно место не может молча завести подписчика
    с именем «Кент»."""
    if not isinstance(name, str):
        return None
    s = name.strip()
    return s or None

def _client_name_input(raw):
    """Имя из запроса на интерактивном пути: форма, содержимое и предел — отказом
    с причиной. Вызывающее место отвечает 400, не дожидаясь `_new_client`.

    Обрезка вместо отказа оставила бы оператора с подпиской, названной не так,
    как он набрал, — ровно то, с чем панель рассталась в #81, когда перестала
    додумывать имя. Но и пропустить предел нельзя: имя ложится в состояние
    копией на каждый вход (измерено: 17), поэтому байт имени стоит панели ~68
    байт файла, а тело запроса принимают до 8 МиБ.
    """
    if raw is not None and not isinstance(raw, str):
        raise _BodyError("имя подписчика — строка")
    nm = (raw or "").strip()
    if not nm:
        raise _BodyError("имя подписчика обязательное")
    if len(nm) > _NAME_MAX:
        raise _BodyError("имя подписчика длиннее %d символов" % _NAME_MAX)
    return nm


_ADD_N_MAX = 8    # сколько конфигураций одного протокола за раз и всего на человека
_ADD_CALL_MAX = 16  # записей за один вызов — предел против случайного «8 × все 17»


def _proto_dup(pr):
    """Чем вторая запись протокола отличается от первой: `cred` — собственным
    ключом записи, `ep` — точкой входа (адресом ссылки).

    Продолжение дефекта #228 (#239): у человека уже есть `wireguard`, и ему нужен
    второй туннель — на другом телефоне, для другой задачи. У туннельных протоколов
    пара ключей, у `trojan` — пароль, у `hysteria2` — строка авторизации: всё это
    лежит в самой записи, поэтому вторая запись даёт вторую ОТДЕЛЬНУЮ ссылку.
    У `vless`/`vmess`/`reality` ссылку несёт идентификатор подписчика, у `shadowsocks`
    — общий пароль входа: там вторая запись обязана нести ДРУГОЙ АДРЕС входа
    (`ep_host`), иначе она повторила бы первую ссылку байт в байт. Входов, где
    нельзя ни того ни другого, панель не множит — отказ называется на месте правки."""
    p = str(pr or "")
    if p in ("wireguard", "amneziawg", "hysteria2") or p.startswith("trojan"):
        return "cred"
    if (p.startswith("vless") or p.startswith("vmess") or p == "reality"
            or p.startswith("shadowsocks")):
        return "ep"
    return ""


def _proto_multi(pr):
    return bool(_proto_dup(pr))


def _is_pub4(s):
    """Наружный ли IPv4. Петлевой, частных сетей и туннельных интерфейсов
    (`awg0`, `veilwg`, `tgw0`) в ссылке быть не может: клиент поедет в свою
    собственную подсеть и молча не поднимет соединение."""
    try:
        o = [int(x) for x in str(s or "").split(".")]
    except ValueError:
        return False
    if len(o) != 4 or not all(0 <= x <= 255 for x in o):
        return False
    a, b = o[0], o[1]
    return not (a in (0, 10, 127) or a >= 224 or (a == 172 and 16 <= b <= 31)
               or (a == 192 and b == 168))


def _ep_variants(inb):
    """Различные адреса одного входа — чем вторая `vless`-ссылка отличается от первой.

    Первый вариант — обычный адрес ссылки (в записи пометы нет). Дальше — прямые
    IPv6 и IPv4 машины на том же порту: узел слушает оба стека и на портах входов,
    и на :443, а TLS-политика входа при адресе-литерале не меняется: `_link`
    кладёт в sni обычный домен, а не литерал — соединение различается только
    сетевым путём. Маску `vpn.<база>` отдельным адресом не кладём: для
    переведённого входа это и есть обычный адрес, а для обычного база и маска
    резолвятся в те же литералы. Второй ПОРТ для того же входа на этом узле
    не открывается (вход слушает ровно свой порт), поэтому порты различаются
    между протоколами, а внутри протокола — адрес."""
    out = [("", 0)]
    port = _pub_port(inb)
    v6 = (_my_ipv6() or "").strip()
    v4 = (_my_ip() or "").strip()
    if v6:
        out.append(("[" + v6 + "]", port))
    if v4 and _is_pub4(v4):
        out.append((v4, port))
    return out


def _rec_mark(proto, c):
    """Различник записей внутри одного протокола — по собственному ключу записи,
    а где ключ общий — по точке входа.

    Сборщик подписки раньше клал ссылки в словарь по протоколу: «у клиента на
    каждый протокол одна ссылка» (#228). С второй конфигурацией `wireguard` та
    мера молча выбросила бы её из выдачи — телефон получил бы один туннель там,
    где оператор завёл два. Различник выбирает то, что отличает записи ДЕЙСТВИТЕЛЬНО:
    публичный ключ туннеля, пароль, строку авторизации; где ключ общий — адрес
    входа из `ep_host`; за неимением и его — идентификатор."""
    ep = str(c.get("ep_host") or "").strip()
    if proto in ("wireguard", "amneziawg"):
        m = str(c.get("client_public_key") or c.get("uuid") or "")
    elif str(proto or "").startswith("trojan"):
        m = str(c.get("password") or c.get("uuid") or "")
    elif proto == "hysteria2":
        m = str(c.get("auth") or c.get("uuid") or "")
    else:
        m = str(c.get("uuid") or "")
    return m + ("|" + ep if ep else "")


def _new_client(name, proto=None, inb=None, **kw):
    # Раньше здесь сидело додумывание: `(name or "").strip() or "Кент"`. Оно
    # превращало ошибку любого вызывающего места в рабочего подписчика с чужим
    # именем, credential и ссылкой — и морда показывала его оператору как настоящего.
    nm = _client_name(name)
    if nm is None:
        raise ValueError("у подписчика нет имени — панель его не придумывает")
    # Последняя граница: через эту функцию идут все места создания, и ни одно
    # из них не может пронести имя длиннее предела (отказ ДО генераторов
    # credential — порядок важен так же, как в #81).
    if len(nm) > _NAME_MAX:
        raise ValueError("имя подписчика длиннее %d символов" % _NAME_MAX)
    c = {"uuid": str(uuidlib.uuid4()),
         "name": nm,
         "sub_token": secrets.token_urlsafe(16),
         "created": int(time.time())}
    # Лимиты трафика/срок (0 = без ограничений)
    c["limit_gb"] = float(kw.get("limit_gb") or 0)
    c["expiry"] = int(kw.get("expiry") or 0)
    rc = (kw.get("reset_cycle") or "").strip().lower()
    c["reset_cycle"] = rc if rc in ("day", "week", "month") else ""
    c["cycle"] = _cycle_key(c["reset_cycle"])
    c["up"] = 0; c["down"] = 0
    try: c["max_devices"] = max(0, int(kw.get("max_devices") or 0))
    except Exception: c["max_devices"] = 0
    if proto and proto.startswith("trojan"):
        c["password"] = secrets.token_urlsafe(12)
    if proto == "hysteria2":
        c["auth"] = secrets.token_hex(16)
    if proto == "wireguard" and inb is not None:
        priv, pub = _gen_keys()
        c["client_private_key"] = _wg_key_std(priv)
        c["client_public_key"] = _wg_key_std(pub)
        c["address"] = _wg_addr(inb, WG_ADDR) + "/32"
    if proto == "amneziawg" and inb is not None:
        priv, pub = _gen_keys()
        c["client_private_key"] = _wg_key_std(priv)
        c["client_public_key"] = _wg_key_std(pub)
        c["address"] = _wg_addr(inb, AWG_ADDR) + "/32"
    return c

# ---------- github / update ----------

def _gh_headers():
    h = {"Accept": "application/vnd.github+json", "User-Agent": "veil-panel"}
    try:
        with open(TOKEN_FILE) as f: tok = f.read().strip()
        if tok: h["Authorization"] = "Bearer " + tok
    except Exception: pass
    return h

def _gh_releases(per_page=15):
    """Релизы репозитория панели списком. Раньше бралась ПЕРВАЯ строка выдачи с
    per_page=1 — а первым там лежит и черновик (draft), и пре-релиз: «v2.17.0-rc1»
    показывался бы оператору как «есть обновление» и одним кликом уезжал бы на
    боевую машину."""
    url = f"https://api.github.com/repos/{REPO}/releases?per_page={per_page}"
    print("[update] GET " + url, flush=True)
    req = urllib.request.Request(url, headers=_gh_headers())
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            data = json.load(r)
        print("[update] OK type=" + type(data).__name__, flush=True)
    except urllib.error.HTTPError as e:
        body = ""
        try: body = e.read().decode(errors="replace")[:500]
        except Exception: pass
        print("[update] HTTP " + str(e.code) + " " + body, flush=True)
        raise
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list):
        raise RuntimeError("непонятный ответ GitHub")
    return [x for x in data if isinstance(x, dict)]

def _gh_latest():
    """Самый свежий ВЫПУЩЕННЫЙ релиз: без черновиков и пре-релизов, и по номеру
    версии, а не по порядку в выдаче."""
    out = [r for r in _gh_releases() if not r.get("draft") and not r.get("prerelease")]
    if not out:
        raise RuntimeError("нет релизов")
    out.sort(key=lambda r: _ver_tuple(str(r.get("tag_name") or "").lstrip("v")), reverse=True)
    return out[0]

def _gh_asset(rel, name):
    """Ссылка на участник релиза по имени. Берём api.github.com (`url`), а не
    github.com (`browser_download_url`): панель и так живёт на api.github.com, а
    второй хост в РФ без VPN часто недоступен — тот же резон, по которому геофайлы
    зеркалятся на сервер, а не отдаются телефону. Ответ может прийти без поля
    `url` (чужие зеркала), поэтому `fallback` обязателен."""
    for a in (rel.get("assets") or []):
        if isinstance(a, dict) and a.get("name") == name:
            return a.get("url") or a.get("browser_download_url")
    return None

def _dl(url, dest):
    h = _gh_headers()
    h["Accept"] = "application/octet-stream"
    print("[update] download " + url, flush=True)
    req = urllib.request.Request(url, headers=h)
    with urllib.request.urlopen(req, timeout=90) as r, open(dest, "wb") as f:
        shutil.copyfileobj(r, f)
    print("[update] downloaded " + str(os.path.getsize(dest)) + " bytes", flush=True)

def _sha256_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

def _sha_expect(text):
    """Ожиданный sha256 из файла суммы. Upstream-и пишут его по-разному: Xray —
    `.dgst` со строчками вида «SHA2-256= <hex>», telemt и старые релизы Xray —
    «<hex>  имя_файла». Ключ нормализуем («SHA-256», «SHA256», «SHA_256» — одно и
    то же), иначе законный релиз с самым ходким написванием был бы отвергнут как
    «непонятный формат». Пустой ответ = формата не распознали."""
    for ln in str(text or "").splitlines():
        ln = ln.strip()
        if not ln:
            continue
        if "=" in ln:
            k, v = ln.split("=", 1)
            if re.fullmatch(r"(?i)sha2?256", re.sub(r"[-_ ]", "", k.strip())):
                return v.strip().split()[0].lower() if v.strip() else ""
            continue
        t = ln.split()[0].lower()
        if re.fullmatch(r"[0-9a-f]{64}", t):
            return t
    return ""

def _verify_sha256(sum_url, path, what):
    """Сверяет скачанный файл с контрольной суммой с той же выдачи. Панель уже
    проверяла sha256 архива панели и зеркал правил, а ядро VPN и Telegram-прокси
    ставила непроверенными: «то, что выложили» держалось только на TLS. Нет сумки
    или не сошлось — отказ словами, а не молчаливая установка."""
    if not sum_url:
        raise RuntimeError(f"{what}: на выдаче нет контрольной суммы — не ставим непроверенный файл")
    sp = path + ".sum"
    try:
        _dl(sum_url, sp)
    except Exception as e:
        raise RuntimeError(f"{what}: не удалось взять контрольную сумму ({type(e).__name__}) — не ставим")
    try:
        with open(sp, encoding="utf-8", errors="replace") as f:
            txt = f.read()
    except Exception:
        txt = ""
    exp = _sha_expect(txt)
    if not exp:
        raise RuntimeError(f"{what}: файл суммы непонятного формата — не ставим")
    got = _sha256_file(path)
    if got.lower() != exp.lower():
        raise RuntimeError(f"{what}: sha256 не совпал ({got[:12]}… вместо {exp[:12]}…) — файл отклонён")
    return exp[:16]

def _free_bytes(path):
    st = None
    try:
        st = os.statvfs(path)
    except Exception:
        return -1
    try:
        return int(st.f_bavail) * int(st.f_frsize)
    except Exception:
        return -1

def _need_room(dst, need, what):
    """Свободное место ДО записи. Запись на полном диске падает на середине, а
    середина здесь — боевой файл, с которого панель запускается. Проверка стоит
    микросекунду, откопать панель после неё приходится с консоли."""
    free = _free_bytes(os.path.dirname(dst) or ".")
    if free >= 0 and free < need:
        raise RuntimeError(f"{what}: свободно {free // 1024} КБ, нужно не меньше "
                           f"{need // 1024} КБ — не пишем")

def _write_atomic(src, dst, mode=None):
    """Файл → файл через временный файл в той же директории и os.replace.
    rename атомарен: на боевом пути лежит либо целиком старый файл, либо целиком
    новый. Обычный copy2 на половине записи оставляет обрезанный panel.py, а
    systemd не поднимет панель с SyntaxError — то есть единственный способ
    «вернуться после сбоя» сам всё и ломает."""
    d = os.path.dirname(dst) or "."
    fd, tmp = tempfile.mkstemp(dir=d, prefix="." + os.path.basename(dst) + ".new.")
    try:
        with os.fdopen(fd, "wb") as out, open(src, "rb") as f:
            shutil.copyfileobj(f, out)
            out.flush()
            os.fsync(out.fileno())
        if mode is None:
            try:
                mode = os.stat(src).st_mode & 0o777
            except Exception:
                mode = 0o755
        os.chmod(tmp, mode)
        os.replace(tmp, dst)
        tmp = None
    finally:
        if tmp:
            try:
                os.unlink(tmp)
            except Exception:
                pass
    try:
        dfd = os.open(d, os.O_RDONLY)
        try:
            os.fsync(dfd)
        finally:
            os.close(dfd)
    except Exception:
        pass

def _src_version(path):
    """VERSION из исходника panel.py, не запуская его. Нужна, чтобы «обновились
    до v2.17.0» означало то, что лежит в архиве: несоответствие тега и сборки
    иначе всплывает только через неделю, когда «обновление» предлагается снова."""
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            m = re.search(r'^VERSION\s*=\s*"([^"]+)"', f.read(), re.M)
        return m.group(1) if m else ""
    except Exception:
        return ""

# ---------- jobs: долгое обновление вне «корзины» состояния ----------
# `_dl` качает с timeout=90, и раньше это происходило внутри do_POST под
# `_STATE_LOCK`. Замерено на живой машине (gp/x1_lock_hold_test.py): висячая
# загрузка xray держала замок 90 с, параллельная «создать подписчика» ждала
# 87.5 с вместо 0.32 с, а фоновый тик — автоблокировка и предупреждения — в это
# время вообще не мог взять замок. Сеть к состоянию панели отношения не имеет,
# поэтому такие ручки уехали в отдельную нить с живым журналом шагов (тот же
# урок, что v2.15.1 выучил на выпуске сертификатов: долгий POST браузер рвёт и
# пишет «не вышло» ровно тогда, когда сервер доделывает работу).

_UP_JOBS = {}
_UP_LOCK = threading.Lock()
_UP_STEPS = {
    "panel": ["Релиз", "Скачивание", "Проверка", "Точка отката", "Установка"],
    "xray": ["Скачивание", "Проверка", "Тест конфига", "Точка отката", "Перезапуск"],
    # «Тест бинаря» — отдельный шаг: `telemt --version` проверяется ДО того, как
    # прежний бинарь скопирован в точку отката. Без этой строки в журнале все
    # последующие шаги сдвигались на чужие имена, а «Перезапуск» не закрывался
    # никогда (индекс 4 за пределами списка молча игнорируется `_up_step`).
    "telemt": ["Скачивание", "Проверка", "Тест бинаря", "Точка отката", "Перезапуск"],
    "restore": ["Проверка копии", "Точка отката", "Установка"],
    # Гео-базы xray (задание «обновить сейчас»): те же индексы, что передаёт
    # `_xray_geo_update` в свой `step`.
    "geo": ["Релиз", "Скачивание", "Проверка", "Замена"],
}

def _up_new(kind, params):
    jid = uuidlib.uuid4().hex[:12]
    now = int(time.time())
    with _UP_LOCK:
        for k in [x for x, v in _UP_JOBS.items()
                  if v.get("done") and now - int(v.get("created") or 0) > 3600]:
            _UP_JOBS.pop(k, None)
        while len(_UP_JOBS) > 20:
            oldest = min(_UP_JOBS, key=lambda x: int(_UP_JOBS[x].get("created") or 0))
            _UP_JOBS.pop(oldest, None)
        _UP_JOBS[jid] = {"id": jid, "kind": kind, "done": False, "ok": False,
                         "error": None, "result": None, "created": now,
                         "params": dict(params or {}),
                         "steps": [{"name": s, "state": "pending", "detail": ""}
                                   for s in _UP_STEPS.get(kind, [])]}
    return jid

def _up_busy():
    with _UP_LOCK:
        return [j for j in _UP_JOBS.values() if not j.get("done")]

def _up_step(jid, idx, state, detail=""):
    with _UP_LOCK:
        j = _UP_JOBS.get(jid)
        if j and 0 <= idx < len(j["steps"]):
            j["steps"][idx]["state"] = state
            if detail:
                j["steps"][idx]["detail"] = str(detail)[:200]

def _up_finish(jid, ok, result=None, error=None):
    with _UP_LOCK:
        j = _UP_JOBS.get(jid)
        if j:
            j["done"] = True
            j["ok"] = bool(ok)
            j["result"] = result
            j["error"] = (str(error)[:300] if error else None)
            # Шаг, на котором всё оборвалось, остался бы «в процессе» навсегда:
            # морда показывала бы «▶ Скачивание» под уже мёртвой задачей.
            if not ok:
                for s in j["steps"]:
                    if s["state"] == "running":
                        s["state"] = "failed"
                        if not s["detail"]:
                            s["detail"] = (str(error) or "")[:120]

def _up_view(jid):
    with _UP_LOCK:
        j = _UP_JOBS.get(jid)
        if not j:
            return None
        return {"id": j["id"], "kind": j["kind"], "done": j["done"], "ok": j["ok"],
                "error": j["error"], "result": j["result"], "created": j["created"],
                "steps": [dict(s) for s in j["steps"]]}

def _up_list():
    with _UP_LOCK:
        ids = sorted(_UP_JOBS, key=lambda x: -int(_UP_JOBS[x].get("created") or 0))
        out = []
        for i in ids[:10]:
            j = _UP_JOBS[i]
            out.append({"id": j["id"], "kind": j["kind"], "done": j["done"], "ok": j["ok"],
                        "error": j["error"], "created": j["created"],
                        "steps": [dict(s) for s in j["steps"]]})
        return out

def _up_start(kind, fn, params=None):
    if _up_busy():
        raise RuntimeError("панель уже ставит одно обновление — дождись его")
    jid = _up_new(kind, params)
    def run():
        try:
            res = fn(jid)
            _up_finish(jid, True, res)
        except Exception as e:
            _up_finish(jid, False, error=e)
            # Журнал задачи живёт в памяти час, а «кто и почему не поставил»
            # должно пережить перезапуск панели.
            _audit("update_job_failed", kind=kind,
                   version=(params or {}).get("version") or None,
                   reason=type(e).__name__ + ": " + str(e)[:200])
            print(f"[update:{kind}] {type(e).__name__}: {str(e)[:200]}", flush=True)
    threading.Thread(target=run, daemon=True).start()
    return {"ok": True, "job": jid, "kind": kind}

def _check_update():
    rel = _gh_latest()
    tag = str(rel.get("tag_name", "")).lstrip("v")
    newer = bool(tag) and _ver_tuple(tag) > _ver_tuple(VERSION)
    return {"current": VERSION, "latest": tag,
            "url": rel.get("html_url", ""),
            "update_available": newer,
            # «новее релиза» — не то же самое, что «обновлений нет»: на этой
            # машине может стоять сборка, которую ещё не выложили. Сказанное
            # вслух спасает от «почему кнопка неактивна, если я новее».
            "ahead": bool(tag) and _ver_tuple(VERSION) > _ver_tuple(tag)}

# ---------- незакоммиченное дерево (#122) ----------
# Установка релиза и откат перезаписывают `panel.py` и `index.html` целиком. До
# этого цикла своя правка, которую ещё не довели до выпуска, исчезала молча: в
# аудите оставалось только `panel_update`, а папка `backup-v<прежняя>-<время>`
# содержит то же самое незакоммиченное состояние, из-за которого человек и пришёл
# бы в git — то есть откатывать после перезаписи нечего. Поэтому дерево меряется
# ДО первой записи, а не после: позже измеряют уже то, что уничтожили.
_TREE_PATHS = ("panel.py", "index.html")

def _tree_state(paths=_TREE_PATHS):
    """Состояние рабочих копий `paths` относительно git: ("clean"|"dirty"|"unknown", files).

    `dirty` — файл отличается от последнего коммита или не записан в git вовсе:
    его содержимого нет ни в одном коммите, и перезапись его нечем отменить.
    `unknown` — git не ответил, не запускается или этого дерева не знает. Так
    бывают хосты, поставленные из архива релиза: выдавать это за `clean` нельзя,
    но и блокировать обновление на них нельзя — иначе машина без репозитория
    никогда не сможет обновляться."""
    def one(args):
        # argv-списком, без `shell=True` и с timeout на каждом вызове: замок
        # `index.lock` от чужого git или зависший репозиторий не должны
        # превращать кнопку «обновить» в вечную фоновую задачу. rc!=0 — не
        # «чисто», а «не знаю»: под это попадают 128 (нет репозитория, нет ни
        # одного коммита) и 1 (нет HEAD). Измерено на живых фикстурах прибора
        # `f28`: обе команды читают объекты, а не индекс, поэтому занятый
        # `index.lock` ворота не ослепляет.
        try:
            r = subprocess.run(["git", "-C", BASE] + args + ["--", *paths],
                               capture_output=True, text=True, timeout=10)
        except Exception:
            return None
        return r if r.returncode == 0 else None
    # Два разных состояния потерянности файла, и одной мерой их не взять:
    # `diff HEAD` молчит про файл, которого git не знает, а `ls-files --others`
    # молчит про изменённый. Без `--exclude-standard`: файл, спрятанный в
    # `.gitignore` и не записанный в HEAD, для панели точно так же нечем
    # отменить — человек велел git его не хранить, но перезапись всё равно
    # обязана быть его решением, а не нашим. Оба вывода относительны к BASE,
    # поэтому и сверяем их с `paths` как есть, не отсекая путь до корня.
    mod = one(["diff", "--name-only", "HEAD"])
    oth = one(["ls-files", "--others"])
    if mod is None or oth is None:
        return "unknown", []
    files = []
    for blob in (mod.stdout, oth.stdout):
        for line in blob.splitlines():
            p = line.strip()
            if p in paths and p not in files:
                files.append(p)
    return ("dirty", files) if files else ("clean", [])

def _guard_dirty_tree(what, to="", force=False, paths=_TREE_PATHS):
    """Стоп разрушительной замены: бросает RuntimeError с именами файлов и словом `force_dirty`.

    Пустой список — «грязного нет» или «согласились потерять». Отказывать по
    `unknown` нельзя: на хосте без репозитория проверка не имеет смысла, а
    обновляться такому хосту всё равно надо. Само пропускание — отдельное слово
    человека, а не чужая воля: панель не решает за оператора, что его правка
    не нужна."""
    state, files = _tree_state(paths)
    if state != "dirty":
        return []
    if not force:
        _audit("panel_update_denied", to=to or None, reason="dirty-tree",
               files=",".join(files), what=what)
        # Порядок слов важен: в журнал задачи попадает только первые двести
        # знаки (`_up_start`), и имя слова, которым отказ обходится, обязано
        # пережить этот обрез — иначе человек читает «у тебя грязное дерево» и
        # не знает, что с этим делать.
        raise RuntimeError(
            "в дереве незакоммиченные файлы: " + ", ".join(files) + " — " + what +
            " перезапишет их, а в git их нет. Закоммить или верни дерево; "
            "потеря сознательна — слово force_dirty")
    _audit("panel_dirty_forced", to=to or None, reason="dirty-tree",
           files=",".join(files), what=what)
    return files

def _install_update(confirm=False, job=None, force_dirty=False):
    def step(i, state, detail=""):
        if job:
            _up_step(job, i, state, detail)
    if not confirm:
        raise RuntimeError("нужно подтверждение: обновление заменяет panel.py и index.html и перезапускает панель")
    rel = _gh_latest()
    tag = str(rel.get("tag_name", "")).lstrip("v")
    step(0, "done", "v" + (tag or "?"))
    if not tag:
        raise RuntimeError("в релизе нет tag_name")
    if not (_ver_tuple(tag) > _ver_tuple(VERSION)):
        raise RuntimeError("нет обновлений (текущая " + VERSION + ", в релизе " + (tag or "?") + ")")
    arch_url = _gh_asset(rel, "veil.tar.gz")
    sum_url = _gh_asset(rel, "veil.tar.gz.sha256")
    for need in ("veil.tar.gz", "veil.tar.gz.sha256"):
        if not _gh_asset(rel, need):
            raise RuntimeError("в релизе нет " + need)
    # Дерево проверяется до качания архива: отказ «у тебя незакоммиченное» обязан
    # приходить до сети и до первой записи, а не после девяноста секунд ожидания.
    dirty = _guard_dirty_tree("обновление панели", to=tag, force=force_dirty)
    with tempfile.TemporaryDirectory(prefix="veil-up-") as tmp:
        arch = os.path.join(tmp, "veil.tar.gz"); shaf = os.path.join(tmp, "sha256")
        step(1, "running")
        _dl(arch_url, arch); _dl(sum_url, shaf)
        step(1, "done")
        with open(shaf, encoding="utf-8", errors="replace") as f:
            expected = _sha_expect(f.read())
        actual = _sha256_file(arch)
        step(2, "running")
        if not expected:
            # Файл суммы есть, но прочесть его мы не умеем — это не «совпало
            # молча»: без сверки ставится то, что кто-то выложил под этим тегом.
            _audit("panel_update_denied", to=tag, reason="sha256-format")
            step(2, "failed", "формат файла суммы")
            raise RuntimeError("файл суммы релиза непонятного формата — обновление отклонено")
        if actual.lower() != expected.lower():
            _audit("panel_update_denied", to=tag, reason="sha256", sha=actual[:16])
            step(2, "failed", "sha256")
            raise RuntimeError("sha256 не совпал — обновление отклонено")
        exdir = os.path.join(tmp, "x"); os.makedirs(exdir, exist_ok=True)
        with tarfile.open(arch, "r:gz") as tar:
            for m in tar.getmembers():
                base = os.path.basename(m.name)
                if base not in ("panel.py", "index.html"): continue
                if not m.isreg():
                    # симлинк или каталог с именем panel.py: `extract` бы его создал,
                    # а copy2 прочитал бы то, на что он указывает, — чужой файл
                    # уехал бы в боевой путь
                    continue
                m.name = base
                try:
                    tar.extract(m, exdir, filter="data")
                except TypeError:
                    tar.extract(m, exdir)
        for fn in ("panel.py", "index.html"):
            if not os.path.exists(os.path.join(exdir, fn)):
                raise RuntimeError("в архиве нет " + fn)
        newpy = os.path.join(exdir, "panel.py")
        # sha256 архива сходится — значит файл тот. Но «тот» не значит «рабочий»:
        # если релиз содержит панель, которая не стартует, мы сами себя похороним
        # (копия-то есть, а поднять её через морду уже нельзя).
        sane, err = _py_sane(newpy)
        if not sane:
            _audit("panel_update_denied", to=tag, reason="compile", detail=err[:160])
            step(2, "failed", "compile")
            raise RuntimeError("panel.py из релиза не компилируется: " + err)
        inner = _src_version(newpy)
        if inner and inner != tag:
            _audit("panel_update_denied", to=tag, reason="version", found=inner)
            step(2, "failed", "VERSION=" + inner)
            raise RuntimeError(f"в архиве панель v{inner}, а релиз v{tag} — обновление отклонено")
        step(2, "done", "sha256 " + actual[:12] + "…")
        need = 2 * (os.path.getsize(newpy) + os.path.getsize(os.path.join(exdir, "index.html"))) + 4 * 1024 * 1024
        _need_room(os.path.join(BASE, "panel.py"), need, "обновление панели")
        step(3, "running")
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S")
        bdir = f"{BASE}/backup-v{VERSION}-{ts}"
        _mkdir_private(bdir)
        for fn in ("panel.py", "index.html"):
            src = os.path.join(BASE, fn)
            if os.path.exists(src): _copy_private(src, os.path.join(bdir, fn))
        step(3, "done", os.path.basename(bdir))
        step(4, "running")
        boot_before = int(time.time())
        # Страж заводится ДО замены файлов: если страховка не поднялась, панель
        # перезаписывать нечем («обновление, после которого панель не стартует»
        # лечится только консолью), а порядок спавна до записи значит, что
        # оборвавшаяся на середине замена всё равно будет кем откатана.
        if not _update_guard_spawn(bdir, tag, boot_before):
            _audit("panel_update_denied", to=tag, reason="guard")
            step(4, "failed", "страхование не запустилось")
            raise RuntimeError("страж отката не запустился — панель не перезаписываем")
        for fn, mode in (("panel.py", 0o755), ("index.html", 0o644)):
            _write_atomic(os.path.join(exdir, fn), os.path.join(BASE, fn), mode)
        # `dirty=N` в удачной установке — след того, что согласились потерять:
        # какие файлы и сколько их были перезаписаны сверх выпуска.
        _audit("panel_update", to=tag, sha=actual[:16], backup=os.path.basename(bdir),
               dirty=len(dirty))
        step(4, "done", "v" + tag)
    _panel_restart_soon(via="update", to=tag)
    return {"ok": True, "from": VERSION, "to": tag, "restarting": True,
            "backup": os.path.basename(bdir)}

# ---------- Telegram Bot Processing ----------

def _is_admin(chat_id):
    admin_ids = CFG_CACHE.get("bot_chat_ids", [])
    return str(chat_id) in [str(x) for x in admin_ids]

