def _pay_lang_for(self):
    _q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query or "")
    _lq = (_q.get("lang") or [""])[0]
    _lck = ""
    for _c in (self.headers.get("Cookie") or "").split(";"):
        _c = _c.strip()
        if _c.startswith("veil_sub_lang="):
            _lck = _c[len("veil_sub_lang="):]
    lang = _sub_lang_pick(_lq, _lck, self.headers.get("Accept-Language", ""))
    L = _sub_L(lang)
    L["_code"] = lang
    return L

# ---------- сводка для админ-API ----------
def _pay_summary():
    pc = _pay_cfg()
    d = _pay_load()
    base = _pay_base()
    invs = sorted(d["invoices"].values(), key=lambda x: -(x.get("created") or 0))[:100]
    st = _load(STATE) or {}
    subs = [{"token": x["sub_token"], "name": x["name"], "expiry": x["expiry"],
             "limit_gb": x["limit_gb"]} for x in _subs_summary(st)][:400]
    return {"enabled": pc["enabled"], "provider": pc["provider"],
            "providers": [{"key": k, "label": _PAY_LABELS[k]} for k in _PAY_PROVIDERS],
            "labels": dict(_PAY_LABELS),
            "secret_set": bool(pc["secret"]), "cb_set": bool(pc["cb_token"]),
            "yoo_set": bool(pc["yoo_shop"] and pc["yoo_secret"]),
            "yoo_shop": pc["yoo_shop"], "notify": pc["notify"],
            "shop_url": base + "/shop",
            "hook_cb": base + "/pay/hook/cryptobot",
            "hook_yoo": base + "/pay/hook/yookassa",
            "api_url": base + "/pay/api/",
            "plans": d["plans"], "invoices": invs,
            "unpaid": sum(1 for v in d["invoices"].values() if not v.get("applied")),
            "paid_total": sum(float(v.get("price") or 0) for v in d["invoices"].values() if v.get("applied")),
            "subs": subs}

def _pay_plan_valid(pl):
    title = str(pl.get("title") or "").strip()[:60]
    if not title:
        raise ValueError("нужно название тарифа")
    try:
        price = float(pl.get("price") or 0)
        days = int(pl.get("days") or 0)
        gb = float(pl.get("gb") or 0)
    except Exception:
        raise ValueError("price/days/gb — числа")
    cur = str(pl.get("currency") or "RUB").strip().upper()[:8]
    if not re.fullmatch(r"[A-Z]{2,8}", cur):
        raise ValueError("валюта: 2-8 букв (RUB, USD…)")
    if price <= 0 or price > 10_000_000:
        raise ValueError("цена: 0…10 000 000")
    if days < 0 or days > 3650:
        raise ValueError("дни: 0…3650")
    if gb < 0 or gb > 100_000:
        raise ValueError("ГБ: 0…100000")
    if days == 0 and gb == 0:
        raise ValueError("тариф должен добавлять дни или ГБ")
    return {"title": title, "price": round(price, 2), "currency": cur,
            "days": days, "gb": round(gb, 3), "reset": bool(pl.get("reset")),
            "shop": bool(pl.get("shop"))}

_PAY_TL = {}
_PAY_TL_LK = threading.Lock()

def _pay_throttle(ip, limit=60):
    now = int(time.time())
    with _PAY_TL_LK:
        if len(_PAY_TL) > 4000:
            # ключ карты — адрес клиента, а их бывает много (LTE-раздача, чужие
            # прокси, поддельные источники за CDN): без чистки карта росла бы до
            # конца жизни процесса. Окно счётчика — минута, всё старше выбрасываем.
            for k in [k for k, v in _PAY_TL.items() if now - v[0] > 60]:
                _PAY_TL.pop(k, None)
            if len(_PAY_TL) > 8000:
                _PAY_TL.clear()
        e = _PAY_TL.get(ip)
        if not e or now - e[0] > 60:
            _PAY_TL[ip] = [now, 1]
            return False
        e[1] += 1
        return e[1] > limit

def _pay_handle_public(self, p):
    """Публичные /pay/* маршруты. True — обработано."""
    ip = self.client_address[0]
    if _pay_throttle(ip):
        self._send(429, {"error": "too many requests"})
        return True
    pc = _pay_cfg()
    # GET /pay/buy/<tok>/<plan> — создать/взять счёт и показать страницу оплаты
    if p.startswith("/pay/buy/"):
        parts = p[len("/pay/buy/"):].strip("/").split("/")
        if len(parts) != 2:
            self._send(404, {"error": "not found"})
            return True
        tok, plan_id = parts
        if not pc["enabled"]:
            self._send(404, {"error": "платежи выключены"})
            return True
        plan = next((x for x in _pay_pub_plans() if str(x.get("id")) == plan_id), None)
        u = _pay_sub_find(tok)
        if not plan or not u:
            self._send(404, {"error": "тариф или подписка не найдены"})
            return True
        d = _pay_load()
        inv = next((v for v in d["invoices"].values()
                    if v.get("sub_token") == u["sub_token"] and str(v.get("plan_id")) == str(plan_id)
                    and not v.get("applied") and (v.get("created") or 0) > time.time() - 3 * 86400), None)
        if not inv:
            try:
                inv = _pay_mkv(u["sub_token"], plan, src="page")
            except Exception as e:
                self._send(502, {"error": "не удалось создать счёт: " + str(e)})
                return True
        self.send_response(302)
        self.send_header("Location", "/pay/i/" + urllib.parse.quote(inv["id"]))
        self.send_header("Content-Length", "0")
        self.end_headers()
        return True
    # GET /pay/i/<id> — страница счёта
    if p.startswith("/pay/i/"):
        inv_id = p[len("/pay/i/"):].strip("/")
        inv = _pay_load()["invoices"].get(inv_id) if _PAY_IID_RE.fullmatch(inv_id or "") else None
        if not inv:
            self._send(404, {"error": "not found"})
            return True
        L = _pay_lang_for(self)
        b = _pay_page_html(inv, L).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(b)))
        self.send_header("Cache-Control", "no-store")
        self._sec_headers()
        self.end_headers()
        self.wfile.write(b)
        return True
    # GET /shop — публичная витрина тарифов
    if p == "/shop":
        L = _pay_lang_for(self)
        b = _shop_page_html(L, _pay_shop_plans()).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(b)))
        self.send_header("Cache-Control", "no-store")
        self._sec_headers()
        self.end_headers()
        self.wfile.write(b)
        return True
    # POST-маршруты ниже
    try:
        raw = self._raw_body(262144)
    except ValueError:
        self._send(400, {"error": "bad body"})
        return True
    if p == "/pay/hook/cryptobot":
        if not pc["cb_token"]:
            self._send(404, {"error": "not found"})
            return True
        if not _pay_cb_sig_ok(raw, self.headers.get("Crypto-Pay-API-Signature", "")):
            _audit("pay_hook_bad_sig", provider="cryptobot", ip=ip)
            self._send(403, {"error": "bad signature"})
            return True
        try:
            upd = json.loads(raw.decode("utf-8", "replace") or "{}")
        except Exception:
            upd = {}
        cb_inv = upd.get("invoice") or {}
        if upd.get("update_type") == "pay_status_changed" and cb_inv.get("status") == "paid":
            mine = _pay_find_by_ext("cryptobot", cb_inv.get("invoice_id"))
            if mine:
                _pay_check_ext(mine["id"])
        self._send(200, {"ok": True})
        return True
    if p == "/pay/hook/yookassa":
        try:
            upd = json.loads(raw.decode("utf-8", "replace") or "{}")
        except Exception:
            upd = {}
        obj = upd.get("object") or {}
        if upd.get("event") == "payment.succeeded":
            mine = _pay_find_by_ext("yookassa", obj.get("id"))
            if mine:
                _pay_check_ext(mine["id"])  # повторный запрос к API — источник истины
        self._send(200, {"ok": True})
        return True
    if p in ("/pay/api/invoice", "/pay/api/paid"):
        if not pc["secret"]:
            self._send(404, {"error": "not found"})
            return True
        if not _pay_pay_sig_ok(raw, self.headers.get("X-Signature", ""), pc["secret"]):
            _audit("pay_hook_bad_sig", provider="generic", ip=ip)
            self._send(403, {"error": "bad signature"})
            return True
        try:
            b = json.loads(raw.decode("utf-8", "replace") or "{}")
        except Exception:
            self._send(400, {"error": "bad json"})
            return True
        if p == "/pay/api/invoice":
            plan = next((x for x in _pay_pub_plans() if str(x.get("id")) == str(b.get("plan_id") or "")), None)
            if not plan:
                self._send(404, {"error": "plan not found"})
                return True
            try:
                inv = _pay_mkv(str(b.get("sub_token") or ""), plan, src="api")
            except Exception as e:
                self._send(400, {"error": str(e)})
                return True
            self._send(200, {"invoice_id": inv["id"], "price": inv["price"],
                             "currency": inv["currency"], "pay_url": inv["pay_url"],
                             "status": "paid" if inv.get("applied") else "new"})
            return True
        inv = _pay_load()["invoices"].get(str(b.get("invoice_id") or ""))
        if not inv:
            self._send(404, {"error": "invoice not found"})
            return True
        # Подпись этим ключом означает «я — своя касса», а не «я — любой счёт».
        # Раньше хук проходил по любому счёту, и старый секрет generic-кассы,
        # который никто не стирал при переходе на cryptobot/YooKassa, дарил
        # оплату их счетов: подписка продлевалась без денег.
        if pc["provider"] != "generic" or inv.get("provider") != "generic":
            _audit("pay_hook_foreign", invoice=inv["id"], invoice_provider=inv.get("provider"),
                   configured=pc["provider"], ip=ip)
            self._send(403, {"error": "этот счёт принадлежит другому способу оплаты"})
            return True
        inv = _pay_mark_paid(inv["id"], "api")
        if not inv:
            # счёт успели вычистить между чтением и отметкой — не ронять обработчик на None
            self._send(404, {"error": "invoice not found"})
            return True
        self._send(200, {"invoice_id": inv["id"], "status": "paid" if inv.get("applied") else inv.get("status")})
        return True
    if p == "/pay/shop/buy":
        if not pc["enabled"]:
            self._send(404, {"error": "платежи выключены"})
            return True
        try:
            b = json.loads(raw.decode("utf-8", "replace") or "{}")
        except Exception:
            b = {}
        plan = next((x for x in _pay_shop_plans()
                     if str(x.get("id")) == str(b.get("plan_id") or "")), None)
        if not plan:
            self._send(404, {"error": "тариф не найден"})
            return True
        tg = str(b.get("tg") or "").strip()[:40]
        if tg and not re.fullmatch(r"@?[A-Za-z0-9_]{3,34}", tg):
            self._send(400, {"error": "telegram: @username без пробелов (3–34 символа)"})
            return True
        dd = _pay_load()
        inv = next((v for v in dd["invoices"].values()
                    if v.get("kind") == "shop" and not v.get("applied")
                    and str(v.get("plan_id")) == str(plan["id"])
                    and str(v.get("tg") or "").lower() == tg.lower()
                    and (v.get("created") or 0) > time.time() - 3 * 86400), None)
        try:
            if not inv:
                inv = _pay_mkv("", plan, src="shop", kind="shop", tg=tg)
        except Exception as e:
            self._send(502, {"error": "не удалось создать счёт: " + str(e)[:160]})
            return True
        _audit("shop_buy", inv=inv["id"], plan=plan["id"])
        self._send(200, {"ok": True, "invoice_id": inv["id"], "url": "/pay/i/" + inv["id"]})
        return True
    self._send(404, {"error": "not found"})
    return True


def _create_subscription(name, limit_gb=0, expiry_days=0):
    st = _load(STATE)
    if st is None:
        st = _new_state("reality")
    _migrate_state(st)
    sub_token = secrets.token_urlsafe(16)
    client_uuid = str(uuidlib.uuid4())
    expiry = (int(time.time()) + int(expiry_days) * 86400) if int(expiry_days) > 0 else 0
    host = _hop_pub_host()
    host = host if "://" not in host else urllib.parse.urlparse(host).netloc
    panel_port = CFG_CACHE.get("panel_port", 8444)
    inbounds = st.setdefault("inbounds", {})
    for proto in _VALID_PROTOCOLS:
        if proto not in inbounds:
            try:
                inbounds[proto] = _alloc_inbound(st, proto)
            except Exception as e:
                print(f"create_sub alloc {proto} -> {e}", flush=True)
    if not inbounds:
        inbounds["reality"] = _alloc_inbound(st, "reality")
    first_link = None
    for proto, inb in inbounds.items():
        c = _new_client(name, proto, inb, limit_gb=float(limit_gb) or 0, expiry=expiry)
        c["uuid"] = client_uuid
        c["sub_token"] = sub_token
        inb.setdefault("clients", []).append(c)
        lnk = _link(inb, host, c, proto)
        if not first_link:
            first_link = lnk
    _awg_sync(st)
    _wg_sync(st)
    _apply_state(st)
    sub_url = f"{_pb(host, panel_port)}/sub/{sub_token}"
    return {"name": name, "sub_token": sub_token, "sub_url": sub_url,
            "link": first_link or "", "limit_gb": float(limit_gb) or 0,
            "expiry_days": int(expiry_days)}

_ONBOARD_LOCK = threading.Lock()

def _onboard_ensure():
    """Первый запуск «из коробки»: нет ни одного клиента — заводим личную подписку владельца.
    Возвращает True, если подписку создали сейчас (нужно оповестить в бот)."""
    try:
        if CFG_CACHE.get("onboarded"):
            return False
        with _ONBOARD_LOCK:
            if CFG_CACHE.get("onboarded"):
                return False
            st = _load(STATE)
            if _client_count(st or {}) > 0:
                CFG_CACHE["onboarded"] = "clients"
                _cfg_save()
                return False
            r = _create_subscription("Я")
            CFG_CACHE["onboarded"] = r["sub_token"]
            _cfg_save()
            try:
                _audit("onboard_first_sub", client=r["name"])
            except Exception:
                pass
            return True
    except Exception as e:
        print("onboard: " + str(e), flush=True)
        return False

def _onboard_info():
    """Данные карточки онбординга для дашборда или None (не показывать)."""
    tok = str(CFG_CACHE.get("onboarded") or "")
    if not tok or tok in ("clients", "seen"):
        return None
    st = _load(STATE) or {}
    if not any(c.get("sub_token") == tok
               for inb in (st.get("inbounds") or {}).values()
               for c in inb.get("clients", [])):
        return None
    host = _hop_pub_host()
    host = host if "://" not in host else urllib.parse.urlparse(host).netloc
    base = _pb(host, CFG_CACHE.get("panel_port", 8444))
    return {"sub_url": base + "/sub/" + tok, "page_url": base + "/p/" + tok}

def _onboard_notify():
    ids = CFG_CACHE.get("bot_chat_ids") or []
    if not ids:
        return
    try:
        info = _onboard_info()
        if not info:
            return
        B = _bot_B(ids[0])
        _bot_send_message(ids[0], B["onboard_msg"] % (_html.escape(info["sub_url"]),
                                                      _html.escape(info["page_url"])),
                          "HTML", _main_menu_keyboard(B))
    except Exception as e:
        print("onboard bot: " + str(e), flush=True)

def _bot_fp(tok):
    """Отпечаток токена, а не сам токен: задание лежит в очереди, а очередь может
    попасть в дамп или traceback — живую секретную строку туда класть не зачем."""
    return hashlib.sha256((tok or "").encode("utf-8")).hexdigest()[:16]

def _bot_send_message(chat_id, text, parse_mode=None, reply_markup=None):
    token = CFG_CACHE.get("bot_token", "")
    if not token:
        return
    fp = _bot_fp(token)
    job = (_bot_send_now, (fp, chat_id, text, parse_mode, reply_markup))
    if _notify_capture(job):
        return   # уйдёт сам, когда вызывающий отпустит _STATE_LOCK
    # Корзины нет — значит мы не в запросе и не в тике: это фоновый поток
    # (предупреждение о блокировке, бэкап, продление адреса). Ждать чужого
    # Telegram здесь всё равно что занять его собой: 10 с на письмо, и поток,
    # который должен следить за лимитами, сам перестаёт за ними следить.
    _notify_out(job)

def _bot_send_now(want_fp, chat_id, text, parse_mode=None, reply_markup=None, attempt=1):
    token = CFG_CACHE.get("bot_token", "")
    if not token or _bot_fp(token) != want_fp:
        # письмо копилось в очереди, а за это время бота заменили или выключили:
        # отдать старое письмо новому боту — значит написать не туда
        return
    if len(text) > 4000:
        text = text[:4000] + "\n… (обрезано)"
    reason = ""
    try:
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        data = {"chat_id": chat_id, "text": text}
        if parse_mode:
            data["parse_mode"] = parse_mode
        if reply_markup:
            data["reply_markup"] = json.dumps(reply_markup)
        data = json.dumps(data).encode()
        req = urllib.request.Request(
            url, data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10):
            return
    except urllib.error.HTTPError as e:
        try:
            body = e.read().decode("utf-8", "replace")
        except Exception:
            body = ""
        print(f"[bot] sendMessage HTTP {e.code}: {body}", flush=True)
        retry, delay = _notify_retry_after(e.code, body, attempt)
        reason = "http_%d" % e.code
        if not retry:
            _audit_throttled("notify_dropped", gap=60, attempt=attempt, reason=reason)
            return
    except Exception as e:
        # сюда же идут socket.timeout и URLError: для письма это «временно»
        print("[bot] sendMessage error: " + _bot_err_text(e, token), flush=True)
        retry, delay = True, 10 * attempt
        reason = type(e).__name__
    _notify_requeue((_bot_send_now, (want_fp, chat_id, text, parse_mode, reply_markup,
                                     attempt + 1)), attempt, reason, delay)


def _bot_answer_callback(callback_query_id, text=None, show_alert=False):
    token = CFG_CACHE.get("bot_token", "")
    if not token:
        return
    # Ответ на нажатие — тоже чужой сервис с urlopen(timeout=10). Вызывается из
    # _process_bot_update, который держит _STATE_LOCK: без отсрочки одно молчаливое
    # нажатие стоило бы панели 10 секунд простоя всей пишущей морды (находка #14).
    fp = _bot_fp(token)
    job = (_bot_answer_now, (fp, callback_query_id, text, show_alert))
    if _notify_capture(job):
        return
    _notify_out(job)

def _bot_answer_now(want_fp, callback_query_id, text=None, show_alert=False):
    token = CFG_CACHE.get("bot_token", "")
    if not token or _bot_fp(token) != want_fp:
        return   # бота за это время сменили — старому нажатию отвечать нечему
    try:
        url = f"https://api.telegram.org/bot{token}/answerCallbackQuery"
        data = {"callback_query_id": callback_query_id}
        if text:
            data["text"] = text
        if show_alert:
            data["show_alert"] = True
        data = json.dumps(data).encode()
        req = urllib.request.Request(
            url, data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10):
            pass
    except Exception as e:
        print("[bot] answerCallbackQuery error: " + _bot_err_text(e, token), flush=True)

def _lang_keyboard():
    return {"inline_keyboard": [[
        {"text": "Русский", "callback_data": "lang_ru"},
        {"text": "English", "callback_data": "lang_en"},
        {"text": "فارسی", "callback_data": "lang_fa"},
        {"text": "中文", "callback_data": "lang_zh"},
    ]]}

_BOT_SEEN = {}
_BOT_SEEN_LK = threading.Lock()
_BOT_SEEN_MAX = 4096


def _bot_uid(update):
    try:
        return int(update.get("update_id"))
    except (AttributeError, TypeError, ValueError):
        return None


def _process_bot_update(update):
    """Исполнить update ровно один раз. Telegram отдаёт вебхум «не меньше одного
    раза» и повторяет поставку, если ответ не дошёл или запоздал, — а второй
    /addsub это два подписчика, второй /restart — второй обрыв на 48 живых
    клиентах. Запоминаем только УСПЕШНУЮ обработку: если внутри исключение,
    повтор обязан иметь шанс доделать."""
    uid = _bot_uid(update)
    if uid is not None:
        with _BOT_SEEN_LK:
            if uid in _BOT_SEEN:
                return
    _bot_update_apply(update)
    if uid is not None:
        with _BOT_SEEN_LK:
            _BOT_SEEN[uid] = int(time.time())
            if len(_BOT_SEEN) > _BOT_SEEN_MAX:
                for k in sorted(_BOT_SEEN, key=lambda x: _BOT_SEEN[x])[:len(_BOT_SEEN) - _BOT_SEEN_MAX]:
                    _BOT_SEEN.pop(k, None)


def _bot_update_apply(update):
    message = update.get("message") or update.get("edited_message")
    callback_query = update.get("callback_query")
    
    if callback_query:
        callback_query_id = callback_query.get("id")
        cb_from = callback_query.get("from") or {}
        cb_data = callback_query.get("data")
        if not callback_query_id or not cb_from.get("id") or not cb_data:
            # неполный/чужой update (ручку может трогать не только Telegram): выходим
            # молча, чем падать KeyError на []-индексации внешних полей
            return
        message = callback_query.get("message")
        tg_code = cb_from.get("language_code") or ""
        if not message:
            # Answer callback query even if no message (shouldn't happen but safety)
            _bot_answer_callback(callback_query_id, _BOT_RU["nocallback"], show_alert=True)
            return
        msg_chat = (message.get("chat") or {})
        if not msg_chat.get("id"):
            return
        chat_id = msg_chat["id"]
        from_id = cb_from["id"]
        data = cb_data
        B = _bot_B(chat_id, tg_code)
        _cb_un = (callback_query.get("from") or {}).get("username") or ""
        if _cb_un:
            try:
                _shop_try_bind(_cb_un, chat_id, B)
            except Exception:
                pass
        if data.startswith("lang_"):
            _bot_answer_callback(callback_query_id)
            lg = data[5:]
            _bot_lang_set(chat_id, lg)
            B2 = _bot_B(chat_id)
            kb = _main_menu_keyboard(B2) if _is_admin(from_id) else _bot_sub_keyboard(B2)
            _bot_send_message(chat_id, B2["lang_saved"] % B2["m_lang"], reply_markup=kb)
            return
        if data.startswith("sub_"):
            _bot_answer_callback(callback_query_id)
            return _bot_sub_cb(chat_id, data, B)
        if not _is_admin(from_id):
            # чужие chat_id наружу не отдаём: «нет прав» — это не подсказка, кому
            # и кого подставлять, чтобы права появились
            print("[bot] norights: chat=%s from=%s admins=%s" %
                  (chat_id, from_id, CFG_CACHE.get('bot_chat_ids', [])), flush=True)
            _bot_send_message(chat_id, B["norights"] % from_id)
            _bot_answer_callback(callback_query_id, B["norights_short"], show_alert=True)
            return
        # Answer callback query first (required by Telegram)
        _bot_answer_callback(callback_query_id)
        if data.startswith("bk"):
            try:
                _bot_backup_cb(chat_id, data, B)
            except Exception as e:
                _bot_send_message(chat_id, B["bk_err"] % str(e))
            return
        if data == "cmd_status":
            cmd = "/status"
        elif data == "cmd_clients":
            cmd = "/clients"
        elif data == "cmd_restart":
            cmd = "/restart"
        elif data == "cmd_addsub":
            cmd = "/addsub"
        elif data == "cmd_help":
            cmd = "/help"
        elif data == "cmd_stats":
            cmd = "/stats"
        elif data == "cmd_2fa":
            cmd = "/2fa"
        elif data == "cmd_pay":
            cmd = "/pay"
        elif data == "cmd_backup":
            cmd = "/backup"
        elif data == "cmd_lang":
            _bot_send_message(chat_id, B["lang_q"], reply_markup=_lang_keyboard())
            return
        else:
            return
        # Simulate command processing
        text = cmd
    else:
        message = update.get("message") or update.get("edited_message")
        if not message:
            return
        chat_id = message.get("chat", {}).get("id")
        from_id = message.get("from", {}).get("id")
        tg_code = (message.get("from") or {}).get("language_code") or ""
        B = _bot_B(chat_id, tg_code)
        text = message.get("text", "").strip()
        _msg_un = (message.get("from") or {}).get("username") or ""
        if _msg_un:
            try:
                _shop_try_bind(_msg_un, chat_id, B)
            except Exception:
                pass
        if not text.startswith("/"):
            stp = BOT_NEW_SUB.get(chat_id)
            if stp and stp.get("step") and _is_admin(from_id):
                step = stp["step"]
                if step == "name":
                    name = text.strip()
                    if not name:
                        _bot_send_message(chat_id, B["add_nameempty"], "HTML")
                        return
                    stp["name"] = name[:40]
                    stp["step"] = "limit"
                    BOT_NEW_SUB[chat_id] = stp
                    _bot_send_message(chat_id,
                        B["add_limitq"] % _html.escape(stp["name"]), "HTML")
                elif step == "limit":
                    try:
                        limit_gb = float(text.replace(",", ".").strip())
                        if limit_gb < 0:
                            raise ValueError
                    except ValueError:
                        _bot_send_message(chat_id, B["add_num"], "HTML")
                        return
                    stp["limit_gb"] = limit_gb
                    stp["step"] = "days"
                    BOT_NEW_SUB[chat_id] = stp
                    _bot_send_message(chat_id,
                        B["add_daysq"] % str(limit_gb), "HTML")
                elif step == "days":
                    try:
                        days = int(text.strip())
                        if days < 0:
                            raise ValueError
                    except ValueError:
                        _bot_send_message(chat_id, B["add_intnum"], "HTML")
                        return
                    stp["days"] = days
                    BOT_NEW_SUB.pop(chat_id, None)
                    name = _client_name(stp.get("name"))
                    if name is None:
                        # Имя спрашивают на первом шаге, здесь его не додумывают:
                        # «Клиент» в response = подписчик, которого никто не заводил.
                        _bot_send_message(chat_id, B["add_nameempty"], "HTML")
                        return
                    try:
                        r = _create_subscription(name, limit_gb=stp.get("limit_gb", 0), expiry_days=days)
                    except Exception as e:
                        _bot_send_message(chat_id, B["add_err"] % str(e))
                        return
                    lim = B["unlim"] if r["limit_gb"] <= 0 else (B["gb"] % r["limit_gb"])
                    day = B["forever"] if r["expiry_days"] <= 0 else (B["daysu"] % r["expiry_days"])
                    _bot_send_message(chat_id,
                        B["created"] % (_html.escape(name), lim, day, _html.escape(r['sub_url'])),
                        "HTML", _main_menu_keyboard(B))
                return
            if not _is_admin(from_id):
                return _bot_sub_msg(chat_id, text, B)
            return
    
    if not _is_admin(from_id):
        return _bot_sub_msg(chat_id, text, B)
    
    parts = text.split()
    cmd = parts[0].lower().split("@", 1)[0]
    args = parts[1:]
    try:
        if cmd == "/start":
            _bot_send_message(chat_id, B["start"] % chat_id,
                "HTML", _main_menu_keyboard(B))
        elif cmd == "/lang":
            _bot_send_message(chat_id, B["lang_q"], reply_markup=_lang_keyboard())
        elif cmd == "/clients":
            st = _load(STATE, {}) or {}
            lines = [B["clients_hdr"]]
            for proto, inb in (st.get("inbounds") or {}).items():
                for c in inb.get("clients", []):
                    online = "🟢" if c.get("online") else "⚪"
                    limit = (" (" + (B["gb"] % c.get('limit_gb', 0)) + ")") if c.get("limit_gb", 0) > 0 else ""
                    lines.append(f"{online} {_html.escape(str(c.get('name', '?')))} — {_html.escape(str(PROTO_LABELS.get(proto, proto)))}{limit}")
            _bot_send_message(chat_id, "\n".join(lines) if len(lines) > 1 else B["clients_empty"], "HTML", _main_menu_keyboard(B))
        elif cmd == "/restart":
            _restart_xray()
            _bot_send_message(chat_id, B["restarted"], reply_markup=_main_menu_keyboard(B))
        elif cmd == "/addsub":
            BOT_NEW_SUB[chat_id] = {"step": "name", "name": ""}
            _bot_send_message(chat_id, B["add_step1"], "HTML")
        elif cmd == "/cancel":
            BOT_NEW_SUB.pop(chat_id, None)
            _bot_send_message(chat_id, B["cancelled"], reply_markup=_main_menu_keyboard(B))
        elif cmd == "/help":
            _bot_send_message(chat_id, B["help"], "HTML", _main_menu_keyboard(B))
        elif cmd in ("/status", "/stats"):
            st = _load(STATE, {}) or {}
            running = _unit_active("xray")
            clients = _client_count(st)
            uptime = _service_active_since("xray")
            gp = _gp_last_history()
            if gp:
                ok, total, pct, ts = gp
                gp_txt = B["gp_ok"] % ("🟢" if pct > 50 else "🔴", ok, total, f"{pct:.0f}", ts)
            else:
                gp_txt = B["gp_none"]
            cpu = mem = None
            try:
                m = get_system_metrics()
                cpu = m.get("cpu_usage"); mem = m.get("mem_usage")
            except Exception:
                pass
            disk = subprocess.run(["df", "-h", "/"], capture_output=True, text=True, timeout=3).stdout
            _bot_send_message(chat_id,
                B["status_hdr"] % (B["xray_on"] if running else B["xray_off"],
                    uptime or '—', clients, len(_load_nodes()), gp_txt,
                    cpu if cpu is not None else '—', mem if mem is not None else '—',
                    disk.splitlines()[1] if len(disk.splitlines()) > 1 else '—'),
                "HTML", _main_menu_keyboard(B))
        elif cmd == "/2fa":
            _bot_send_message(chat_id, B["twofa"],
                "HTML", _main_menu_keyboard(B))
        elif cmd == "/pay":
            try:
                pc = _pay_cfg()
                if not pc["enabled"]:
                    _bot_send_message(chat_id, B["pay_off"], "HTML", _main_menu_keyboard(B))
                    return
                d = _pay_load()
                labels = dict(_PAY_LABELS)
                applied = [v for v in d["invoices"].values() if v.get("applied")]
                collected = sum(float(v.get("price") or 0) for v in applied)
                cur0 = (applied[0].get("currency") if applied and applied[0].get("currency") else "RUB")
                unpaid = sum(1 for v in d["invoices"].values() if not v.get("applied"))
                lines = [B["pay_hdr"] % (labels.get(pc["provider"], pc["provider"]),
                                         len(d["plans"]), unpaid, "%g" % collected, cur0)]
                invs = sorted(d["invoices"].values(), key=lambda x: -(x.get("created") or 0))[:6]
                if invs:
                    lines.append(B["pay_recent"])
                    for v in invs:
                        stt = B["pay_paidst"] if v.get("applied") else B["pay_wait"]
                        lines.append(B["pay_line"] % (v.get("id"),
                                                      _html.escape(str(v.get("name") or "?")),
                                                      "%g" % float(v.get("price") or 0),
                                                      v.get("currency") or "RUB", stt))
                else:
                    lines.append(B["pay_none"])
                _bot_send_message(chat_id, "\n".join(lines), "HTML", _main_menu_keyboard(B))
            except Exception as e:
                _bot_send_message(chat_id, B["err"] % str(e))
        elif cmd == "/paycheck":
            try:
                d = _pay_load()
                open_invs = [v["id"] for v in d["invoices"].values()
                             if not v.get("applied") and v.get("provider") in ("cryptobot", "yookassa")
                             and v.get("external_id")]
                if not open_invs:
                    _bot_send_message(chat_id, B["pay_none_open"], "HTML", _main_menu_keyboard(B))
                    return
                before = sum(1 for v in d["invoices"].values() if v.get("applied"))
                for iid in open_invs[:30]:
                    _pay_check_ext(iid)
                after = sum(1 for v in _pay_load()["invoices"].values() if v.get("applied"))
                _bot_send_message(chat_id, B["pay_checked"] % (len(open_invs), after - before),
                                  "HTML", _main_menu_keyboard(B))
            except Exception as e:
                _bot_send_message(chat_id, B["err"] % str(e))
        elif cmd == "/backup":
            _bot_backup_menu(chat_id, B)
        else:
            _bot_send_message(chat_id, B["unknown"], reply_markup=_main_menu_keyboard(B))
    except Exception as e:
        import traceback
        print("[bot] ошибка обработки " + str(text) + ": " + str(e), flush=True)
        traceback.print_exc()
        try:
            _bot_send_message(chat_id, B["err"] % str(e))
        except Exception:
            pass

def _load_nodes():
    try:
        st = _load(STATE, {}) or {}
        return [n for n in (st.get("nodes") or {})]
    except Exception:
        return []

# ---------- HTTP ----------

CFG_CACHE = _load(CFG, {}) or {}

def _cookie(self):
    m = re.search(r"sid=([^;]+)", self.headers.get("Cookie", "") or "")
    return m.group(1) if m else None

def _authed(self):
    t = _cookie(self)
    if t is None:
        t = (self.headers.get("X-Sid") or "").strip() or None
    e = SESSIONS.get(t) if t else None
    return bool(e and e > time.time())

# ---------- роли: операторы с настраиваемыми правами ----------
PERM_KEYS = ["clients", "nodes", "hop", "proxy", "rotation", "site", "pay",
             "backups", "restore", "settings", "bot", "security", "logs", "appearance"]

def _clean_perms(d):
    d = d if isinstance(d, dict) else {}
    return {k: bool(d.get(k)) for k in PERM_KEYS}

# Логи служб (вкладка «Логи»): id, метка, источник (journal=имя юнита, file=путь), цель
LOG_SOURCES = [
    ("xray", "Xray (VPN-ядро)", "journal", "xray"),
    ("telemt", "telemt (Telegram-прокси)", "journal", "telemt"),
    ("vpnpanel", "Veil-панель", "journal", "vpnpanel"),
    ("nginx", "nginx (веб-фронт)", "journal", "nginx"),
    ("cloudflared", "Cloudflare Tunnel", "journal", "cloudflared"),
    ("zapret", "veil-zapret2 (обход DPI)", "journal", "veil-zapret2"),
    ("syslog", "Системный (syslog)", "file", "/var/log/syslog"),
]

def _tail_lines(path, count):
    with open(path, "rb") as f:
        f.seek(0, os.SEEK_END)
        sz = f.tell()
        off = max(0, sz - 1500000)
        f.seek(off)
        data = f.read().decode("utf-8", "replace")
    ls = data.splitlines()
    if off > 0 and ls:
        ls = ls[1:]
    return ls[-count:]

# ============ Остаток credential-форм на НОСИТЕЛЕ журнала (#229) ============
# Ручка «Логи» сворачивает credential при ЧТЕНИИ (в стоке `/api/logs`:
# `_audit_redact` со строгим разделителем), а `LogFilterPatterns` (#217) стоит на
# конвейере systemd и не даёт НОВЫМ строкам лечь ни в journald, ни в копию rsyslog. Про строки, которые
# уже лежат на диске, он не делает ничего. Замер 07.10 на этой машине:
# `journalctl -u telemt` за всё окно (9932 строк) — `0` форм, а `/var/log/syslog` —
# `1374` (04.10 — `706`, 05.10 — `498`, 06.10 — `170`, сегодня `0`) плюс `218` в
# `syslog.1.gz`; писатель `100`% — `telemt` (баннер `MAESTRO`). То есть «фильтр
# стоит» и «на носителе лежат чужие ключи» были неразличимы: панель молчала, а
# молчание читалось как ноль.
#
# Мера считает ровно то, что панель умеет сворачивать: строка засчитана, если её
# меняет одним из трёх сворачиваний стока — строгим шаблоном `_LOG_SECRET_RE`,
# credential до `@` в ссылке подписчика из `_AUDIT_URL_RE` и путь-credential
# (`/p/<tok>`) из `_AUDIT_TOK_PATH_RE`. Значения не печатаются нигде — только число
# строк, число строк носителя и имя писателя из третьего поля (формат rsyslog
# `ISO-8601 хост процесс[пид]:`).
#
# Охват совпадает с маской читателя намеренно: мерить двумя сворачиваниями из трёх
# значило бы назвать чистым носитель, на котором лежат подписочные токены, свёрнутые
# пока только в окне чтения. Замер 07.10 по всему носителю: путь-credential даёт `0`
# строк из `1593` — это снятое число, а не молчание.
#
# У одного критерия есть цена, и она названа, а не замалчивается: проза вида
# `key = os.path.join(root, dom, "privkey.pem")` маска сворачивает так же, как чужой
# ключ, — это тот же класс, что #216 судил по строгости шаблона. На живом носителе
# этой коробки это `1` строка из `1593`, и её отдаёт писатель: `telemt (1592)`,
# `python3 (1)`. Делать второй критерий «похоже на ключ или нет» — значит мерить
# догадкой; число остаётся числом маски, а классы разделяются тем, кто писал строку.
#
# Границы меры названы, а не умолчаны: носитель мерится вместе с ротациями
# (`syslog.N`, `syslog.N.gz`), файл больше `cap` не читается вовсе (`skipped`), а
# скан, упёршийся в `deadline`, отдаёт `partial` — и по числу прочитанных строк
# против размера файла видно, что замер частичный, а не что журнал чист. Файлы без
# полного вердикта собраны в `unread` по именам: `0` при непустом `unread` — это
# «не прочитано», а не «чисто».
_LOG_CRED_URL_RE = _AUDIT_URL_RE
_LOG_CRED_SEP_RE = _LOG_SECRET_RE
_LOG_CRED_PATH_RE = _AUDIT_TOK_PATH_RE
# У этого критерия есть один названный класс-исключение, и он зафиксирован ногой, а
# не спрятан: загрузочная строка ядра. Замер 09.10: бут 08.10 положил в `/var/log/syslog`
# четыре строки ядра о загрузке сертификата с автогенерированным ключом сборки (шаблон
# ниже несёт байтовую копию сообщения), и строгий разделитель сворачивает их как
# форму — хотя это ключ, вшитый в образ ядра при сборке, он печатается на каждой
# загрузке и не даёт доступа ни к чему клиентскому.
# Маска читателя такую строку по-прежнему сворачивает (охват окна не сужается), а мера
# её не считает. Ворота узкие с двух сторон: писатель обязан быть `kernel`, а строка —
# побайтно совпасть с известным сообщением ядра, включая закрывающую кавычку; и этим
# сообщением строка обязана кончаться — что стоит после кавычки, в класс не входит.
# Гипотетическая строка ядра с `secret=` в эти ворота не входит и остаётся формой.
_LOG_KERNEL_BOOT_RE = re.compile(
    r"Loaded X\.509 cert 'Build time autogenerated kernel key:\s*[0-9a-fA-F]{6,}'\s*$")
_LOG_RESIDUE_TTL = 900.0        # чаще этого носитель не перечитывать: живой опрос вкладки «Логи» идёт каждые 3 с
_LOG_RESIDUE_CAP = 400 * 1024 * 1024   # файл больше этого не сканируется — это граница меры, а не «чисто»
# Потолок скана всего носителя снят замером, а не взят «на глазок»: полный проход по
# живому носителю этой коробки (одно ядро) — `67` с на трёх файлах (`syslog` `11.9` с
# на `85.6` Мб, `syslog.1.gz` `26.0` с на `6.8` Мб, `syslog.2.gz` `28.6` с на `7.7` Мб).
# Прежние `60` с резали носитель пополам, и `partial` на последней ротации читался как
# «пусто». Двойной запас остаётся потолком: упёрся — вердикт `partial`, а не ноль.
_LOG_RESIDUE_DEADLINE = 120.0
_LOG_RESIDUE_CACHE = {}
_LOG_RESIDUE_LOCK = threading.Lock()


def _log_carrier(path):
    """Носитель и его ротации: `/var/log/syslog` + `syslog.N` / `syslog.N.gz`."""
    out = [path]
    try:
        d, b = os.path.dirname(path) or ".", os.path.basename(path)
        for f in sorted(os.listdir(d)):
            if f.startswith(b + ".") and (f.endswith(".gz") or
                                          f[len(b) + 1:].isdigit()):
                out.append(os.path.join(d, f))
    except Exception:
        pass
    return out


def _log_cred_line(line):
    """Бьёт ли по этой строке то же сворачивание, что стоит в стоке: строгий
    разделитель, credential до `@` в ссылке подписчика и путь-credential
    (`/p/<tok>`). Критерий меры совпадает с маской читателя, а не с догадкой о том,
    что «похоже на ключ»: иначе мера назвала бы чистым носитель, на котором лежит
    форма, сворачиваемая только в окне чтения. Единственное названное исключение —
    загрузочная строка ядра: писатель `kernel` и побайтное совпадение с известным
    сообщением загрузки, этот класс разобран комментарием у `_LOG_KERNEL_BOOT_RE`."""
    if _LOG_KERNEL_BOOT_RE.search(line) and _log_writer(line) == "kernel":
        return False
    return (bool(_LOG_CRED_SEP_RE.search(line) or _LOG_CRED_URL_RE.search(line))
            or bool(_LOG_CRED_PATH_RE.search(line)))


def _log_writer(line):
    """Имя писателя из третьего поля rsyslog (`… процесс[пид]:`), без содержания строки.

    Имя обязано быть стабильным: по нему нога судит, кто пишет. Поэтому снимаются
    и скобки с pid, и двоеточие — одним шаблоном, а не по очереди с хвоста."""
    p = line.split(None, 3)
    if len(p) < 3:
        return "?"
    return re.sub(r"(\[[0-9]+\])?:$", "", p[2])[:40] or "?"


def _log_residue_scan_one(path, deadline):
    """Потоковый счётчик по одному файлу: формы, строки, писатели. Нечитаемый файл —
    `error`, а не `0`: молчание и пустой носитель различаются числом."""
    st = {"path": path, "forms": 0, "lines": 0, "bytes": 0, "writers": {}, "sec": 0.0,
          "partial": False, "skipped": False, "error": ""}
    try:
        sz = os.path.getsize(path)
    except Exception as e:
        st["error"] = type(e).__name__
        return st
    st["bytes"] = sz
    if sz > _LOG_RESIDUE_CAP:
        st["skipped"] = True
        return st
    opener = (lambda: gzip.open(path, "rt", errors="replace")) \
        if path.endswith(".gz") else (lambda: open(path, "rt", errors="replace"))
    try:
        started = time.time()
        with opener() as f:
            for line in f:
                st["lines"] += 1
                if _log_cred_line(line):
                    st["forms"] += 1
                    w = _log_writer(line)
                    st["writers"][w] = st["writers"].get(w, 0) + 1
                if time.time() - started > deadline:
                    st["partial"] = True
                    break
    except Exception as e:
        st["error"] = type(e).__name__
    return st


def _log_residue_scan(path, files, sig):
    """Скан носителя: складывает счётчики по файлам и складывает результат в кэш.
    В потоке запроса не вызывается никогда — см. `_log_residue`.

    Остаток бюджета делится поровну между файлами, которые ещё не читались, а не
    по их размеру: размер про работу не говорит — развёрнутый `syslog` стоит
    `0.14` с на Мб, а сжатая ротация `3.8` с на Мб, то есть в `27` раз дороже.
    Доля по байтам отдавала бы почти всё живому файлу и резала ротации."""
    res = {"files": [], "forms": 0, "lines": 0, "writers": {}, "measured": int(time.time()),
           "partial": False, "skipped": False, "error": "", "measuring": False,
           "elapsed_s": 0.0, "unread": []}
    started = time.time()
    for i, p in enumerate(files):
        left = _LOG_RESIDUE_DEADLINE - (time.time() - started)
        one_t0 = time.time()
        one = _log_residue_scan_one(p, max(0.5, left / (len(files) - i)))
        one["sec"] = round(time.time() - one_t0, 1)
        res["files"].append(one)
        res["forms"] += one["forms"]
        res["lines"] += one["lines"]
        for w, n in one["writers"].items():
            res["writers"][w] = res["writers"].get(w, 0) + n
        res["partial"] = res["partial"] or one["partial"]
        res["skipped"] = res["skipped"] or one["skipped"]
        if one["error"]:
            res["error"] = (res["error"] + " " + one["error"]).strip()
        # файл без полного вердикта не даёт сказать «чисто»: он не прочитан
        if one["partial"] or one["skipped"] or one["error"]:
            res["unread"].append(os.path.basename(p))
        if time.time() - started >= _LOG_RESIDUE_DEADLINE:
            res["partial"] = True
            break
    res["elapsed_s"] = round(time.time() - started, 1)
    with _LOG_RESIDUE_LOCK:
        _LOG_RESIDUE_CACHE[path] = {"ts": time.time(), "sig": sig, "res": res, "busy": False}


def _log_residue(path):
    """Остаток credential-форм на носителе: {'forms': N, 'lines': N, 'writers': {имя: N},
    'files': [...], 'unread': [имя файла], 'measured': ts, 'elapsed_s': N,
    'partial': bool, 'skipped': bool, 'error': str, 'measuring': bool,
    'stale': bool, 'age_s': N}.

    Скан идёт в отдельном потоке и никогда в потоке запроса: живой носитель этой
    коробки — `90` Мб, и мерка, снятая в запросе за `4` с, дочитывала `5` % и
    называлась `partial`, то есть отвечала на вопрос оператора нечислом. Первый
    вызов поэтому ничего не знает и честно говорит `measuring` с `forms=None`:
    молчание и «ноль» — разные вердикты, а не одно состояние. Дальше работает `TTL`:
    вкладка «Логи» опрашивается каждые `3` с, а носитель за это время успевает
    вырасти, и перечитывать его на каждый опрос — значит мерить глазами одна и та
    же строку."""
    files = _log_carrier(path)
    try:
        sig = tuple((p, os.path.getsize(p), int(os.path.getmtime(p))) for p in files)
    except Exception:
        sig = tuple(files)
    now = time.time()
    with _LOG_RESIDUE_LOCK:
        ent = _LOG_RESIDUE_CACHE.get(path)
        if ent:
            out = dict(ent["res"])
            out.update(stale=(ent["sig"] != sig), age_s=int(now - ent["ts"]),
                       busy=bool(ent.get("busy")))
            if ent.get("busy") or now - ent["ts"] < _LOG_RESIDUE_TTL:
                return out
            known, ts, old_sig = ent["res"], ent["ts"], ent["sig"]
        else:
            known = {"files": [], "forms": None, "lines": 0, "writers": {},
                     "measured": 0, "partial": False, "skipped": False,
                     "error": "", "measuring": True, "unread": [], "elapsed_s": 0.0}
            ts, old_sig = now, sig
        _LOG_RESIDUE_CACHE[path] = {"ts": ts, "sig": old_sig, "res": known, "busy": True}
    threading.Thread(target=_log_residue_scan, args=(path, files, sig), daemon=True).start()
    out = dict(known)
    out.update(stale=(old_sig != sig), age_s=0, busy=True)
    return out


# ================= Passkeys (WebAuthn): Face ID / Touch ID =================
# Самодостаточная реализация без внешних зависимостей: минимальный декодер CBOR
# и проверка ECDSA P-256 (ES256) на чистом Python. Регистрация — TOFU: ключ
# привязывается из уже аутентифицированной сессии и принимается как есть;
# вход доказывает владение приватным ключом подписью `assertion`'а (UV обязателен,
# т.е. биометрия/PIN на устройстве).
PASSKEYS_FILE = f"{BASE}/passkeys.json"
_PK_LOCK = threading.Lock()
_PK_DB_LOCK = threading.Lock()  # passkeys.json: чтобы две операции не перетёрли друг друга
_PK_PENDING = {}  # token -> {"ch": bytes, "exp": ts, "host": str}

def _b64u_dec(s):
    s = str(s or "")
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))

def _b64u_enc(b):
    return base64.urlsafe_b64encode(bytes(b)).decode().rstrip("=")

def _cbor_dec(d, i=0):
    v = d[i]; i += 1
    mt, ai = v >> 5, v & 31
    def ln():
        nonlocal i
        if ai < 24: return ai
        if ai == 24: n = d[i]; i += 1; return n
        if ai == 25: n = int.from_bytes(d[i:i + 2], "big"); i += 2; return n
        if ai == 26: n = int.from_bytes(d[i:i + 4], "big"); i += 4; return n
        if ai == 27: n = int.from_bytes(d[i:i + 8], "big"); i += 8; return n
        raise ValueError("cbor")
    if mt == 0: return ln(), i
    if mt == 1: return -1 - ln(), i
    if mt == 2:
        n = ln(); return bytes(d[i:i + n]), i + n
    if mt == 3:
        n = ln(); return d[i:i + n].decode("utf-8", "replace"), i + n
    if mt == 4:
        if ai == 31:
            out = []
            while d[i] != 0xFF:
                x, i = _cbor_dec(d, i); out.append(x)
            return out, i + 1
        n = ln(); out = []
        for _ in range(n):
            x, i = _cbor_dec(d, i); out.append(x)
        return out, i
    if mt == 5:
        if ai == 31:
            out = {}
            while d[i] != 0xFF:
                k, i = _cbor_dec(d, i); x, i = _cbor_dec(d, i); out[k] = x
            return out, i + 1
        n = ln(); out = {}
        for _ in range(n):
            k, i = _cbor_dec(d, i); x, i = _cbor_dec(d, i); out[k] = x
        return out, i
    if mt == 6:
        ln()
        return _cbor_dec(d, i)
    if mt == 7:
        if ai == 20: return False, i
        if ai == 21: return True, i
        if ai == 22: return None, i
        if ai == 24: return d[i], i + 1
        n = {25: 2, 26: 4, 27: 8}.get(ai)
        if n: return None, i + n
    raise ValueError("cbor")

_EC_P = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
_EC_N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
_EC_GX = 0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296
_EC_GY = 0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5

def _ec_inv(a, m):
    return pow(a % m, m - 2, m)

def _ec_add(p, q):
    if p is None: return q
    if q is None: return p
    if p[0] == q[0]:
        if (p[1] + q[1]) % _EC_P == 0: return None
        s = (3 * p[0] * p[0] - 3) * _ec_inv(2 * p[1], _EC_P) % _EC_P
    else:
        s = (q[1] - p[1]) * _ec_inv(q[0] - p[0], _EC_P) % _EC_P
    x = (s * s - p[0] - q[0]) % _EC_P
    return (x, (s * (p[0] - x) - p[1]) % _EC_P)

def _ec_mul(k, p):
    r0, rp = None, p
    while k:
        if k & 1: r0 = _ec_add(r0, rp)
        rp = _ec_add(rp, rp); k >>= 1
    return r0

def _ecdsa_verify(msg_int, r, s, x, y):
    if not (1 <= r < _EC_N and 1 <= s < _EC_N): return False
    w = _ec_inv(s, _EC_N)
    pt = _ec_add(_ec_mul((msg_int * w) % _EC_N, (_EC_GX, _EC_GY)), _ec_mul((r * w) % _EC_N, (x, y)))
    return pt is not None and pt[0] % _EC_N == r

def _der_rs(b):
    try:
        if b[0] != 0x30: return None
        i = 2
        if b[1] & 0x80: i += (b[1] & 0x7F)
        if b[i] != 0x02: return None
        rl = b[i + 1]; r = int.from_bytes(b[i + 2:i + 2 + rl], "big"); i += 2 + rl
        if b[i] != 0x02: return None
        sl = b[i + 1]; s = int.from_bytes(b[i + 2:i + 2 + sl], "big")
        return r, s
    except Exception:
        return None

def _pk_authdata(ad):
    if len(ad) < 37: return None
    out = {"rp": ad[:32], "flags": ad[32], "counter": int.from_bytes(ad[33:37], "big"), "cred": None}
    if out["flags"] & 0x40:
        rest = ad[37:]
        if len(rest) < 19: return None
        cl = int.from_bytes(rest[16:18], "big")
        if len(rest) < 18 + cl: return None
        try:
            cose, _ = _cbor_dec(rest, 18 + cl)
        except Exception:
            return None
        out["cred"] = {"id": rest[18:18 + cl], "cose": cose}
    return out

def _pk_cose_es256(cose):
    try:
        if cose.get(1) != 2 or cose.get(3) != -7 or cose.get(-1) != 1: return None
        x, y = cose.get(-2), cose.get(-3)
        if isinstance(x, (bytes, bytearray)) and len(x) == 32 \
                and isinstance(y, (bytes, bytearray)) and len(y) == 32:
            return int.from_bytes(x, "big"), int.from_bytes(y, "big")
    except Exception:
        pass
    return None

def _pk_load():
    try:
        with open(PASSKEYS_FILE, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}

def _pk_host(self):
    h = (self.headers.get("Host") or "").strip()
    if h.startswith("["):
        try:
            return h[1:h.index("]")]
        except Exception:
            return h
    return h.split(":")[0]

def _pk_new_pending(host):
    with _PK_LOCK:
        now = time.time()
        for k in [k for k, v in _PK_PENDING.items() if v.get("exp", 0) < now]:
            _PK_PENDING.pop(k, None)
        tok = secrets.token_hex(8)
        _PK_PENDING[tok] = {"ch": secrets.token_bytes(32), "exp": now + 180, "host": host}
        return tok, _PK_PENDING[tok]["ch"]

def _pk_take_pending(tok):
    with _PK_LOCK:
        p = _PK_PENDING.pop(str(tok or ""), None)
    if not p or p["exp"] < time.time(): return None
    return p

def _pk_clientdata(rb, want_type, ch_b64, host):
    try:
        raw = _b64u_dec((rb or {}).get("clientDataJSON"))
        cd = json.loads(raw.decode("utf-8"))
    except Exception:
        return None, "clientDataJSON не разобран", None
    if cd.get("type") != want_type:
        return None, "не тот тип церемонии", None
    if cd.get("challenge") != ch_b64:
        return None, "challenge не совпал", None
    try:
        oh = urllib.parse.urlparse(str(cd.get("origin") or "")).hostname or ""
    except Exception:
        return None, "origin не разобран", None
    if oh.lower() != str(host or "").lower():
        return None, "origin не совпал с адресом панели", None
    return cd, None, raw

def _pk_uid(self):
    u = _auth_user(self)
    if u is None: return None
    return "" if u.get("owner") else u.get("login")

def _pk_reg_end(self, b, uid):
    p = _pk_take_pending(b.get("token"))
    if not p: return 400, {"error": "попытка истекла — начни заново"}
    rb = b.get("response") or b
    cd, err, raw = _pk_clientdata(rb, "webauthn.create", _b64u_enc(p["ch"]), p["host"])
    if cd is None: return 401, {"error": err}
    try:
        att = _b64u_dec(rb.get("attestationObject"))
        am, _ = _cbor_dec(att)
        ad = _pk_authdata(am.get("authData") or b"")
    except Exception:
        return 400, {"error": "attestationObject не разобран"}
    if not ad or not ad.get("cred"): return 400, {"error": "нет данных кредитенциала"}
    if not (ad["flags"] & 0x01): return 401, {"error": "UP не подтверждён"}
    if ad["rp"] != hashlib.sha256(p["host"].encode()).digest(): return 401, {"error": "rpIdHash не совпал"}
    xy = _pk_cose_es256(ad["cred"]["cose"])
    if not xy: return 400, {"error": "поддерживаются только ключи ES256 (P-256)"}
    if am.get("fmt") == "packed":
        st_ = am.get("attStmt") or {}
        sig = st_.get("sig")
        if sig and not st_.get("x5c"):
            try:
                cdh, i2 = _cbor_dec(att)
                blob = am.get("authData") + hashlib.sha256(raw).digest()
                rs = _der_rs(bytes(sig))
                if rs and not _ecdsa_verify(int.from_bytes(hashlib.sha256(blob).digest(), "big"),
                                            rs[0], rs[1], xy[0], xy[1]):
                    return 401, {"error": "подпись аттестации не прошла"}
            except Exception:
                return 400, {"error": "packed-аттестация не разобрана"}
    name = str(b.get("name") or "").strip()[:40] or \
        ((self.headers.get("User-Agent") or "ключ")[:40])
    with _PK_DB_LOCK:   # одна правка файла на всю операцию
            db = _pk_load()
            lst = db.get(uid) or []
            if len(lst) >= 12: return 400, {"error": "слишком много ключей (макс. 12)"}
            cid = _b64u_enc(ad["cred"]["id"])
            if any(c.get("id") == cid for c in lst): return 409, {"error": "такой ключ уже привязан"}
            lst.append({"id": cid, "x": "%064x" % xy[0], "y": "%064x" % xy[1],
                        "name": name, "rp": p["host"], "created": _now_iso(), "counter": 0})
            db[uid] = lst
            _save(PASSKEYS_FILE, db)
    _audit("passkey_add", user=uid or "owner", name=name)
    return 200, {"ok": True, "keys": _pk_public(lst)}

def _pk_public(lst):
    return [{"id": c.get("id"), "name": c.get("name"), "created": c.get("created")} for c in (lst or [])]

def _pk_login_end(self, b):
    cip = self.client_address[0]
    ua_h = (self.headers.get("User-Agent") or "")[:256]
    if _login_throttle(cip):
        return 429, {"error": "слишком много попыток. подожди 10 минут"}
    p = _pk_take_pending(b.get("token"))
    if not p: return 400, {"error": "попытка истекла — начни заново"}
    rb = b.get("response") or b
    found, fuid = None, None
    with _PK_DB_LOCK:   # одна правка файла на всю операцию
            db = _pk_load()
            ckey = None
            try:
                ckey = _b64u_enc(_b64u_dec(b.get("id")))
            except Exception:
                pass
            for uid, lst in db.items():
                for c in lst:
                    if ckey and c.get("id") == ckey:
                        found, fuid = c, uid
            if not found:
                _login_fail(cip)
                _login_history("fail", ip=cip, ua=ua_h, err="passkey_unknown_cred")
                return 401, {"error": "ключ не привязан к этой панели"}
            cd, err, raw = _pk_clientdata(rb, "webauthn.get", _b64u_enc(p["ch"]), p["host"])
            if cd is None:
                _login_fail(cip)
                _login_history("fail", ip=cip, ua=ua_h, err="passkey_clientdata")
                return 401, {"error": err}
            try:
                ad_raw = _b64u_dec(rb.get("authenticatorData"))
                a = _pk_authdata(ad_raw)
                sig = _der_rs(_b64u_dec(rb.get("signature")))
            except Exception:
                a, sig = None, None
            if not a or not sig:
                return 400, {"error": "ответ устройства не разобран"}
            if not (a["flags"] & 0x01):
                return 401, {"error": "устройство не подтвердило присутствие (UP)"}
            if not (a["flags"] & 0x04):
                return 401, {"error": "биометрия не подтверждена (UV) — на устройстве должен быть настроен Face ID/Touch ID или PIN"}
            if a["rp"] != hashlib.sha256((found.get("rp") or "").encode()).digest():
                return 401, {"error": "ключ выпущен для другого адреса"}
            old = int(found.get("counter") or 0)
            if old and a["counter"] and a["counter"] <= old:
                return 401, {"error": "возможно клонирование ключа — привяжи заново"}
            blob = ad_raw + hashlib.sha256(raw).digest()
            if not _ecdsa_verify(int.from_bytes(hashlib.sha256(blob).digest(), "big"),
                                 sig[0], sig[1], int(found["x"], 16), int(found["y"], 16)):
                _login_fail(cip)
                _login_history("fail", ip=cip, ua=ua_h, err="passkey_bad_sig")
                return 401, {"error": "подпись не прошла"}
            if fuid:
                x = next((u for u in (CFG_CACHE.get("users") or []) if u.get("login") == fuid), None)
                if not x or x.get("disabled"):
                    return 403, {"error": "оператор удалён или заблокирован"}
            _login_ok(cip)
            t = secrets.token_hex(32)
            SESSIONS[t] = time.time() + 30 * 86400
            SESSIONS_META[t] = {"ip": cip, "ua": ua_h, "created": _now_iso(),
                                "last_seen": _now_iso(), "remember": True,
                                "user": fuid, "passkey": True}
            found["counter"] = a["counter"] or old
            _save(PASSKEYS_FILE, db)
    _login_history("ok", ip=cip, ua=ua_h, user=fuid or "owner")
    _audit("login_passkey", ip=cip, user=fuid or "owner", ok=True)
    _save_sessions()
    self._cookies = ["sid=" + t + "; Path=/; HttpOnly; Max-Age=2592000; SameSite=Lax"
                     + ("; Secure" if self._is_tls() else "")]
    return 200, {"ok": True, "sid": t}

def _auth_sid(self):
    t = _cookie(self)
    if t is None:
        t = (self.headers.get("X-Sid") or "").strip() or None
    if not t:
        return None
    e = SESSIONS.get(t)
    if not (e and e > time.time()):
        return None
    # Сессия жива, только если у неё есть «паспорт» (мета с владельцем или
    # логином). Без этого ключ от /api/state и подобных «_authed-ручек»
    # оставался бы действителен, а _auth_user уже не даёт владельца из пустоты.
    if not isinstance(SESSIONS_META.get(t), dict):
        return None
    return t

def _auth_user(self):
    sid = _auth_sid(self)
    if not sid:
        return None
    m = SESSIONS_META.get(sid)
    if not isinstance(m, dict):
        # Паспорт сессии потерялся — это не «владелец по умолчанию», а «никто».
        # Раньше `({}).get("user") or ""` превращал пустоту в владельца.
        return None
    uname = m.get("user") or ""
    if not uname:
        return {"owner": True, "login": str(CFG_CACHE.get("login") or "owner"), "perms": {}}
    for x in (CFG_CACHE.get("users") or []):
        if x.get("login") == uname:
            if x.get("disabled"):
                return None
            return {"owner": False, "login": uname, "perms": x.get("perms") or {}}
    return None

def _drop_user_sessions(login):
    drop = [t for t, mlist in SESSIONS_META.items() if (mlist or {}).get("user") == login]
    for t in drop:
        SESSIONS.pop(t, None)
        SESSIONS_META.pop(t, None)
    if drop:
        try:
            _save_sessions()
        except Exception:
            pass

def _perm_for(p, m):
    if not p.startswith("/api/"):
        return None
    if p in ("/api/login", "/api/logout", "/api/me", "/api/bot/webhook", "/api/hop/register"):
        return None
    if p == "/api/onboard/dismiss":
        # Значение живёт в config.json и ОДНО на всю панель: «первый запуск
        # просмотрен». Сотрудник без права «настройки» прятал этим подсказку
        # хозяина — и наоборот, хозяин сбрасывал её под оператора. Морда
        # вызывает ручку в try/catch, поэтому 403 для не-владельца ничего не
        # ломает:`banner` просто остаётся видимым тому, кому он и показан.
        return ["owner"]
    if p.startswith("/api/ext/") or p.startswith("/pay/"):
        return None
    if p == "/api/theme" and m == "GET":
        return None
    if p == "/api/backup":
        # Тот же URL, что и «скачать резервную копию», но по POST — это ПОЛНОЕ
        # восстановление: config.json (там права операторов), state.json (ключи и
        # подписчики) и конфиг xray заменяются присланным файлом целиком. Раньше
        # обоим глаголам хватало права «резервные копии», так что сотруднику,
        # которому доверили только забирать файлы, открывался и вход хозяина.
        return ["restore"] if m == "POST" else ["backups"]
    if p.startswith("/api/backups"):
        return ["restore"] if p == "/api/backups/restore" else ["backups"]
    if p.startswith("/api/users"):
        return ["owner"]
    if p.startswith("/api/2fa/"):
        return ["owner"]
    if p.startswith("/api/nodes"):
        return ["nodes"]
    if p.startswith("/api/hop"):
        return ["hop"]
    if p.startswith("/api/migrate"):
        return ["owner"]
    if p in ("/api/tg/switch", "/api/tg/restore", "/api/tg/restart"):
        # Подмена бинаря и перезапуск systemd-службы — это не «переключить прокси»,
        # а замена софта на машине: право settings, а не proxy. Иначе сотрудник с
        # единственной галкой «прокси» получает возможность залить любой телемет
        # руткит и поднять его той же кнопкой. Ручной рестарт — сюда же: он рвёт
        # тоннели у всех, кто пользуется прокси прямо сейчас.
        return ["settings"]
    if (p.startswith("/api/tg/") or p.startswith("/api/webproxy")
            or p.startswith("/api/webmux") or p.startswith("/api/front/")):
        return ["proxy"]
    # единый выпуск имён+сертификата живёт и во вкладке Мюкс (proxy), и во вкладке Сайт (cert) —
    # право либо на то, либо на другое
    if p.startswith("/api/veil"):
        return ["proxy", "site"]
    if (p.startswith("/api/rotate") or p.startswith("/api/dynv6")
            or p.startswith("/api/globalping") or p.startswith("/api/fix/")):
        return ["rotation"]
    if p.startswith("/api/cert"):
        return ["site"]
    if p.startswith("/api/term"):
        return ["owner"]
    if p.startswith("/api/ssh/port"):
        return ["owner"]
    if p.startswith("/api/ai"):
        return ["owner"]
    if p.startswith("/api/flux"):
        return ["owner"]
    if p.startswith("/api/pay"):
        return ["pay"]
    if p.startswith("/api/bot/"):
        return ["bot"]
    if (p.startswith("/api/sessions") or p in ("/api/security", "/api/login/history", "/api/audit")
            or p.startswith("/api/journal")):
        return ["security"]
    if p.startswith("/api/logs"):
        return ["security", "logs"]
    if (p.startswith("/api/clients") or p.startswith("/api/subs") or p.startswith("/api/bans")
            or p.startswith("/api/sub/") or p.startswith("/api/wgconf") or p.startswith("/api/awgconf")
            or p in ("/api/favorite", "/api/extimport/apply", "/api/extimport/preview",
                     "/api/subscription/settings")):
        return ["clients"]
    if (p.startswith("/api/logo") or p.startswith("/api/wallpaper")
            or p == "/api/theme"):
        return ["appearance"]
    for pref in ("/api/settings", "/api/panel", "/api/xray", "/api/versions", "/api/update",
                 "/api/restart", "/api/port", "/api/inbound", "/api/network", "/api/vpn",
                 "/api/selftest", "/api/schedule"):
        if p.startswith(pref):
            return ["settings"]
    return None

def _perm_gate(self, p, m):
    need = _perm_for(p, m)
    if need is None:
        return None
    u = _auth_user(self)
    if u is None:
        return (401, {"error": "unauthorized"})
    if u["owner"]:
        return None
    if any(u["perms"].get(k) for k in need):
        return None
    return (403, {"error": "недостаточно прав", "need": need[0]})


# ---------- telemt / telegram proxy ----------


# ---------- node `federation`: входящий API (/api/ext/*) ----------

_EXT_SCOPES = ("read", "write")
_EXT_HITS = {}
_EXT_LOCK = threading.Lock()

def _node_tokens():
    toks = CFG_CACHE.get("node_tokens")
    return toks if isinstance(toks, list) else []

def _save_node_tokens(toks):
    CFG_CACHE["node_tokens"] = toks
    _cfg_save()

def _ext_rate_ok(ip):
    now = time.time()
    with _EXT_LOCK:
        q = [t for t in (_EXT_HITS.get(ip) or []) if now - t < 10]
        if len(q) >= 30:
            _EXT_HITS[ip] = q
            return False
        q.append(now)
        _EXT_HITS[ip] = q
        if len(_EXT_HITS) > 512:
            for k in [k for k, v in _EXT_HITS.items() if not v or now - max(v) > 60]:
                _EXT_HITS.pop(k, None)
    return True

def _ext_auth(self, need_write=False):
    """Auth /api/ext/* по Bearer/X-Node-Token. Возвращает dict токена или None (ответ отправлен)."""
    ip = self.client_address[0] if getattr(self, "client_address", None) else "?"
    if not _ext_rate_ok(ip):
        _audit("ext_rate_limit", ip=ip)
        self._send(429, {"error": "слишком много запросов"})
        return None
    auth = self.headers.get("Authorization", "") or ""
    tok = auth[7:].strip() if auth.startswith("Bearer ") else (self.headers.get("X-Node-Token") or "").strip()
    if not tok or len(tok) > 128:
        self._send(401, {"error": "unauthorized"})
        return None
    given = hashlib.sha256(tok.encode()).hexdigest()
    match = None
    for t in _node_tokens():
        h = t.get("hash") or ""
        if isinstance(h, str) and h and secrets.compare_digest(given, h):
            match = t
            break
    if not match:
        _audit("ext_denied", ip=ip, token_hint=(given[:12] or None))
        self._send(401, {"error": "unauthorized"})
        return None
    if need_write and "write" not in (match.get("scopes") or []):
        self._send(403, {"error": "токен только для чтения"})
        return None
    now = int(time.time())
    if now - int(match.get("last_used") or 0) > 300:
        match["last_used"] = now
        _save_node_tokens(_node_tokens())
    return match

def _ext_owned_group(st, tid, u):
    return [c for proto, inb in (st.get("inbounds") or {}).items()
            for c in inb.get("clients", []) if c.get("uuid") == u and c.get("ext_owner") == tid]

# ---------- node `federation`: исходящий вызов мастер→нода ----------

def _node_host_ok(node):
    """SSRF-guard для федерации нод: хост ноды задаёт оператор, и по нему мастер
    ходит HTTPS (а при диагностике — ещё и HTTP) и пересылает Bearer-токен.
    Прячем самые опасные направления: loopback (метаданные облачной сети, панель
    на своём 8443) и link-local/metadata 169.254/16. Приватные RFC1918-ноды
    (домашняя/внутренняя сеть) — легитимны, их не режем. Хост резолвится; если это
    уже IP — проверяется напрямую. None, если адрес запрещён."""
    import ipaddress
    host = (node.get("host") or "").strip()
    if not host:
        return None
    try:
        infos = socket.getaddrinfo(host, None)
    except Exception:
        # резолв не прошёл — не блокируем: проверку сделает сам коннект
        return host
    for _fam, _t, _p, _c, sa in infos:
        try:
            ip = ipaddress.ip_address(sa[0])
        except Exception:
            continue
        if ip.is_loopback or ip.is_link_local or (ip.version == 4 and ip in ipaddress.IPv4Network("169.254.169.254/32")):
            return None
    return host

# Кому панель верит в X-Forwarded-For. По умолчанию — только петля: собственного
# фронта у панели нет, она отдаётся наружу на прямом :8443, и всё, что приходит не
# с петли, пришло от клиента напрямую.
# RFC1918 в список по умолчанию не входит (#89): в 10.0.0.0/8 лежат туннельные сети
# самих подписчиков (здесь 10.10.0.0/24 и 10.20.0.0/24), а их трафик делает круг
# через этот же сервер — подписчик приходит на :8443 с адресом из «доверенной»
# сети и до правки вписывал себе в устройства любой IP заголовком. Свой фронт
# (nginx на петле, отдельный прокси-хост, туннель) оператор называет явно списком
# `trusted_proxy_cidrs` в config.json.
_TRUSTED_PROXY_NETS = (ipaddress.ip_network("127.0.0.0/8"), ipaddress.ip_network("::1/128"))
_TRUSTED_NETS_CACHE = [None, _TRUSTED_PROXY_NETS]

def _trusted_proxy_nets():
    """Сети фронтов из `trusted_proxy_cidrs`, разобранные один раз на значение.
    Мусорную строку не чиним и не расширяем доверие молча: не разобралось —
    значит сети нет. Сплошное 0.0.0.0/0 (::/0) тоже не принимаем: это не фронт,
    а отмена проверки — тот самый класс, который здесь закрывается."""
    raw = CFG_CACHE.get("trusted_proxy_cidrs") or []
    if isinstance(raw, str):
        raw = [raw]
    if not isinstance(raw, (list, tuple)):
        raw = []
    key = repr([str(x) for x in raw])
    if _TRUSTED_NETS_CACHE[0] != key:
        nets = list(_TRUSTED_PROXY_NETS)
        for item in raw:
            s = str(item or "").strip()
            if not s:
                continue
            try:
                n = ipaddress.ip_network(s, strict=False)
            except Exception:
                continue
            if n.prefixlen == 0:
                continue
            nets.append(n)
        _TRUSTED_NETS_CACHE[0] = key
        _TRUSTED_NETS_CACHE[1] = tuple(nets)
    return _TRUSTED_NETS_CACHE[1]

def _req_client_ip(self):
    """Адрес, который пишем в журнал «устройства подписки». X-Forwarded-For
    слушаем ТОЛЬКО когда соединение пришло от названного фронта (петля или явно
    перечисленная сеть) И заголовок разбирается как адрес. Иначе — настоящего
    пира: без этой оговорки подписчик вписывает себе в устройство любой IP, а
    владелец видит ровно то, что клиент сам напечатал в заголовке. Возвращаем
    нормализованный литерал, а не исходную строку: в файл не уезжает ни
    «unknown», ни хвост от цепочки, ни то, что не является адресом."""
    try:
        peer = str((self.client_address or [""])[0] or "")
    except Exception:
        peer = ""
    xff = (self.headers.get("X-Forwarded-For") or "").split(",")[0].strip()[:64]
    if xff and peer:
        try:
            ip = ipaddress.ip_address(peer)
            mapped = getattr(ip, "ipv4_mapped", None)
            if mapped is not None:
                ip = mapped
            xip = ipaddress.ip_address(xff)
        except ValueError:
            return peer
        if any(ip in n for n in _trusted_proxy_nets()):
            return str(xip)
    return peer or "?"

def _dial_addr_ok(host):
    """Один ответ для всех мест, где панель САМА идёт по адресу, который вписал
    оператор: нода, фронт, SSH-бустрап. Loopback и link-local/metadata облачной
    сети запрещены, приватные RFC1918 легитимны (домашний/внутренний сервер).
    Тот же guard, что стоит в _node_call на federation-пути; раньше он был только
    там, и обходными дверями оставались /api/nodes/bootstrap (панель уходила
    ssh root@127.0.0.1) и hop-фронт (проба портов с бэка в 127.0.0.1:*, 169.254.*)."""
    return _node_host_ok({"host": (host or "").strip()}) is not None

def _node_port(node):
    """Порт ноды с числом по умолчанию: приводим к int, мусор/вне-диапазона → 8443,
    чтобы int() на дисковых данных не ронял обработчик."""
    try:
        p = int(node.get("port") or 8443)
    except (TypeError, ValueError):
        return 8443
    return p if 1 <= p <= 65535 else 8443

def _node_call(node, path, body=None, timeout=8, need_token=True):
    """HTTPS-запрос к Node API ноды. (data, err, fp): fp — sha256 дерта сертификата.
    Pin-нинг: если у ноды задан `pin`, чужой сертификат отсекается до отправки токена."""
    import http.client
    host = (node.get("host") or "").strip()
    port = _node_port(node)
    if not host:
        return None, "нода без адреса", ""
    if _node_host_ok(node) is None:
        return None, "адрес ноды запрещён (loopback/metadata)", ""
    token = (node.get("token") or "").strip()
    if need_token and not token:
        return None, "у ноды не задан токен", ""
    ctx = ssl._create_unverified_context()
    conn = http.client.HTTPSConnection(host, port, timeout=timeout, context=ctx)
    try:
        conn.connect()
        der = conn.sock.getpeercert(True)
        fp = hashlib.sha256(der).hexdigest() if der else ""
        pin = (node.get("pin") or "").strip().lower()
        if pin and fp and pin != fp:
            return None, "сертификат ноды не совпадает с закреплённым отпечатком (возможен MITM)", fp
        hdrs = {"Authorization": f"Bearer {token}", "User-Agent": f"VeilPanel/{VERSION}"}
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            hdrs["Content-Type"] = "application/json"
        conn.request("POST" if body is not None else "GET", path, body=data, headers=hdrs)
        r = conn.getresponse()
        raw = r.read()
        if r.status >= 400:
            try:
                msg = json.loads(raw or b"{}").get("error")
            except Exception:
                msg = None
            return None, (msg or f"HTTP {r.status}"), fp
        return (json.loads(raw or b"{}"), None, fp)
    except Exception as e:
        return None, str(e)[:200], ""
    finally:
        try:
            conn.close()
        except Exception:
            pass

def _veil_plain_http_hint(node):
    """Диагностика «нода офлайн» для veil-нод: если HTTPS-рукопожатие упало, проверим,
    не отвечает ли этот порт обычным HTTP. Это типично для свежей панели без сертификата —
    Node API намеренно требует HTTPS, токен не поедет в открытом виде. Возвращаем
    подсказку или None. Сам транспорт это не ослабляет: связь с нодой по-прежнему только HTTPS."""
    import http.client
    host = (node.get("host") or "").strip()
    port = _node_port(node)
    if not host or _node_host_ok(node) is None:
        return None
    try:
        c = http.client.HTTPConnection(host, port, timeout=6)
        c.request("GET", "/api/version", headers={"User-Agent": f"VeilPanel/{VERSION}"})
        r = c.getresponse(); raw = r.read(); c.close()
    except Exception:
        return None
    try:
        j = json.loads(raw or b"null")
    except Exception:
        j = None
    if isinstance(j, dict):
        return ("нода отвечает по HTTP, а Node API требует HTTPS (шифрование токена). "
                "Выпустите сертификат на панели-ноде: вкладка «Сайт» → Let's Encrypt, "
                "затем переподключите ноду.")
    return None

def _veil_nodes(nodes=None):
    nodes = nodes if nodes is not None else get_nodes()
    return [n for n in (nodes or []) if (n.get("type") or "agent") == "veil"]

def _agent_nodes(nodes=None):
    nodes = nodes if nodes is not None else get_nodes()
    return [n for n in (nodes or []) if (n.get("type") or "agent") == "agent"]

EXT_CAPS = ["clients_add", "clients_update", "clients_delete", "traffic", "restart"]

def _node_restart(n):
    """Перезапуск ядра на ноде: veil -> /api/ext/restart, agent -> apply restart. Возвращает err или None."""
    if (n.get("type") or "agent") == "veil":
        _d, err, _fp = _node_call(n, "/api/ext/restart", {}, timeout=15)
    else:
        _d, err, _fp = _node_call(n, "/agent/apply", {"action": "restart"}, timeout=25)
    return err

def _nodes_public():
    return [{k: v for k, v in n.items() if k != "token"} for n in get_nodes()]

def _node_poll_one(n):
    """Один опрос ноды (veil или agent): online/pin/кэш статуса. Меняет n на месте."""
    if (n.get("type") or "agent") == "veil":
        data, err, fp = _node_call(n, "/api/ext/status")
        if data is not None:
            n["online"] = True
            n["err"] = None
            n["remote_version"] = data.get("version")
            n["node_clients"] = data.get("clients")
            n["node_online"] = data.get("online")
            n["node_xray"] = data.get("xray")
            n["status_cache"] = {"inbounds": data.get("inbounds") or [],
                                 "at": int(time.time())}
            n["node_caps"] = data.get("caps") or []
        else:
            n["online"] = False
            e = (err or "")
            if ("SSL" in e or "record layer" in e.lower() or "handshake" in e.lower()
                    or "wrong version" in e.lower() or "decrypt" in e.lower()
                    or "tlsv" in e.lower() or "eof occurred" in e.lower()):
                n["err"] = _veil_plain_http_hint(n) or err
            else:
                n["err"] = err
    else:
        data, err, fp = _node_call(n, "/agent/status")
        if data is None:
            n["online"] = False
            n["err"] = err
            n["last_check"] = int(time.time())
            if fp and not (n.get("pin") or "").strip():
                n["pin"] = fp
            return
        n["online"] = True
        n["err"] = None
        n["remote_version"] = data.get("version")
        n["node_clients"] = data.get("clients")
        n["node_xray"] = data.get("xray")
        n["node_caps"] = data.get("caps") or []
        hd, herr, hfp = _node_call(n, "/agent/hello", need_token=False)
        if hd and hd.get("public_key"):
            hd["at"] = int(time.time())
            n["agent_params"] = hd
        elif not (n.get("agent_params") or {}):
            n["err"] = herr or "нода не вернула параметры"
    if not (n.get("pin") or "").strip() and fp:
        n["pin"] = fp  # TOFU: фиксируем при первом успешном контакте
    n["last_check"] = int(time.time())

def _nodes_poll_loop():
    import traceback
    while True:
        try:
            nodes = get_nodes()
            if nodes:
                observed = {}
                for n in nodes:
                    _node_poll_one(n)
                    observed[n.get("host") or ""] = {k: n.get(k) for k in _NODE_OBSERVED
                                                     if k in n}
                _nodes_merge_observed(observed)
        except Exception:
            try:
                with open(f"{BASE}/logs/panel.err", "a") as f:
                    f.write("nodes_poll: " + traceback.format_exc() + "\n")
            except Exception:
                pass
        time.sleep(45)

# ========== АВТОПОДКЛЮЧЕНИЕ НОДЫ ПО SSH (бустрап) ==========
# Пароль SSH используется однократно (через SSH_ASKPASS, только в env процесса),
# нигде не сохраняется и не пишется в логи; дальше — ed25519-ключ панели.

NODE_KEYS_DIR = f"{BASE}/node_keys"
BOOT_JOBS = {}
BOOT_LOCK = threading.Lock()

def _boot_host_key(host):
    os.makedirs(NODE_KEYS_DIR, 0o700, exist_ok=True)
    slug = hashlib.sha1(host.encode()).hexdigest()[:16]
    base = f"{NODE_KEYS_DIR}/{slug}"
    if not os.path.exists(base):
        subprocess.run(["ssh-keygen", "-t", "ed25519", "-N", "",
                        "-C", f"veil-panel@{socket.gethostname()}", "-f", base, "-q"],
                       capture_output=True, timeout=30)
    try:
        os.chmod(base, 0o600)
    except Exception:
        pass
    return base, base + ".pub"

def _ssh_opts(keyfile):
    return ["-o", f"UserKnownHostsFile={NODE_KEYS_DIR}/known_hosts",
            "-o", "StrictHostKeyChecking=accept-new",
            "-o", f"IdentityFile={keyfile}", "-o", "IdentitiesOnly=yes",
            "-o", "ConnectTimeout=10", "-o", "ServerAliveInterval=15"]

_SSH_USER_RE = re.compile(r"[A-Za-z0-9_][A-Za-z0-9._-]{0,63}")
_SSH_HOST_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,252}")

def _ssh_target_ok(user, host):
    # «-» в начале уехал бы в getopt ssh как опция (-oProxyCommand=...) = RCE на бэке
    return bool(_SSH_USER_RE.fullmatch(user or "") and _SSH_HOST_RE.fullmatch(host or ""))

def _scrub(text, *secrets):
    """Вычёркивает из текста наружу то, что панель сама считает секретом.

    У SSH-воркеров есть свойство: stdin — это «пароль + скрипт», и если sudo не
    спросил пароль (кэш timestamp или NOPASSWD), bash исполняет первую строку как
    команду и печатает её в stderr. Так пароль фронта попадает в steps[].detail,
    job["error"] и audit.json. Панель не отдаёт наружу ни одно значение, которое
    она сама держит как credential, — даже в обрезанном виде."""
    if not isinstance(text, str) or not text:
        return text
    out = text
    # длинные вперёд: короткий секрет не должен уцелеть внутри длинного
    for s in sorted({x for x in secrets if isinstance(x, str) and len(x) >= 4},
                    key=len, reverse=True):
        if s in out:
            out = out.replace(s, "[скрыто]")
    return out

def _boot_askpass_sweep(keep_seconds=600):
    """Убрать заглушки за убитыми прогонами. Живёт ровно время запуска `ssh`; процесс,
    у которого отняли жизнь по бюджету, удалить её не может. На этой коробке замерено
    `94` таких файла и `0` держателей. Свой файл свежее границы, поэтому не чинится."""
    gone = 0
    try:
        now = time.time()
        with os.scandir(tempfile.gettempdir()) as it:
            for e in it:
                if not e.name.startswith(".vpw"):
                    continue
                try:
                    if e.is_file(follow_symlinks=False) and now - e.stat().st_mtime > keep_seconds:
                        os.unlink(e.path)
                        gone += 1
                except OSError:
                    pass
    except OSError:
        pass
    return gone

def _boot_askpass_run(password, argv, timeout=60):
    """Запуск ssh/ssh-copy-id с вводом пароля через SSH_ASKPASS (пароль — только в env)."""
    fd, script = tempfile.mkstemp(prefix=".vpw")
    try:
        os.write(fd, b"#!/bin/sh\nprintf '%s\\n' \"$VP_SSH_PASS\"\n")
    finally:
        os.close(fd)
    os.chmod(script, 0o700)
    _boot_askpass_sweep()
    env = dict(os.environ)
    env.update(VP_SSH_PASS=password, SSH_ASKPASS=script, SSH_ASKPASS_REQUIRE="force",
               TMPDIR=os.path.dirname(script))
    env.pop("SSH_ASKPASS_DELAY", None)
    try:
        return subprocess.run(argv, capture_output=True, timeout=timeout, env=env,
                              stdin=subprocess.DEVNULL)
    finally:
        try:
            os.unlink(script)
        except Exception:
            pass

def _boot_new_job(params):
    jid = uuidlib.uuid4().hex[:12]
    steps = ["Подключение по SSH", "Права root", "Xray", "Файлы агента",
             "Конфиг и порты", "Служба veil-agent", "Файрвол",
             "Токен ноды", "Регистрация"]
    job = {"id": jid,
           "steps": [{"name": s, "state": "pending", "detail": ""} for s in steps],
           "done": False, "ok": False, "error": None,
           "created": int(time.time()), "params": params}
    with BOOT_LOCK:
        BOOT_JOBS[jid] = job
        if len(BOOT_JOBS) > 50:
            # Держим ~40 свежих. Из старых убираем завершённые, а зависшие (поток
            # worker мог так и не стартовать — тогда «done» не выставится никогда) —
            # по предельному возрасту: иначе словарь рос бы бесконечно и хранил
            # SSH-пароли незавершённых задач.
            now = int(time.time())
            old = sorted(BOOT_JOBS, key=lambda k: BOOT_JOBS[k]["created"])[:-40]
            for k in [x for x in old
                      if BOOT_JOBS[x]["done"] or now - BOOT_JOBS[x]["created"] > 1800]:
                BOOT_JOBS.pop(k, None)
            if len(BOOT_JOBS) > 200:
                for k in sorted(BOOT_JOBS, key=lambda k: BOOT_JOBS[k]["created"])[:-40]:
                    BOOT_JOBS.pop(k, None)
    return jid

def _boot_step(jid, idx, state, detail=""):
    with BOOT_LOCK:
        job = BOOT_JOBS.get(jid)
        if job:
            job["steps"][idx]["state"] = state
            if detail:
                job["steps"][idx]["detail"] = str(detail)[:300]

def _node_bootstrap_worker(jid):
    import traceback, shlex
    with BOOT_LOCK:
        job = BOOT_JOBS.get(jid) or {}
        prm = dict(job.get("params") or {})
    host = prm.get("host")
    sport = int(prm.get("ssh_port") or 22)
    user = prm.get("user") or "root"
    password = prm.get("password") or ""
    name = prm.get("name") or "Veil node"
    sni = prm.get("sni") or "www.samsung.com"

    def st(i, s, d=""):
        _boot_step(jid, i, s, _scrub(d, password))

    def finish(ok, err=None):
        with BOOT_LOCK:
            job["done"] = True
            job["ok"] = ok
            job["error"] = _scrub(err, password)
            jp = job.get("params") or {}
            jp["password"] = ""

    def fail(i, msg):
        st(i, "failed", msg)
        finish(False, msg)
        try:
            _audit("node_bootstrap_fail", host=host, step=i,
                   error=_scrub(str(msg)[:200], password))
        except Exception:
            pass

    try:
        # --- 0. SSH-доступ: своим ключом, при отказе — пароль однократно + ssh-copy-id
        if not _ssh_target_ok(user, host):
            return fail(0, "недопустимые SSH-логин или адрес")
        try:
            own = _pub_ip4() or ""
        except Exception:
            own = ""
        if own and host == own:
            # «внешняя нода», оказавшаяся этим же хостом: агент встанет на панель,
            # его xray столкнётся с живым xray и подписчики упадут. Тот же случай,
            # что и «переехать в себя» в _mv_plan, поэтому и ответ тот же.
            return fail(0, "это адрес текущего хоста — подключить панель к самой себе нельзя")
        st(0, "running")
        keyfile, pubkey = _boot_host_key(host)
        base = ["/usr/bin/ssh", "-p", str(sport)] + _ssh_opts(keyfile)
        target = f"{user}@{host}"

        def key_run(cmd, timeout=60, input=None, text=True):
            return subprocess.run(base + [target, cmd], capture_output=True, text=text,
                                  timeout=timeout, input=input,
                                  stdin=subprocess.DEVNULL if input is None else None)

        try:
            r = key_run("true", timeout=20)
            ok_key = r.returncode == 0
        except Exception:
            ok_key = False
        if not ok_key:
            if not password:
                return fail(0, "нет доступа по ключу панели, а пароль не задан")
            r = _boot_askpass_run(password, base + [target, "echo VPOK"], timeout=45)
            if r.returncode != 0 or b"VPOK" not in (r.stdout or b""):
                etxt = (r.stderr or b"").decode("utf-8", "ignore")
                if "denied" in etxt.lower() or "permission" in etxt.lower():
                    etxt = "SSH отклонил логин/пароль"
                return fail(0, etxt[:200])
            # ssh-copy-id в OpenSSH 10.2 сломан (литерал ~ в `mktemp`) — ставим ключ напрямую
            try:
                pubtxt = open(pubkey).read().strip()
            except Exception:
                pubtxt = ""
            pubtxt = pubtxt.replace("'", "'\\''")
            if not pubtxt:
                return fail(0, "не читается публичный ключ панели")
            r = _boot_askpass_run(password, base + [target,
                                  "umask 077; mkdir -p ~/.ssh; touch ~/.ssh/authorized_keys; "
                                  "grep -qxF '%s' ~/.ssh/authorized_keys || printf '%%s\\n' '%s' "
                                  ">> ~/.ssh/authorized_keys" % (pubtxt, pubtxt)],
                                  timeout=45)
            if r.returncode != 0:
                return fail(0, "установка ключа: " + (r.stderr or b"").decode("utf-8", "ignore")[:200])
            try:
                ok_key = key_run("true", timeout=20).returncode == 0
            except Exception:
                ok_key = False
            if not ok_key:
                return fail(0, "ключ панели не принимается после установки")
        st(0, "done", "вход по ключу панели")

        # --- 1. root/sudo
        st(1, "running")
        r = key_run('u=$(id -u); p=$(command -v sudo || true); py=$(command -v python3 || true); '
                    'if [ "$u" = 0 ]; then m=root; elif [ -n "$p" ] && sudo -n true 2>/dev/null; '
                    'then m=sudo_n; elif [ -n "$p" ]; then m=s_s; else m=none; fi; '
                    'echo "$m $(uname -m) ${py:-nopy}"', timeout=30)
        if r.returncode != 0:
            return fail(1, "SSH-команда не прошла: " + (r.stderr or r.stdout or "")[:150])
        parts = (r.stdout or "").split()
        mode = parts[0] if parts else "none"
        arch = parts[1] if len(parts) > 1 else "?"
        haspy = len(parts) > 2 and parts[2] != "nopy"
        if mode == "s_s":
            try:
                if key_run("sudo -k -S -p '' true", timeout=30,
                           input=password.rstrip("\n") + "\n").returncode == 0:
                    mode = "sudo_s"
            except Exception:
                pass
        if mode not in ("root", "sudo_n", "sudo_s"):
            return fail(1, "нужны root или sudo (парольный или без пароля)")
        if not haspy:
            return fail(1, "на ноде нет python3 — агент не запустится")
        st(1, "done", {"root": "root", "sudo_n": "sudo без пароля",
                       "sudo_s": "sudo с паролем"}[mode])

        def rscript(script, args=(), timeout=180):
            shell = "bash -euo pipefail -s --"
            if mode == "sudo_n":
                shell = "sudo -n bash -euo pipefail -s --"
            elif mode == "sudo_s":
                script = password.rstrip("\n") + "\n" + script
                shell = "sudo -k -S -p '' bash -euo pipefail -s --"
            return subprocess.run(base + [target, shell] + [shlex.quote(str(a)) for a in args],
                                  capture_output=True, text=True, timeout=timeout, input=script)

        def rput(local_path, remote_tmp, timeout=600):
            with open(local_path, "rb") as f:
                return subprocess.run(base + [target, f"cat > {shlex.quote(remote_tmp)}"],
                                      stdin=f, capture_output=True, timeout=timeout)

        # --- 2. xray
        st(2, "running")
        r = rscript('command -v xray >/dev/null 2>&1 || [ -x /usr/local/bin/xray ] '
                    '&& echo have || echo need')
        if r.returncode != 0:
            return fail(2, (r.stderr or "")[:200])
        if "have" in (r.stdout or ""):
            st(2, "done", "xray уже есть")
        else:
            local_xray = shutil.which("xray") or (XRAY_BIN if os.path.exists(XRAY_BIN) else None)
            try:
                larch = socket.uname().machine
            except Exception:
                larch = ""
            if arch == "x86_64" and larch == "x86_64" and local_xray:
                if rput(local_xray, f"/tmp/.veil_xray_{jid}").returncode != 0:
                    return fail(2, "не удалось передать бинарник xray")
                r = rscript(f'install -m 0755 /tmp/.veil_xray_{jid} /usr/local/bin/xray '
                            f'&& rm -f /tmp/.veil_xray_{jid} && /usr/local/bin/xray version | head -1')
                if r.returncode != 0:
                    return fail(2, "установка локального xray: " + (r.stderr or "")[:150])
                st(2, "done", "скопирован xray с панели")
            else:
                r = rscript('curl -fsSL https://github.com/XTLS/Xray-install/raw/main/scripts/install-release.sh '
                            '-o /tmp/.veil_xi.sh || wget -qO /tmp/.veil_xi.sh '
                            'https://github.com/XTLS/Xray-install/raw/main/scripts/install-release.sh; '
                            'bash /tmp/.veil_xi.sh install >/dev/null 2>&1; rm -f /tmp/.veil_xi.sh; '
                            'xray version | head -1', timeout=300)
                if r.returncode != 0 or "Xray" not in (r.stdout or ""):
                    return fail(2, "не удалось установить xray (на ноде нужен интернет и curl/wget)")
                st(2, "done", "установлен xray из официального репозитория")

        # --- 3. файлы агента
        st(3, "running")
        agent_src = f"{BASE}/agent.py"
        if not os.path.exists(agent_src):
            return fail(3, "в каталоге панели нет agent.py")
        if rput(agent_src, f"/tmp/.veil_agent_{jid}", timeout=120).returncode != 0:
            return fail(3, "передача agent.py не удалась")
        r = rscript(f'mkdir -p /opt/veil-agent && install -m 0644 /tmp/.veil_agent_{jid} '
                    f'/opt/veil-agent/agent.py && rm -f /tmp/.veil_agent_{jid}')
        if r.returncode != 0:
            return fail(3, (r.stderr or "")[:200])
        st(3, "done", "/opt/veil-agent/agent.py")

        # --- 4. конфиг: свободные порты, имена
        st(4, "running")
        r = rscript('''set -e
freep() { for p in "$@"; do ss -H -ltnu 2>/dev/null | awk '{print $5}' | sed 's/.*://' | grep -qx "$p" || { echo "$p"; return 0; }; done; return 1; }
API=$(freep 9444 9445 19444 29444) || exit 21
XP=$(freep 8444 8445 14444 24444) || exit 22
SP=$(freep 10090 10091 10099 10199) || exit 23
XB=$(command -v xray || echo /usr/local/bin/xray)
python3 -c 'import json,sys; json.dump({"api_port": int(sys.argv[1]), "xport": int(sys.argv[2]), "stats_port": int(sys.argv[3]), "xray_bin": sys.argv[4], "name": sys.argv[5], "sni": sys.argv[6]}, open("/opt/veil-agent/agent.conf.json", "w"), ensure_ascii=False, indent=2)' "$API" "$XP" "$SP" "$XB" "$1" "$2"
echo "$API $XP $SP"
''', args=(name, sni), timeout=60)
        if r.returncode != 0:
            return fail(4, "конфиг не записан" +
                        (" (все кандидаты портов заняты)" if r.returncode in (21, 22, 23) else
                         ": " + (r.stderr or "")[:150]))
        try:
            api_port, x_port, sp_port = (r.stdout or "").split()[:3]
            api_port, x_port, sp_port = int(api_port), int(x_port), int(sp_port)
        except Exception:
            return fail(4, "не разобраны порты из конфига: " + (r.stdout or "")[:80])
        st(4, "done", f"API {api_port}, вход {x_port}")

        # --- 5. systemd-юнит
        st(5, "running")
        r = rscript('''set -e
cat > /etc/systemd/system/veil-agent.service <<'EOS'
[Unit]
Description=Veil node agent
After=network-online.target

[Service]
WorkingDirectory=/opt/veil-agent
ExecStart=/usr/bin/env python3 /opt/veil-agent/agent.py
Restart=always
RestartSec=5
StartLimitIntervalSec=0

[Install]
WantedBy=multi-user.target
EOS
systemctl daemon-reload
systemctl enable veil-agent >/dev/null 2>&1 || true
systemctl restart veil-agent
sleep 2
systemctl is-active veil-agent
''', timeout=90)
        if r.returncode != 0 or "active" not in (r.stdout or ""):
            return fail(5, "служба не запустилась: " + ((r.stderr or "") + (r.stdout or ""))[:200])
        st(5, "done", "veil-agent: active")

        # --- 6. файрвол (best-effort)
        st(6, "running")
        r = rscript(f'''ok=""
if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
  ufw allow {x_port}/tcp >/dev/null 2>&1 && ok=ufw
  ufw allow {api_port}/tcp >/dev/null 2>&1 || true
fi
if command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
  firewall-cmd --permanent --add-port={x_port}/tcp >/dev/null 2>&1 || true
  firewall-cmd --permanent --add-port={api_port}/tcp >/dev/null 2>&1 || true
  firewall-cmd --reload >/dev/null 2>&1 && ok="firewalld $ok"
fi
echo "${{ok:-не активно}}"
''', timeout=60)
        st(6, "done", ("открыты порты: " + (r.stdout or "").strip()) if r.returncode == 0
           else "файрвол не трогали (best-effort)")

        # --- 7. токен агента
        st(7, "running")
        r = rscript("cd /opt/veil-agent && python3 agent.py --token", timeout=60)
        token = ((r.stdout or "").strip().splitlines() or [""])[-1].strip()
        if r.returncode != 0 or not (30 <= len(token) <= 80) or not re.fullmatch(r"[A-Za-z0-9_\-]+", token):
            return fail(7, "не удалось прочитать токен агента: " + (r.stderr or "")[:150])
        st(7, "done", "получен")

        # --- 8. регистрация ноды + TOFU
        st(8, "running")
        nodes = get_nodes()
        entry = next((n for n in nodes
                      if (n.get("host") or "").strip().lower() == host.lower()), None)
        if entry is None:
            entry = {"added": int(time.time())}
            nodes.append(entry)
        entry.update({"name": name, "host": host, "port": api_port, "type": "agent",
                      "token": token, "online": False,
                      "ssh_user": user, "ssh_port": sport, "ssh_key": keyfile,
                      "ssh_sudo": mode})
        save_nodes(nodes)
        deadline = time.time() + 25
        while time.time() < deadline:
            _node_poll_one(entry)
            if entry.get("online"):
                break
            time.sleep(2)
        # до этого места мы крутили запись 25 секунд — за это время список на
        # диске мог измениться чужой рукой, поэтому возврат всего снимка сюда
        # не годится: накладываем только свои измерения
        _nodes_merge_observed({host: {k: entry.get(k) for k in _NODE_OBSERVED if k in entry}})
        if entry.get("online"):
            st(8, "done", f"нода онлайн, отпечаток {str(entry.get('pin') or '')[:12]}… закреплён")
        else:
            st(8, "done", "нода добавлена, API ещё не отвечает — слежение включено")
        finish(True)
        _audit("node_bootstrap", host=host, name=name, api_port=api_port, x_port=x_port)
    except subprocess.TimeoutExpired:
        with BOOT_LOCK:
            cur = next((s["name"] for s in job["steps"] if s["state"] == "running"), "?")
        finish(False, f"таймаут на шаге «{cur}»")
    except Exception:
        try:
            with open(f"{BASE}/logs/panel.err", "a") as f:
                f.write("node_bootstrap: " + traceback.format_exc() + "\n")
        except Exception:
            pass
        with BOOT_LOCK:
            cur = next((s["name"] for s in job["steps"] if s["state"] == "running"), "?")
        finish(False, f"сбой на шаге «{cur}» (см. logs/panel.err)")

def _node_expiry_days(c):
    ex = _ts_of(c.get("expiry"))
    if ex <= 0:
        return 0
    return max(0, -(-(ex - int(time.time())) // 86400))

def _client_node_entries(st, u):
    ents = {}
    for proto, inb in (st.get("inbounds") or {}).items():
        for c in inb.get("clients", []):
            if c.get("uuid") == u:
                for h, e in (c.get("nodes") or {}).items():
                    ents[h] = e
    return ents

def _agent_link(n, ap, u, c0):
    """vless+reality ссылка на агента-ноду из параметров /agent/hello."""
    host = (n.get("host") or "").strip()
    qparts = {"type": "tcp", "security": "reality",
              "pbk": ap.get("public_key") or "",
              "fp": ap.get("fp") or "firefox",
              "sni": ap.get("sni") or "", "sid": ap.get("sid") or "",
              "spx": "/", "flow": "xtls-rprx-vision"}
    q = urllib.parse.urlencode(qparts)
    name = f"{c0.get('name') or 'Veil'} · {n.get('name') or host}"
    return f"vless://{u}@{host}:{int(ap.get('port') or 443)}?{q}#{urllib.parse.quote(name)}"

# Порядок предпочтения протокола при размещении клиента на ноде:
# берём первый протокол клиента, который нода реально поддерживает.
_NODE_PROTO_PRIORITY = ("reality", "vless-xhttp-reality", "hysteria2",
                        "vless-xhttp-tls", "vless-ws-tls", "vless-tcp-tls", "vless-grpc-tls", "vless-ws",
                        "trojan-tcp-tls", "trojan-ws-tls", "trojan-grpc-tls",
                        "vmess-ws-tls", "vmess-tcp-tls", "vmess-ws",
                        "shadowsocks", "wireguard", "amneziawg")

def _deploy_client_to_nodes(st, u):
    """Разместить клиента u на всех онлайн-нодах (Veil API и агент). (`deployed`, skipped)."""
    deployed, skipped = [], []
    recs = [(proto, inb, c) for proto, inb in (st.get("inbounds") or {}).items()
            for c in inb.get("clients", []) if c.get("uuid") == u]
    if not recs:
        return deployed, [{"host": "-", "reason": "клиент не найден"}]
    by_proto = {proto: (proto, inb, c) for proto, inb, c in recs}
    nodes = get_nodes()
    for n in nodes:
        host = (n.get("host") or "").strip()
        is_agent = (n.get("type") or "agent") == "agent"
        if not n.get("online"):
            skipped.append({"host": host, "reason": "офлайн"})
            continue
        if any((c.get("nodes") or {}).get(host) for _, _, c in recs):
            skipped.append({"host": host, "reason": "уже размещён"})
            continue
        if is_agent:
            # агент поднимает только VLESS+Reality — ищем именно его среди протоколов клиента
            rec = by_proto.get("reality")
            if not rec:
                skipped.append({"host": host,
                                "reason": "у клиента нет VLESS+Reality — агент поддерживает только его"})
                continue
            dep, sk = _deploy_client_to_agent(n, host, recs, rec, u)
        else:
            dep, sk = _deploy_client_to_veil(n, host, recs, by_proto, u)
        deployed.extend(dep)
        skipped.extend(sk)
    if deployed:
        _save(STATE, st)
        # из записей нод мы здесь поменяли только status_cache/agent_params, а
        # между чтением списка и этим местом ушло время на сетевые вызовы
        _nodes_merge_observed({(n.get("host") or ""):
                               {k: n[k] for k in _NODE_OBSERVED if k in n} for n in nodes})
    return deployed, skipped

def _deploy_client_to_veil(n, host, recs, by_proto, u):
    deployed, skipped = [], []
    sc = n.get("status_cache") or {}
    inbs = sc.get("inbounds") or []
    if time.time() - int(sc.get("at") or 0) > 120:
        data, err, _ = _node_call(n, "/api/ext/inbounds")
        if data is None:
            return deployed, [{"host": host, "reason": err or "нет ответа"}]
        inbs = data.get("inbounds") or []
        n["status_cache"] = {"inbounds": inbs, "at": int(time.time())}
    node_protos = {i.get("proto") for i in inbs}
    proto_local = next((p for p in _NODE_PROTO_PRIORITY
                        if p in by_proto and p in node_protos), None)
    if proto_local is None:
        common = [p for p in by_proto if p in node_protos]
        proto_local = common[0] if common else None
    if proto_local is None:
        return deployed, [{"host": host, "reason": "нет общего поддерживаемого протокола с нодой"}]
    c0 = by_proto[proto_local][2]
    body = {"name": c0.get("name") or "без имени", "proto": proto_local,
            "limit_gb": _gb_of(c0.get("limit_gb"))}
    ed = _node_expiry_days(c0)
    if ed:
        body["expiry_days"] = ed
    if c0.get("reset_cycle"):
        body["reset_cycle"] = c0["reset_cycle"]
    if _cnt_of(c0.get("max_devices")) > 0:
        body["max_devices"] = _cnt_of(c0["max_devices"])
    data, err, _ = _node_call(n, "/api/ext/clients", body)
    nc = (data or {}).get("client") or {}
    if data is None or not nc.get("uuid"):
        return deployed, [{"host": host, "reason": err or "ошибка ноды"}]
    for _, _, c in recs:
        c.setdefault("nodes", {})[host] = {
            "uuid": nc["uuid"], "proto": nc.get("proto") or proto_local,
            "link": nc.get("link") or "", "sub_url": nc.get("sub_url") or "",
            "at": int(time.time())}
    return [{"host": host, "name": n.get("name") or host}], []

def _deploy_client_to_agent(n, host, recs, rec, u):
    deployed, skipped = [], []
    c0 = rec[2]
    ap = n.get("agent_params") or {}
    if not ap.get("public_key") or time.time() - int(ap.get("at") or 0) > 900:
        hd, herr, _ = _node_call(n, "/agent/hello", need_token=False)
        if hd and hd.get("public_key"):
            hd["at"] = int(time.time())
            n["agent_params"] = ap = hd
        elif not ap.get("public_key"):
            return deployed, [{"host": host, "reason": herr or "нода не вернула параметры"}]
    body = {"action": "add", "uuid": u, "name": c0.get("name") or "без имени",
            "limit_gb": _gb_of(c0.get("limit_gb"))}
    ed = _node_expiry_days(c0)
    if ed:
        body["expiry_days"] = ed
    if c0.get("reset_cycle"):
        body["reset_cycle"] = c0["reset_cycle"]
    data, err, _ = _node_call(n, "/agent/apply", body)
    if data is None and "уже есть" not in (err or ""):
        return deployed, [{"host": host, "reason": err or "ошибка ноды"}]
    link = _agent_link(n, n.get("agent_params") or ap, u, c0)
    for _, _, c in recs:
        c.setdefault("nodes", {})[host] = {
            "uuid": u, "proto": "reality", "link": link, "sub_url": "",
            "at": int(time.time())}
    return [{"host": host, "name": n.get("name") or host}], []

def _nodes_by_host():
    out = {}
    for n in get_nodes():
        h = (n.get("host") or "").strip().lower()
        if h:
            out[h] = n
    return out

def _node_agent_purge(node):
    """Снять veil-agent с хоста agent-ноды (best-effort по ключу панели).
    veil-ноду (чужую полноценную панель) НЕ трогаем — вернёт (None, пояснение)."""
    if (node.get("type") or "agent") != "agent":
        return (None, "не агент-нода: чужая панель не демонтируется")
    host = (node.get("host") or "").strip()
    user = (node.get("ssh_user") or "root").strip() or "root"
    key = (node.get("ssh_key") or "").strip()
    try:
        sport = int(node.get("ssh_port") or 22)
    except Exception:
        sport = 22
    if not host or not key or not os.path.exists(key):
        return (False, "нет SSH-ключа панели — агент не снят автоматически")
    cmd = ("systemctl disable --now veil-agent >/dev/null 2>&1; "
           "pkill -9 -f '[x]ray-agent.json' >/dev/null 2>&1; "
           "pkill -9 -f '[v]eil-agent/agent.py' >/dev/null 2>&1; "
           "rm -rf /opt/veil-agent /etc/systemd/system/veil-agent.service; "
           "systemctl daemon-reload >/dev/null 2>&1; echo VPURGED")
    full = ["/usr/bin/ssh", "-p", str(sport)] + _ssh_opts(key) + [f"{user}@{host}", cmd]
    try:
        r = subprocess.run(full, capture_output=True, text=True, timeout=25,
                           stdin=subprocess.DEVNULL)
        if r.returncode == 0 and "VPURGED" in (r.stdout or ""):
            return (True, "агент снят с сервера")
        return (False, ((r.stderr or "") + (r.stdout or "")).strip()[:160] or "сбой SSH")
    except subprocess.TimeoutExpired:
        return (False, "таймаут SSH — агент остался на сервере")
    except Exception as e:
        return (False, str(e)[:160])

def _node_apply_remove(n, uuid):
    # (ok, ошибка): отозвать ключ на ноде и не узнать, вышло ли, — это не отзыв.
    if (n.get("type") or "agent") == "agent":
        return _node_call(n, "/agent/apply", {"action": "remove", "uuid": uuid}, timeout=6)[:2]
    return _node_call(n, "/api/ext/clients/delete", {"uuid": uuid}, timeout=6)[:2]

def _undeploy_client_from_nodes(st, u):
    ents = _client_node_entries(st, u)
    nodes = _nodes_by_host()
    for host, e in ents.items():
        n = nodes.get(host.strip().lower())
        if n and e.get("uuid"):
            _node_apply_remove(n, e["uuid"])

def _repropagate_client_to_nodes(st, u):
    """Синхронизировать лимит/срок клиента на нодах, где он размещён."""
    ents = _client_node_entries(st, u)
    if not ents:
        return
    recs = [c for proto, inb in (st.get("inbounds") or {}).items()
            for c in inb.get("clients", []) if c.get("uuid") == u]
    if not recs:
        return
    c0 = recs[0]
    nodes = _nodes_by_host()
    for host, e in ents.items():
        n = nodes.get(host.strip().lower())
        if not n or not e.get("uuid"):
            continue
        if (n.get("type") or "agent") == "agent":
            _node_call(n, "/agent/apply", {
                "action": "set_limits", "uuid": e["uuid"],
                "limit_gb": _gb_of(c0.get("limit_gb")),
                "expiry_days": _node_expiry_days(c0),
                "reset_cycle": c0.get("reset_cycle") or ""}, timeout=6)
        else:
            _node_call(n, "/api/ext/clients/update", {
                "uuid": e["uuid"], "limit_gb": _gb_of(c0.get("limit_gb")),
                "expiry_days": _node_expiry_days(c0)}, timeout=6)


def _tg_api(method, path, body=None):
    import urllib.request, urllib.error
    url = TELEMT_API + path
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(
        url, data=data, method=method,
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=10) as r:
        raw = r.read()
        return json.loads(raw) if raw else {}

def _tg_available():
    try:
        _tg_api("GET", "/v1/users")
        return True
    except Exception:
        return False

def _tg_status():
    try:
        d = _tg_api("GET", "/v1/users")
    except Exception:
        return {"installed": False, "users": []}
    web = _tg_web_get()
    web_links = {u: _tg_web_link(u) for u in (web["profiles"] if web else [])}
    mp = _tg_mtproto_info()
    users = []
    for u in d.get("data", []):
        users.append({
            "username": u.get("username", ""),
            "enabled": bool(u.get("enabled")),
            "link": _tg_pick_tls_link((u.get("links") or {}).get("tls"), _tg_advertised_host()),
            "web_link": web_links.get(u.get("username", ""), ""),
            "ad_tag": u.get("user_ad_tag") or "",
            "connections": u.get("active_unique_ips", 1 if u.get("current_connections", 0) else 0),
            "max_ips": int(u.get("max_unique_ips") or 0),
            "conns": int(u.get("current_connections") or 0),
            "total_octets": u.get("total_octets", 0),
        })
    for u in users:
        u["link"] = _tg_fix_mtproto_link(u.get("link") or "", mp.get("port"))
    # #158: розданную вручную ссылку показываем побайтно, как её держат клиенты, —
    # иначе карточка начнёт предлагать адрес, которого у telemt в истории нет
    man = _tg_manual_status(d.get("data") or [])
    by_user = {m["username"]: m for m in man if m["ok"] and m.get("link")}
    for u in users:
        m = by_user.get(u["username"])
        if m and (m.get("kind") or "proxy") == "web":
            # Ссылка веб-прокси живёт в своём поле: в `link` карточки лежит MTProto,
            # и подменять его веб-ссылкой значит соврать про протокол.
            u["web_link"] = m["link"]
            u["web_manual"] = {"front": m["front"], "ts": m["ts"]}
            continue
        if m:
            u["link"] = m["link"]
            u["manual"] = {"port": m["port"], "front": m["front"], "ts": m["ts"]}
    # #180: ссылка чужого фронта не едет на общий :443 — развилка ведёт её по имени из
    # секрета, а не по `server=`. Без этого признака морда сверяла фронт с именем маски и
    # на маршруте `mp` врала в обе стороны: свежая ссылка выглядела чужой, прежняя — своей.
    for u in users:
        u["on443"] = bool(_tg_mp_route_for(u.get("link") or ""))
    res = {"installed": True, "users": users, "sni": _tg_sni(), "mtproto": mp, "manual": man}
    if web:
        res["web"] = web
    return res


def _tg_link_front(link):
    """Фронт, зашитый в `ee`-секрет ссылки, — его назовёт клиент в SNI. Толерантно:
    битая или чужая ссылка даёт пустую строку, а не исключение (ссылку отдаём всё равно)."""
    try:
        q = urllib.parse.parse_qs((link or "").split("?", 1)[1])
        m = _TG_EE_SECRET.match((q.get("secret") or [""])[0].strip().lower())
        return "" if not m else bytes.fromhex(m.group(2)).decode("ascii").strip().lower()
    except Exception:
        return ""


def _tg_mp_route_for(link):
    """#168: имя, под которым эта ссылка едет общий :443, или пустое — если не едет.
    Развилка выбирает дорожку по SNI, а клиент берёт SNI из фронта секрета, а не из
    `server=`. Значит на :443 легальна только ссылка, чей фронт уже называет `mp.<база>`;
    прежние ссылки (фронт — маска или чужой домен) остаются на публичном порту слушателя."""
    mp = _tg_mp_domain_on()
    return mp if mp and _tg_link_front(link) == mp else ""


def _tg_advertised_host():
    """Имя, под которым панель отдаёт СВЕЖУЮ ссылку: имя маршрута, иначе прежнее."""
    return _tg_mp_domain_on() or _tg_front_host()


def _tg_mp_domain_on():
    """Имя прокси, если маршрут на общий :443 включён (метки ставит `_mux_apply`)."""
    if not CFG_CACHE.get("tg_mp_on443"):
        return ""
    return (CFG_CACHE.get("tg_mp_domain") or "").strip()


def _tg_front_host():
    """Прежний порядок имени ссылки: сайт-маска → hop → база. Именно его держат уже
    розданные ссылки, поэтому он не зависит от маршрута MTProto."""
    return ((CFG_CACHE.get("tg_mask_domain") or "").strip() or
            (CFG_CACHE.get("hop_public_host") or "").strip() or
            (CFG_CACHE.get("panel_domain") or "").strip())


def _tg_host_ok(link):
    # Когда мюкс перенёс tg-фасад на tg.<база> (CFG_CACHE["tg_mask_domain"] ставит
    # _mux_apply и снимает _mux_revert), ссылки обязаны называть именно его: SNI базы
    # занят веб-фронтом. Без мюкса — прежний порядок hop → база.
    # #168: имя прокси и имя сайт-маски — РАЗНЫЕ, и подсказываем прокси только ссылке,
    # которая сама его называет (`_tg_mp_route_for`): иначе ссылка соврёт про :443.
    host = _tg_mp_route_for(link) or _tg_front_host()
    if not host or not link:
        return link
    return re.sub(r"(?i)(server=)[^&:]+", lambda m: m.group(1)+host, link)

def _tg_toml_server_port():
    """Устарело: см. _tg_toml_get_server_port. Оставлено как алиас для внешних потребителей."""
    return _tg_toml_get_server_port()

def _tg_mtproto_info():
    """Реальный публичный MTProto listener: тот порт, куда должны приходить tg://proxy-клиенты.
    В telemt 3.5+ массив [[server.listeners]] исчерпывающий: если в нём нет публичного
    transport=mtproxy блока, telemt не слушает [server] port, даже когда тот задан."""
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        text = ""
    try:
        c = _tg_api("GET", "/v1/config").get("data", {}).get("censorship") or {}
    except Exception:
        c = {}
    mask = bool(c.get("mask"))
    try:
        mask_port = int(c.get("mask_port") or 0)
    except (TypeError, ValueError):
        mask_port = 0
    server_port = _tg_toml_get_server_port(text) if text else 0
    listeners = _tg_toml_listeners(text) if text else []
    pub = _tg_toml_public_mp_listener(text) if text else None
    if pub:
        port = pub["port"] or server_port
    elif not listeners:
        # Классический конфиг без listeners-массива — telemt сам биндит [server] port
        port = server_port
    else:
        # Listeners объявлены, но публичного mtproxy среди них нет — telemt MTProto не слушает
        port = server_port
    if not port:
        port = 443
    info = {"port": port, "mask": mask, "mask_port": mask_port, "server_port": server_port,
            "up": False, "proc": "", "note": "", "has_public_listener": bool(pub)}
    occ = _sock_occupant(port)
    info["proc"] = occ.get("proc", "")
    if occ.get("free"):
        info["note"] = ("на :%d никто не слушает — публичный MTProto listener не объявлен в "
                        "[[server.listeners]]" % port)
    elif "telemt" in (occ.get("proc") or ""):
        info["up"] = True
        info["note"] = "MTProto активен на :%d" % port
    else:
        info["note"] = ("порт :%d занят %s — не telemt; MTProto-клиенты туда не попадут"
                        % (port, occ.get("proc") or "другим процессом"))
    return info

def _tg_fix_mtproto_link(link, port):
    """Ссылка tg://proxy: подставить публичный домен и реальный порт MTProto
    (telemt иногда отдаёт порт своего loopback-веб-листенера вместо нативного).
    #168: когда маршрут MTProto на общем :443 включён, новые ссылки идут на него —
    слушатель на своём порту остаётся живым для уже розданных. На :443 ведём только
    ссылку, чей фронт уже называет имя прокси (`_tg_mp_route_for`)."""
    link = _tg_host_ok(link)
    if _tg_mp_route_for(link):
        port = 443
    if link and port:
        link = re.sub(r"(?i)(port=)\d+", lambda m: m.group(1)+str(port), link)
    return link

_TG_MP_MARK = "Veil:MTProtoListener"

def _tg_toml_get_server_port(text=None):
    """[server] port из telemt.toml (0 если не задан)."""
    if text is None:
        try:
            with open(TELEMT_CONF, "r", encoding="utf-8") as f: text = f.read()
        except Exception:
            return 0
    m = re.search(r"(?ms)^\s*\[server\]\s*$(.+?)(?=^\s*\[\[?|\Z)", text)
    if not m:
        return 0
    pm = re.search(r"(?m)^\s*port\s*=\s*(\d+)", m.group(1))
    return int(pm.group(1)) if pm else 0

def _tg_toml_set_server_port(text, port):
    """Вернуть текст с [server] port = port (вставить секцию, если её нет)."""
    port = int(port)
    m = re.search(r"(?ms)(^\s*\[server\]\s*$)(.+?)(?=^\s*\[\[?|\Z)", text)
    if not m:
        return text.rstrip("\n") + "\n\n[server]\nport = %d\n" % port
    body = m.group(2)
    if re.search(r"(?m)^\s*port\s*=", body):
        nb = re.sub(r"(?m)^(\s*port\s*=\s*)\d+", lambda mm: mm.group(1)+str(port), body, count=1)
    else:
        nb = body.rstrip("\n") + "\nport = %d\n" % port
    return text[:m.start(2)] + nb + text[m.end(2):]

def _tg_toml_listeners(text):
    """Список всех [[server.listeners]] блоков: [{ip, port, transport, span}].
    Transport по умолчанию — mtproxy; port по умолчанию наследует [server] port."""
    default_port = _tg_toml_get_server_port(text)
    out = []
    for m in re.finditer(r"(?ms)^\s*\[\[server\.listeners\]\]\s*$(.+?)(?=^\s*\[\[?|\Z)", text):
        body = m.group(1)
        ipm = re.search(r"(?m)^\s*ip\s*=\s*\"([^\"]*)\"", body)
        ptm = re.search(r"(?m)^\s*port\s*=\s*(\d+)", body)
        trm = re.search(r"(?m)^\s*transport\s*=\s*\"([^\"]*)\"", body)
        out.append({
            "ip": (ipm.group(1) if ipm else ""),
            "port": int(ptm.group(1)) if ptm else int(default_port or 0),
            "transport": (trm.group(1) if trm else "mtproxy").lower(),
            "span": (m.start(), m.end()),
        })
    return out

def _tg_toml_public_mp_listener(text):
    """True если в [[server.listeners]] есть mtproxy-блок, слушающий не-loopback IP."""
    for L in _tg_toml_listeners(text):
        if L["transport"] != "mtproxy":
            continue
        ip = L["ip"] or "0.0.0.0"
        if ip.startswith("127.") or ip in ("::1", ""):
            # ""=не задан; по доке это тоже любой интерфейс — считаем публичным
            if ip == "":
                return L
            continue
        return L
    return None

def _tg_toml_has_any_listener(text):
    return bool(_tg_toml_listeners(text))

def _tg_toml_ipv6_set(text, on=True):
    """Записать [network] ipv6 = true|false. Без флага (по умолчанию false) telemt молча
    НЕ биндит ни ::, ни v6-адрес: AAAA домен живёт, а слушателя нет, и iOS под VPN
    (где v6-маршрут появляется) теряет MTProto-прокси.
    Флаг пишем и в сторону false: прежнее применение оставляло в файле `ipv6 = true`
    из прошлого захода, поэтому переключатель снимал только слушателя, а не v6-маршруты
    к DC — а под middle-proxy именно они (сам telemt называет их экспериментальными)
    рвутся тысячами в час и съедают загрузку медиа."""
    want = "true" if on else "false"
    lines = text.split("\n")
    start = None
    for i, ln in enumerate(lines):
        if ln.strip() == "[network]":
            start = i
            break
    if start is None:
        return text.replace("[server]\n", "[network]\nipv6 = %s\n\n[server]\n" % want, 1)
    j = start + 1
    while j < len(lines) and not lines[j].lstrip().startswith("["):
        if re.match(r"\s*ipv6\s*=", lines[j]):
            lines[j] = "ipv6 = " + want
            return "\n".join(lines)
        j += 1
    lines.insert(start + 1, "ipv6 = " + want)
    return "\n".join(lines)

def _tg_mp_ipv6_want():
    """Держать ли IPv6 у MTProto: и слушателя `::`, и [network] ipv6. По умолчанию ВКЛ
    (прежнее поведение). Гасим только когда оператор снял переключатель `tg_mp_ipv6`
    И middle-proxy включён — именно под middle-proxy v6-маршрут появляется у клиента
    (iOS под VPN), и тогда публичный `[network] ipv6 = true` + слушатель `::` —
    осознанный выбор, а не случайность."""
    return bool(CFG_CACHE.get("tg_mp_ipv6", True)) or not _tg_middle_proxy_on()

def _tg_toml_add_mp_listener(text, port, ipv6=True):
    """Добавить публичные MTProto-listeners на port; вернуть (новый_текст, блок).
    При ipv6=False — только v4-слушатель, и [network] ipv6 пишется явно в false.
    Вставляем сразу после последнего существующего [[server.listeners]] (если есть) —
    тогда все listeners сгруппированы; иначе — в конец файла."""
    if _TG_MP_MARK in text:
        raise RuntimeError("VEIL-MTProto-listener уже добавлен — сначала откат")
    text = _tg_toml_ipv6_set(text, ipv6)
    block = (
        "# "+_TG_MP_MARK+"\n"
        "[[server.listeners]]\n"
        "ip = \"0.0.0.0\"\n"
        "port = "+str(int(port))+"\n"
        "transport = \"mtproxy\"\n"
    )
    if ipv6:
        block += (
            "\n# "+_TG_MP_MARK+"\n"
            "[[server.listeners]]\n"
            "ip = \"::\"\n"
            "port = "+str(int(port))+"\n"
            "transport = \"mtproxy\"\n"
        )
    last = None
    for m in re.finditer(r"(?ms)^\s*\[\[server\.listeners\]\]\s*$(.+?)(?=^\s*\[\[?|\Z)", text):
        last = m
    if last:
        ins = last.end()
        return text[:ins].rstrip("\n") + "\n\n" + block + text[ins:].lstrip("\n"), block
    return text.rstrip("\n") + "\n\n" + block, block

def _tg_toml_remove_mp_listener(text):
    """Вырезать наши блоки-маркеры (v4+v6): строка-комментарий, заголовок [[server.listeners]]
    и тело до следующей секции/комментария.

    Цифра после маркера переживается намеренно: v6-слушателя прежняя версия панели
    подписывала `# Veil:MTProtoListener6`, и на живых машинах такой блок до сих пор
    в файле. Без этой цифры откат вырезал один блок из двух и молча оставлял
    публичного `::`-слушателя, рапортуя успех.
    """
    pat = re.compile(r"(?m)^#[ \t]*" + re.escape(_TG_MP_MARK) + r"[ \t]*\d*[ \t]*\n"
                     r"\[\[server\.listeners\]\][^\n]*\n(?:[^\[#\n][^\n]*\n)*")
    new, n = pat.subn("", text)
    if n == 0:
        raise RuntimeError("наш MTProto-listener не найден в telemt.toml — откатывать нечего")
    return new

def _tg_mp_preview():
    """Можно ли оживить MTProto: добавив публичный [[server.listeners]] (transport=mtproxy).
    Telemt 3.5+ рассматривает массив listeners как исчерпывающий: если задан только web-loopback,
    публичного MTProto-входа нет даже при корректном [server] port. Чиним это декларативно."""
    info = _tg_mtproto_info()
    telemt_up = _tg_available()
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        text = ""
    cur_public = _tg_toml_public_mp_listener(text) if text else None
    any_listener = _tg_toml_has_any_listener(text) if text else False
    server_port = _tg_toml_get_server_port(text) if text else 0
    # Публичный порт, куда должны приходить MTProto-клиенты:
    public_port = (cur_public or {}).get("port") or info.get("port") or server_port or 0
    already_up = bool(info.get("up"))
    blockers, can_apply, cand = [], False, 0
    if not os.path.exists(TELEMT_CONF):
        blockers.append("нет %s — MTProto-прокси не установлен" % TELEMT_CONF)
    if not telemt_up:
        blockers.append("telemt не отвечает по API (не запущен?)")
    if already_up:
        blockers.append("MTProto уже активен на :%d — ничего делать не нужно" % public_port)
    elif cur_public is not None:
        # Публичный listener есть, но порт занят чужим или telemt не смог связаться
        occ = _sock_occupant(public_port)
        if not occ.get("free") and "telemt" not in (occ.get("proc") or ""):
            cand = _find_free_port(pref=[7443, 2443, 8843, 6443, 9443], avoid={public_port})
            if cand:
                can_apply = False   # перенос порта публичного listener'а — отдельная фича, не v2.7.7
                blockers.append("наш MTProto listener на :%d, но порт занят %s — освободите :%d или включите мюкс"
                                % (public_port, occ.get("proc") or "?", public_port))
            else:
                blockers.append("порт :%d занят и свободных альтернатив нет" % public_port)
        else:
            blockers.append("listener есть на :%d, но telemt его не слушает — перезапустите telemt" % public_port)
    else:
        # Нет публичного MTProto listener'а → можно добавить на [server] port (или на free)
        want = server_port or 0
        occ = _sock_occupant(want) if want else {"free": True}
        if want and not occ.get("free") and "telemt" not in (occ.get("proc") or ""):
            cand = _find_free_port(pref=[7443, 2443, 8843, 6443, 9443], avoid={want})
        else:
            cand = want or _find_free_port(pref=[7443, 2443, 8843, 6443, 9443])
        if not cand:
            blockers.append("не нашёл свободный порт для MTProto listener'а")
        else:
            can_apply = bool(telemt_up)
    note = ""
    if can_apply:
        note = (" telemt держит массив [[server.listeners]] как исчерпывающий — добавим публичный "
                "MTProto-listener на :%d (nginx/Reality не трогаем). После применения ссылка tg://proxy "
                "указывает на :%d, fake-TLS-фронт работает как раньше." % (cand, cand))
    elif already_up:
        note = "MTProto активен на :%d — ничего делать не нужно." % public_port
    else:
        note = info.get("note") or ""
    return {"mask": bool(info.get("mask")), "public_port": public_port, "server_port": server_port,
            "ipv6": "on" if _tg_mp_ipv6_want() else "off",
            "mp_ipv6": bool(CFG_CACHE.get("tg_mp_ipv6", True)),
            "middle_proxy": bool(_tg_middle_proxy_on()),
            "up": already_up, "proc": info.get("proc") or "",
            "has_public_listener": bool(cur_public), "has_any_listener": any_listener,
            "candidate_port": cand, "can_apply": can_apply, "blockers": blockers, "note": note,
            "marked": bool(_TG_MP_MARK in text),
            "applied": bool((_load(_TGBP_STATE, {}) or {}).get("applied"))}

_MPST = {"ts": 0.0, "res": None}

def _tls_probe(ip, port, sni, timeout=6):
    """TLS-рукопожатие с SNI=фронт к ip:port (CERT_NONE — facade-сертификат не валиден
    по определению). Вернуть (ok, detail): detail содержит `subject` сервера при успехе."""
    try:
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        fam = socket.AF_INET6 if ":" in ip else socket.AF_INET
        with socket.socket(fam, socket.SOCK_STREAM) as raw:
            raw.settimeout(timeout)
            raw.connect((ip, port))
            s = ctx.wrap_socket(raw, server_hostname=sni)
            try:
                der = s.getpeercert(True)
            finally:
                try:
                    s.close()
                except Exception:
                    pass
        if not der:
            return False, "handshake прошёл, но сертификата нет"
        fd, p = tempfile.mkstemp(suffix=".der")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(der)
            r = subprocess.run(["openssl", "x509", "-inform", "DER", "-noout", "-subject"],
                               capture_output=True, text=True, timeout=8)
            subj = re.sub(r"^subject=", "", (r.stdout or "").strip())[:90]
        finally:
            try:
                os.unlink(p)
            except Exception:
                pass
        return True, subj
    except Exception as e:
        return False, str(e)[:120]

_TG_DC_FAIL = re.compile(
    r"Connection (?:timeout|refused|reset|failed)\s+to\s+([0-9A-Za-z_.:\[\]-]+):(\d+)")


def _tg_dc_complaints(mins=10):
    """К каким адресам Telegram узел не достучался по словам самого telemt.

    telemt говорит это прямо («Upstream failed after retries: Connection timeout to …»), но
    реплика тонет в журнале, а морда без неё не отличает «прокси сломан» от «у этого сервера
    нет пути к Telegram». Возвращает ([(хост, порт, число жалоб)], ошибка)."""
    try:
        # Приоритет указывать нельзя: telemt пишет в stderr без syslog-префикса, и journald
        # ставит таким строкам PRIORITY=6. фильтр `-p warning` (≤4) отсекает ВСЕ их, и
        # самотест молча рапортует «не жаловался» там, где за час сто двадцать таймаутов.
        r = subprocess.run(["journalctl", "-u", "telemt", "--no-pager", "-q",
                            "-n", "3000", "--since", "-%dm" % mins],
                           capture_output=True, text=True, timeout=15)
    except FileNotFoundError:
        return [], "журнала systemd нет"
    except Exception as e:
        return [], str(e)[:120]
    if r.returncode != 0:
        return [], (r.stderr or "journalctl rc=%s" % r.returncode)[:120]
    tally = {}
    for m in _TG_DC_FAIL.finditer(r.stdout or ""):
        host = (m.group(1) or "").strip("[]")
        try:
            port = int(m.group(2))
        except Exception:
            continue
        if host:
            tally[(host, port)] = tally.get((host, port), 0) + 1
    return sorted(tally.items(), key=lambda kv: (-kv[1], kv[0])), ""


_TG_DC_TRIES = 6
_TG_DC_TIMEOUT = 2.0
_TG_DC_TTL = 900.0
# Медиа-узел отделяется от основного величиной номера, а не знаком: см. `_tg_dc_media`.
_TG_MEDIA_DC = 100
# Потерю подъёма мерим СНАРЯДА, а не в ответе на запрос морды: шесть попыток по два метра
# на адрес — это секунды, а `/api/tg/dcs` открывается на каждом обновлении вкладки.
_tg_dc_loss = {"rows": {}, "error": ""}
_tg_dc_loss_lock = threading.Lock()


def _tg_dc_endpoints():
    """Адреса узлов Telegram, с которыми движок работает сам, — из его статистики и из
    его же действующего конфига.

    Вбитый список запрещён тем же, чем он запрещён для жалоб: адреса Telegram меняются, а
    мерить надо ровно тот путь, которым идёт наша сессия. Исключение — наверх, его читает
    тик и красит ошибку в снимке, а не в морде.

    Статистика называет тот адрес, который движок использует СЕЙЧАС, и молчит про путь,
    который он собирается использовать, когда ME не готов: `dc_overrides` живёт в
    действующем конфиге и в статистику не попадает. Замер 07.10: движок сам SYN-ил на
    адрес из `dc_overrides` `7` раз подряд без ответа, а панель знала только адрес
    ME-прокси, — то есть туннель накрывал путь, который не работает, и не накрывал тот,
    который режется. Конфиг читается у того же живого движка, поэтому список не становится
    вбитым; ошибка чтения — не авария: мера остаётся по статистике."""
    d = _tg_api("GET", "/v1/stats/dcs").get("data") or {}
    out = []
    seen = set()
    for x in (d.get("dcs") or []):
        for ep in (x.get("endpoints") or []):
            ep = str(ep).strip()
            if ep and (x.get("dc"), ep) not in seen:
                seen.add((x.get("dc"), ep))
                out.append((x.get("dc"), ep))
    try:
        ov = ((_tg_api("GET", "/v1/config").get("data") or {}).get("dc_overrides") or {})
    except Exception:
        ov = {}
    for dc, eps in (ov.items() if isinstance(ov, dict) else []):
        for ep in (eps if isinstance(eps, (list, tuple)) else [eps]):
            ep = str(ep).strip()
            if ep and (dc, ep) not in seen:
                seen.add((dc, ep))
                out.append((dc, ep))
    return out


def _tg_dc_probe(ep):
    """Сколько подъёмов соединения до `хост:порт` дошло из `_TG_DC_TRIES`: (ок, провал, лучший мс).

    Именно подъём, а не «отвечает ли адрес»: `_hop_public` делает одну попытку и тонущий в
    половине случаев узел выдаёт как здоровый — так прежняя проверка и прятала #183.
    """
    host, _, port = ep.rpartition(":")
    try:
        port = int(port)
    except Exception:
        return 0, 0, None
    # Скобки из `[::1]:443` — не адрес: без них `create_connection` теряет семью и пишет
    # IPv6-узел в провалы, то есть врёт про потерю там, где ничего не терялось.
    host = host.strip("[]")
    ok = fail = 0
    best = None
    for _ in range(_TG_DC_TRIES):
        t0 = time.monotonic()
        try:
            s = socket.create_connection((host or ep, port), timeout=_TG_DC_TIMEOUT)
            s.close()
            ok += 1
            ms = (time.monotonic() - t0) * 1000.0
            best = ms if best is None else min(best, ms)
        except Exception:
            fail += 1
    return ok, fail, (round(best, 1) if best is not None else None)


def _tg_dc_loss_tick():
    """Один адрес за тик: попыток много, тик общий со страховками, и гнать их вразнобой нельзя.

    Очередь берёт того, чей замер устарел давнее всех, а не первого по порядку списка
    движка. Живой замер 07.10: адресов `25`, тик раз в `60` с, срок жизни замера `900` с —
    это `15` тиков, а полный круг стоит `25` мин. Голова списка устаревает раньше, чем
    очередь доходит до хвоста, и первый по порядку мерится снова: хвост из `10` адресов за
    `28` мин не получил ни одного замера, поэтому потеря по резервному пути медиа-кластера
    оставалась немереной (#222 не подтверждался именно поэтому). Скидку «медиа первыми»
    эта же фикстура забраковала числом: круг от неё не закрывался, а теряющий адрес из
    хвоста ждал дольше срока жизни замера."""
    try:
        eps = _tg_dc_endpoints()
    except Exception as e:
        with _tg_dc_loss_lock:
            _tg_dc_loss["error"] = str(e)[:120]
        return
    now = time.time()
    with _tg_dc_loss_lock:
        rows = _tg_dc_loss["rows"]
        due = []
        for dc, ep in eps:
            at = float((rows.get(ep) or {}).get("at") or 0)
            if now - at > _TG_DC_TTL:
                due.append((at, dc, ep))
        _tg_dc_loss["error"] = ""
    if not due:
        return
    # ключ один и числовой: номер узла приходит и целым, и строкой, а сравнивать их нельзя
    _at, dc, ep = min(due, key=lambda t: t[0])
    ok, fail, best = _tg_dc_probe(ep)
    total = ok + fail
    with _tg_dc_loss_lock:
        _tg_dc_loss["rows"][ep] = {"dc": dc, "ep": ep, "ok": ok, "fail": fail,
                                   "total": total,
                                   "loss": (round(100.0 * fail / total) if total else None),
                                   "best_ms": best, "at": int(now)}


def _tg_dc_num(dc):
    """Номер узла как число. Строковой порядок (`"-203" < "-5"`) путает медиа с основным."""
    try:
        return int(dc)
    except (TypeError, ValueError):
        return 0


def _tg_dc_media(dc):
    """Медиа-узел или основной. Знак для этого не мерка: у живого движка медиа-узел
    приходит и под `203`, и под `-203`, а `-1…-5` — семейство основных узлов. Замер
    07.10: |dc| = 1, 2, 3, 4, 5 и 203 — разрыв измерен, медиа начинаются за `100`.
    Положительный медиа-узел, отброшенный по знаку, панелью просто не мерился."""
    n = _tg_dc_num(dc)
    return n < 0 or abs(n) >= _TG_MEDIA_DC


def _tg_dc_size(v):
    """Сколько элементов в значении строки `/v1/stats/dcs`.

    Форма у движка разная: `endpoints` — список адресов, `available_endpoints` — число.
    Живой промер 06.10: `int()` на списке ронял всю карту в пустоту, и диагностика
    врала про «режим не прочитан» там, где движок был совершенно здоров."""
    if isinstance(v, (list, tuple)):
        return len(v)
    try:
        return int(v or 0)
    except (TypeError, ValueError):
        return 0


def _tg_dc_loss_view():
    """Снимок замеров подъёма: строки, теряющие адреса и адреса без потерь. Только чтение."""
    now = time.time()
    with _tg_dc_loss_lock:
        rows = [dict(v) for v in _tg_dc_loss["rows"].values()]
        err = _tg_dc_loss.get("error") or ""
    for r in rows:
        r["stale"] = (now - float(r.get("at") or 0)) > 2 * _TG_DC_TTL
        r["media"] = _tg_dc_media(r.get("dc"))
    rows.sort(key=lambda r: (0 if r["media"] else 1, _tg_dc_num(r.get("dc")), r.get("ep") or ""))
    live = [r for r in rows if not r["stale"]]
    lossy = [r for r in live if (r.get("loss") or 0) >= 20]
    return {"rows": rows,
            "lossy": [r["ep"] for r in lossy],
            "media_lossy": [r["ep"] for r in lossy if r["media"]],
            "healthy": [r["ep"] for r in live if r.get("loss") == 0],
            "error": err, "tries": _TG_DC_TRIES, "ttl": int(_TG_DC_TTL)}


# ---------- Медиа-путь: подъём соединений к медиа-узлам через туннель WG ----------
# Узел Telegram теряет подъём соединений (#183), а медиа-адрес теряет их сильнее всего:
# живой замер 06.10 — напрямую доходит `19` подъёмов из `40` (медиана `50` мс), через
# туннель до WARP — `40` из `40` (медиана `36` мс). Вбитый список набора не меняет:
# адреса берутся из живых замеров тика, а не из-под пера.
# Таблица маршрутизации своя, правило без селектора: падение звена ядро разворачивает
# напрямую само (замерено — маршруты гибнут вместе с падением линка, правило переживает
# его, и трафик уходит как шло). Дефолтный маршрут и DNS коробки не тронуты ни на байт.
_MR_IF = "tgw0"
_MR_TBL = "203"
_MR_PRIO_BASE = 100
_MR_DIR = "/var/lib/veil-media-route"
_MR_REG = _MR_DIR + "/reg.json"
_MR_STATE = f"{BASE}/media_route.json"
_MR_MTU = "1280"
_MR_KEEP = "25"
_MR_ROT = 900.0      # как часто меняем молчаливый аккаунт WARP: облако считает `POST /reg`
_MR_MAX = 8            # потолок адресов в туннеле: и разумность правил, и бюджет звена
_MR_LOSS = 20.0        # потеря подъёма, с которой адрес — кандидат (тот же порог, что у измерителя)
_MR_GIVEUP = 50.0      # потеря УЖЕ в туннеле: туннель не помог, адрес откатываем
_MR_COOL = 3600.0      # сколько секунд адрес после отката не претендует на туннель
# Подъём соединения — средство, а не цель: цель — писатели, которые движок ставит на
# адрес. Живой замер 07.10 (#221): адрес в туннеле отвечал на `6` подъёмов из `6`
# (`7.4` мс, потеря `0`%), а движок при этом не имел ни одного писателя (`0` из `3`) и
# считал сам адрес недоступным (`0` из `1`). Как только адрес отдали напрямую, писатели
# родились за `10` с, а покрытие выросло с `86.0` до `100.0` и держалось. Прежний
# критерий такой туннель считал удачным и не отбраковывал никогда.
_MR_STARVE = 3         # сколько тиков подряд узел требует писателей и не получает ни одного
_MR_STARVE_BAN = 86400.0  # на столько секунд (сутки) адрес уходит напрямую после приговора
                          # туннелю: возвращать его каждый час — значит обнулять медиа каждые
                          # минуты
_MR_REG_URL = "https://api.cloudflareclient.com/v0a2223/reg"
_MR_UA = "wireguard-go-rs"
_MR_ERR = ""
# когда в последний раз меняли молчаливый аккаунт: глобал обязан рождаться с нулём, иначе
# первая же ротация читает несуществующее имя и роняет весь тик до записи состояния
_MR_ROTATE = 0.0


def _mr_want():
    """Желание оператора: вести медиа-трафик через туннель. Тот же конфиг, что у остальных переключателей."""
    return bool(CFG_CACHE.get("tg_media_route"))


def _mr_cmd(*a, **kw):
    """Один вызов командной строки без право-левого разбора: (код возврата, вывод, ошибка)."""
    r = subprocess.run(list(a), capture_output=True, text=True, timeout=15, **kw)
    return r.returncode, (r.stdout or "").strip(), (r.stderr or "").strip()


def _mr_registered():
    """Снимок аккаунта WARP. Приватный ключ наружу не печатается нигде: файл `0600` вне репозитория."""
    reg = _load(_MR_REG) or {}
    need = ("private_key", "peer_public_key", "tunnel_v4", "endpoint", "endpoint_port")
    return reg if all(reg.get(k) for k in need) else None


def _mr_register():
    """Заводим бесплатный аккаунт WARP ровно один раз и запоминаем его.

    Вторым вызовом API тот же публичный ключ не принимается, а приватную часть он не
    отдаёт, поэтому ключ и ответ пишутся в файл до любой новой пробы. Форма тела и
    заголовок проверены на живой коробке: на другой форме облако отказывает.
    Рабочий адрес пиера отдаёт ответ, а не имя из присланной конфигурации: имя резолвится
    в узел, который на рукопожатие молчит. Возвращает (аккаунт, причина отказа)."""
    rc, priv, err = _mr_cmd("wg", "genkey")
    if rc != 0 or not priv:
        return None, "ключ не выпущен"
    # `text=True` обязывает `input` быть строкой: байты на Python 3.14 вызывают
    # `'bytes' object has no attribute 'encode'` внутри `subprocess` (живая находка
    # этого цикла — офлайн-фикстура этого не видела)
    p = subprocess.run(["wg", "pubkey"], input=priv, capture_output=True,
                       text=True, timeout=10)
    pub = (p.stdout or "").strip()
    if p.returncode != 0 or not pub:
        return None, "публичный ключ не вычислен"
    zero = "00000000-0000-0000-0000-000000000000"
    body = json.dumps({"key": pub, "install_id": "0", "token": zero, "type": "free",
                       "license": "", "waitlist": False, "version": "20211018.1",
                       "fingerprint": zero, "fp": zero}).encode()
    req = urllib.request.Request(_MR_REG_URL, data=body, method="POST",
                                 headers={"Content-Type": "application/json",
                                          "User-Agent": _MR_UA})
    try:
        with urllib.request.urlopen(req, timeout=15) as f:
            d = json.loads(f.read().decode("utf-8", "replace") or "{}")
    except Exception as e:
        # под лимитом облако отвечает `429` с `retry-after` — причину обязан увидеть
        # оператор, а не общую строку «аккаунта нет»
        return None, "регистрация не прошла: " + str(e)[:90]
    cfg = d.get("config") or {}
    iface = cfg.get("interface") or {}
    peer = (cfg.get("peers") or [{}])[0]
    ep = peer.get("endpoint") or {}
    # `v4` приходит в форме «адрес:порт» с нулевым портом, а настоящий порт — списком в
    # `ports`; приватной части в ответе нет вовсе (замерено на сохранённом снимке)
    v4 = str(ep.get("v4") or "").split(":")[0]
    ports = ep.get("ports") or []
    reg = {"private_key": d.get("private_key") or iface.get("private_key") or priv,
           "peer_public_key": peer.get("public_key") or "",
           "tunnel_v4": ((iface.get("addresses") or {}).get("v4") or "").split("/")[0],
           "endpoint": v4 or ep.get("host") or "",
           "endpoint_port": str(ports[0] if ports else (ep.get("port") or "2408")),
           "at": int(time.time())}
    if not all(reg[k] for k in ("private_key", "peer_public_key", "tunnel_v4", "endpoint")):
        return None, "ответ облака не полный"
    try:
        os.makedirs(_MR_DIR, mode=0o700, exist_ok=True)
        _save(_MR_REG, reg, 0o600)
    except Exception as e:
        return None, "аккаунт не сохранён: " + str(e)[:90]
    return reg, ""


def _mr_retire(reason):
    """Мёртвый аккаунт WARP в расход: новый ключ облако принимает, молчаливый — нет.

    Живая находка цикла: звено собрано безупречно (интерфейс вверх, ключ стоит, адрес
    пиера из ответа, сторожевой пакет 25 с), исходящая инициация уходит на net0, а
    ответных байтов нет — `latest-handshakes` держится нул. За цикл на коробке
    нарезано несколько бесплатных аккаунтов, и облако имеет право молчать старому.
    Проверено пробой: тот же способ сборки со СВЕЖИМ аккаунтом донёс медиа-адрес за
    `30` мс. Поэтому молчание чиним не пересборкой того же ключа каждый тик, а
    заменой аккаунта — но редко: `POST /reg` на один адрес считается облаком и может
    ответить `429`."""
    global _MR_ROTATE
    now = time.time()
    if now - _MR_ROTATE < _MR_ROT:
        return reason + "; новый аккаунт не раньше чем через %d с" % int(
            _MR_ROT - (now - _MR_ROTATE))
    _MR_ROTATE = now
    try:
        os.remove(_MR_REG)
    except OSError:
        return reason + "; аккаунт не снять"
    return reason


def _mr_live_eps():
    """Медиа-адреса из замеров тика: [(хост, потеря %, когда измерено)]. Только свежие строки снимка."""
    now = time.time()
    out = []
    with _tg_dc_loss_lock:
        rows = [dict(v) for v in _tg_dc_loss["rows"].values()]
    for r in rows:
        at = float(r.get("at") or 0)
        if now - at > 2 * _TG_DC_TTL:
            continue
        if not _tg_dc_media(r.get("dc")):
            continue
        host = str(r.get("ep") or "").rpartition(":")[0].strip("[]")
        if re.match(r"^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$", host or ""):
            out.append((host, float(r.get("loss") or 0), at))
    return out


def _mr_writers(tun):
    """Писатели тех медиа-узлов, которые туннель может объяснить один: {хост: (живо, требуется)}.

    Движок считает писателей УЗЛОМ, а не адресом, поэтому приговор адресу подписываем
    только когда ВСЕ зарегистрированные адреса узла идут через туннель: иначе ноль
    принадлежал бы прямому адресу, а виноват был бы туннель. Движок молчит или ошибается —
    меры нет, а отсутствие меры — не приговор (тот же порядок, что с `ping` в `_mr_carries`).
    Узел, который писателей не требует (`0` в поле), судить нечем: он их и не терял."""
    if not tun:
        return {}
    try:
        dcs = ((_tg_api("GET", "/v1/stats/dcs").get("data") or {}).get("dcs")) or []
    except Exception:
        return {}
    out = {}
    for x in dcs:
        if not _tg_dc_media(x.get("dc")):
            continue
        req = int(x.get("required_writers") or 0)
        alive = int(x.get("alive_writers") or 0)
        hosts = set(str(ep).rpartition(":")[0].strip("[]") for ep in (x.get("endpoints") or []))
        hosts = set(h for h in hosts if h)
        if req <= 0 or not hosts or not hosts <= set(tun):
            continue
        for h in hosts:
            out[h] = (alive, req)
    return out


def _mr_want_eps():
    """Какие адреса обязаны идти через туннель прямо сейчас.

    Кандидат — медиа-адрес, у которого замерена потеря подъёма. У адреса, уже сидящего в
    туннеле, два приговора: потеря подъёма (`_MR_GIVEUP`) и отсутствие писателей
    (`_MR_STARVE`). Оставляли бы только первый — и туннель, который не даёт грузить медиа,
    выглядел бы образцово: он поднимает соединение, а рукопожатие медиа-узла за ним
    обрывается (#221, замер в шапке секции)."""
    st = _load(_MR_STATE, {}) or {}
    cur = st.get("targets") or {}
    now = time.time()
    live = _mr_live_eps()
    # откат судим только замеру, сделанному после того, как звено поднялось: молчащее
    # звено мерит адрес напрямую, и «туннель не помог» оказалось бы выводом из замера,
    # в котором туннеля не было вовсе (живая находка этого цикла)
    since = float(st.get("up_since") or 0)
    tun = set(h for h, e in cur.items() if (e or {}).get("mode") == "tunnel")
    writers = _mr_writers(tun)
    want = []
    for host, loss, at in live:
        ent = dict(cur.get(host) or {})
        if ent.get("mode") == "tunnel":
            w = writers.get(host)
            if w and w[0]:
                # писатели есть — счётчик голода обнуляем, туннель их даёт
                ent["starve"] = 0
            elif w and since > 0:
                ent["starve"] = int(ent.get("starve") or 0) + 1
                ent["writers"] = "0 из %d" % w[1]
            if since > 0 and at >= since and loss >= _MR_GIVEUP:
                ent.update({"mode": "direct", "banned_until": now + _MR_COOL})
            elif int(ent.get("starve") or 0) >= _MR_STARVE:
                ent.update({"mode": "direct", "banned_until": now + _MR_STARVE_BAN,
                            "why": "writers"})
            else:
                want.append(host)
        elif (float(ent.get("banned_until") or 0) <= now and loss >= _MR_LOSS
              and len(want) < _MR_MAX):
            ent.update({"mode": "tunnel", "starve": 0})
            ent.pop("why", None)
            want.append(host)
        if ent:
            cur[host] = ent
    # запись не обязана переживать адрес: цель — список на сейчас, а не архив измерений
    seen = set(h for h, _loss, _at in live)
    cur = dict((h, e) for h, e in cur.items()
               if h in seen or float((e or {}).get("banned_until") or 0) > now)
    return sorted(want)[:_MR_MAX], cur


def _mr_flush_rules():
    """Снять НАШИ правила. Маршруты умирают вместе со связью сами, а правило — нет:
    после удаления интерфейса оно остаётся смотреть в пустую таблицу и молча копится."""
    for prio, _net in _mr_rules():
        _mr_cmd("ip", "rule", "del", "priority", str(prio))


def _mr_rules():
    """Наши правила: [(приоритет, сеть)]. Судим только правило, ведущее в нашу таблицу.

    Хостовое правило ядро печатает БЕЗ маски: `to 91.105.192.110 lookup 203`, а не
    `.../32` — тот же дефект, что и в разборе маршрутов, из-за него живое правило не
    узнавалось, `ip rule add` отвечал `File exists`, а звено казалось не готовым."""
    rc, out, _ = _mr_cmd("ip", "-o", "rule", "show")
    if rc != 0:
        return []
    got = []
    for line in out.splitlines():
        if ("lookup " + _MR_TBL) not in line:
            continue
        prio = line.split(":", 1)[0].strip()
        m = re.search(r"to\s+([0-9a-fA-F.:]+)(?:/([0-9]+))?", line)
        if m and prio.isdigit():
            net, mask = m.group(1), m.group(2)
            net = net + (("/128" if ":" in net else "/32") if mask is None else "/" + mask)
            got.append((int(prio), net))
    return got


def _mr_routes():
    """Наши маршруты в таблице: {сеть: интерфейс}.

    Хостовый маршрут ядро печатает БЕЗ маски: `91.105.192.110 dev tgw0`, а не `.../32`.
    Прежний разбор требовал слэш с цифрой, из-за чего полностью собранное звено казалось
    пустым и пересобиралось каждый тик (живая находка этого цикла)."""
    rc, out, _ = _mr_cmd("ip", "-o", "route", "show", "table", _MR_TBL)
    if rc != 0:
        return {}
    got = {}
    for line in out.splitlines():
        m = re.match(r"^(?:v6\s+)?([0-9a-fA-F.:]+)(?:/([0-9]+))?\s+dev\s+(\S+)", line)
        if not m:
            continue
        net, mask = m.group(1), m.group(2)
        net = net + (("/128" if ":" in net else "/32") if mask is None else "/" + mask)
        got[net] = m.group(3)
    return got


def _mr_sync_cidrs(cidrs, reg):
    """Сводим правила, маршруты и набор адресов пиера к одному списку сетей.

    Разрешённые сети — это не только «куда слать», но и «что пускать обратно»: сузишь до
    одного адреса — и ответный трафик с прочих адресов тот же пиер погасит. Поэтому
    набор обновляем одной операцией вместе с маршрутами."""
    nets = [c + "/32" for c in cidrs]
    cur_rules = _mr_rules()
    have = set(n for _, n in cur_rules)
    used = set(p for p, _ in cur_rules)
    for prio, net in cur_rules:
        if net not in nets:
            _mr_cmd("ip", "rule", "del", "priority", str(prio))
            # освобождённый приоритет возвращается в оборот: иначе каждое изменение
            # набора целей уводит новое правило на шаг вверх и приоритеты ползут
            used.discard(prio)
    for net in nets:
        if net in have:
            continue
        prio = _MR_PRIO_BASE
        while prio in used:
            prio += 1
        rc, _, err = _mr_cmd("ip", "rule", "add", "priority", str(prio), "to", net,
                             "lookup", _MR_TBL)
        if rc != 0:
            return "правило не поставлено: " + err[:90]
        used.add(prio)
    rt = _mr_routes()
    for net in nets:
        if rt.get(net) != _MR_IF:
            # `replace`, а не `add`: маршрут умер вместе с падением линка, а правило
            # его пережило — без этой операции адрес навсегда остаётся напрямую.
            # Отказ молча гасить нельзя: на опущенном интерфейсе ядро отвечает
            # «сеть недоступна», и правило остаётся смотреть в пустую таблицу
            rc, _, err = _mr_cmd("ip", "route", "replace", net, "dev", _MR_IF,
                                 "src", reg["tunnel_v4"], "table", _MR_TBL)
            if rc != 0:
                return "маршрут не поставлен: " + err[:90]
    for net, dev in rt.items():
        if net not in nets and dev == _MR_IF:
            _mr_cmd("ip", "route", "del", net, "dev", _MR_IF, "table", _MR_TBL)
    if nets:
        rc, _, err = _mr_cmd("wg", "set", _MR_IF, "peer", reg["peer_public_key"],
                             "allowed-ips", ",".join(nets))
        if rc != 0:
            return err[:120]
    return ""


def _mr_link_ready(cidrs):
    """Поднято ли звено НА САНОМ ДЕЛЕ: интерфейс вверх, ключ стоит, пиру известен адрес
    облака, маршруты ведут в него.

    `ip link show` отвечает «есть» и на полуразобранное звено: после отказа `wg set`
    интерфейс остаётся созданным, но без ключа и без адреса пиера, а прежний код принимал
    такое за поднятое — медиа шло мимо туннеля, а панель рапортовала туннель (живая
    находка этого цикла)."""
    rc, out, _ = _mr_cmd("ip", "-o", "link", "show", _MR_IF)
    if rc != 0:
        return False
    if "UP" not in out.partition("<")[2].partition(">")[0].split(","):
        return False
    rc, out, _ = _mr_cmd("wg", "show", _MR_IF, "public-key")
    if rc != 0 or out.strip() in ("", "(none)"):
        return False
    rc, out, _ = _mr_cmd("wg", "show", _MR_IF, "endpoints")
    if rc != 0 or not out.strip() or "(none)" in out:
        return False
    rt = _mr_routes()
    return all(rt.get(c + "/32") == _MR_IF for c in cidrs)


def _mr_link_up(reg, cidrs):
    """Поднимаем интерфейс, вешаем пира, ключ отдаём на стандартный ввод.

    `/usr/bin/wg` в этом выпуске системы закрыт профилем ограничения доступа, и читать
    ему разрешено файлы только из `@{etc_rw}/wireguard`: любой другой путь — и отдельный
    файл, и дескриптор `/proc/self/fd/N` — отвечает «отказано в праве» (живая находка
    этого цикла; прежний код спотыкался именно здесь, а офлайн-фикстура этого не видела).
    Ключ из трубки не остаётся на диске и не виден в аргументах, которые читают чужие
    процессы."""
    rc, _, err = _mr_cmd("ip", "link", "add", _MR_IF, "type", "wireguard")
    if rc != 0 and "File exists" not in err:
        return "связь не создана: " + err[:90]
    _mr_cmd("ip", "-4", "addr", "replace", reg["tunnel_v4"] + "/32", "dev", _MR_IF)
    rc, _, err = _mr_cmd("wg", "set", _MR_IF, "private-key", "/dev/stdin",
                         "peer", reg["peer_public_key"],
                         "endpoint", "%s:%s" % (reg["endpoint"], reg["endpoint_port"]),
                         "allowed-ips", ",".join(c + "/32" for c in cidrs),
                         "persistent-keepalive", _MR_KEEP,
                         input=reg["private_key"] + "\n")
    if rc != 0:
        return "веер не настроен: " + err[:90]
    rc, _, err = _mr_cmd("ip", "link", "set", _MR_IF, "up", "mtu", _MR_MTU)
    if rc != 0:
        return "связь не поднята: " + err[:90]
    return _mr_sync_cidrs(cidrs, reg)


def _mr_handshake_age():
    """Сколько секунд назад было последнее рукопожатие (или нет, если звена нет).

    Пиер отвечает на сторожевой пакет, поэтому свежее рукопожатие значит «до облака
    достучаться можно», а не «до Telegram достучаться можно»: второе судим по подъёмам.
    Единочное число в `wg show` облако не принимает — живой ответ требует множественное
    `latest-handshakes` и отдаёт построчно «ключ пиера <TAB> метка времени»."""
    rc, out, _ = _mr_cmd("wg", "show", _MR_IF, "latest-handshakes")
    if rc != 0:
        return None
    ts = 0
    for line in out.splitlines():
        parts = line.split()
        if len(parts) < 2:
            continue
        try:
            ts = max(ts, int(parts[-1]))
        except ValueError:
            continue
    return int(max(0, time.time() - ts)) if ts > 0 else None


def _mr_carries(addr):
    """Несёт ли звено: один пакет до адреса, который обязан идти через туннель.

    Нулевого рукопожатия для приговора мало: `wg` сам шлёт инициацию только когда
    появится трафик или сторожевой пакет, поэтому молчание проверяем пакетом. Цена —
    до `2` секунд в тике и только когда рукопожатие не свежее. Мерить нечем (нет `ping`)
    — это не доказательство молчания: звено остаётся там, где его поставили."""
    try:
        rc, _, err = _mr_cmd("ping", "-c1", "-W2", "-I", _MR_IF, addr)
    except (OSError, subprocess.SubprocessError):
        return True
    if rc == 127 or "not found" in err:
        return True
    return rc == 0


def _mr_tick():
    """Страховка медиа-пути: один шаг за тик, вне замка состояния (ходит в командную строку).

    Порядок обязан быть таким: без желания оператора — разобрать; без аккаунта — завести;
    с молчащим звеном — снять правила и уйти напрямую, иначе адреса останутся в правилах,
    которые никуда не ведут."""
    global _MR_ERR
    if SBX:
        return
    st = _load(_MR_STATE, {}) or {}
    if not _mr_want():
        if st.get("targets") or st.get("up") or st.get("enabled"):
            _mr_flush_rules()
            _mr_cmd("ip", "link", "del", _MR_IF)
            _save(_MR_STATE, {"enabled": False, "targets": {}, "up": False,
                              "ts": _now_iso()}, 0o600)
        return
    cidrs, cur = _mr_want_eps()
    reg, why = _mr_registered(), ""
    if not reg:
        reg, why = _mr_register()
    if not reg or not cidrs:
        # нечего вести, или аккаунта нет: связи нет вовсе — ни правил, ни сторожевых пакетов
        _mr_flush_rules()
        _mr_cmd("ip", "link", "del", _MR_IF)
        err = "" if reg else (why or "аккаунта нет")
        _MR_ERR = err
        _save(_MR_STATE, {"enabled": True, "targets": cur, "up": False, "count": 0,
                          "handshake_age": None, "error": err, "ts": _now_iso()}, 0o600)
        return
    rc, _, _ = _mr_cmd("ip", "link", "show", _MR_IF)
    age = _mr_handshake_age()
    # звено пересобирается, если оно не просто существует, а НЕ готово нести: после
    # любого отказа `wg set` интерфейс остаётся полусобранным, и прежний код считал его
    # поднятым (живая находка этого цикла)
    rebuilt = (rc != 0 or not _mr_link_ready(cidrs))
    if rebuilt:
        err = _mr_link_up(reg, cidrs)
        age = _mr_handshake_age()
    else:
        err = _mr_sync_cidrs(cidrs, reg)
    if err == "" and (age is None or age > 4 * int(_MR_KEEP)) and not _mr_carries(cidrs[0]):
        # молчание судим пакетом, а не отсутствием рукопожатия: сам `wg` шлёт инициацию,
        # только когда появится трафик или сторожевой пакет (замерено: живой пиер
        # отвечает на первый же пакет через tgw0, мёртвый не отвечает ни на один)
        _mr_flush_rules()
        _mr_cmd("ip", "link", "del", _MR_IF)
        err, age = "звено молчит: до облака нет ответа", None
        rebuilt = True
        err = _mr_retire(err)
    up = (err == "")
    now = time.time()
    # момент, с которого звено несёт трафик: раньше него замер сделан напрямую, и сравнить
    # его с «потерей в туннеле» нельзя — это и был ложный откат на живой коробке. Пересборка
    # звена отодвигает этот момент вперёд: замеры к прежнему туннелю не относятся
    since = (now if (up and (rebuilt or not st.get("up")))
             else (float(st.get("up_since") or 0) if up else 0))
    _MR_ERR = err
    _save(_MR_STATE, {"enabled": True, "targets": cur, "up": up, "handshake_age": age,
                      "up_since": since,
                      "tunnel_v4": (reg["tunnel_v4"] if up else ""),
                      "count": (len(cidrs) if up else 0), "error": err,
                      "ts": _now_iso()}, 0o600)


def _mr_view():
    """Снимок для морды и ноги самопроверки: только чтение, ничего не поднимает."""
    st = _load(_MR_STATE, {}) or {}
    rc, _, _ = _mr_cmd("ip", "link", "show", _MR_IF)
    tg = st.get("targets") or {}
    now = time.time()
    tun = sorted(h for h, e in tg.items() if (e or {}).get("mode") == "tunnel")
    # отбракованные писателями адреса называем их меркой: без числа строка выглядела бы
    # как «туннель не поднят», а это решение замера, а не авария
    ret = sorted((h, str((e or {}).get("writers") or "")) for h, e in tg.items()
                 if (e or {}).get("why") == "writers"
                 and float((e or {}).get("banned_until") or 0) > now)
    return {"want": _mr_want(), "account": bool(_mr_registered()), "link": rc == 0,
            "ready": _mr_link_ready(tun),
            "up": bool(st.get("up")), "targets": sorted(tg.keys()),
            "tunneled": tun,
            "retired": [h for h, _w in ret],
            "retired_writers": ", ".join(w for _h, w in ret if w),
            "starve_ticks": _MR_STARVE,
            "starve_ban_h": int(_MR_STARVE_BAN // 3600),
            "count": int(st.get("count") or 0), "handshake_age": st.get("handshake_age"),
            "error": st.get("error") or _MR_ERR, "ts": st.get("ts"),
            "max": _MR_MAX, "loss_pct": int(_MR_LOSS), "giveup_pct": int(_MR_GIVEUP)}


# ---------- ME: вход в сеть Telegram и его аварийные пути (#218) ----------
# ME (`middle proxy`) — не «ещё один протокол», а входная точка, через которую движок
# добирается до сети Telegram: у неё больше адресов и лучше разгрузка, чем у прямого
# пути к дата-центру. Медиа-узлы живут в подписанных списках ME отдельными группами
# (у них отрицательный номер DC); прямой путь их не знает: `direct_relay/routing.rs`
# ищет оверрайд по строке `-203`, не находит и с предупреждением съедает запрос на
# «кластер по умолчанию». Отсюда #193: текст ходит, картинки и видео — нет.
# Ключей три: `use_middle_proxy` — сам вход, `me2dc_fallback` — разрешение уехать на
# прямой DC, `me2dc_fast` — бюджет быстрых попыток; по коду движка он активен ТОЛЬКО
# вместе с `fallback` (`admission.rs:42`), то есть один он не значит ничего. Важное, чего
# по ключам не видно: при включённом `fallback` движок СТАРТУЕТ в Direct и добирает ME в
# фоне (`runtime_build.rs:131`), поэтому «ME включён» ещё не значит «сессии идут через
# ME» — это отдельный факт, и движок сам его отдаёт на `/v1/runtime/gates`.
# Замер в песочнице (06.10, варианты A0–A3, живую службу не трогали): `/v1/config`
# отдаёт 142 ЭФФЕКТИВНЫХ ключа `general` — отсутствующий в файле приходит как дефолт
# движка, а все три дефолта `true`. Значит «кто выключил» судит текст файла, а «чем
# живёт сейчас» — только API. Пустой `/v1/stats/dcs` в первые секунды — прогрев: карта
# появилась на замере через 8 с, а при `use_middle_proxy = false` не появилась вовсе.
# Границу прогрева меряем не на глаз: у движка `STARTUP_FALLBACK_AFTER = 80 с` до
# первого ready и `RUNTIME_FALLBACK_AFTER = 6 с` после (`admission.rs:13-14`).
_TG_ME_KEYS = ("use_middle_proxy", "me2dc_fallback", "me2dc_fast")
_TG_ME_GRACE = 80.0
# Ключи, которые движок разбирает, но в рантайме не читает: проверка по всей коробке —
# упоминания только в `src/config` (объявление, дефолт, список известных ключей). В
# нашем `telemt.toml` они написаны (`true` и `2`), и полагаться на них как на защиту
# нельзя: настоящим съездом на Direct правят `me2dc_fallback`/`me2dc_fast` в
# `admission.rs`.
_TG_ME_DECOR = ("auto_degradation_enabled", "degradation_min_unavailable_dc_groups")


def _telemt_start_ts():
    """Epoch-время подъёма процесса telemt (0 — не известно).

    Monotonic-часы ядра и `/proc/uptime` берутся вместе, как в `_xray_start_ts`: у
    отметки systemd нет часового пояса, и на сервере с не-UTC поясом она врёт на часы —
    ровно на столько, чтобы спутать прогрев с аварией."""
    try:
        r = subprocess.run(["systemctl", "show", "telemt",
                            "-p", "ExecMainStartTimestampMonotonic", "--value"],
                           capture_output=True, text=True, timeout=10)
        mono = int((r.stdout or "0").strip()) / 1e6
        with open("/proc/uptime") as f:
            up = float(f.read().split()[0])
        if mono <= 0:
            return 0.0
        return time.time() - (up - mono)
    except Exception:
        return 0.0


def _tg_general_file_values(keys):
    """Значения ключей, БУКВАЛЬНО написанных в `[general]` файла telemt.toml.

    Нужен именно файл: API доподставляет дефолты, и по нему не отличить «оператор
    включил» от «оператор не трогал». Ключ вне `[general]` не считается — движок читает
    их только там. Отдаём строку как есть: значения бывают и булевы, и числа —
    `degradation_min_unavailable_dc_groups = 2` живой файл тоже задаёт."""
    try:
        text = _tg_manual_read_toml()
    except Exception:
        return {}
    out, sect = {}, ""
    for line in (text or "").splitlines():
        s = line.strip()
        if s.startswith("[") and s.endswith("]"):
            sect = s.strip("[]").strip().strip('"').strip().lower()
            continue
        if sect != "general" or "=" not in s or s.startswith("#"):
            continue
        k, _, v = s.partition("=")
        k = k.strip().strip('"').lower()
        if k in keys:
            out[k] = v.split("#", 1)[0].strip().strip('"')
    return out


def _tg_me_file_values():
    """Три ME-ключа из файла как `True`/`False`; `None` — написано не булево.

    Ключа в файле нет — его здесь тоже нет, то есть живёт на дефолте движка."""
    out = {}
    for k, v in _tg_general_file_values(_TG_ME_KEYS).items():
        low = v.lower()
        out[k] = (low == "true") if low in ("true", "false") else None
    return out


def _tg_me_state():
    """Сводка про ME для диагностики: включён ли вход, чем движок ведёт сессии сейчас.

    Ничего не переключает и не «починяет» молча: явный `false` — выбор оператора, и
    панель обязана его назвать, а не переписать. Поля: три ключа (`file` — что написано
    в файле, `None` — ключа нет и живёт на дефолте движка), `off_by` (кто выключил),
    `fast_inert` (быстрые попытки есть, а резервного пути нет), `gates` (ответ
    `/v1/runtime/gates`: режим маршрутизации, готовность пула, стадия старта), `map`
    (карта `/v1/stats/dcs`, разделённая на медиа-узлы с отрицательным номером и
    основные), `age`/`warm` (возраст юнита и порог прогрева), `direct` (вход включён,
    а новые сессии идут мимо ME), `silent` (вход включён, карты нет, прогрев прошёл),
    `decor` (ключи, которые движок разбирает, но не читает) и `note` — вердикт короткой
    строкой, чтобы влез в самопроверку."""
    st = {"error": "", "map": {}, "gates": {}, "file": {}, "decor": []}
    try:
        g = (_tg_api("GET", "/v1/config").get("data") or {}).get("general") or {}
    except Exception as e:
        g = {}
        st["error"] = str(e)[:120]
    fv = _tg_me_file_values()
    st["file"] = {k: fv.get(k) for k in _TG_ME_KEYS}
    off_by = ""
    for k in _TG_ME_KEYS:
        eff = g.get(k)
        st[k] = bool(eff) if eff is not None else bool(fv.get(k, True))
        if fv.get(k) is False:
            off_by = off_by or "файл telemt.toml"
        elif eff is False:
            off_by = off_by or "рантайм движка (в файле этого нет)"
    st["off_by"] = off_by
    st["fast_inert"] = bool(st["me2dc_fast"] and not st["me2dc_fallback"])
    dfv = _tg_general_file_values(_TG_ME_DECOR)
    st["decor"] = ["%s = %s" % (k, dfv[k]) for k in _TG_ME_DECOR if k in dfv]
    try:
        gt = _tg_api("GET", "/v1/runtime/gates").get("data") or {}
        st["gates"] = {"route": str(gt.get("route_mode") or ""),
                       "reroute": bool(gt.get("reroute_active")),
                       "reason": str(gt.get("reroute_reason") or ""),
                       "ready": bool(gt.get("me_runtime_ready")),
                       "fast_live": bool(gt.get("me2dc_fast_enabled")),
                       "startup": str(gt.get("startup_status") or ""),
                       "progress": round(float(gt.get("startup_progress_pct") or 0.0), 1),
                       "accepting": bool(gt.get("accepting_new_connections")),
                       "since": int(gt.get("reroute_to_direct_at_epoch_secs") or 0)}
    except Exception as e:
        # Старый движок без `/v1/runtime/gates` — не авария, а отсутствие меры: тогда
        # про режим судим по карте и ключам, и говорим это прямо.
        if not st["error"]:
            st["error"] = str(e)[:120]
    try:
        d = _tg_api("GET", "/v1/stats/dcs").get("data") or {}
        dcs = d.get("dcs") or []
        media = [x for x in dcs if _tg_dc_media(x.get("dc"))]
        main = [x for x in dcs if not _tg_dc_media(x.get("dc"))]

        def _cnt(xs, key):
            return sum(_tg_dc_size(x.get(key)) for x in xs)

        # Живые писатели против требуемых — то, о чём движок сам предупреждает
        # «ME init incomplete: no live writers for DC groups»: узел есть в карте, а
        # поднимать соединения ему некому. Считаем только медиа-узлы: их потеря и есть #193.
        st["map"] = {"enabled": bool(d.get("middle_proxy_enabled")),
                     "rows": len(dcs),
                     "media_rows": len(media), "media_eps": _cnt(media, "endpoints"),
                     "media_avail": _cnt(media, "available_endpoints"),
                     "media_short": sum(1 for x in media if _tg_dc_size(x.get("alive_writers"))
                                        < _tg_dc_size(x.get("required_writers"))),
                     "main_rows": len(main), "main_eps": _cnt(main, "endpoints"),
                     "main_avail": _cnt(main, "available_endpoints"),
                     "generated": int(d.get("generated_at_epoch_secs") or 0)}
    except Exception as e:
        if not st["error"]:
            st["error"] = str(e)[:120]
    ts = _telemt_start_ts()
    st["age"] = int(time.time() - ts) if ts else None
    gt = st["gates"]
    if gt:
        st["warm"] = bool(gt.get("startup") != "ready" and ts
                          and (time.time() - ts) < _TG_ME_GRACE)
    else:
        st["warm"] = bool(ts and (time.time() - ts) < _TG_ME_GRACE)
    st["direct"] = bool(st["use_middle_proxy"] and gt.get("reroute"))
    # Пустая карта по причине «API не ответил» — это не «пул не собран»: врать про
    # движок, когда нечем мерить, дороже молчания.
    st["silent"] = bool(st["use_middle_proxy"] and st["map"]
                        and not st["map"].get("media_rows") and not st["warm"])
    m = st["map"]
    if not st["use_middle_proxy"]:
        st["note"] = "вход в сеть Telegram (ME) выключен — %s" % (off_by or "чем-то")
    elif st["direct"]:
        st["note"] = "ME включён, но новые сессии идут напрямую (%s)" % (gt.get("reason") or "причина не названа")
    elif st["silent"]:
        st["note"] = "ME включён, но ни одного адреса сети Telegram движок не раздаёт"
    elif m.get("media_short"):
        st["note"] = "под медиа-узлов %d из %d живых писателей меньше, чем движок требует" % (
            m["media_short"], m.get("media_rows"))
    elif m.get("media_eps") and m.get("media_avail") is not None \
            and m["media_avail"] < m["media_eps"]:
        st["note"] = "вход держится, но медиа-адресов доступно %d из %d" % (
            m["media_avail"], m["media_eps"])
    elif m.get("media_rows"):
        st["note"] = "вход держится: через ME %d медиа-узлов, %d адресов" % (
            m.get("media_rows"), m.get("media_eps"))
    else:
        st["note"] = "режим не прочитан: %s" % (st["error"] or "ответ пустой")
    return st


def _tg_mp_selftest(force=False):
    """«MTProto под VPN» — самотест: помнит ли мир нашу беду (petlya-2026-09).
    1) facade-рукопожатие на свой публичный :7443 (v4 и v6) — путь клиента под VPN
       приходит в этот же порт, но через xray; 2) sniffing xray обязан исключать все
       фронты, иначе destination перезапишется SNI и сервер начнёт долбить чужой CDN
       на мёртвом порту (SYN-шторм); 3) synfix: свои SYN не должны упираться в лимит;
       4) сайт-маска (если настроена) — живой сертификат на :443. Кэш 60 с."""
    if not force and _MPST["res"] and time.time() - _MPST["ts"] < 60:
        return _MPST["res"]
    checks = []
    def add(id_, label, ok, detail="", warn=False):
        checks.append({"id": id_, "label": label, "ok": bool(ok),
                       "detail": (detail or "")[:200], "warn": bool(warn)})
    if not _tg_available():
        res = {"ok": False, "ran": int(time.time()),
               "checks": [{"id": "telemt", "label": "Прокси жив", "ok": False,
                           "detail": "telemt API не отвечает — сначала включи MTProto-прокси",
                           "warn": False}]}
        _MPST.update(ts=time.time(), res=res)
        return res
    add("telemt", "Прокси жив", True, "")
    try:
        port = int(_tg_mtproto_info().get("port") or 0)
    except Exception:
        port = 0
    add("listener", "Публичный MTProto-порт", bool(port),
        (":%d" % port) if port else "публичный listener не найден")
    if not port:
        res = {"ok": False, "ran": int(time.time()), "checks": checks}
        _MPST.update(ts=time.time(), res=res)
        return res
    fronts = _veil_front_domains()
    # Имя для рукопожатия берём по приоритету: сначала имя маршрута (под ним едут свежие
    # ссылки), затем фасад, который называет сам движок, и лишь потом фронт веб-прокси.
    # Очередь начиналась с `front_domain`, и проверка светилась именем веб-прокси, хотя
    # MTProto шёл под другим: галочка была зелёной, но доказывала чужое имя (#185).
    sni = ""
    whence = ""
    for cand, label in ((_tg_advertised_host(), "имя маршрута"),
                        (_tg_sni().get("tls_domain"), "фасад движка"),
                        (CFG_CACHE.get("front_domain"), "фронт веб-прокси")):
        v = (cand or "").strip().lower()
        if v:
            sni, whence = v, label
            break
    if not sni:
        sni, whence = ((fronts[0] if fronts else "www.microsoft.com").strip().lower(),
                       "первый фронт движка")
    gate = "общий :443" if port == 443 else "прежний слушатель :%d" % port
    for ip, fam in ((_pub_ip4(), "IPv4"), (_pub_ip6(), "IPv6")):
        if not ip:
            add("tls_" + fam.lower(), "Facade-рукопожатие %s" % fam, True,
                "сервер без %s — пропускаем" % fam, warn=True)
            continue
        if fam == "IPv6" and not _tg_mp_ipv6_want():
            # Живой замер (`l42`, 05.10): на коробке с `tg_mp_ipv6` снятым проверка
            # краснела («Connection refused»), хотя слушателя `::` нет по воле оператора.
            # Спрашивать нечего — и это не поломка: кого касается, тот назван проверкой
            # «Клиенты едут под именем маршрута».
            add("tls_ipv6", "Facade-рукопожатие IPv6", True,
                "IPv6 у MTProto погашен переключателем — слушателя `::` нет, спрашивать "
                "нечего", warn=True)
            continue
        ok, detail = _tls_probe(ip, port, sni)
        add("tls_" + fam.lower(), "Facade-рукопожатие %s на %s:%d (SNI=%s — %s; %s)"
            % (fam, ip, port, sni, whence, gate), ok, detail)
    try:
        with open(XRAY, encoding="utf-8") as f:
            xc = json.load(f)
        need = set(fronts)
        bad = []
        n_inb = 0
        for ib in xc.get("inbounds", []):
            sn = ib.get("sniffing") or {}
            if not sn.get("enabled"):
                continue
            n_inb += 1
            miss = need - set(d.lower() for d in (sn.get("domainsExcluded") or []))
            if miss:
                bad.append("%s: нет %s" % (ib.get("tag") or ib.get("port"), ",".join(sorted(miss))))
        add("sniffing", "Xray: фронты исключены из подмены адресов", not bad and n_inb > 0,
            ("all %d inbound'ов в порядке" % n_inb) if not bad and n_inb else
            ("; ".join(bad[:4]) if bad else "ни одного inbound со sniffing — странно"))
    except Exception as e:
        add("sniffing", "Xray: фронты исключены из подмены адресов", False, str(e)[:160])
    try:
        t = subprocess.run(["nft", "list", "table", "inet", "veil_synfix"],
                           capture_output=True, text=True, timeout=10)
        txt = t.stdout or ""
        has_own = ("local_accept" in txt) and (("local6_accept" in txt) or not _pub_ip6())
        has_lim = ("other_accept" in txt) and (("other6_accept" in txt) or not _pub_ip6())
        # #170: «таблица есть» ещё не значит «таблица верная» — правила могли остаться на
        # старом наборе портов, пока авто-список уехал (маршрут MTProto на :443).
        want = tuple(_synfix_ports()["want"])
        live = _synfix_live()[0]
        drift = want != live
        ok = t.returncode == 0 and has_own and has_lim and not drift
        add("synfix", "Защита SYN-лимитов: свои проходят, чужие нормируются", ok,
            "" if ok else ("%s%s" % (
                "" if t.returncode == 0 and has_own and has_lim else
                "нет таблицы veil_synfix или правил (v4/v6) accept/лимит для своих и чужих; ",
                ("живые порты %s, должно быть %s" % (list(live) or "пусто", list(want))
                 if drift else ""))))
    except Exception as e:
        add("synfix", "Защита SYN-лимитов", False, str(e)[:160])
    try:
        fs = _front_status()
        if fs.get("domain"):
            add("front", "Сайт-маска (свой фронт)", fs.get("active") and fs.get("https_ok"),
                "%s: cert %s, %s" % (fs["domain"], "ок" if fs.get("cert_ok") else "НЕТ",
                                      "отвечает на :443" if fs.get("https_ok") else "на :443 не отвечает"))
        else:
            add("front", "Сайт-маска (свой фронт)", True,
                "не настроена — прокси прячется за чужим фронтом; кнопка «Настроить сайт-маску» ниже",
                warn=True)
    except Exception:
        pass
    try:
        mm = _tg_manual_status()
        if mm:
            bad = [x for x in mm if not x["ok"]]
            add("manual", "Разданные ссылки держатся побайтно", not bad,
                ("все %d на месте" % len(mm)) if not bad else
                "; ".join("%s — %s" % (x["username"], x["detail"]) for x in bad[:3]))
    except Exception as e:
        add("manual", "Разданные ссылки держатся побайтно", False, str(e)[:160])
    # #180: десктоп держит ссылку, выданную до маршрута `mp` на :443. Такая ссылка не
    # сломана — она просто едет другой дорогой, и по имени из секрета. Самотест обязан
    # назвать этих клиентов, иначе «не работает прокси» выглядит как поломка telemt.
    # Сверяемся с ОТДАВАЕМОЙ ссылкой (`_tg_status`), а не с выдачей telemt: розданную вручную
    # (#158) клиент держит побайтно, и именно она может быть прежнего фронта.
    try:
        mp = _tg_mp_domain_on()
        if mp:
            stray = [u.get("username") or "?" for u in (_tg_status().get("users") or [])
                     if u.get("link") and not u.get("on443")]
            add("mp_front", "Клиенты едут под именем маршрута", not stray,
                ("%d из списка — ссылка прежнего фронта: на :443 не едет, живёт на порту "
                 "слушателя: %s" % (len(stray), ", ".join(stray[:5]))) if stray else
                ("все под %s" % mp), warn=True)
    except Exception as e:
        add("mp_front", "Клиенты едут под именем маршрута", False, str(e)[:160], warn=True)
    # #218: ME — вход в сеть Telegram, а не «ещё один узел». Без него клиент держит
    # сессию и читает текст, а фото, видео и истории не грузятся: тяжёлый трафик идёт
    # через ME к медиа-узлам, у них отрицательный номер DC. Панель вход ни гасит, ни
    # включает молча — она обязана назвать, кто его выключил, и жив ли аварийный путь.
    try:
        ms = _tg_me_state()
        mmap = ms.get("map") or {}
        gt = ms.get("gates") or {}
        parts = []
        if not ms["use_middle_proxy"]:
            parts.append("вход выключен — %s; медиа не будут грузиться"
                         % (ms.get("off_by") or "чем-то"))
        elif ms["direct"]:
            parts.append("новые сессии идут мимо ME (%s): текст ходит, картинки и видео — нет"
                         % (gt.get("reason") or "причина не названа"))
        elif ms["silent"]:
            parts.append("движок не раздаёт ни одного адреса сети Telegram")
        elif mmap.get("media_short"):
            parts.append("у %d медиа-узлов живых писателей меньше, чем требует движок"
                         % mmap["media_short"])
        elif mmap.get("media_eps") and mmap.get("media_avail") is not None \
                and mmap["media_avail"] < mmap["media_eps"]:
            parts.append("медиа-адресов доступно %d из %d"
                         % (mmap["media_avail"], mmap["media_eps"]))
        if ms["warm"] and not mmap.get("media_rows"):
            parts.append("старт %d с назад, ME инициализирован на %d%%"
                         % (ms.get("age") or 0, gt.get("progress") or 0))
        if ms.get("fast_inert"):
            parts.append("быстрые попытки включены, а резервного пути нет — они ничего не дают")
        elif not ms["me2dc_fallback"]:
            parts.append("резервного пути нет — при отказе ME клиент не получит даже текст")
        if ms.get("error") and not mmap:
            parts.append("карту не прочитали: %s" % ms["error"])
        if ms.get("decor"):
            parts.append("на %s как на защиту полагаться нельзя: движок их разбирает и не читает"
                         % ", ".join(ms["decor"]))
        ok = bool(ms["use_middle_proxy"] and not ms["direct"] and not ms["silent"])
        add("me", "Вход в сеть Telegram (ME) и аварийные пути", ok,
            "; ".join(parts) if parts else (ms.get("note") or ""), warn=ok and bool(parts))
    except Exception as e:
        add("me", "Вход в сеть Telegram (ME) и аварийные пути", False, str(e)[:160], warn=True)
    try:
        # #193: медиа может идти и через туннель, и напрямую. Гаснет туннель — трафик
        # уходит напрямую сам, и это не авария; авария — когда оператор просил туннель,
        # а медиа идёт мимо него.
        mv = _mr_view()
        if not mv["want"]:
            add("media_route", "Медиа-путь к узлам Telegram через туннель", True,
                "выключен — медиа идёт напрямую", warn=True)
        elif mv.get("retired") and not mv["tunneled"]:
            # Туннель отбракован замером писателей: это не авария звена, а решение, и
            # краснеть тут не за чем. Но без числа оператор увидел бы либо молчание,
            # либо «туннель не поднят» там, где его отключил сам замер (#221).
            add("media_route", "Медиа-путь к узлам Telegram через туннель", True,
                "туннель отбракован писателями: %s — %d адрес(ов) идут напрямую, медиа "
                "грузится" % (mv.get("retired_writers") or "ни одного писателя",
                              len(mv["retired"])), warn=True)
        else:
            bits = []
            if mv["up"] and mv["ready"]:
                bits.append("%d адрес(ов) в туннеле, рукопожатие %s с назад"
                            % (len(mv["tunneled"]), mv.get("handshake_age")))
            elif mv["up"]:
                bits.append("звено собрано неполностью: маршрутов или ключа нет")
            else:
                bits.append(mv.get("error") or "туннель не поднят")
            if not mv["account"] and not any("аккаунт" in x for x in bits):
                bits.append("аккаунта облака нет")
            add("media_route", "Медиа-путь к узлам Telegram через туннель",
                bool(mv["up"] and mv["ready"]),
                "; ".join(bits), warn=bool(mv["up"]) and bool(mv.get("error")))
    except Exception as e:
        add("media_route", "Медиа-путь к узлам Telegram через туннель", False,
            str(e)[:160], warn=True)
    # #180: TCP от клиента проходит весь путь — :443, развилка по SNI, слушатель, — и сессии
    # всё равно нет: узел сам не дотягивается до адресов Telegram. Это не поломка прокси, и
    # называть её поломкой прокси значит гонять хозяина по неверному следу. Жалобы берём у
    # самого telemt, а не из вбитого списка адресов (Telegram их меняет), и обязательно
    # подтверждаем своей пробой: вчерашняя авария не должна светиться красным сегодня.
    try:
        bad, err = _tg_dc_complaints()
        lv = _tg_dc_loss_view()
        lossy = [r for r in lv["rows"] if not r["stale"] and (r.get("loss") or 0) >= 20]
        # Медиа-узел называем отдельно: с ним не доходит именно тяжёлый трафик,
        # и «прокси работает, а картинки нет» (#193) иначе выглядит противоречием.
        lost = ", ".join("%s%s — %d из %d подъёмов не дошли"
                         % ("медиа-адрес " if r.get("media") else "",
                            r["ep"], r["fail"], r["total"])
                         for r in lossy[:2])
        dead = []
        for (h, p), n in bad[:2]:
            if all(not _hop_public(h, p, timeout=2.5) for _ in range(2)):
                dead.append("%s:%d (%d жалоб)" % (h, p, n))
        said = ", ".join("%s:%d×%d" % (h, p, x) for (h, p), x in bad[:2])
        if dead:
            add("dc", "Путь этого сервера к Telegram", False,
                "нет пути отсюда: %s — прокси принимает клиента, но сам узел не достучится "
                "до Telegram; на этом протоколе сессия не держится%s" %
                (", ".join(dead), (", а по нашему замеру %s" % lost) if lost else ""))
        elif lossy:
            note = "telemt не жаловался" if not bad else \
                "жалобы были (%s), но сейчас отвечает" % said
            add("dc", "Путь этого сервера к Telegram", True,
                "%s, а по нашему замеру %s" % (note, lost), warn=True)
        elif err:
            add("dc", "Путь этого сервера к Telegram", True,
                "не измерено: %s" % err, warn=True)
        elif not bad:
            add("dc", "Путь этого сервера к Telegram", True,
                "telemt не жаловался за 10 минут")
        else:
            add("dc", "Путь этого сервера к Telegram", True,
                "жалобы были (%s), но сейчас отвечает — путь неустойчив" % said,
                warn=True)
    except Exception as e:
        add("dc", "Путь этого сервера к Telegram", False, str(e)[:160], warn=True)
    res = {"ok": all(c["ok"] for c in checks), "ran": int(time.time()), "checks": checks}
    _MPST.update(ts=time.time(), res=res)
    return res

def _tg_mp_firewall_open(port):
    """Best-effort: открыть порт в `firewalld`, если он активен. Молча игнорируем отсутствие."""
    try:
        if subprocess.run(["bash", "-c",
                           "command -v firewall-cmd >/dev/null && firewall-cmd --state >/dev/null 2>&1"],
                          capture_output=True, timeout=10).returncode == 0:
            subprocess.run(["firewall-cmd", "--permanent", "--add-port=%d/tcp" % port], capture_output=True, timeout=15)
            subprocess.run(["firewall-cmd", "--reload"], capture_output=True, timeout=15)
            return True
    except Exception:
        pass
    return False

_SSH_SOCKET_DROPIN = "/etc/systemd/system/ssh.socket.d/veil-port.conf"
_SSHD_PORT_DROPIN = "/etc/ssh/sshd_config.d/61-veil-port.conf"
_VEIL_SSH_NFT = "/etc/netfilter/veil-ssh.nft"
_VEIL_SSH_GUARD = "veil-ssh-guard"


def _ssh_socket_listen_ports():
    """Порты, которые ДЕРЖИТ живой сокет `ssh.socket` (рантайм-свойство `Listen=…`,
    `0.0.0.0:22 (Stream)`). Пусто — значит сокет ничего не слушает и порт держит сам
    sshd (классический запуск). Именно непустой ответ и есть признак сокет-активации:
    systemd владеет fd листнера, а конфиг-`Port` для такого sshd игнорируется.

    Свойство называется по-разному на версиях systemd: рантайм-лист кушает `Listen=`,
    а `ListenStream=` может отдаваться пустым — пробуем оба."""
    ports = []
    for prop in ("Listen", "ListenStream"):
        try:
            r = subprocess.run(["systemctl", "show", "ssh.socket", "-p", prop, "--value"],
                               capture_output=True, text=True, timeout=10)
            if r.returncode == 0:
                for tok in (r.stdout or "").split():
                    m = re.search(r":(\d+)$", tok.strip())
                    if m:
                        ports.append(int(m.group(1)))
        except Exception:
            pass
        if ports:
            break
    return sorted(set(ports))


def _ssh_effective_ports():
    """Порт(ы), которые реально слушает ssh. Первичный источник — живой сокет (он держит
    fd при сокет-активации). Если сокет молчит, ориентируемся на `Port` в sshd-конфиге
    (классический запуск sshd.service), иначе по умолчанию 22."""
    ports = _ssh_socket_listen_ports()
    if ports:
        return ports
    ports = []
    import glob as _glob
    for path in ["/etc/ssh/sshd_config"] + sorted(
            _glob.glob("/etc/ssh/sshd_config.d/*.conf")):
        try:
            for m in re.finditer(r"(?m)^\s*Port\s+(\d+)\b", open(path, encoding="utf-8",
                                                                 errors="replace").read()):
                ports.append(int(m.group(1)))
        except Exception:
            continue
    return sorted(set(ports)) or [22]


def _ssh_banner_ok(port, host="127.0.0.1", timeout=6):
    """Дошёл ли sshd до нового порта: читать приветствие `SSH-…`. Проба по петлевому
    адресу — гард `veil_ssh` пропускает `lo` и не мешает; сам баннер доказывает, что
    листнер поднялся и sshd его обслуживает (а не просто порт занят чем-то чужим)."""
    try:
        with socket.create_connection((host, int(port)), timeout=timeout) as s:
            s.settimeout(timeout)
            data = s.recv(64)
        return data.startswith(b"SSH-")
    except Exception:
        return False


def _ssh_nft_set_ports(txt, ports):
    """Переписать все правила `dport` в `veil-ssh.nft` на набор `ports` (один — литерал,
    несколько — множество `{ a, b }`). Управляемый нами файл содержит ТОЛЬКО ssh-dport,
    поэтому перезапись всех вхождений безопасна и идемпотентна для заданного набора."""
    expr = str(ports[0]) if len(ports) == 1 else ("{ " + ", ".join(str(p) for p in ports) + " }")
    txt = re.sub(r"(\bdport\s+)\d+(?!\d)", lambda m: m.group(1) + expr, txt)
    txt = re.sub(r"(\bdport\s+)\{[^}]*\}", lambda m: m.group(1) + expr, txt)
    return txt


def _ssh_guard_apply():
    """Переподнять гард из файла (ExecStart юнита сносит таблицу и грузит заново). Если
    юнита нет — молча пропустить: значит автономной защиты sshd-порта на машине нет."""
    if not os.path.exists(_VEIL_SSH_NFT):
        return False
    try:
        subprocess.run(["systemctl", "restart", _VEIL_SSH_GUARD], capture_output=True,
                       timeout=40)
        return True
    except Exception:
        return False


def _ssh_port_status():
    ports = _ssh_effective_ports()
    sock_ports = _ssh_socket_listen_ports()
    nft = ""
    try:
        if os.path.exists(_VEIL_SSH_NFT):
            nft = open(_VEIL_SSH_NFT, encoding="utf-8", errors="replace").read()
    except Exception:
        nft = ""
    guarded = [p for p in ports if re.search(r"\bdport\s+(?:%s\b|\{[^}]*\b%s\b)" % (p, p), nft)]
    return {"ports": ports, "current": ports[0] if len(ports) == 1 else None,
            "socket_active": _unit_active("ssh.socket"),
            # Признак сокет-активации — сам сокет держит листнер (непустой `Listen=`),
            # а НЕ «ssh.service выключен»: при сокет-активации сервис честно активен.
            "socket_activation": bool(sock_ports),
            "guard_unit": _unit_active(_VEIL_SSH_GUARD), "guard_managed": bool(nft),
            "guarded_ports": guarded, "reserved": sorted(_RESERVED_PORTS)}


def _ssh_port_set(new_port, confirm=False, user=None):
    """Сменить локальный порт sshd без самоблокировки: двойной бинд → проверка нового →
    перенос гарда → кут-овер; при любой неудаче — авто-откат к снапшоту. Старый слушатель
    не снимается, пока новый не доказан баннером, поэтому доступ теряется только если откажет
    и новый, и восстановление снапшота (тогда остаётся открытая сессия/консоль провайдера).
    Все мутации под `_STATE_LOCK` (вызывающий), `confirm` обязателен."""
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    try:
        new_port = int(new_port)
    except (TypeError, ValueError):
        raise RuntimeError("порт должен быть числом")
    if not (1 <= new_port <= 65535):
        raise RuntimeError("порт вне диапазона 1..65535")
    if new_port in _RESERVED_PORTS:
        raise RuntimeError("порт %d зарезервирован панелью (веб/xray/mtproto)" % new_port)
    cur = _ssh_effective_ports()
    old = cur[0] if cur else 22
    if new_port == old:
        raise RuntimeError("новый порт совпадает с текущим (%d)" % new_port)
    occ = _sock_occupant(new_port)
    if not occ.get("free"):
        raise RuntimeError("порт :%d уже занят %s — выберите другой" % (new_port, occ.get("proc") or "?"))
    has_guard = os.path.exists(_VEIL_SSH_NFT)

    # --- снапшот для отката: содержимое или отсутствие каждого трогаемого файла ---
    def _snap(path):
        try:
            return ("bytes", open(path, "rb").read())
        except Exception:
            return ("absent", None)
    snap_nft = _snap(_VEIL_SSH_NFT) if has_guard else ("absent", None)
    snap_sock = _snap(_SSH_SOCKET_DROPIN)
    snap_sshd = _snap(_SSHD_PORT_DROPIN)

    def _restore(path, snap):
        kind, data = snap
        try:
            if kind == "absent":
                if os.path.exists(path):
                    os.remove(path)
            else:
                with open(path, "wb") as f:
                    f.write(data)
        except Exception:
            pass

    def _reload_ssh():
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True, timeout=40)
        subprocess.run(["systemctl", "restart", "ssh.socket"], capture_output=True, timeout=90)

    def _rollback(why):
        _restore(_VEIL_SSH_NFT, snap_nft) if has_guard else None
        _restore(_SSH_SOCKET_DROPIN, snap_sock)
        _restore(_SSHD_PORT_DROPIN, snap_sshd)
        _reload_ssh()
        if has_guard:
            _ssh_guard_apply()
        raise RuntimeError("откат на :%d: %s" % (old, why))

    try:
        # 1) переходный гард: следит ОБА порта, чтобы проверка нового не упёрлась в лимит/дроп
        if has_guard:
            try:
                nft_txt = open(_VEIL_SSH_NFT, encoding="utf-8").read()
                with open(_VEIL_SSH_NFT, "w", encoding="utf-8") as f:
                    f.write(_ssh_nft_set_ports(nft_txt, sorted({old, new_port})))
                _ssh_guard_apply()
            except Exception as e:
                raise RuntimeError("не удалось перевести гард на два порта: %s" % str(e)[:120])

        # 2) двойной бинд сокета + согласованный Port в sshd-конфиге
        os.makedirs(os.path.dirname(_SSH_SOCKET_DROPIN), exist_ok=True)
        with open(_SSH_SOCKET_DROPIN, "w", encoding="utf-8") as f:
            f.write("[Socket]\nListenStream=\nListenStream=0.0.0.0:%d\nListenStream=[::]:%d\n"
                    "ListenStream=0.0.0.0:%d\nListenStream=[::]:%d\n" % (old, old, new_port, new_port))
        with open(_SSHD_PORT_DROPIN, "w", encoding="utf-8") as f:
            f.write("# veil: порт ssh (сокет-активация держит реальный листнер)\n"
                    "Port %d\nPort %d\n" % (old, new_port))
        t = subprocess.run(["sshd", "-t"], capture_output=True, text=True, timeout=30)
        if t.returncode != 0:
            raise RuntimeError("sshd -t: %s" % ((t.stderr or t.stdout).strip()[:160]))
        _reload_ssh()

        # 3) доказать, что новый порт обслуживается sshd (перезапуск сокета асинхронен)
        up = False
        for _ in range(6):
            time.sleep(1)
            if new_port in _ssh_effective_ports() and _ssh_banner_ok(new_port):
                up = True
                break
        if not up:
            raise RuntimeError("новый порт :%d не отвечает баннером sshd" % new_port)

        # 4) кут-овер: сокет и конфиг только на новый порт, гард — только новый
        with open(_SSH_SOCKET_DROPIN, "w", encoding="utf-8") as f:
            f.write("[Socket]\nListenStream=\nListenStream=0.0.0.0:%d\nListenStream=[::]:%d\n"
                    % (new_port, new_port))
        with open(_SSHD_PORT_DROPIN, "w", encoding="utf-8") as f:
            f.write("# veil: порт ssh (сокет-активация держит реальный листнер)\nPort %d\n" % new_port)
        t = subprocess.run(["sshd", "-t"], capture_output=True, text=True, timeout=30)
        if t.returncode != 0:
            raise RuntimeError("sshd -t после кут-овера: %s" % ((t.stderr or t.stdout).strip()[:160]))
        if has_guard:
            nft_txt = open(_VEIL_SSH_NFT, encoding="utf-8").read()
            with open(_VEIL_SSH_NFT, "w", encoding="utf-8") as f:
                f.write(_ssh_nft_set_ports(nft_txt, [new_port]))
            _ssh_guard_apply()
        _reload_ssh()

        ok2 = False
        for _ in range(6):
            time.sleep(1)
            pl = _ssh_effective_ports()
            if new_port in pl and old not in pl and _ssh_banner_ok(new_port):
                ok2 = True
                break
        if not ok2:
            raise RuntimeError("после кут-овера :%d не слушается/не отвечает или :%d не освобождён"
                               % (new_port, old))
    except Exception as e:
        _rollback(str(e)[:200])

    CFG_CACHE["ssh_port_local"] = new_port
    _cfg_save()
    _audit("ssh_port_change", user=user, old=old, new=new_port, guard_migrated=bool(has_guard))
    return {"ok": True, "old": old, "new": new_port, "guard_migrated": bool(has_guard),
            "ports": _ssh_effective_ports()}

# --- Оптимизация узла (пункт доски #172). Цели сняты с разбора чужого
# установщика (#107, только чтение), каждое значение перечитывается живьём
# перед записью и после неё; применение оставляет снимок «до» на диске и
# обязано откатиться, если ядро отвергнуло хотя бы один ключ.
_NODE_OPT_DROPIN = "/etc/sysctl.d/99-vpnpanel-tune.conf"
_NODE_OPT_MODULES = "/etc/modules-load.d/vpnpanel-bbr.conf"
_OPT_STATE = f"{BASE}/opt_node.json"

# Ключ ядра -> (требуемое значение, метка для человека). Порядок здесь —
# порядок строк в карточке морды.
_NODE_OPT_TARGETS = [
    ("net.core.somaxconn", "65535", "очередь принятия соединений"),
    ("net.ipv4.tcp_max_syn_backlog", "65535", "полуоткрытые подъёмы"),
    ("net.core.netdev_max_backlog", "65535", "входящая очередь драйвера"),
    ("net.ipv4.tcp_fastopen", "3", "подъём с первым пакетом данных"),
    ("net.core.default_qdisc", "fq", "очередная дисциплина"),
    ("net.ipv4.tcp_congestion_control", "bbr", "алгоритм перегрузки"),
    ("net.ipv4.tcp_keepalive_time", "45", "простаивание до зонда"),
    ("net.ipv4.tcp_keepalive_intvl", "15", "шаг между зондами"),
    ("net.ipv4.tcp_keepalive_probes", "3", "число зондов"),
    ("fs.file-max", "2097152", "потолок открытых файлов узла"),
]

_NODE_OPT_CC_KEY = "net.ipv4.tcp_congestion_control"


def _opt_proc_path(key):
    return "/proc/sys/" + key.replace(".", "/")


def _opt_current():
    """Живые значения всех целей: строка из `procfs` или None, если ключ не читается."""
    out = {}
    for k, _want, _label in _NODE_OPT_TARGETS:
        v = None
        try:
            with open(_opt_proc_path(k), encoding="utf-8") as f:
                v = f.read().strip()
        except Exception:
            pass
        out[k] = v
    return out


def _opt_cc_available():
    """Список алгоритмов перегрузки, которые ядро приняло модулями."""
    try:
        with open("/proc/sys/net/ipv4/tcp_available_congestion_control",
                  encoding="utf-8") as f:
            return f.read().split()
    except Exception:
        return []


def _opt_dropin_text(targets):
    lines = ["# veil: оптимизация узла (пункт #172); переживает перезагрузку"]
    for k, v, _ in targets:
        lines.append("%s = %s" % (k, v))
    return "\n".join(lines) + "\n"


def _opt_snap(path):
    try:
        with open(path, "rb") as f:
            return ["bytes", base64.b64encode(f.read()).decode("ascii")]
    except Exception:
        return ["absent", None]


def _opt_restore_files(snap):
    """Вернуть оба файла по снимку: `absent` — снять, `bytes` — положить прежние."""
    for tag, path in (("dropin", _NODE_OPT_DROPIN), ("modules", _NODE_OPT_MODULES)):
        kind, data = (snap.get(tag) or ["absent", None])[:2]
        try:
            if kind == "absent":
                if os.path.exists(path):
                    os.remove(path)
            else:
                with open(path, "wb") as f:
                    f.write(base64.b64decode(data))
        except Exception:
            pass


def _opt_restore_vals(vals):
    for k, v in (vals or {}).items():
        if v is None:
            continue
        subprocess.run(["sysctl", "-w", "%s=%s" % (k, v)],
                       capture_output=True, text=True, timeout=10)


def _opt_reload_sysctls():
    subprocess.run(["sysctl", "--system"], capture_output=True, text=True, timeout=60)


def _node_opt_status():
    cur = _opt_current()
    st = _load(_OPT_STATE, {}) or {}
    has_bbr = "bbr" in _opt_cc_available()
    items = []
    for k, want, label in _NODE_OPT_TARGETS:
        got = cur.get(k)
        items.append({"key": k, "want": want, "cur": got, "label": label,
                      "ok": got == want,
                      "skipped": bool(k == _NODE_OPT_CC_KEY and not has_bbr)})
    return {"ok": True, "items": items,
            "in_sync": all(i["ok"] for i in items if not i["skipped"]),
            "applied": bool(st.get("applied")),
            "has_snapshot": bool((st.get("snap") or {}).get("vals")),
            "applied_ts": int(st.get("applied_ts") or 0),
            "bbr_supported": has_bbr, "sbx": bool(SBX)}


def _node_opt_apply(confirm=False, user=None):
    """Применить цели: снять «до» на диск, поднять модуль `bbr`, написать
    дроп-инет, перезагрузить значения и ПЕРЕПРОЧИТАТЬ их; при отказе ядра —
    откатить файлы и значения. Все мутации под `_STATE_LOCK` (вызывающий),
    `confirm` обязателен, под песочницей (`SBX`) — отказ."""
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    if SBX:
        raise RuntimeError("под песочницей настройки узла не трогаем")
    cur = _opt_current()
    has_bbr = "bbr" in _opt_cc_available()
    if not has_bbr:
        subprocess.run(["modprobe", "tcp_bbr"], capture_output=True, text=True, timeout=30)
        has_bbr = "bbr" in _opt_cc_available()
    targets = [t for t in _NODE_OPT_TARGETS
               if not (t[0] == _NODE_OPT_CC_KEY and not has_bbr)]
    st = _load(_OPT_STATE, {}) or {}
    if not (st.get("snap") or {}).get("vals"):
        # снимок «до» пишется один раз: повторное применение не должно
        # превращать «после первого применения» в новое «до»
        st = {"snap": {"vals": {t[0]: cur.get(t[0]) for t in _NODE_OPT_TARGETS},
                       "dropin": _opt_snap(_NODE_OPT_DROPIN),
                       "modules": _opt_snap(_NODE_OPT_MODULES)}}
    try:
        os.makedirs(os.path.dirname(_NODE_OPT_DROPIN), exist_ok=True)
        with open(_NODE_OPT_DROPIN, "w", encoding="utf-8") as f:
            f.write(_opt_dropin_text(targets))
        if has_bbr:
            os.makedirs(os.path.dirname(_NODE_OPT_MODULES), exist_ok=True)
            with open(_NODE_OPT_MODULES, "w", encoding="utf-8") as f:
                f.write("tcp_bbr\n")
        r = subprocess.run(["sysctl", "--system"], capture_output=True,
                           text=True, timeout=60)
        after = _opt_current()
        bad = ["%s: ждали %s, ядро отдаёт %s" % (k, w, after.get(k))
               for k, w, _ in targets if after.get(k) != w]
        if bad:
            why = "; ".join(bad)[:200]
            if r.returncode != 0:
                why += " || вывод: " + (r.stderr or r.stdout).strip()[:120]
            raise RuntimeError(why)
    except Exception as e:
        _opt_restore_files(st.get("snap") or {})
        _opt_restore_vals((st.get("snap") or {}).get("vals"))
        _opt_reload_sysctls()
        raise RuntimeError("откат: " + str(e)[:200])
    st["applied"] = True
    st["applied_ts"] = int(time.time())
    st["changed"] = [k for k, w, _ in targets if cur.get(k) != w]
    _save(_OPT_STATE, st, 0o600)
    _audit("node_opt_apply", user=user, changed=len(st["changed"]),
           skipped=0 if has_bbr else 1)
    return _node_opt_status()


def _node_opt_rollback(confirm=False, user=None):
    """Вернуть узел к снимку «до»: файлы по их виду (`absent` — снять),
    значения через прямую запись, затем перезагрузка окружения.
    `confirm` обязателен; под песочницей — отказ."""
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    if SBX:
        raise RuntimeError("под песочницей настройки узла не трогаем")
    st = _load(_OPT_STATE, {}) or {}
    snap = st.get("snap") or {}
    if not snap.get("vals"):
        raise RuntimeError("снимка «до» нет — откатывать нечего")
    _opt_restore_files(snap)
    _opt_restore_vals(snap.get("vals"))
    _opt_reload_sysctls()
    st["applied"] = False
    _save(_OPT_STATE, st, 0o600)
    _audit("node_opt_rollback", user=user)
    return _node_opt_status()


def _tg_mp_apply(port=None, confirm=False):
    """Добавить публичный MTProto [[server.listeners]] в telemt.toml и перезапустить telemt."""
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    pv = _tg_mp_preview()
    if not pv["can_apply"]:
        raise RuntimeError("нельзя применить: " + "; ".join(pv["blockers"] or ["неизвестно"]))
    try:
        new_port = int(port) if port else int(pv["candidate_port"])
    except (TypeError, ValueError):
        new_port = int(pv["candidate_port"])
    if not (0 < new_port < 65536):
        raise RuntimeError("некорректный порт")
    occ = _sock_occupant(new_port)
    if not occ.get("free") and "telemt" not in (occ.get("proc") or ""):
        raise RuntimeError("порт :%d уже занят %s — выберите другой" % (new_port, occ.get("proc") or "?"))
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            backup = f.read()
    except Exception as e:
        raise RuntimeError("не смог прочитать telemt.toml: %s" % e)
    prev_server_port = _tg_toml_get_server_port(backup)
    text = backup
    if prev_server_port != new_port:
        # Меняем [server] port, чтобы у ссылки и listener'а был один источник истины
        text = _tg_toml_set_server_port(text, new_port)
    want_v6 = _tg_mp_ipv6_want()
    text, block = _tg_toml_add_mp_listener(text, new_port, ipv6=want_v6)
    with open(TELEMT_CONF, "w", encoding="utf-8") as f:
        f.write(text)
    r = subprocess.run(["systemctl", "restart", "telemt"], capture_output=True, text=True, timeout=120)
    import time as _t
    up = False
    for _ in range(10):
        _t.sleep(1)
        ni = _tg_mtproto_info()
        if ni.get("up") and ni.get("port") == new_port:
            up = True
            break
    if not up:
        with open(TELEMT_CONF, "w", encoding="utf-8") as f:
            f.write(backup)
        subprocess.run(["systemctl", "restart", "telemt"], capture_output=True, timeout=120)
        raise RuntimeError("MTProto не поднялся на :%d (restart rc=%d) — конфиг откачен" % (new_port, r.returncode))
    selfw = _tg_mp_firewall_open(new_port)
    try:
        _synfix_apply()
    except Exception as e:
        print("synfix: " + str(e), flush=True)
    _save(_TGBP_STATE, {"applied": True, "port": new_port, "prev_server_port": prev_server_port,
                        "ts": _now_iso()}, 0o600)
    _audit("tg_mtproto_listen", port=new_port, prev=prev_server_port)
    return {"ok": True, "port": new_port, "prev_port": prev_server_port,
            "ipv6": "on" if want_v6 else "off",
            "firewall": "open" if selfw else "skip",
            "note": "MTProto активен на :%d. Убедитесь, что облачный security group пропускает :%d." % (new_port, new_port)}

def _tg_mp_revert(confirm=False):
    """Убрать наш MTProto-listener (и вернуть прежний [server] port, если меняли)."""
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    st = _load(_TGBP_STATE, {}) or {}
    if not st.get("applied"):
        return {"ok": True, "already": True, "message": "VEIL-MTProto-listener не добавляли — откатывать нечего"}
    prev = int(st.get("prev_server_port") or 0)
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            backup = f.read()
    except Exception as e:
        raise RuntimeError("не смог прочитать telemt.toml: %s" % e)
    try:
        text = _tg_toml_remove_mp_listener(backup)
    except Exception as e:
        raise RuntimeError(str(e))
    if prev:
        text = _tg_toml_set_server_port(text, prev)
    with open(TELEMT_CONF, "w", encoding="utf-8") as f:
        f.write(text)
    subprocess.run(["systemctl", "restart", "telemt"], capture_output=True, timeout=120)
    _save(_TGBP_STATE, {"applied": False, "port": prev, "ts": _now_iso()}, 0o600)
    try:
        _synfix_apply()
    except Exception as e:
        print("synfix: " + str(e), flush=True)
    ni = _tg_mtproto_info()
    _audit("tg_mtproto_revert", port=prev)
    if ni.get("up"):
        note = "VEIL-MTProto listener убран, но telemt всё ещё слушает :%s (значит у вас был свой публичный listener)." % prev
    elif not ni.get("proc"):
        note = "VEIL-MTProto listener убран; MTProto больше неактивен (никто не слушает :%s)." % prev
    else:
        note = "VEIL-MTProto listener убран; на :%s теперь сидит %s — MTProto-клиенты туда не попадут." % (prev, ni.get("proc"))
    return {"ok": True, "port": prev, "up": bool(ni.get("up")), "message": note, "note": note}


def _tg_ensure_secret_in_toml(username, secret):
    """Добавить секрет пользователя в [access.users] telemt.toml (если его там нет)."""
    if not (username and secret):
        return
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return
    if re.search(r"(?m)^\"?%s\"?\s*=" % re.escape(username), text):
        return
    if "[access.users]" in text:
        text = text.replace("[access.users]", '[access.users]\n%s = "%s"%s' % (username, secret, "\n" if text.split("[access.users]", 1)[1].strip() else ""), 1)
    else:
        text = text.rstrip("\n") + '\n[access.users]\n%s = "%s"\n' % (username, secret)
    with open(TELEMT_CONF, "w", encoding="utf-8") as f:
        f.write(text)

def _tg_pick_tls_link(tls, prefer=""):
    """Первая ссылка обычно IPv4 — предпочтём её.
    #168: `prefer` — имя, под которым панель отдаёт ссылку. telemt возвращает по ссылке
    на каждый фронт, и порядок их не обещан: брать первую и подписывать её чужим именем
    нельзя — SNI клиент возьмёт из секрета, и развилка уведёт такую ссылку в веб. Поэтому
    сначала ищем ссылку собственным фронтом, и только потом — прежнюю эвристику."""
    tls = tls or []
    prefer = (prefer or "").strip().lower()
    if prefer:
        for l in tls:
            if _tg_link_front(l) == prefer and "server=" in l and \
                    ":" not in l.split("server=")[1].split("&")[0]:
                return l
    for l in tls:
        if "server=" in l and ":" not in l.split("server=")[1].split("&")[0]:
            return l
    return (tls or [""])[0]

def _tg_web_enable_user(name):
    """Добавить пользователя в веб-профили `vhosts` (нужен включённый web в telemt)."""
    w = _tg_web_get()
    if not (w and w.get("enabled") and w.get("host")):
        return ""
    users = list(w["profiles"])
    if name not in users:
        users.append(name)
        try:
            _tg_web_set_profiles(users)
            w = _tg_web_get()
        except Exception:
            w = None
    if not w or name not in w["profiles"]:
        return ""
    return _tg_web_link(name)

def _tg_add(username, mode="both"):
    """Создать пользователя telemt. mode: mtproto | web | `both`."""
    name = (username or "").strip().replace(" ", "_")
    if not name:
        raise RuntimeError("имя пустое")
    if not re.match(r"^[a-zA-Z0-9_.-]{1,32}$", name):
        raise RuntimeError("только латиница, цифры, _ . - (до 32 символов)")
    mode = mode if mode in ("mtproto", "web", "both") else "both"
    if mode == "web":
        w0 = _tg_web_get()
        if not (w0 and w0.get("enabled") and w0.get("host")):
            raise RuntimeError("веб-прокси в telemt выключен — сначала установи Web Proxy (nginx)")
    d = _tg_api("POST", "/v1/users", {"username": name})
    secret = d.get("secret", "")
    _tg_ensure_secret_in_toml(name, secret)
    links = ((d.get("data") or {}).get("user") or {}).get("links", {})
    link = _tg_pick_tls_link(links.get("tls"), _tg_advertised_host())
    web_link = _tg_web_enable_user(name) if mode in ("web", "both") else ""
    return {"username": name, "secret": secret,
            "link": _tg_fix_mtproto_link(link, _tg_mtproto_info().get("port")),
            "web_link": web_link}

def _tg_remove(username):
    if not username:
        raise RuntimeError("имя пустое")
    w = _tg_web_get()
    if w and username in w["profiles"]:
        try:
            _tg_web_set_profiles([u for u in w["profiles"] if u != username])
        except Exception:
            pass
    _tg_api("DELETE", "/v1/users/" + urllib.parse.quote(username))
    return {"ok": True}

_TG_HEX32 = re.compile(r"^[0-9a-f]{32}$")

def _tg_user_row(username):
    return (_tg_api("GET", "/v1/users/" + urllib.parse.quote(username)).get("data") or {})

def _tg_set_adtag(username, tag):
    """Спонсорский канал @MTProxybot: телеметрик-тег пользователя (32 hex) либо null (снять).

    Ссылка клиента при этом НЕ меняется — телеграм подставляет канал по тегу на стороне прокси,
    для чего нужен general.use_middle_proxy = true (у telemt по умолчанию включён).
    """
    name = (username or "").strip()
    if not name:
        raise RuntimeError("имя пустое")
    tag = (tag or "").strip().lower()
    if tag and not _TG_HEX32.match(tag):
        raise RuntimeError("ad_tag — ровно 32 hex-символа из @MTProxybot (или пусто, чтобы снять)")
    _tg_api("PATCH", "/v1/users/" + urllib.parse.quote(name), {"user_ad_tag": tag or None})
    warn = ""
    if tag and not _tg_middle_proxy_on():
        warn = ("телеметрик-тег подставляет ME, а вход в сеть Telegram "
                "(general.use_middle_proxy) выключен — %s; включи и перезапусти telemt, "
                "иначе медиа у клиентов грузиться перестанут вовсе"
                % (_tg_me_state().get("off_by") or "чем-то"))
    return {"username": name, "ad_tag": tag or None, "warning": warn}

def _tg_set_max_ips(username, n):
    """Лимит одновременных адресов (устройств) на ссылку TG-прокси.

    Считает telemt: больше N живых IP с одним секретом — новым подключениям отказ.
    0/пусто = без лимита. Это тот же смысл, что max_devices у подписки VPN."""
    name = (username or "").strip()
    if not name:
        raise RuntimeError("имя пустое")
    try:
        n = int(n or 0)
    except Exception:
        raise RuntimeError("лимит — целое число")
    if n < 0 or n > 999:
        raise RuntimeError("лимит: 0..999 (0 — без ограничений)")
    _tg_api("PATCH", "/v1/users/" + urllib.parse.quote(name),
            {"max_unique_ips": n or None})
    return {"username": name, "max_ips": n}

def _tg_middle_proxy_on():
    # Один источник правды с диагностикой (#218): по рантайму, а не по догадке. При
    # молчании API `_tg_me_state` откатывается к файлу и к дефолту движка (`true`), то
    # есть мертвоподнявшийся telemt не превращает предупреждение в запрет.
    return bool(_tg_me_state().get("use_middle_proxy", True))

def _tg_rotate_secret(username, secret=""):
    """Смена секрета пользователя: ссылка меняется, telemt сам обновляет [access.users]."""
    name = (username or "").strip()
    if not name:
        raise RuntimeError("имя пустое")
    secret = (secret or "").strip().lower()
    if secret and not _TG_HEX32.match(secret):
        raise RuntimeError("секрет — 32 hex-символа или пусто (сгенерировать автоматически)")
    d = _tg_api("POST", "/v1/users/" + urllib.parse.quote(name) + "/rotate-secret",
                {"secret": secret} if secret else {}).get("data") or {}
    new_secret = d.get("secret") or ""
    if new_secret:
        _tg_ensure_secret_in_toml(name, new_secret)
    links = ((d.get("user") or {}).get("links") or {}).get("tls") or []
    return {"username": name, "secret": new_secret,
            "link": _tg_fix_mtproto_link(
                _tg_pick_tls_link(links, _tg_advertised_host()), _tg_mtproto_info().get("port")),
            "web_link": _tg_web_link(name)}

def _tg_sni():
    """SNI (маскировка) прокси: censorship.tls_domain + список tls_domains."""
    try:
        c = _tg_api("GET", "/v1/config").get("data", {}).get("censorship") or {}
    except Exception:
        return {"tls_domain": "", "tls_domains": [], "mlkem": None}
    return {"tls_domain": c.get("tls_domain") or "", "tls_domains": c.get("tls_domains") or [],
            "mlkem": _sni_mlkem_ok(c.get("tls_domain") or "")}

def _veil_front_domains():
    """Домены-фронты MTProto facade (SNI в ClientHello подделки TLS). Xray-сервер
    обязан исключать их из sniffing-override: туннельное соединение к прокси
    (hairpin: телефон под VPN → xray → свой же :7443) имеет изначальный `dest`
    = IP/домен панели, но внутри — TLS ClientHello с SNI=фронт. Если sniffing
    перезапишет `dest` этим SNI (docs telemt XRAY-SINGBOX-ROUTING, «Вариант B»),
    сервер начнёт долбить фронт (Akamai microsoft.com) на порту 7443 — там
    никто не слушает: шторм безответных SYN, а telemt не видит ни одного
    соединения. Отсюда и «прокси не работает под VPN» в клиентах без
    DirectIp-исключений (Incy)."""
    doms = []
    text = ""
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            text = f.read()
        m = re.search(r'(?m)^\s*tls_domain\s*=\s*"([^"]+)"', text)
        if m:
            doms.append(m.group(1).strip().lower())
        m = re.search(r'(?m)^\s*tls_domains\s*=\s*\[([^\]]*)\]', text)
        if m:
            doms += [d.strip().strip(",").strip().strip('"').lower()
                     for d in m.group(1).split(",")]
    except Exception:
        pass
    # секреты facade: фронт зашит и в secret'ы пользователей:
    # ee + key(16B) + [первый байт SNI] + hex(остаток SNI)
    for mm in re.finditer(r'(?m)^\s*secret\s*=\s*"ee([0-9a-f]{64,})"', text or ""):
        try:
            hx = mm.group(1)
            if len(hx) < 68:
                continue
            host = chr(int(hx[64:66], 16)) + bytes.fromhex(hx[66:]).decode("ascii", "ignore")
            if re.fullmatch(r"[a-z0-9.-]+", host or ""):
                doms.append(host.lower())
        except Exception:
            pass
    if not doms:
        doms = ["www.microsoft.com", "my.aeza.ru"]
    return sorted({d for d in doms if d and "." in d})

def _tg_sni_set(tls_domain=None, tls_domains=None):
    dom = (tls_domain or "").strip().lower() if tls_domain is not None else None
    if dom is not None:
        if dom and not re.fullmatch(r"[a-z0-9]([a-z0-9.-]{0,252}[a-z0-9])?", dom):
            raise RuntimeError("домен: только имя хоста без портов и путей")
    extra = None
    if tls_domains is not None:
        extra = []
        for d0 in tls_domains:
            d0 = (d0 or "").strip().lower()
            if not d0:
                continue
            if not re.fullmatch(r"[a-z0-9]([a-z0-9.-]{0,252}[a-z0-9])?", d0):
                raise RuntimeError("домен: только имя хоста без портов и путей")
            if d0 not in extra:
                extra.append(d0)
    body = {}
    if dom is not None:
        body["tls_domain"] = dom
    if extra is not None:
        body["tls_domains"] = extra
    if not body:
        raise RuntimeError("нечего менять")
    _tg_api("PATCH", "/v1/config", {"censorship": body})
    _SNI_PQ_CACHE.clear()
    _audit("tg_sni", **({"domain": dom} if dom is not None else {}))
    return _tg_sni()


# ---- #168: откуда telemt снимает настоящую форму TLS (источник фасадного профиля) ----
# `censorship.mask_host` + `mask_port`. Пока фасад смотрит на публичный :443, источник
# и есть этот публичный маршрут. С #168 SNI прокси ведёт прямо в слушателя mtproxy, и
# публичный съём формы превращается в петлю: telemt пришёл бы сам к себе, профиль
# протухает за `tls_full_cert_ttl_secs`, а без профиля мертво и прокси-клиенту, и браузеру.
# Поэтому источник уводим на петлевой фронт сайт-маски. Мерено живьём: с `127.0.0.1:8447`
# профиль скачивается (100 КБ) и отдаётся клиенту полной цепью, 5119 байт рукопожатия.
_MASK_FRONT_DEFAULT_PORT = 443
_MASK_FRONT_LOOPBACK = "127.0.0.1"
# Петлевой фронт имени прокси (#168) может быть назван любым локальным адресом —
# сверяться надо со списком, а не с одной записью.
_MASK_FRONT_LOOPBACKS = (_MASK_FRONT_LOOPBACK, "localhost", "::1")

def _tg_mask_front_get():
    """{mask_host, mask_port} — текущий источник формы. Пустой host = прежнее поведение
    (снимать с самого фасада по публичному маршруту)."""
    try:
        c = _tg_api("GET", "/v1/config").get("data", {}).get("censorship") or {}
    except Exception:
        return {"mask_host": "", "mask_port": 0}
    try:
        port = int(c.get("mask_port") or 0)
    except (TypeError, ValueError):
        port = 0
    return {"mask_host": (c.get("mask_host") or "").strip(), "mask_port": port}


def _tg_mask_front_set(host, port):
    """Поставить источник формы. API принимает только непустой хост (пустая строка — 400),
    поэтому снятие делает `_tg_mask_front_clear`, а не PATCH."""
    host = (host or "").strip()
    port = int(port or 0)
    if not host or not (1 <= port <= 65535):
        raise RuntimeError("нужны хост и порт источника формы")
    _tg_api("PATCH", "/v1/config", {"censorship": {"mask_host": host, "mask_port": port}})
    _audit("tg_mask_front", host=host, port=port)
    return _tg_mask_front_get()


def _tg_mask_front_clear():
    """Вернуть источник формы к базовой линии: строки `mask_host` в файле не было, а
    `mask_port` стоял 443. Через API это невозможно: пустая строка — `400 Bad Request`,
    `null` — молча `changed: []` (мерено). Значим только вырез строки + перезапуск."""
    port = _MASK_FRONT_DEFAULT_PORT
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        text = ""
    if text:
        new = re.sub(r"(?m)^\s*mask_host\s*=.*\n", "", text)
        new = re.sub(r"(?m)^(\s*mask_port\s*=\s*)\d+", r"\g<1>%d" % port, new)
        if new != text:
            with open(TELEMT_CONF, "w", encoding="utf-8") as f:
                f.write(new)
    _tg_api("PATCH", "/v1/config", {"censorship": {"mask_port": port}})


def _tg_mask_front_off(saved=None):
    """Снять источник формы к базовой линии, выбрав движок по снимку «до».

    Одно правило на все три хода (отключение маршрута, откат применения, присмотр):
    честное «до» — только снимок, записанный при включении. Если в нём чужой хост с
    портом, возвращаем его PATCH'ем; если пусто, или хост наш петлевой (снимки состояний,
    записанных до #168, могли сохранить собственное действие как «до»), строку режет
    `_tg_mask_front_clear` — API пустоту не принимает (`400`), а `null` молча `changed: []`.
    """
    back = saved if isinstance(saved, dict) else {}
    host = (back.get("mask_host") or "").strip()
    try:
        port = int(back.get("mask_port") or 0)
    except (TypeError, ValueError):
        port = 0
    if host and host not in _MASK_FRONT_LOOPBACKS:
        _tg_mask_front_set(host, port or _MASK_FRONT_DEFAULT_PORT)
    else:
        _tg_mask_front_clear()


# Присмотр за источником формы (#174). `telemt` сам переписывает полученный PATCH на диск,
# поэтому рестарт службы его не теряет — теряют другие: восстановление снимка `telemt.toml`,
# переустановка пакета, любая правка файла со стороны. Симптом всегда молчаливый и всегда
# один: фасад имени прокси снимает форму сам с себя, профиль протухает, в журнале
# `Raw TLS fetch attempt failed sni=mp… ServerHelloMissing`, и мертво и прокси-клиенту,
# и браузеру. Чинить обязан не только тот, кто потерял, а сам порядок.
_MASK_FRONT_GUARD = {"want": "", "have": "", "fixed": "", "skipped": "", "error": "",
                     "ts": None}


def _tg_mask_front_guard():
    """Держать источник формы в согласии с маршрутом MTProto на :443.

    Возвращает строку о сделанном ("" — ничего не тронули). На спокойном проходе в журнал
    не пишет — как хранитель имён. Петлевой порт проверяется живым коннектом: ставить
    источник на мёртвый порт хуже публичной петли, там хотя бы есть шанс на профиль."""
    _MASK_FRONT_GUARD.update(want="", have="", fixed="", error="", ts=time.time(),
                             skipped="песочница: живую службу не трогаем" if SBX else "")
    if SBX:
        # Песочница переселяет ФАЙЛЫ харнесса, а юнит `telemt` остаётся живой (`#114`). Значит
        # сверка делала бы выводы по снимку-фикстуре, а удар пришёлся по настоящей службе.
        return ""
    ms = _load(_MUX_STATE, {}) or {}
    if not (ms.get("mp") or isinstance(ms.get("mp_prev"), dict) or CFG_CACHE.get("tg_mp_on443")):
        _MASK_FRONT_GUARD["skipped"] = "маршрут MTProto на :443 не применялся"
        return ""
    if _mv_locked():
        _MASK_FRONT_GUARD["skipped"] = "переезд: самопроизвольные правки приостановлены"
        return ""
    if not _tg_available():
        _MASK_FRONT_GUARD["skipped"] = "telemt не отвечает"
        return ""
    cur = _tg_mask_front_get()
    have = "%s:%s" % (cur.get("mask_host") or "", cur.get("mask_port") or 0)
    local = (cur.get("mask_host") or "").strip() in _MASK_FRONT_LOOPBACKS
    want_port = 0
    route_on = bool(ms.get("applied") and ms.get("mp"))
    if route_on:
        try:
            want_port = int(ms.get("mp_mask_port") or 0)
        except (TypeError, ValueError):
            want_port = 0
        if not 1 <= want_port <= 65535:
            # Маршрут включён, а порта фронта в снимке нет (состояние записано версией,
            # которая его не писала). Выдумывать порт нельзя, а «снять к базовой линии»
            # — значит оборвать живую маску: поэтому сверка приостановлена, а не решена.
            _MASK_FRONT_GUARD["skipped"] = ("маршрут включён, но порт петлевого фронта "
                                            "в снимке не записан — сверка приостановлена")
            return ""
    _MASK_FRONT_GUARD["have"] = have
    _MASK_FRONT_GUARD["want"] = ("%s:%d" % (_MASK_FRONT_LOOPBACK, want_port)
                                 if want_port else "базовая линия")
    try:
        if route_on:
            if local and cur.get("mask_port") == want_port:
                return ""
            try:
                with socket.create_connection((_MASK_FRONT_LOOPBACK, want_port), timeout=2):
                    pass
            except Exception:
                _MASK_FRONT_GUARD["skipped"] = ("петлевой фронт на :%d не отвечает — "
                                                "источник не переведён" % want_port)
                return ""
            _tg_mask_front_set(_MASK_FRONT_LOOPBACK, want_port)
            did = "источник формы → %s:%d" % (_MASK_FRONT_LOOPBACK, want_port)
        else:
            if not local:
                return ""
            _tg_mask_front_off(ms.get("mp_prev"))
            did = "источник формы снят к базовой линии"
        # Правка цензуры применяется перезапуском: `PATCH` отвечает
        # `restart_required: true` и отдельного reload-эндпоинта у telemt нет (мерено —
        # `/v1/config/reload` это 404). Без перезапуска чинился бы файл, а не служба.
        subprocess.run(["systemctl", "restart", "telemt"], capture_output=True, timeout=120)
        for _ in range(10):
            time.sleep(1)
            if _tg_available():
                break
    except Exception as e:
        _MASK_FRONT_GUARD["error"] = str(e)[:120]
        _audit("tg_mask_front_guard", have=have, want=_MASK_FRONT_GUARD["want"],
               error=_MASK_FRONT_GUARD["error"])
        return ""
    _MASK_FRONT_GUARD["fixed"] = did
    _audit("tg_mask_front_guard", have=have, want=_MASK_FRONT_GUARD["want"], fixed=did)
    return did


# ------------------------------------------------------------------ #158: подгонка под уже розданную ссылку

_TG_EE_SECRET = re.compile(r"^ee([0-9a-f]{32})([0-9a-f]{2,})$")
# #241: у веб-прокси секрет короче: `dd` + 32 hex, и hex этот — тот же ключ клиента из
# `[access.users]`, что стоит за `ee`-секретами MTProto. Ни порта, ни фронта в ссылке нет.
_TG_DD_SECRET = re.compile(r"^dd([0-9a-f]{32})$")
# #196: @MTProxybot отдаёт секрет голыми 32 hex — ни `ee`, ни имени фронта. Клиент по
# такой строке идёт прямым MTProto на порт, а наш :443 держит TLS-развилку, поэтому
# рукопожатие не складывается и ссылка «не работает». Физика та же, что у розданных
# ссылок: телеграм ждёт `ee` + ключ + hex тега, а на фронтовом прокси тегом и является
# имя фронта. Значит недостающее панель обязана достроить сама, а не требовать от бота.
_TG_PLAIN_SECRET = re.compile(r"^(?:ee)?([0-9a-f]{32})$")
_TG_MANUAL_MARK = "Veil:MTProtoManual"
_TG_MANUAL_STATE = f"{BASE}/tg_manual_links.json"
_TG_USER_NAME = re.compile(r"[a-zA-Z0-9_.\-]{1,32}")


def _tg_manual_front_for(server):
    """#196: какое имя фронта подшить под голый hex из бота. Адрес из ссылки годится,
    только если это домен (он и есть то, что клиент назовёт в SNI); IP фронтом быть не
    может — тогда берём публичное имя MTProto, которое панель раздаёт сама."""
    s = (server or "").strip().lower().rstrip(".")
    if ("." in s and ":" not in s and not re.fullmatch(r"[0-9a-f.]+", s) and
            re.fullmatch(r"[a-z0-9]([a-z0-9.\-]{0,251}[a-z0-9])?", s)):
        return s
    return _tg_advertised_host() or _tg_front_host()


def _tg_manual_compose(secret, server):
    """#196: достроить `ee`-секрет из того, что дал бот. Возвращает (секрет, имя фронта)
    или (None, "") — если строка вообще не похожа на ключ."""
    m = _TG_PLAIN_SECRET.match((secret or "").strip().lower())
    if not m:
        return None, ""
    front = _tg_manual_front_for(server)
    if not front:
        raise RuntimeError("в секрете нет имени фронта, а панели нечем его заменить: "
                           "узел не отдаёт публичного имени MTProto — включите маршрут "
                           "на общий порт или вставьте ссылку целиком, с ee…")
    return "ee" + m.group(1) + front.encode("ascii").hex(), front


def _tg_manual_parse(link):
    """Разобрать готовую ссылку `tg://proxy` целиком: `server`, `port` и `ee`-секрет на ключ и фронт.

    Физика секрета (мерено на `telemt` 3.5.7): `ee` + 32 hex-символа ключа + `hex` имени фронта,
    без байта длины. Поэтому розданная ссылка самодостаточна: фронт вшит в неё в момент выпуска
    секрета, а не в момент создания клиента. Под себя panel обязана подстроить ровно три вещи —
    ключ, список фронтов и публичный слушатель на порту ссылки.

    #196: бот спонсорства отдаёт секрет голыми 32 hex — без `ee` и без фронта, и ссылка с ним
    не работает на фронтовом порту. Такое вставка достраивается сама; имя фронта, которое
    панель подшила, возвращается в поле `composed`, чтобы морда показала готовую ссылку.

    #241: сюда же приехала ссылка веб-прокси — у неё своя физика и свой разбор,
    `_tg_manual_parse_web`; поле `kind` различает их («proxy» и «web»).
    """
    raw = (link or "").strip().strip('"').strip("'")
    if not raw:
        raise RuntimeError("вставьте ссылку целиком: tg://proxy?server=…&port=…&secret=ee…")
    composed = ""
    if re.fullmatch(r"(?i)(?:ee)?[0-9a-f]{32}", raw):
        # Голый ключ без ссылки: адрес и порт берём те, что панель отдаёт уже сейчас.
        host = _tg_advertised_host() or _tg_front_host()
        if not host:
            raise RuntimeError("вставлен только секрет, а у панели нет публичного имени MTProto: "
                               "включите маршрут на общий порт или вставьте ссылку целиком")
        secret0, composed = _tg_manual_compose(raw, host)
        try:
            gport = int((_tg_mtproto_info() or {}).get("port") or 443)
        except Exception:
            gport = 443
        raw = "tg://proxy?server=%s&port=%d&secret=%s" % (host, gport, secret0)
        # Порт — как у `_tg_fix_mtproto_link`: ссылка, чей фронт называет имя маршрута,
        # идёт на общий :443, остальное — на публичный порт слушателя.
        if _tg_mp_route_for(raw):
            raw = re.sub(r"(?i)(port=)\d+", lambda m: m.group(1) + "443", raw)
    if re.match(r"(?i)^https?://t\.me/proxy", raw):
        i = raw.find("?")
        if i < 0:
            raise RuntimeError("в ссылке t.me нет параметров — вставьте её целиком")
        raw = "tg://proxy" + raw[i:]
    if re.match(r"(?i)^tg://webproxy\?", raw):
        return _tg_manual_parse_web(raw)
    if not re.match(r"(?i)^tg://proxy\?", raw):
        raise RuntimeError("это не ссылка tg://proxy и не tg://webproxy: панель подгоняет "
                           "MTProto-фасад (tg://proxy?server=…&port=…&secret=ee…) и "
                           "веб-прокси (tg://webproxy?server=…&secret=dd…)")
    q = {k.lower(): v for k, v in urllib.parse.parse_qs(raw.split("?", 1)[1]).items()}
    server = (q.get("server") or [""])[0].strip().lower().rstrip(".")
    ports = (q.get("port") or [""])[0].strip()
    secret = (q.get("secret") or [""])[0].strip().lower()
    if not server or not re.fullmatch(r"[a-z0-9]([a-z0-9.:%_\-]{0,251}[a-z0-9])?", server):
        raise RuntimeError("в ссылке непонятный server= — нужен домен или адрес без порта и пути")
    if not re.fullmatch(r"[0-9]{1,5}", ports or "") or not 0 < int(ports) < 65536:
        raise RuntimeError("в ссылке непонятный port= — нужен порт 1…65535")
    m = _TG_EE_SECRET.match(secret)
    if not m:
        secret, composed = _tg_manual_compose(secret, server)
        m = _TG_EE_SECRET.match(secret or "")
    if not m:
        raise RuntimeError("секрет не ee-формата: нужно ee, 32 hex-символа ключа и hex имени фронта")
    key, tail = m.group(1), m.group(2)
    try:
        front = bytes.fromhex(tail).decode("ascii").strip().lower()
    except Exception:
        raise RuntimeError("хвост секрета не расшифровывается в имя фронта — ссылка битая")
    if "." not in front or not re.fullmatch(r"[a-z0-9]([a-z0-9.\-]{0,251}[a-z0-9])?", front):
        raise RuntimeError("фронт из секрета прочитался как «%s» — это не домен" % front[:40])
    return {"kind": "proxy", "server": server, "port": int(ports), "key": key,
            "front": front, "secret": secret, "composed": composed,
            "link": "tg://proxy?server=%s&port=%d&secret=%s" % (server, int(ports), secret)}


def _tg_manual_parse_web(raw):
    """#241: разобрать готовую ссылку `tg://webproxy` — имя фасада и `dd`-секрет на ключ.

    Физика (мерено на живом `telemt`): в ссылке два поля — `server` (имя веб-фасада, оно же
    vhost в `[web.vhosts]`) и `dd` + 32 hex ключа клиента из `[access.users]`. Ни порта, ни
    фронта: путь до :443 держит nginx, а имя сервера читает сам Telegram. Под себя панель
    обязана подстроить ровно то же, что и по MTProto-ссылке: ключ клиента и имя фасада.
    """
    q = {k.lower(): v for k, v in urllib.parse.parse_qs(raw.split("?", 1)[1]).items()}
    server = (q.get("server") or [""])[0].strip().lower().rstrip(".")
    secret = (q.get("secret") or [""])[0].strip().lower()
    if not server or not re.fullmatch(r"[a-z0-9]([a-z0-9.\-]{0,251}[a-z0-9])?", server):
        raise RuntimeError("в ссылке webproxy непонятный server= — нужно имя без порта и пути")
    m = _TG_DD_SECRET.match(secret)
    if not m:
        raise RuntimeError("секрет webproxy: нужен `dd` и 32 hex-символа ключа — "
                           "вид tg://webproxy?server=…&secret=dd…")
    return {"kind": "web", "server": server, "port": 443, "key": m.group(1),
            "front": server, "secret": secret, "composed": "",
            "link": "tg://webproxy?server=%s&secret=%s" % (server, secret)}


def _tg_manual_read_toml():
    try:
        with open(TELEMT_CONF, "r", encoding="utf-8") as f:
            return f.read()
    except Exception as e:
        raise RuntimeError("не смог прочитать telemt.toml: %s" % e)


def _tg_toml_access_users(text=None):
    """{имя: ключ} из секции `[access.users]` — без обращения к API."""
    if text is None:
        text = _tg_manual_read_toml()
    m = re.search(r"(?ms)^\s*\[access\.users\]\s*$(.+?)(?=^\s*\[\[?|\Z)", text)
    if not m:
        return {}
    out = {}
    for ln in m.group(1).splitlines():
        mm = re.match(r'^\s*"?([^"=\s]+)"?\s*=\s*"([0-9a-f]{32})"\s*$', ln)
        if mm:
            out[mm.group(1)] = mm.group(2)
    return out


def _tg_manual_public_ports(text=None):
    """Порты публичных mtproxy-слушателей (петлевые не в счёт).

    `[server] port` считается только когда блоков `[[server.listeners]]` нет вовсе: telemt
    трактует массив как исчерпывающий и сам на него не биндится.
    """
    if text is None:
        text = _tg_manual_read_toml()
    ports = []
    for L in _tg_toml_listeners(text):
        if L["transport"] != "mtproxy":
            continue
        ip = L["ip"] or "0.0.0.0"
        if ip.startswith("127.") or ip == "::1":
            continue
        if L["port"]:
            ports.append(int(L["port"]))
    if ports:
        return sorted(set(ports))
    if not _tg_toml_has_any_listener(text):
        sp = _tg_toml_get_server_port(text)
        return [int(sp)] if sp else []
    return []


def _tg_toml_add_manual_listener(text, port, ipv6=True):
    """Добавить публичный mtproxy-слушатель на port, если такого ещё нет; вернуть (текст, добавлено).

    Маркер отдельный от «Оживить MTProto»: ручных портов может быть несколько, и откат одного
    не обязан съедать другой. Вставка — после последнего имеющегося блока, чтобы слушатели
    оставались группой и telemt перекрывал массив целиком за один проход.
    """
    port = int(port)
    if port in _tg_manual_public_ports(text):
        return text, False
    text = _tg_toml_ipv6_set(text, ipv6)
    block = (
        "# " + _TG_MANUAL_MARK + "\n"
        "[[server.listeners]]\n"
        "ip = \"0.0.0.0\"\n"
        "port = " + str(port) + "\n"
        "transport = \"mtproxy\"\n"
    )
    if ipv6:
        block += (
            "\n# " + _TG_MANUAL_MARK + "\n"
            "[[server.listeners]]\n"
            "ip = \"::\"\n"
            "port = " + str(port) + "\n"
            "transport = \"mtproxy\"\n"
        )
    last = None
    for mm in re.finditer(r"(?ms)^\s*\[\[server\.listeners\]\]\s*$(.+?)(?=^\s*\[\[?|\Z)", text):
        last = mm
    if last:
        ins = last.end()
        return text[:ins].rstrip("\n") + "\n\n" + block + text[ins:].lstrip("\n"), True
    return text.rstrip("\n") + "\n\n" + block, True


def _tg_manual_records():
    return _load(_TG_MANUAL_STATE, []) or []


def _tg_manual_store(rec):
    """Запомнить розданную ссылку побайтно за её клиентом.

    Храним именно ссылку, а не её пересборку: карточка не имеет права предлагать оператору
    другой текст, чем тот, что уже у клиентов на руках.
    """
    # #241: один клиент может держать две розданные ссылки — MTProto и веб-прокси, —
    # поэтому снятый по имени откат различает носитель, а не только клиента.
    kind = rec.get("kind") or "proxy"
    recs = [r for r in _tg_manual_records()
            if not (r.get("username") == rec.get("username")
                    and (r.get("kind") or "proxy") == kind)]
    recs.append(rec)
    _save(_TG_MANUAL_STATE, recs, 0o600)
    return recs


def _tg_manual_for(username):
    for r in _tg_manual_records():
        if r.get("username") == username:
            return r
    return None


def _tg_link_secret(link):
    m = re.search(r"(?i)[?&]secret=([^&\s]+)", link or "")
    return (m.group(1) if m else "").strip().lower()


def _tg_user_secrets(row):
    """Все ee-секреты, которые telemt выдаёт этому клиенту прямо сейчас: по одному на фронт."""
    out = set()
    for l in ((row or {}).get("links") or {}).get("tls") or []:
        s = _tg_link_secret(l)
        if s:
            out.add(s)
    return out


def _tg_toml_tls_domains(text=None):
    """`tls_domain` + `tls_domains` из telemt.toml — то же, что отдаёт API, но без сети."""
    if text is None:
        try:
            text = _tg_manual_read_toml()
        except Exception:
            return []
    doms = []
    m = re.search(r'(?m)^\s*tls_domain\s*=\s*"([^"]+)"', text)
    if m:
        doms.append(m.group(1).strip().lower())
    m = re.search(r'(?m)^\s*tls_domains\s*=\s*\[([^\]]*)\]', text)
    if m:
        doms += [d.strip().strip(",").strip().strip('"').strip().lower()
                 for d in m.group(1).split(",")]
    return sorted({d for d in doms if d and "." in d})


def _tg_manual_fronts():
    try:
        sni = _tg_sni()
    except Exception:
        sni = {}
    doms = [(sni.get("tls_domain") or "")] + list(sni.get("tls_domains") or [])
    doms = sorted({d.strip().lower() for d in doms if d and d.strip()})
    # если API молчит, список берём из файла: записать один фронт вместо живого списка
    # означало бы потерять фронты уже розданных ссылок
    return doms or _tg_toml_tls_domains()


def _tg_key_owner(key):
    """Имя клиента, которому уже принадлежит этот ключ (по `[access.users]`)."""
    for name, k in _tg_toml_access_users().items():
        if k == key:
            return name
    return ""


def _tg_manual_name(front, key, taken):
    """Имя нового клиента из фронта: допустимое для telemt и не занятое."""
    base = _tg_slug((front.split(".")[0] if "." in front else front)[:24], "proxy")[:24]
    if base not in taken:
        return base
    cand = (base[:23] + "-" + key[:8])[:32]
    if cand not in taken:
        return cand
    raise RuntimeError("клиент «%s» уже есть, а имя для этого ключа занято — укажите клиента сами" % cand)


def _tg_manual_status(rows=None):
    """Состояние розданных ссылок: помнит ли telemt побайтно каждый вставленный секрет.

    #241: у ссылки веб-прокси своя доверка — её telemt выдаёт не из `links.tls`, а собирает
    из имени vhost'а и ключа клиента, поэтому судим её равнением готовой ссылки.
    """
    recs = _tg_manual_records()
    if not recs:
        return []
    if rows is None:
        try:
            rows = _tg_api("GET", "/v1/users").get("data") or []
        except Exception:
            rows = []
    by = {(r0.get("username") or ""): r0 for r0 in rows or []}
    out = []
    for r in recs:
        name = r.get("username") or ""
        row = by.get(name)
        kind = r.get("kind") or "proxy"
        if kind == "web":
            live = ""
            try:
                live = _tg_web_link(name)
            except Exception:
                live = ""
            ok = bool(r.get("link")) and live == r["link"]
            if not row:
                detail = "клиент «%s» не найден в telemt" % name
            elif not r.get("link"):
                detail = "ссылка не записана полностью"
            elif not ok:
                detail = "web не выдаёт эту ссылку: фасад %s или ключ потеряны" % (r.get("front") or "?")
            else:
                detail = ""
        else:
            ok = bool(r.get("secret")) and r["secret"] in _tg_user_secrets(row)
            if not row:
                detail = "клиент «%s» не найден в telemt" % name
            elif not r.get("secret"):
                detail = "ссылка не записана полностью"
            elif not ok:
                detail = ("telemt не выдаёт этот секрет: фронт %s или ключ потеряны"
                          % (r.get("front") or "?"))
            else:
                detail = ""
        out.append({"username": name, "kind": kind, "link": r.get("link") or "",
                    "port": r.get("port"),
                    "front": r.get("front") or "", "ts": r.get("ts") or "",
                    "ok": ok, "detail": detail})
    return out


def _tg_manual_preview_web(p, username=""):
    """#241: план подгонки под розданную ссылку `tg://webproxy` — только чтение.

    Ссылка веб-прокси называет две вещи: имя фасада и ключ клиента. Фронта и порта в ней нет,
    поэтому и подгонка короче: ключ, имя vhost'а, присутствие клиента в профилях. Всё остальное
    (сертификат на имя, DNS) панель обязана назвать, но не чинит — это живёт во вкладке Сайт.
    """
    if not _tg_available():
        raise RuntimeError("telemt API не отвечает — сначала включи MTProto-прокси")
    w = _tg_web_get()
    if not w:
        raise RuntimeError("telemt не отдаёт раздел `[web]` — веб-прокси в движке не виден")
    users = [u.get("username") or "" for u in (_tg_api("GET", "/v1/users").get("data") or [])]
    name = (username or "").strip()
    if name and not _TG_USER_NAME.fullmatch(name):
        raise RuntimeError("имя клиента: только латиница, цифры, _ . - (до 32 символов)")
    if name and name not in users:
        raise RuntimeError("клиента «%s» нет в telemt — выберите существующего или оставьте поле пустым"
                           % name)
    owner = _tg_key_owner(p["key"])
    blockers, warnings, actions = [], [], []
    if owner and name and owner != name:
        blockers.append("ключ из ссылки уже принадлежит клиенту «%s»: перепривязка к «%s» "
                        "оставила бы два клиента на одном ключе" % (owner, name))
    target = name or owner
    if not target:
        target = _tg_manual_name(p["front"], p["key"], set(users))
    need_user = target not in users
    if need_user:
        actions.append("создать клиента «%s»" % target)
    need_key = owner != target
    if need_key:
        actions.append("привязать ключ из ссылки к клиенту «%s»" % target)
        # Одно и то же число держит и `ee`-секреты MTProto, и `dd` этого веб-прокси:
        # молчать об этом нельзя — у клиента меняются все розданные ссылки.
        warnings.append("ключ у клиента один: меняя его под ссылку веб-прокси, панель меняет "
                        "и MTProto-ссылки клиента «%s»" % target)
    need_enable = not w.get("enabled")
    if need_enable:
        blockers.append("веб-прокси в telemt выключен — включи его в верхнем блоке вкладки «Прокси», "
                        "здесь панель его не поднимает")
    need_host = bool(w.get("host")) and w["host"] != p["server"]
    if need_host:
        actions.append("подставить имя фасада %s в vhost веб-прокси (сейчас %s)"
                       % (p["server"], w["host"]))
    need_profile = not need_user and target not in (w.get("profiles") or [])
    if need_profile:
        actions.append("добавить клиента «%s» в профили веб-прокси" % target)
    need_mode = ""
    if not need_user and target in (w.get("profiles") or []):
        mode = (_tg_toml_web_profiles() or {}).get(target, "")
        if mode and mode != "dd":
            need_mode = mode
            actions.append("перевести профиль «%s» в режим секретов dd (сейчас %s)"
                           % (target, mode))
    cp = _cert_pathes()
    cert_file = cp["cert"]
    if cert_file and os.path.exists(cert_file):
        names = _cert_dns_names(cert_file)
        if not _host_covered_by(names, p["server"]):
            blockers.append("сертификат %s не покрывает имя %s (SAN: %s) — клиенты по ссылке "
                            "получат ошибку TLS, а не прокси"
                            % (os.path.basename(cert_file), p["server"],
                               ", ".join(names[:4]) or "пустой"))
    else:
        blockers.append("сертификата в настройках панели нет — на имя %s клиенты придут с ошибкой "
                        "TLS; выпустите сертификат во вкладке Сайт" % p["server"])
    occ = _sock_occupant(443)
    if occ.get("free") or not ("nginx" in (occ.get("proc") or "")
                               or "telemt" in (occ.get("proc") or "")):
        warnings.append("на :443 сидит %s, а не фасад веб-прокси: ссылка заработает только после "
                        "установки веб-прокси (это не блокирует подгонку конфига)"
                        % (occ.get("proc") or "никто"))
    try:
        ips = _resolve_ips(p["server"])
        ours = _our_ips()
        if ips and ours and not (ips & ours):
            warnings.append("адрес %s из ссылки резолвится на %s, а этот сервер — %s: пока DNS "
                            "не сойдётся, клиенты по ссылке придут не сюда (это не блокирует "
                            "подгонку конфига)"
                            % (p["server"], ", ".join(sorted(ips)[:2]), ", ".join(sorted(ours)[:2])))
    except Exception:
        pass
    if not w.get("host") and not need_enable:
        blockers.append("у веб-прокси нет ни одного vhost'а — включите его и задайте имя во "
                        "верхнем блоке вкладки «Прокси»")
    issued_ok = False
    try:
        issued_ok = _tg_web_link(target) == p["link"]
    except Exception:
        issued_ok = False
    already = issued_ok and not actions
    if actions:
        actions.append("перезапустить telemt один раз" if need_host
                       else "telemt не перезапускаем: правки профилей он принимает на ходу")
    return {"ok": True, "kind": "web", "parsed": p, "username": target, "owner": owner,
            "front": p["server"], "port": 443, "server": p["server"],
            "web": {"enabled": w.get("enabled"), "host": w.get("host"),
                    "profiles": list(w.get("profiles") or [])},
            "need_user": need_user, "need_key": need_key, "need_host": need_host,
            "need_profile": need_profile, "need_mode": need_mode,
            "need_enable": need_enable, "restart": bool(need_host), "already": already,
            "actions": actions or ["подгонка не требуется — ссылка уже настроена"],
            "blockers": blockers, "warnings": warnings, "can_apply": not blockers}


def _tg_manual_preview(link, username=""):
    """Только чтение: план подгонки под розданную ссылку, блокеры и предупреждения.

    Ни файла, ни API не касается.
    """
    p = _tg_manual_parse(link)
    if p.get("kind") == "web":
        return _tg_manual_preview_web(p, username)
    if not _tg_available():
        raise RuntimeError("telemt API не отвечает — сначала включи MTProto-прокси")
    text = _tg_manual_read_toml()
    users = [u.get("username") or "" for u in (_tg_api("GET", "/v1/users").get("data") or [])]
    name = (username or "").strip()
    if name and not _TG_USER_NAME.fullmatch(name):
        raise RuntimeError("имя клиента: только латиница, цифры, _ . - (до 32 символов)")
    if name and name not in users:
        raise RuntimeError("клиента «%s» нет в telemt — выберите существующего или оставьте поле пустым"
                           % name)
    owner = _tg_key_owner(p["key"])
    fronts = _tg_manual_fronts()
    ports = _tg_manual_public_ports(text)
    blockers, warnings, actions = [], [], []
    if owner and name and owner != name:
        blockers.append("ключ из ссылки уже принадлежит клиенту «%s»: перепривязка к «%s» "
                        "оставила бы два клиента на одном ключе" % (owner, name))
    target = name or owner
    if not target:
        target = _tg_manual_name(p["front"], p["key"], set(users))
    if target not in users:
        actions.append("создать клиента «%s»" % target)
    if owner != target:
        actions.append("привязать секрет из ссылки к клиенту «%s»" % target)
    need_front = p["front"] not in fronts
    if need_front:
        actions.append("добавить фронт %s в список tls_domains, сохранив остальные" % p["front"])
    need_port = p["port"] not in ports
    if need_port:
        actions.append("добавить публичный MTProto-слушатель на :%d" % p["port"])
    occ = _sock_occupant(p["port"])
    if need_port and not occ.get("free") and "telemt" not in (occ.get("proc") or ""):
        blockers.append("порт :%d занят %s — клиенты по этой ссылке туда не придут"
                        % (p["port"], occ.get("proc") or "другим процессом"))
        if p["port"] == 443:
            blockers.append("на :443 сидит развилка мюкса: MTProto на общий порт включайте "
                            "галочкой протокола во вкладке «Мюкс», а не здесь")
    if actions:
        actions.append("перезапустить telemt один раз")
    if p.get("composed"):
        # #196: ссылка на глазах стала другой, и молчать об этом нельзя.
        warnings.append("панель достроила секрет из бота: было 32 hex без `ee` и без фронта, "
                        "стало `ee` + ключ + hex(«%s»); готовая ссылка — ниже" % p["composed"])
    try:
        ips = _resolve_ips(p["server"])
        ours = _our_ips()
        if ips and ours and not (ips & ours):
            warnings.append("адрес %s из ссылки резолвится на %s, а этот сервер — %s: пока DNS "
                            "не сойдётся, клиенты по ссылке придут не сюда (это не блокирует "
                            "подгонку конфига)"
                            % (p["server"], ", ".join(sorted(ips)[:2]), ", ".join(sorted(ours)[:2])))
    except Exception:
        pass
    issued = _tg_user_secrets(_tg_user_row(target)) if target in users else set()
    already = p["secret"] in issued and not need_port
    return {"ok": True, "kind": "proxy", "parsed": p, "username": target, "owner": owner,
            "front": p["front"], "port": p["port"], "fronts": fronts, "ports": ports,
            "need_user": target not in users, "need_front": need_front, "need_port": need_port,
            "restart": bool(actions), "already": already,
            "actions": actions or ["подгонка не требуется — ссылка уже настроена"],
            "blockers": blockers, "warnings": warnings, "can_apply": not blockers}


def _tg_manual_guard(backup):
    """Откат: вернуть снятый `telemt.toml` и поднять движок. Одна физика для обеих веток."""
    def _restore(why):
        try:
            with open(TELEMT_CONF, "w", encoding="utf-8") as f:
                f.write(backup)
            subprocess.run(["systemctl", "restart", "telemt"], capture_output=True, timeout=120)
        except Exception as e2:
            why += " (откат не выполнен: %s)" % str(e2)[:80]
        raise RuntimeError(why)
    return _restore


def _tg_manual_apply_web(pv):
    """#241: подогнать веб-прокси под уже розданную ссылку `tg://webproxy`.

    Порядок: ключ клиента, потом имя фасада и адрес, потом профили — и побайтная доверка
    ссылки, которую отдаёт сам telemt. Не сошлось — снятый `telemt.toml`, рестарт и отказ.
    """
    p = pv["parsed"]
    target = pv["username"]
    backup = _tg_manual_read_toml()
    _restore = _tg_manual_guard(backup)
    created = bound = moved = False
    try:
        if pv["need_user"]:
            _tg_add(target, "web")
            created = True
        if pv["need_key"]:
            _tg_rotate_secret(target, p["key"])
            bound = True
        if pv["need_host"]:
            _tg_web_set_vhost(host=p["server"])
            moved = True
        if pv["need_profile"] or pv["need_mode"]:
            keep = list((pv.get("web") or {}).get("profiles") or [])
            _tg_web_set_profiles(list(dict.fromkeys(keep + [target])), secret_mode="dd")
            moved = True
    except Exception as e:
        _restore("не смог подстроить веб-прокси: %s — прежнее состояние возвращено" % str(e)[:140])
    restarted = False
    if pv["restart"]:
        r = subprocess.run(["systemctl", "restart", "telemt"], capture_output=True,
                           text=True, timeout=120)
        restarted = True
        if r.returncode != 0:
            _restore("telemt не перезапустился (rc=%d) — конфиг откачен" % r.returncode)
    verok = False
    for _ in range(15 if pv["restart"] else 3):
        try:
            verok = _tg_web_link(target) == p["link"]
        except Exception:
            verok = False
        if verok:
            break
        time.sleep(1)
    if not verok:
        _restore("telemt не выдаёт вставленную ссылку побайтно — под клиента «%s» он отдал другое; "
                 "конфиг откачен%s" % (target, "" if not created else
                                       ", клиента можно удалить"))
    occ = _sock_occupant(443)
    listening = (not occ.get("free")) and ("nginx" in (occ.get("proc") or "")
                                           or "telemt" in (occ.get("proc") or ""))
    _tg_manual_store({"kind": "web", "username": target, "link": p["link"],
                      "secret": p["secret"], "front": p["server"], "port": 443,
                      "ts": _now_iso()})
    _audit("tg_manual_link", kind="web", username=target, host=p["server"],
           created=created, bound=bound, moved=moved, restarted=restarted)
    note = "Ссылка настроена: telemt выдаёт её побайтно клиенту «%s»" % target
    if not listening:
        note += ". На :443 сейчас %s — фасад веб-прокси надо установить или перевыпустить " \
                "(вкладка «Прокси», блок «Веб-прокси»)" % (occ.get("proc") or "никто")
    if pv["warnings"]:
        note += ". " + " ".join(pv["warnings"])
    return {"ok": True, "kind": "web", "username": target, "link": p["link"],
            "port": 443, "front": p["server"], "verified": True, "listening": listening,
            "created": created, "bound": bound, "moved": moved, "restarted": restarted,
            "note": note, "warnings": pv["warnings"]}


def _tg_manual_apply(link, username="", confirm=False):
    """Подогнать telemt под уже розданную ссылку, чтобы её клиенты не заметили переезда.

    Порядок намеренный: сначала API (он сам перезаписывает telemt.toml), потом правка файла
    с слушателем, потом единственный перезапуск — иначе telemt затёр бы нашу дописку.
    Верификация побайтная: секрет, который telemt выдаёт привязанному клиенту, обязан равняться
    вставленному. Не совпало — возврат снятого файла, рестарт и честный отказ.
    """
    if not confirm:
        raise RuntimeError("нужно подтверждение (confirm)")
    pv = _tg_manual_preview(link, username)
    if not pv["can_apply"]:
        raise RuntimeError("нельзя применить: " + "; ".join(pv["blockers"] or ["неизвестно"]))
    p = pv["parsed"]
    if p.get("kind") == "web":
        return _tg_manual_apply_web(pv)
    target = pv["username"]
    backup = _tg_manual_read_toml()
    _restore = _tg_manual_guard(backup)
    created = False
    added = False
    try:
        if pv["need_user"]:
            _tg_add(target, "mtproto")
            created = True
        if pv["owner"] != target:
            _tg_rotate_secret(target, p["key"])
        if pv["need_front"]:
            _tg_sni_set(tls_domains=pv["fronts"] + [p["front"]])
        if pv["need_port"]:
            # перечитываем: `telemt` сам перезаписывает файл при изменении через API
            text = _tg_manual_read_toml()
            text, added = _tg_toml_add_manual_listener(text, p["port"],
                                                       ipv6=_tg_mp_ipv6_want())
            if added:
                with open(TELEMT_CONF, "w", encoding="utf-8") as f:
                    f.write(text)
    except Exception as e:
        _restore("не смог подстроить конфиг: %s — прежнее состояние возвращено" % str(e)[:140])
    restarted = False
    if pv["restart"]:
        r = subprocess.run(["systemctl", "restart", "telemt"], capture_output=True,
                           text=True, timeout=120)
        restarted = True
        if r.returncode != 0:
            _restore("telemt не перезапустился (rc=%d) — конфиг откачен" % r.returncode)
    verok = False
    for _ in range(15 if pv["restart"] else 1):
        try:
            got = _tg_user_secrets(_tg_user_row(target))
        except Exception:
            got = set()
        if p["secret"] in got:
            verok = True
            break
        time.sleep(1)
    if not verok:
        _restore("telemt не выдаёт вставленный секрет побайтно — ссылка не заработала, "
                 "конфиг откачен%s" % ("" if not created else
                                       "; клиента «%s» можно удалить" % target))
    listening = True
    if pv["need_port"]:
        occ = _sock_occupant(p["port"])
        listening = (not occ.get("free")) and "telemt" in (occ.get("proc") or "")
        if not listening:
            _restore("после перезапуска на :%d сидит %s, а не telemt — конфиг откачен"
                     % (p["port"], occ.get("proc") or "никто"))
    try:
        _tg_mp_firewall_open(p["port"])
    except Exception:
        pass
    try:
        _synfix_apply()
    except Exception as e:
        print("synfix: " + str(e), flush=True)
    _tg_manual_store({"username": target, "link": p["link"], "secret": p["secret"],
                      "front": p["front"], "port": p["port"], "ts": _now_iso()})
    _audit("tg_manual_link", username=target, port=p["port"], front=p["front"],
           added_listener=added, added_front=pv["need_front"], created=created,
           restarted=restarted)
    note = "Ссылка настроена: telemt выдаёт её побайтно клиенту «%s»" % target
    if pv["need_port"] and added:
        note += ", MTProto принимает на :%d" % p["port"]
    if pv["warnings"]:
        note += ". " + " ".join(pv["warnings"])
    return {"ok": True, "username": target, "link": p["link"], "port": p["port"],
            "front": p["front"], "verified": True, "listening": listening,
            "added_listener": added, "added_front": pv["need_front"],
            "created": created, "restarted": restarted, "note": note,
            "warnings": pv["warnings"]}


FRONT_SITE_DIR = "/opt/vpnpanel/frontsite"
# #168: у MTProto-имени своя сайт-маска — свой корень и свой петлевой фронт. Форма,
# которую играет прокси, снимается с НЕЁ, а не с чужого фасада: два разных имени не
# обязаны отдавать один и тот же байт-в-байт сайт.
FRONT_SITE_MP_DIR = "/opt/vpnpanel/frontsite-mp"
_NG_FRONT_CONF = "/etc/nginx/conf.d/veil-front.conf"

def _front_dns_ensure(domain):
    """Фронт обязан жить в зоне Cloudflare панели: серые A/AAAA на этот сервер.
    Создаёт записи, если их нет; пересоздаёт, если они облачные/уехали."""
    zid, zone = _cf_zone()
    if not (domain == zone or domain.endswith("." + zone)):
        raise RuntimeError("фронт " + domain + " не в Cloudflare-зоне " + (zone or "?") +
                           " — для своего фронта нужна зона с настроенным токеном (вкладка Сайт)")
    ip4, ip6 = _pub_ip4() or "", _pub_ip6() or ""
    rep = []
    for typ, ip in (("A", ip4), ("AAAA", ip6)):
        if not ip:
            continue
        q = "/zones/%s/dns_records?type=%s&name=%s&per_page=5" % (
            urllib.parse.quote(zid), typ, urllib.parse.quote(domain))
        res = _cf_api("GET", q) or []
        if len(res) == 1 and (res[0].get("content") or "").lower() == ip.lower() \
                and not res[0].get("proxied"):
            rep.append("%s %s уже указывает сюда" % (typ, domain))
            continue
        for r0 in res:
            _cf_api("DELETE", "/zones/%s/dns_records/%s" % (
                urllib.parse.quote(zid), urllib.parse.quote(r0.get("id") or "")))
        _cf_api("POST", "/zones/%s/dns_records" % urllib.parse.quote(zid),
                {"type": typ, "name": domain, "content": ip, "ttl": 60, "proxied": False})
        rep.append("%s %s → %s (создана/обновлена)" % (typ, domain, ip))
    return rep

def _front_cert_issue(domain):
    """LE-сертификата произвольного домена через DNS-01 (Cloudflare-хук панели).
    В отличие от _cert_issue — НЕ трогает настройки панели (cert_domain/panel_domain),
    продлевается общим циклом certbot renew (имя veil-<domain>)."""
    live = "%s/live/veil-%s" % (CERT_DIR, domain)
    certp, keyp = live + "/fullchain.pem", live + "/privkey.pem"
    if os.path.exists(certp) and os.path.exists(keyp):
        exp = _cert_expire(certp)
        if exp and exp > time.time() + 21 * 86400:
            return certp, keyp
    if _dns01_provider() != "cloudflare":
        raise RuntimeError("для своего фронта нужен Cloudflare (токен Zone→DNS:Edit) — "
                           "только он умеет выпускать TXT-записи для Let's Encrypt")
    if _CERT_STATE.get("busy"):
        raise RuntimeError("выпуск сертификата уже идёт — подожди минуту")
    import sys
    me = os.path.abspath(__file__)
    py = sys.executable or "python3"
    email = (CFG_CACHE.get("cert_email") or "").strip()
    # Тот же порядок, что у `_cert_issue` (#175): собственный фронт не имеет права
    # сузить набор имён уже выпущенной связки — иначе исчезнут имена, под которые
    # раздают ссылки клиенты.
    uni = _cert_san_union(domain)
    if uni["over_limit"]:
        raise RuntimeError("имён получилось %d, а сервиса выдачи сертификатов позволяет "
                           "%d в одном сертификате — убери лишние имена" %
                           (len(uni["keep"]), _SAN_MAX_NAMES))
    bud = _le_budget(domain)
    if bud["visible"] and bud["left"] <= 0:
        raise RuntimeError("лимит выпуска на домен %s исчерпан этой коробкой (%d из %d за "
                           "неделю)" % (bud["domain"], bud["issued"], bud["limit"]))
    dargs = []
    for n0 in uni["keep"] or [domain]:
        dargs += ["-d", n0]
    args = ["certbot", "certonly", "--manual", "--preferred-challenges", "dns",
            "--manual-auth-hook", "%s %s --dns01-hook auth" % (py, me),
            "--manual-cleanup-hook", "%s %s --dns01-hook cleanup" % (py, me)]
    args += dargs + ["--non-interactive", "--agree-tos",
                     "--deploy-hook", "systemctl reload nginx"]
    if os.path.exists("%s/renewal/veil-%s.conf" % (CERT_DIR, domain)) and \
            [n.lower() for n in (uni["keep"] or [domain])] != [h.lower() for h in uni["have"]]:
        args += ["--expand"]
    args += ["--email", email] if email else ["--register-unsafely-without-email"]
    args += ["--config-dir", CERT_DIR, "--work-dir", CERT_DIR + "/work",
             "--logs-dir", CERT_DIR + "/logs", "--cert-name", "veil-" + domain]
    _CERT_STATE["busy"] = True
    try:
        os.makedirs(CERT_DIR, exist_ok=True)
        r = subprocess.run(args, capture_output=True, text=True, timeout=320)
        if r.returncode != 0:
            raise RuntimeError("certbot: " + (r.stderr or r.stdout)[-400:])
        _cert_tree_perms()
    finally:
        _CERT_STATE["busy"] = False
    if not (os.path.exists(certp) and os.path.exists(keyp)):
        raise RuntimeError("certbot завершился, но fullchain/privkey не найдены")
    return certp, keyp

