def _ai_key_check(ov=None):
    """Один короткий тестовый запрос текущим (или переданным) ключом/эндпоинтом/моделью.
    Возвращает вердикт человеческими словами и НИКОГДА не отдаёт ключ в ответ."""
    ov = ov or {}
    base = ((ov.get("base") if "base" in ov else CFG_CACHE.get("ai_base"))
            or "https://api.openai.com/v1").strip()
    key = ((ov.get("key") if "key" in ov else CFG_CACHE.get("ai_key")) or "").strip()
    model = ((ov.get("model") if "model" in ov else CFG_CACHE.get("ai_model"))
             or "gpt-4o-mini").strip()
    if not re.match(r"^https?://", base):
        return {"ok": False, "code": "badscheme",
                "msg": "URL эндпоинта должен начинаться с https:// (или http:// для локальной модели)"}
    if not key:
        return {"ok": False, "code": "nokey",
                "msg": "Ключа нет вообще — вставь его в поле «API-ключ» и сохрани. "
                       "Локальной модели (Ollama на 127.0.0.1) ключ не нужен."}
    body = {"model": model, "messages": [{"role": "user", "content": "ping"}],
            "max_tokens": 3, "temperature": 0}
    req = urllib.request.Request(base.rstrip("/") + "/chat/completions",
                                 data=json.dumps(body).encode(), method="POST",
                                 headers={"Content-Type": "application/json",
                                          "Authorization": "Bearer " + key})
    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=30, context=ctx) as r:
            j = json.loads(r.read().decode("utf-8", "replace") or "{}")
        ch = ((j.get("choices") or [{}])[0]).get("message") or {}
        _audit("ai_key_check", ok=True, model=model, base=base[:80])
        echo = str(ch.get("content") or "").strip()[:40]
        return {"ok": True,
                "msg": "Ключ работает: %s ответил%s." %
                (model, (" «" + echo + "»") if echo else "")}
    except urllib.error.HTTPError as e:
        try:
            det = (e.read().decode("utf-8", "replace") or "")[:300]
        except Exception:
            det = ""
        code = e.code
        hints = {400: "эндпоинт не понял запрос — чаще всего это неверный ключ или модель не от этого сервиса",
                 401: "ключ не принят — скорее всего скопирован не целиком, устарел или от другого сервиса",
                 403: "ключ принят, но прав на эту модель/эндпоинт нет",
                 404: "нет такой модели или неверный URL эндпоинта (проверь, что в конце путь /v1, а не /chat/completions)",
                 429: "ключ живой, но упёрся в лимит или баланс пуст",
                 500: "модельный сервис сам моргает — попробуй позже",
                 503: "эндпоинт временно недоступен"}
        msg = hints.get(code, "эндпоинт ответил HTTP %d" % code)
        low = det.lower()
        if ("api key not valid" in low or "invalid_api_key" in low
                or "invalid api key" in low or "incorrect api key" in low):
            msg = "сервис прямо говорит: API-ключ неверный"
        elif "no available" in low or "balance" in low or "quota" in low:
            msg = "кончился баланс или квота — пополни счёт у провайдера"
        elif ("model" in low and ("not found" in low or "does not exist" in low
                                  or "unknown" in low)):
            msg = "модель с таким именем у этого провайдера не найдена"
        _audit("ai_key_check", ok=False, http=code, base=base[:80])
        return {"ok": False, "code": "http%d" % code, "msg": msg, "detail": det}
    except Exception as e:
        _audit("ai_key_check", ok=False, err=str(e)[:120], base=base[:80])
        return {"ok": False, "code": "net",
                "msg": "до эндпоинта не достучались: " + str(e)[:160]}


# ---------- `flux`: узел `openflux`, ведомый панелью ----------

# Ядро берётся с официальной выдачи закреплённым выпуском и проверяется гашением
# дважды: о закреплённое число панели и о `SHA256SUMS.txt` той же выдачи. Панель
# ядро не изменяет — она только скачивает, кладёт и запускает штатными флагами,
# поэтому GPL-3.0 обязывает нас назвать источник, а не отдавать исходники: это
# делает `flux/CREDITS`.
FLUX_VER = "v0.4.1"
FLUX_ASSET = "openflux-linux-amd64"
FLUX_SHA = "428f5b2a1dbaf06778dc3274c1dbb3fd70d9e6caecce6440146cd53c3998611a"
FLUX_DL = ("https://github.com/p1neappleXpress/OpenFlux/releases/download/"
           + FLUX_VER + "/" + FLUX_ASSET)
FLUX_SUMS_DL = ("https://github.com/p1neappleXpress/OpenFlux/releases/download/"
                + FLUX_VER + "/SHA256SUMS.txt")
FLUX_REPO = "https://github.com/p1neappleXpress/OpenFlux"
FLUX_BIN = "/usr/local/bin/openflux"
FLUX_DIR = f"{BASE}/flux"
FLUX_STATE = f"{BASE}/flux.json"
FLUX_SECRET = f"{FLUX_DIR}/secret.key"
FLUX_UNIT = "openflux-exit"
FLUX_UNIT_PATH = f"/etc/systemd/system/{FLUX_UNIT}.service"
# 28 МБ ядра + место под Cookie-жар и запись: на исходе диска установка обрывается
# на середине боевого пути, поэтому порог назван числом, а не «немного осталось»
FLUX_MIN_FREE = 96 * 1024 * 1024
FLUX_CTX_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,63}")
FLUX_MODES = ("l4", "l3")
FLUX_DEFAULT_PORT = 8446
FLUX_LOCK = threading.Lock()

# Носители белых списков. Смысл узла не в `direct`, а в том, чтобы туннель ехал
# поверх сервиса, который у оператора остаётся открытым и в режим белого списка.
# Приоритеты и точные формы ссылок взяты не отсюда, а из самого ядра —
# `provision/transports.go`: `vyandex` стоит 100, `mailru` 90, а `direct` там
# сознательно опущен до 50 и служит запасным, а не главным. Ссылка обязана нести
# те же числа: по ним клиент выбирает, чем ехать.
FLUX_DIRECT_PRI = 50
# Свой носитель живёт на коробке, а не в чужом публичном документе: панель держит
# байты скрипта и подпись соседа, ядро читает их по пути из юнита. Ключ проверки —
# публичная часть той же подписи; приватная наружу не выходит.
FLUX_CAR_DIR = f"{BASE}/carriers"
FLUX_R7_PUBKEY = "0d4cc83deeb73817129a286bd39c8dc0711ebfddcf6d1f49b2cda18c08f199a7"
FLUX_CARRIERS = (
    {"type": "vyandex", "pri": 100, "flag": "--vyandex-url",
     "name": "Яндекс",
     "hint": "https://docs.yandex.ru/edit/d/…",
     "re": re.compile(r"https://(?:docs|disk)\.yandex\.(?:ru|com|by|kz|uz)"
                      r"/edit/d/[A-Za-z0-9_-]{16,200}")},
    {"type": "mailru", "pri": 90, "flag": "--mailru-url",
     "name": "Mail.ru",
     "hint": "https://cloud.mail.ru/public/…/…",
     "re": re.compile(r"https://cloud\.mail\.ru/public/[A-Za-z0-9_-]{2,64}"
                      r"/[A-Za-z0-9_-]{2,128}")},
    # `cupsonline` — комната собеседования cups.online. Панель ставит ей 70:
    # номер не из ядрового списка, а отсюда, и он ниже документовых носителей,
    # которых судит ядро. Смысл отдельный: комнату сервис выдаёт анонимно, без
    # входа и без телефона, — в отличие от Яндекса и Mail.ru, где нужен аккаунт.
    # Адрес комнаты живёт в запросе (`?room=`), поэтому у строки стоит
    # `keep_query`: обычный разрез по `?` убил бы саму комнату.
    {"type": "cupsonline", "pri": 70, "flag": "--cupsonline-url",
     "name": "Cups.online", "keep_query": True,
     "hint": "https://interview.cups.online/live-coding/?room=…",
     "re": re.compile(r"https://interview\.cups\.online/live-coding/"
                      r"\?room=[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-"
                      r"[0-9a-f]{4}-[0-9a-f]{12}")},
    # `r7` — носитель, сочинённый здесь. Байты скрипта и подпись к нему панель
    # держит на коробке, но ссылку чужого документа строка всё равно обязана
    # спросить: живым промером снято, что ядро передаёт скрипту адрес через
    # `--url`, а без него носитель сразу глохнет («ссылка документа не задана»).
    # Имя транспорта ядро знает одно (`script`), имя носителя скрипт называет сам.
    # Приоритет `85` встал между `mailru` и `cupsonline`: свой черновик идёт ниже
    # чужих документовых носителей, потому что на клиенте он ещё не мерян.
    {"type": "r7", "tl": "script", "pri": 85, "own": True, "script": "r7",
     "pubkey": FLUX_R7_PUBKEY, "flag": "--url", "name": "R7 — свой скрипт",
     "hint": "https://cloud.mail.ru/public/…/…",
     "re": re.compile(r"https://cloud\.mail\.ru/public/[A-Za-z0-9_-]{2,64}"
                      r"/[A-Za-z0-9_-]{2,128}")},
)
FLUX_CARRIER_BY = {c["type"]: c for c in FLUX_CARRIERS}


def _flux_state():
    st = _load(FLUX_STATE, {})
    if not isinstance(st, dict):
        st = {}
    st.setdefault("port", FLUX_DEFAULT_PORT)
    st.setdefault("mode", "l4")
    st.setdefault("ctx", "veil.flux")
    st.setdefault("carriers", [])
    return st


def _flux_save(st):
    _save(FLUX_STATE, st, 0o600)


def _flux_enabled():
    # Включено по умолчанию — выключено: морда не спрашивает, юнит не ставится,
    # пока владелец сам не поднимет рубильник в самой вкладке.
    return bool(CFG_CACHE.get("flux_enabled"))


def _flux_ctx_ok(ctx):
    return bool(FLUX_CTX_RE.fullmatch(str(ctx or "")))


def _flux_port_ok(port):
    try:
        port = int(port)
    except (TypeError, ValueError):
        return None
    return port if 1024 <= port <= 65535 else None


def _flux_clean_link(url, keep_query=False):
    """Ссылка носителя очищается ровно так, как это делает ядро в `cleanLink()`:
    без `?`, без `#` и без хвостовой косой черты. У носителя, помеченного
    `keep_query`, запрос остаётся: у комнаты адрес живёт именно в нём, и разрез
    по `?` стёр бы комнату. Панель чистит первой, потому что
    клиент потом читает то, что записано в ссылке, а `--make-link` форму не
    проверяет и пропускает мусор."""
    u = str(url or "").strip()
    cuts = ("#",) if keep_query else ("?", "#")
    for cut in cuts:
        u = u.split(cut, 1)[0]
    return u.rstrip("/")


def _flux_car_prj(c):
    """Что уносим из таблицы по выбранному носителю. Свои носители несут путь,
    имя транспорта ядра и ключ проверки — без них юнит не собрать."""
    return {k: c[k] for k in ("type", "pri", "flag", "name", "hint", "tl", "script",
                              "pubkey", "own") if k in c}


def _flux_script_ok(c):
    """Жив ли свой носитель: байты скрипта и подпись соседа сходятся с ключом.

    Верим не один раз при выпуске, а каждый раз, когда собираем юнит или просим
    состояние: файл лежит в директории, доступ к которой есть не только у панели,
    а ядро исполняет его в юните. Молча принять подмену значило бы отдать
    `--script-pubkey` роль штампа: ядро сверяет подпись с КЛЮЧОМ, который ему
    назвали мы, и подменённый файл с нашей же подписью соседа прошёл бы дальше.
    Возвращает (живо, причина отказа, байт скрипта)."""
    path = os.path.join(FLUX_CAR_DIR, c["script"] + ".js")
    try:
        with open(path, "rb") as f:
            body = f.read()
        with open(path + ".sig", "rb") as f:
            sig = f.read()
    except OSError:
        return False, "файла носителя или его подписи нет", 0
    if len(sig) != 64:
        return False, f"подписи не `64` байта, а {len(sig)}", len(body)
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(c["pubkey"])).verify(sig, body)
    except ImportError:
        return False, "библиотеки проверки подписи на коробке нет", len(body)
    except Exception:
        return False, "подпись не сходится с байтами носителя", len(body)
    return True, "", len(body)


def _flux_carriers_ok(raw):
    """Носители белых списков: принимаем только те типы, чью форму мы умеем
    собрать в юнит, и судим ссылку тем же правилом, которым ядро судит ноду
    (`CheckTransports`). Возвращает (принятые по убыванию приоритета, отказы).
    Отказ называет носителя, а не молчит: «транспорт выбран неверно» и «ссылка
    не той формы» — разные причины, и чинить их надо разными действиями."""
    items = raw if isinstance(raw, list) else []
    seen, out, bad = set(), [], []
    for it in items:
        if not isinstance(it, dict):
            continue
        t = str(it.get("type") or "").strip()
        if not t:
            continue
        c = FLUX_CARRIER_BY.get(t)
        if c is None:
            bad.append(f"транспорт `{t}` нельзя выбрать для ноды")
            continue
        if t in seen:
            bad.append(f"транспорт `{t}` выбран дважды")
            continue
        if c.get("own"):
            # Своего носителя судят двумя мерами: файлом с коробки — подпись
            # обязана сойтись с байтами скрипта, — и ссылкой того же документного
            # вида, что и у чужих: её ядро передаёт скрипту через `--url`.
            ok, why, _size = _flux_script_ok(c)
            if not ok:
                bad.append(f"{c['name']}: {why}")
                continue
        url = _flux_clean_link(it.get("url"), keep_query=bool(c.get("keep_query")))
        if not url:
            bad.append(f"{c['name']}: ссылка пуста")
            continue
        if not c["re"].fullmatch(url):
            bad.append(f"{c['name']}: нужна ссылка вида {c['hint']}")
            continue
        seen.add(t)
        out.append(_flux_car_prj(c) | {"url": url})
    out.sort(key=lambda x: -x["pri"])
    return out, bad


def _flux_carriers_state(raw):
    """В состоянии живёт минимальная форма — только тип и ссылка. Приоритет, флаг
    и имя берутся из таблицы при каждой сборке, чтобы правка приоритета не
    застряла в уже записанном состоянии."""
    cars, _bad = _flux_carriers_ok(raw)
    return [{"type": c["type"], "url": c["url"]} for c in cars]


def _flux_port_busy(port):
    """Чем занят порт: имя держателя из `ss`, или пусто, если порт свободен.

    `-p` здесь обязателен: `ss -H -ltn` печатает строку слушателя, но имя
    процесса не показывает никогда, то есть без этого флага функция возвращала
    пустоту и на занятом порту — проверка «порт свободен» была пустой и
    пропускала чужой порт. Имя берётся из `users:(("xray",pid=..))`.
    """
    try:
        r = subprocess.run(["ss", "-H", "-ltnp", f"sport = :{int(port)}"],
                           capture_output=True, text=True, timeout=10)
    except Exception:
        return ""
    owner = ""
    for ln in (r.stdout or "").splitlines():
        m = re.search(r'\(\("([^"]+)"', ln)
        if m:
            owner = m.group(1)
            break
    return owner


def _flux_port_blocker(port):
    """Держатель порта, который мешает: чужой процесс. Свой `openflux` не
    мешает — применение делает `systemctl restart`, который освободит порт и
    займёт его заново, иначе узел нельзя было бы переприменить никогда."""
    owner = _flux_port_busy(port)
    if not owner:
        return ""
    if owner == os.path.basename(FLUX_BIN) and _unit_active(FLUX_UNIT):
        return ""
    return owner


def _flux_unit_enabled():
    """Стоит ли служба в автозапуске. Отдельно от «поднята прямо сейчас»:
    узел может быть запущен и снят с автозапуска, и наоборот — после
    перезагрузки коробки он не вернётся, а владелец будет думать, что вернётся."""
    try:
        return subprocess.run(["systemctl", "is-enabled", FLUX_UNIT],
                              capture_output=True, timeout=20).returncode == 0
    except Exception:
        return False


def _flux_sums_expect(text, asset):
    """Гашение нужного файла из общей сводки: в `SHA256SUMS.txt` восемь строк, и
    первая из них — чужой платформы файл. Взять «первую» значит отвергнуть свой."""
    for ln in str(text or "").splitlines():
        parts = ln.split()
        if len(parts) >= 2 and parts[-1] == asset:
            h = parts[0].lower()
            if re.fullmatch(r"[0-9a-f]{64}", h):
                return h
    return ""


def _flux_bin_info():
    """Что лежит на диске под именем ядра — есть ли, чьё, целое ли. Гашение
    считается по месту (28 МБ — десятые доли секунды), а не берётся на веру из
    прошлого снимка: файл могли подменить в обход панели."""
    out = {"present": False, "size": 0, "digest": "", "digest_ok": False,
           "ver": _flux_state().get("installed_ver") or ""}
    try:
        out["size"] = os.path.getsize(FLUX_BIN)
        out["present"] = True
    except OSError:
        return out
    try:
        out["digest"] = _sha256_file(FLUX_BIN)[:64]
    except Exception as e:
        out["err"] = type(e).__name__
        return out
    out["digest_ok"] = (out["digest"] == FLUX_SHA)
    return out


def _flux_unit_body(st):
    port = _flux_port_ok(st.get("port")) or FLUX_DEFAULT_PORT
    mode = st.get("mode") if st.get("mode") in FLUX_MODES else "l4"
    ctx = st.get("ctx") if _flux_ctx_ok(st.get("ctx")) else "veil.flux"
    # `direct` всегда в списке и всегда последним: когда носитель не поднялся
    # (документ требуют капчи, ссылка живёт на другом аккаунте), выход обязан
    # остаться доступным, а не молча умереть вместе с носителем.
    cars, _bad = _flux_carriers_ok(st.get("carriers"))
    tl = ",".join([f'{c.get("tl") or c["type"]}:{c["pri"]}' for c in cars]
                  + [f"direct:{FLUX_DIRECT_PRI}"])
    urls = "".join(f' {c["flag"]}="{c["url"]}"' for c in cars if c["url"])
    # Своему носителю в юните дают путь и ключ автора: ядро читает скрипт с диска,
    # сверяет подпись соседа до первого запуска кода и передаёт ему ссылку тем же
    # `--url`, каким кормит одиночный транспорт.
    urls += "".join(f' --script-path="{os.path.join(FLUX_CAR_DIR, c["script"] + ".js")}"'
                    f' --script-pubkey={c["pubkey"]}' for c in cars if c.get("own"))
    extra = ""
    if mode == "l3":
        # сырые сокеты и таблицы маршрутов: без этих прав `l3` падает на старте
        extra = ("AmbientCapabilities=CAP_NET_RAW CAP_NET_ADMIN CAP_NET_BIND_SERVICE\n"
                 "CapabilityBoundingSet=CAP_NET_RAW CAP_NET_ADMIN CAP_NET_BIND_SERVICE\n")
    return (
        "[Unit]\n"
        "Description=OpenFlux exit (ставит и снимает панель)\n"
        "After=network-online.target\n"
        "Wants=network-online.target\n"
        "StartLimitIntervalSec=60\n"
        "StartLimitBurst=5\n\n"
        "[Service]\n"
        "Type=simple\n"
        f"WorkingDirectory={FLUX_DIR}\n"
        f"ExecStart={FLUX_BIN} --role=exit --mode={mode} --negotiate"
        f" --transports={tl}{urls} --direct-listen=0.0.0.0:{port}"
        f" --encryption-key-file={FLUX_SECRET} --session-context={ctx}"
        f" --cookie-store={FLUX_DIR}/cookies.json\n"
        "Restart=always\n"
        "RestartSec=3\n"
        "LimitNOFILE=65536\n"
        "NoNewPrivileges=yes\n"
        "PrivateTmp=yes\n"
        "ProtectHome=yes\n"
        "ProtectSystem=strict\n"
        f"ReadWritePaths={FLUX_DIR}\n"
        + extra +
        "\n[Install]\nWantedBy=multi-user.target\n"
    )


def _flux_secret_ensure():
    """Ключ живёт отдельным файлом 0600 и НИКОГДА не уезжает в состояние, в
    журнал или в ответ морды: в состоянии лежит только путь к нему."""
    if os.path.exists(FLUX_SECRET) and os.path.getsize(FLUX_SECRET) >= 32:
        return "есть"
    _mkdir_private(FLUX_DIR)
    fd = os.open(FLUX_SECRET, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write(secrets.token_hex(32) + "\n")
    return "создан"


def _flux_install():
    """Скачать, сверить гашение, положить. Порядок важен: проверка стоит ДО
    боевого пути, а не после — иначе на диске остаётся подменённое ядро, с
    которого юнит и стартует."""
    with FLUX_LOCK:
        free = _free_bytes("/usr/local/bin")
        if free >= 0 and free < FLUX_MIN_FREE:
            raise RuntimeError(f"свободно {free // 1048576} МиБ, нужно не меньше "
                               f"{FLUX_MIN_FREE // 1048576} МиБ — не ставим")
        tmp = tempfile.mkstemp(prefix=".flux-", dir="/tmp")[1]
        sums = tmp + ".sums"
        try:
            _dl(FLUX_SUMS_DL, sums)
            with open(sums, encoding="utf-8", errors="replace") as f:
                exp_sums = _flux_sums_expect(f.read(), FLUX_ASSET)
            if not exp_sums:
                raise RuntimeError("в сводке выдачи нет строки для "
                                   f"{FLUX_ASSET} — не ставим вслепую")
            if exp_sums != FLUX_SHA:
                raise RuntimeError(f"сводка выдачи ({exp_sums[:12]}…) не совпала с "
                                   f"закреплённым числом панели ({FLUX_SHA[:12]}…) — "
                                   "выпуск переснят, число нужно закрепить заново")
            _dl(FLUX_DL, tmp)
            got = _sha256_file(tmp)
            if got != FLUX_SHA:
                raise RuntimeError(f"sha256 скачанного не совпал ({got[:12]}… вместо "
                                   f"{FLUX_SHA[:12]}…) — файл отклонён")
            _write_atomic(tmp, FLUX_BIN, 0o755)
        finally:
            for p in (tmp, sums):
                try:
                    os.unlink(p)
                except OSError:
                    pass
        _flux_license()
        st = _flux_state()
        st["installed_ver"] = FLUX_VER
        st["installed_sha"] = FLUX_SHA[:12]
        _flux_save(st)
        _audit("flux_install", ver=FLUX_VER, sha=FLUX_SHA[:12])
        return {"ok": True, "ver": FLUX_VER, "sha": FLUX_SHA[:12],
                "bytes": os.path.getsize(FLUX_BIN)}


def _flux_license():
    """Источник назван письмом рядом с ядром: выпуск, адрес, гашение, лицензия."""
    _mkdir_private(FLUX_DIR)
    try:
        for name, mode in (("LICENSE", 0o644), ("NOTICE", 0o644)):
            dst = os.path.join(FLUX_DIR, name)
            if os.path.exists(dst):
                continue
            tmp = tempfile.mkstemp(prefix=".fluxlic-", dir="/tmp")[1]
            try:
                _dl(f"{FLUX_REPO}/raw/main/{name}", tmp)
                _write_atomic(tmp, dst, mode)
            except Exception:
                pass
            finally:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass
    except Exception as e:
        print("[flux] лицензия: " + type(e).__name__, flush=True)
    cred = os.path.join(FLUX_DIR, "CREDITS")
    try:
        with open(cred, "w", encoding="utf-8") as f:
            f.write(f"openflux {FLUX_VER} — {FLUX_DL}\n"
                    f"sha256 {FLUX_SHA}\n"
                    f"лицензия: GPL-3.0 (ядро не изменено, панель только запускает)\n"
                    f"проект: {FLUX_REPO}\n")
        os.chmod(cred, 0o644)
    except Exception:
        pass


def _flux_snapshot_unit():
    """Снимок юнита ДО записи — ради отката. Нет снимка, и предыдущий файл был
    написан руками: возврат был бы «удалили то, чего панель не ставила»."""
    if not os.path.exists(FLUX_UNIT_PATH):
        return None
    dst = os.path.join(FLUX_DIR, "unit-prev.service")
    try:
        _mkdir_private(FLUX_DIR)
        shutil.copy2(FLUX_UNIT_PATH, dst)
        os.chmod(dst, 0o600)
        return dst
    except Exception as e:
        print("[flux] снимок юнита: " + type(e).__name__, flush=True)
        return None


def _flux_rollback(snap, was_enabled):
    """Вернуть ровно то, что было до применения: байты юнита и состояние
    автозапуска. Молча оставить полуживой юнит хуже, чем не применить."""
    try:
        subprocess.run(["systemctl", "stop", FLUX_UNIT], capture_output=True, timeout=30)
    except Exception:
        pass
    try:
        if snap and os.path.exists(snap):
            _mkdir_private(FLUX_DIR)
            shutil.copy2(snap, FLUX_UNIT_PATH)
            os.chmod(FLUX_UNIT_PATH, 0o644)
        else:
            if was_enabled:
                subprocess.run(["systemctl", "disable", FLUX_UNIT], capture_output=True, timeout=30)
            os.unlink(FLUX_UNIT_PATH)
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True, timeout=60)
    except Exception as e:
        print("[flux] откат: " + type(e).__name__, flush=True)
        return False
    return True


def _flux_journal_tail():
    """Последние строки службы — для ответа владельцу, когда старт не поднялся.
    Строка с ключом вырезается до того, как текст покидает функцию: ядро на
    `--debug=0` ключ не печатает, но проверка стоит ровно одну строку и
    закрывает класс «что-то изменилось в ядре». Ссылку носителя ядро печатает
    открыто — `carrier "vyandex" ... unexpected status 404 at https://…` — а это
    приватный адрес документа, который осел бы в журнале панели навсегда: его
    снимаем той же строкой, что и ключ."""
    secret = ""
    try:
        with open(FLUX_SECRET, encoding="utf-8") as f:
            secret = f.read().strip()
    except Exception:
        pass
    try:
        r = subprocess.run(["journalctl", "-u", FLUX_UNIT, "-n", "12", "--no-pager", "-o", "cat"],
                           capture_output=True, text=True, timeout=10)
        lines = (r.stdout or "").splitlines()
    except Exception:
        return ""
    keep = [ln for ln in lines
            if not (secret and secret in ln) and "openflux://" not in ln]
    keep = [re.sub(r"https?://\S+", "ссылку носителя", ln) for ln in keep]
    return (" · ".join(keep[-3:]) or "")[:240]


def _flux_apply(body):
    st = _flux_state()
    port = _flux_port_ok(body.get("port", st.get("port")))
    if port is None:
        raise RuntimeError("порт должен быть целым числом от 1024 до 65535")
    mode = (body.get("mode") or st.get("mode") or "l4")
    if mode not in FLUX_MODES:
        raise RuntimeError("режим выхода — `l4` или `l3`")
    ctx = (body.get("ctx") or st.get("ctx") or "veil.flux")
    if not _flux_ctx_ok(ctx):
        raise RuntimeError("контекст сессии — до 64 знаков: буквы, цифры, точка, "
                           "двоеточие, дефис, подчёркивание")
    # Носители принимаем только теми словами, которыми их судит ядро: кривую
    # форму нельзя отложить на потом — выход поднимется и будет молча ретраить
    # носитель, которого клиент никогда не дождётся.
    if "carriers" in body:
        _cars, bad = _flux_carriers_ok(body.get("carriers"))
        if bad:
            raise RuntimeError(" · ".join(bad)[:240])
        st["carriers"] = _flux_carriers_state(body.get("carriers"))
    else:
        st["carriers"] = _flux_carriers_state(st.get("carriers"))
    car_types = [c["type"] for c in _flux_carriers_ok(st["carriers"])[0]]
    st.update(port=port, mode=mode, ctx=ctx)
    info = _flux_bin_info()
    if not info["present"] or not info["digest_ok"]:
        raise RuntimeError("ядро не установлено или его гашение не совпало с "
                           f"закреплённым ({FLUX_SHA[:12]}…) — сначала «Поставить ядро»")
    busy = _flux_port_blocker(port)
    if busy:
        raise RuntimeError(f"порт :{port} уже слушается ({busy}) — выбери свободный")
    _flux_secret_ensure()
    _mkdir_private(FLUX_DIR)
    snap = _flux_snapshot_unit()
    was_enabled = False
    try:
        was_enabled = subprocess.run(["systemctl", "is-enabled", FLUX_UNIT],
                                     capture_output=True, timeout=20).returncode == 0
    except Exception:
        pass
    _save_ok = True
    try:
        tmp = os.path.join(FLUX_DIR, "unit.new.service")
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(_flux_unit_body(st))
        _write_atomic(tmp, FLUX_UNIT_PATH, 0o644)
    except Exception as e:
        _save_ok = False
        raise RuntimeError("не записали юнит: " + str(e)[:160])
    finally:
        try:
            os.unlink(os.path.join(FLUX_DIR, "unit.new.service"))
        except OSError:
            pass
    if not _save_ok:
        return {"ok": False}
    try:
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True, timeout=60, check=True)
        subprocess.run(["systemctl", "enable", FLUX_UNIT], capture_output=True, timeout=60)
        subprocess.run(["systemctl", "restart", FLUX_UNIT], capture_output=True,
                       timeout=90, check=True)
        if not _svc_unit_up(FLUX_UNIT):
            raise RuntimeError("служба не поднялась"
                               + ((" — " + _flux_journal_tail()) if _flux_journal_tail() else ""))
    except Exception as e:
        rolled = _flux_rollback(snap, was_enabled)
        _flux_save(st)
        _audit("flux_apply", ok=False, port=port, mode=mode, rolled=rolled,
               carriers=car_types,
               err=str(e)[:160])
        raise
    _flux_save(st)
    _audit("flux_apply", ok=True, port=port, mode=mode, carriers=car_types)
    return {"ok": True, "port": port, "mode": mode, "ctx": ctx,
            "carriers": car_types,
            "active": _unit_active(FLUX_UNIT)}


def _flux_start():
    if not _flux_enabled():
        raise RuntimeError("узел выключен рубильником — сначала включи его")
    if not _flux_bin_info()["digest_ok"]:
        raise RuntimeError("ядро не установлено или его гашение не совпало")
    subprocess.run(["systemctl", "start", FLUX_UNIT], capture_output=True, timeout=90,
                   check=True)
    if not _svc_unit_up(FLUX_UNIT):
        raise RuntimeError("служба не поднялась"
                           + ((" — " + _flux_journal_tail()) if _flux_journal_tail() else ""))
    _audit("flux_start", port=_flux_state().get("port"))
    return {"ok": True, "active": True}


def _flux_stop():
    subprocess.run(["systemctl", "stop", FLUX_UNIT], capture_output=True, timeout=60)
    _audit("flux_stop", port=_flux_state().get("port"),
           still=_unit_active(FLUX_UNIT))
    return {"ok": True, "active": _unit_active(FLUX_UNIT)}


def _flux_remove(wipe=False):
    """Снять юнит, оставить состояние и ключ: без них ссылка клиента перестаёт
    читаться, а «удалить службу» не значит «забыть узел». Ключ стирают только
    `wipe`."""
    try:
        subprocess.run(["systemctl", "disable", FLUX_UNIT], capture_output=True, timeout=30)
    except Exception:
        pass
    subprocess.run(["systemctl", "stop", FLUX_UNIT], capture_output=True, timeout=60)
    gone = True
    try:
        os.unlink(FLUX_UNIT_PATH)
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True, timeout=60)
    except Exception:
        gone = False
    if wipe:
        for name in ("secret.key", "unit-prev.service"):
            try:
                os.unlink(os.path.join(FLUX_DIR, name))
            except OSError:
                pass
    _audit("flux_remove", unit=gone, wipe=bool(wipe))
    return {"ok": bool(gone), "wipe": bool(wipe), "active": _unit_active(FLUX_UNIT)}


def _flux_host():
    """Место входа в ссылке: адрес СОБСТВЕННО этой коробки. Фронт двойного
    прыжка (`hop_public_host`) для `flux` не годится: он терминирует TLS на :443 и
    не несёт произвольный порт, а `direct` звонится ровно на тот порт, который
    слушает выход."""
    dom = (CFG_CACHE.get("panel_domain") or "").strip()
    if dom and "/" not in dom and ":" not in dom:
        return dom
    return (_my_ip() or "").strip()


def _flux_transports(st, host, port):
    """Список транспортов ссылки: носители по убыванию приоритета и `direct`
    запасным. Тот же порядок, что и в юните, — ссылка обязана обещать клиенту
    ровно то, на чём узел стоит, иначе клиент выберет канал, которого узел не
    поднимал."""
    cars, _bad = _flux_carriers_ok(st.get("carriers"))
    # Своего носителя в ссылке нет: сборщик ссылки ядра знает только встроенные
    # имена и на `script` отвечает `unknown transport type`. Носитель обязан
    # приехать клиенту отдельным импортом, поэтому обещать его в ссылке панель не
    # может — клиент бы выбрал канал, которого у него нет.
    tl = [{"type": c["type"], "url": c["url"], "priority": c["pri"]}
          for c in cars if not c.get("own")]
    tl.append({"type": "direct", "dial": f"{host}:{int(port)}",
               "priority": FLUX_DIRECT_PRI})
    return cars, tl


def _flux_link():
    """Ссылку собирает само ядро (`--make-link`), а не панель: формат
    `openflux://` живёт в одном месте и на клиенте, и на выходе. Ссылка содержит
    ключ — поэтому она не пишется ни в журнал, ни в ответ без явного запроса.
    Носители едут в ней тем же списком, что и в юните, с теми же приоритетами, а
    `direct` стоит запасным: клиент сам выбирает, чем ехать, и если белый список
    оператора закрыл носитель, он уедет по прямому каналу."""
    st = _flux_state()
    if not os.path.exists(FLUX_SECRET):
        raise RuntimeError("ключа нет — сначала «Применить и запустить»")
    host = _flux_host()
    if not host:
        raise RuntimeError("не знаем публичного адреса — ссылка будет без места входа")
    port = _flux_port_ok(st.get("port")) or FLUX_DEFAULT_PORT
    cars, tl = _flux_transports(st, host, port)
    payload = {"name": "veil-flux", "negotiate": True, "codec": "batched",
               "context": st.get("ctx") or "veil.flux",
               "transports": tl}
    try:
        with open(FLUX_SECRET, encoding="utf-8") as f:
            payload["secret"] = f.read().strip()
    except Exception as e:
        raise RuntimeError("ключ не читается: " + type(e).__name__)
    try:
        r = subprocess.run([FLUX_BIN, "--make-link", "-"], input=json.dumps(payload),
                           capture_output=True, text=True, timeout=30)
        out = json.loads(r.stdout or "{}")
    except Exception as e:
        raise RuntimeError("ядро не собрало ссылку: " + (str(e)[:120]))
    link = out.get("link") or ""
    if not link.startswith("openflux://"):
        code = (out.get("error") or {}).get("code") if isinstance(out.get("error"), dict) else ""
        raise RuntimeError("ядро отказало ссылкой" + (f" (`{code}`)" if code else ""))
    _audit("flux_link", port=port, carriers=[c["type"] for c in cars])
    note = "в ссылке лежит ключ: покажи её только своему клиенту"
    own = [c["name"] for c in cars if c.get("own")]
    if own:
        note += (f" · своих носителей ({', '.join(own)}) в ссылке нет — ядро "
                 "пускает в ссылку только встроенные имена, клиент обязан "
                 "импортировать их сам")
    return {"link": link, "carriers": [c["type"] for c in cars],
            "dial": f"{host}:{port}",
            "note": note}


def _flux_mint_room():
    """Cups.online выдаёт комнату анонимно: сама страница несёт `data-room` со
    свежим uuid, без входа и без телефона — в этом и смысл носителя для хозяина,
    у которого аккаунтов документальных носителей нет. Берём только uuid и
    возвращаем адрес ровно в той форме, какую читает ядро. Комната — место
    встречи, а не ключ: ключ по-прежнему лежит в ссылке `openflux://`, поэтому
    адрес комнаты не пишется ни в журнал, ни в аудит."""
    req = urllib.request.Request("https://cups.online/live-coding/",
                                 headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            page = r.read(4194304).decode("utf-8", "replace")
    except Exception as e:
        raise RuntimeError("комната не выдана: " + type(e).__name__)
    m = re.search(r'data-room="([^"]*)"', page)
    if not m:
        raise RuntimeError("комната не выдана — страница без `data-room`")
    try:
        room = json.loads(_html.unescape(m.group(1)))
    except Exception:
        raise RuntimeError("комната не читается")
    uid = str(room.get("uuid") or "") if isinstance(room, dict) else ""
    if not re.fullmatch(r"[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}", uid):
        raise RuntimeError("комната без uuid")
    _audit("flux_room", ok=True)
    return {"url": "https://interview.cups.online/live-coding/?room=" + uid}


def _flux_view():
    st = _flux_state()
    info = _flux_bin_info()
    free = _free_bytes("/usr/local/bin")
    blockers = []
    if not info["present"]:
        blockers.append("ядро не поставлено")
    elif not info["digest_ok"]:
        blockers.append(f"гашение ядра не совпало с закреплённым ({info['digest'][:12]}… "
                        f"вместо {FLUX_SHA[:12]}…)")
    busy = _flux_port_blocker(st.get("port"))
    if busy:
        blockers.append(f"порт :{st.get('port')} занят ({busy})")
    if free >= 0 and free < FLUX_MIN_FREE:
        blockers.append(f"свободно {free // 1048576} МиБ, нужно {FLUX_MIN_FREE // 1048576} МиБ")
    active = _unit_active(FLUX_UNIT)
    host = _flux_host()
    cars, _bad = _flux_carriers_ok(st.get("carriers"))
    owner = _flux_port_busy(st.get("port"))
    # Свои носители показываем отдельной мерой: выбранный и пропавший из-за
    # расшедшейся подписи носитель юнит не везёт, и молчание об этом выглядело бы
    # как «узел едет хорошо».
    scripts = []
    for c in FLUX_CARRIERS:
        if not c.get("own"):
            continue
        ok, why, size = _flux_script_ok(c)
        chosen = any(str(x.get("type") or "") == c["type"]
                     for x in (st.get("carriers") or []) if isinstance(x, dict))
        scripts.append({"type": c["type"], "name": c["name"], "pri": c["pri"],
                        "ok": ok, "why": why, "bytes": size, "chosen": chosen,
                        "file": c["script"] + ".js"})
        if chosen and not ok:
            blockers.append(f"{c['name']} выбран, но файла живого нет: {why} — "
                            "юнит соберётся без него")
    return {"enabled": _flux_enabled(), "ver": FLUX_VER, "sha": FLUX_SHA[:12],
            "bin": info, "free": free, "port": st.get("port"), "mode": st.get("mode"),
            "ctx": st.get("ctx"), "active": active,
            "listen": bool(owner), "listen_by": owner,
            "unit_enabled": _flux_unit_enabled(),
            "journal": _flux_journal_tail(), "stamp": _ldate("%H:%M:%S"),
            "host": host, "dial": (f"{host}:{st.get('port')}" if host else ""),
            "since": (_service_active_since(FLUX_UNIT) if active else ""),
            "secret": os.path.exists(FLUX_SECRET), "unit_file": os.path.exists(FLUX_UNIT_PATH),
            "carriers": cars,
            "carrier_kinds": [{k: c[k] for k in ("type", "pri", "name", "hint")}
                              for c in FLUX_CARRIERS],
            "own_scripts": scripts,
            "direct_pri": FLUX_DIRECT_PRI,
            "blockers": blockers,
            "peer_note": ("узел не пишет в журнал ни подъём клиента, ни его уход: "
                          "проверять надо на устройстве клиента"),
            "one_client": "выход обслуживает одного активного клиента за раз"}


class _AiBadUpstream(RuntimeError):
    """Ответ провайдера технически 200, но содержимого для ответа нет.
    Отдельный класс затем, чтобы воронка `/api/ai/chat` отвечала причину,
    а не превращала 200-ю заглушку в пустой ответ."""


def _ai_llm(base, key, model, messages, tools):
    url = (base or "https://api.openai.com/v1").rstrip("/") + "/chat/completions"
    body = {"model": model or "gpt-4o-mini", "messages": messages,
            "temperature": 0.2, "tools": tools}
    data = json.dumps(body).encode()
    req = urllib.request.Request(url, data=data, method="POST", headers={
        "Content-Type": "application/json", "Authorization": "Bearer " + key})
    ctx = ssl.create_default_context()
    with urllib.request.urlopen(req, timeout=45, context=ctx) as r:
        raw = r.read().decode("utf-8", "replace")
    try:
        j = json.loads(raw)
    except Exception:
        # 200 с не-JSON внутри — ровно тот случай, который раньше превращался в «(пусто)»
        raise _AiBadUpstream("провайдер ответил не JSON: " + raw[:180])
    if not isinstance(j, dict):
        raise _AiBadUpstream("провайдер ответил не объект: " + raw[:180])
    if j.get("error"):
        raise _AiBadUpstream("провайдер вернул error: " + json.dumps(j["error"], ensure_ascii=False)[:300])
    return j


def _ai_answer(user_msgs, user_login):
    """Прогон диалога через LLM с петлёй инструментов (только чтение). Возвращает текст ответа."""
    base = CFG_CACHE.get("ai_base") or "https://api.openai.com/v1"
    key = (CFG_CACHE.get("ai_key") or "").strip()
    model = CFG_CACHE.get("ai_model") or "gpt-4o-mini"
    msgs = [{"role": "system", "content": _AI_SYS}] + [
        {"role": m.get("role"), "content": m.get("content")}
        for m in user_msgs if m.get("role") in ("user", "assistant")][-12:]
    used = []
    for _ in range(4):
        j = _ai_llm(base, key, model, msgs, _AI_TOOLS)
        choices = j.get("choices") or []
        ch0 = (choices[0] if choices else {}) or {}
        ch = ch0.get("message") or {}
        finish = ch0.get("finish_reason")
        tcs = ch.get("tool_calls") or []
        if not tcs:
            content = (ch.get("content") or "").strip()
            if not content:
                # Пустой content при HTTP 200 — это не «ответ ассистента», а отказ
                # провайдера. Раньше он уходил в морду как законченный ответ:
                # оператор видел «(пусто)» без причины, а журнал — успешную запись.
                try:
                    _audit("ai_chat", user=user_login, ok=False, finish=finish,
                           tools=used or None,
                           q=(user_msgs[-1].get("content") or "")[:200] if user_msgs else None)
                except Exception:
                    pass
                raise _AiBadUpstream("провайдер вернул пустой ответ"
                                     + (" (finish_reason=" + str(finish) + ")" if finish else ""))
            try:
                _audit("ai_chat", user=user_login, ok=True, finish=finish,
                       tools=used or None,
                       q=(user_msgs[-1].get("content") or "")[:200] if user_msgs else None)
            except Exception:
                pass
            return {"answer": content, "tools": used}
        msgs.append({"role": "assistant", "content": ch.get("content"), "tool_calls": tcs})
        for tc in tcs:
            fn = (tc.get("function") or {})
            name = fn.get("name")
            try:
                args = json.loads(fn.get("arguments") or "{}")
            except Exception:
                args = {}
            if name in _AI_DISPATCH:
                used.append(name)
                res = _ai_run_tool(name, args)
            else:
                res = {"error": "инструмент недоступен"}
            msgs.append({"role": "tool", "tool_call_id": tc.get("id"),
                         "content": json.dumps(res, ensure_ascii=False)[:8000]})
    try:
        _audit("ai_chat", user=user_login, ok=False, tools=used, too_long=True)
    except Exception:
        pass
    return {"answer": "Слишком длинная цепочка запросов — переформулируй короче.", "tools": used}


class _BodyError(ValueError):
    """Тело запроса непригодно. Отдельный класс нужен затем, чтобы do_POST
    отвечал честные 400/413, а не «внутренняя ошибка панели»: мусорный JSON,
    не-UTF-8 и тело на гигабайт присылает сканер или чужой клиент, а не морда.
    500 на такое — это и сломанная диагностика, и бесплатный сигнал для
    фингерпринта (по списку 500-х ручек сканер рисует карту панели).
    Наследник ValueError: полтора десятка местных `except ValueError: 400`
    продолжат работать как работали."""
    def __init__(self, msg, code=400):
        ValueError.__init__(self, msg)
        self.code = code


def _field(b, key):
    """Поле тела как строка: строка возвращается сама, отсутствие и `null` —
    пустой строкой, любой другой тип — отказом `400`. Раньше здесь стояло
    `(b.get(key) or "").strip()`, и на числе, списке или словаре оно падало в
    AttributeError; воронка `do_POST` превращала это в `500` «внутренняя ошибка
    панели» и в запись `post_error`. То есть панель обвиняла себя в том, что
    прислал вызывающий, а оператор в журнале видел шум вместо причины.
    Значение поля в отказ не попадает — поля могут быть путями и адресами."""
    v = b.get(key)
    if v is None:
        return ""
    if isinstance(v, str):
        return v
    raise _BodyError("поле «%s» — строка, а не %s" % (key, type(v).__name__))


def _nfield(b, key, default=0, lo=None, hi=None):
    """Поле тела как целое число. `null`, отсутствие и пустая строка — `default`;
    число и числовая строка — как умели раньше; список, словарь, «abc» — отказ
    `400` с именем поля. Голый `int(b.get(key) or 0)` на списке падал в TypeError,
    и воронка do_POST отвечала за это 500 и писала post_error.
    Границы `lo`/`hi` не только про вежливость: поле уходит в файл истории, а
    диск сервера и так заполнен на 83%. Значение в текст отказа не печатается."""
    v = b.get(key)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    try:
        n = int(v) if isinstance(v, (int, float)) else int(str(v).strip())
    except (TypeError, ValueError, OverflowError):
        raise _BodyError("поле «%s» — число, а не %s" % (key, type(v).__name__))
    if lo is not None and n < lo:
        raise _BodyError("поле «%s»: не меньше %s" % (key, lo))
    if hi is not None and n > hi:
        raise _BodyError("поле «%s»: не больше %s" % (key, hi))
    return n


def _slist(b, key, seps=r"[,\s]+", limit=256):
    """Поле тела как список строк: морда шлёт массив, а человек в поле «пул»
    вставляет строку через пробел — раньше оба формата разбирать приходилось
    на месте, и `(x or "").strip()` на элементе-числе падало в AttributeError
    (500) вместо «элемент списка — строка». Не-список и не-строка тоже отказ,
    а не молчаливый пустой пул: опустошить пул молча опаснее, чем попросить
    переписать поле. Пустота возвращается пустым списком, это законный «выключить».
    `limit` — чтобы один запрос не раздувал конфиг до размеров тела."""
    v = b.get(key)
    if v is None or v == "":
        return []
    if isinstance(v, str):
        items = [x for x in re.split(seps, v) if x]
    elif isinstance(v, (list, tuple)):
        for x in v:
            if not isinstance(x, str):
                raise _BodyError("элемент «%s» — строка, а не %s" % (key, type(x).__name__))
        items = list(v)
    else:
        raise _BodyError("поле «%s» — список или строка, а не %s" % (key, type(v).__name__))
    if len(items) > limit:
        raise _BodyError("поле «%s»: не больше %s значений" % (key, limit))
    return items


def _jfield(b, key, limit=20000, kinds=(list, dict)):
    """Поле тела как JSON-структура с известным верхом по размеру. Нужно там,
    где значение едет в файл: без веры в тип и в объём один запрос превращал
    историю в несколько сотен мегабайт. `kinds` — какие структуры тут законны:
    морда шлёт список объектов, и словарь она же сломает при отрисовке.
    Тип в текст отказа печатается, значение — нет."""
    v = b.get(key)
    if v is None:
        return None
    if not isinstance(v, kinds):
        raise _BodyError("поле «%s» — %s, а не %s"
                         % (key, " или ".join(k.__name__ for k in kinds), type(v).__name__))
    try:
        size = len(json.dumps(v, ensure_ascii=False))
    except (TypeError, ValueError):
        raise _BodyError("поле «%s» — не JSON" % key)
    if size > limit:
        raise _BodyError("поле «%s» слишком большое" % key)
    return v


# Гость, который повесил трубку посреди письма, — не сбой панели. Пока этого
# различия не было, живой прогон шторма (V7) оставлял в аудите 16 записей
# post_error, и ВСЕ шестнадцать — ConnectionReset/BrokenPipe от оборванных
# соединений: настоящая внутренняя ошибка тонула в шуме ровно так же, как её
# искал оператор. Наружу в таком запросе писать уже некуда, поэтому класс
# отсекается до общего обработчика: без трейсбека в stderr и без post_error.
# Отдельная запись `client_gone` остаётся, но не чаще раза в минуту — смысл её
# «такое бывает», а не «сколько раз»: шторм из обрывов не должен раздувать аудит.
_CLIENT_GONE = (BrokenPipeError, ConnectionResetError, TimeoutError, ssl.SSLError)
_client_gone_at = [0.0]
_client_gone_lk = threading.Lock()


def _client_gone(path, e):
    now = time.time()
    with _client_gone_lk:
        if now - _client_gone_at[0] < 60:
            return
        _client_gone_at[0] = now
    try:
        _audit("client_gone", path=_audit_path(path), detail=type(e).__name__)
    except Exception:
        pass


# `_send` сжимает не всё подряд: ниже этого размера gzip ничего не экономит
# (типичный `{"ok": true}` — 12 байт), а заголовок стоит.
_GZIP_MIN = 1024
# Только текстовые ответы: `image/*` и уже сжатые байты вторым gzip испортятся.
_GZIP_CT = ("application/json", "text/")


class H(http.server.BaseHTTPRequestHandler):
    # HTTP/1.1 = keep-alive: без него каждый <script>/<img>/fetch открывает
    # грузилась секундами. timeout освобождает зависшие потоки через 30 с.
    protocol_version = "HTTP/1.1"
    timeout = 30

    def log_message(self, *a): pass

    def handle_error(self, request, client_address):
        import sys as _sys
        et = _sys.exc_info()[0]
        if et and issubclass(et, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError,
                                  socket.timeout, TimeoutError)):
            return
        super().handle_error(request, client_address)

    def _is_tls(self):
        try:
            return isinstance(self.request, ssl.SSLSocket)
        except Exception:
            return False

    def _sec_headers(self):
        # Панель, витрина и страницы подписок не для индексов. До этой строки
        # невидимость была случайной (у /shop нет ни robots.txt, ни sitemap, ни
        # ссылки-источника — замер с чужих машин, группа P), а должна быть
        # решением: кто дал ссылку, тот не обязан заодно давать её краулеру.
        self.send_header("X-Robots-Tag", "noindex, nofollow, noarchive")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "same-origin")
        if self._is_tls():
            self.send_header("Strict-Transport-Security", "max-age=31536000")

    def _send(self, code, obj, ctype="application/json"):
        if code == 200 and isinstance(obj, dict) and "ok" not in obj:
            obj = dict(obj)
            obj["ok"] = True
        b = obj if isinstance(obj, bytes) else json.dumps(obj, ensure_ascii=False).replace(r'\/', '/').encode()
        # Мобильный канал: `/api/clients` весит 148 КБ, `/api/subs` — 82 КБ, а морда
        # берёт их каждые десять секунд. HTML панель сжимала и раньше (`/` и `/p/`),
        # а JSON до этой строки шёл голым: gzip-6 снимает 93% и стоит миллисекунду.
        # Кто про gzip не объявился, получает ровно то, что получал.
        enc = None
        if len(b) >= _GZIP_MIN and ctype.startswith(_GZIP_CT) and \
                "gzip" in (self.headers.get("Accept-Encoding") or "").lower():
            b, enc = gzip.compress(b, 6), "gzip"
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        # Длина считается ПОСЛЕ сжатия: посчитанная до неё браузер дочитал бы не те
        # байты, и соединение встало бы.
        self.send_header("Content-Length", str(len(b)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("Vary", "Accept-Encoding")
        if enc: self.send_header("Content-Encoding", enc)
        self._sec_headers()
        for c in getattr(self, "_cookies", []):
            self.send_header("Set-Cookie", c)
        self.end_headers(); self.wfile.write(b)

    def _refuse_unshapable(self, raw, public=False):
        """True — названный 500 уже отправлен, обработчику надо вернуться сразу (№64).

        Одна функция, а не шесть одинаковых веток, потому что первый вечер
        долечил только тех читателей, до которых нашарилась ручка: `/api/state`,
        `/api/subs` и `/api/subs/export` врали пустотой, а `/api/dashboard`,
        `/api/clients` и `/api/vpn/protocols` на контейнере-списке падали в общий
        500 с трейсбеком в журнале (замерено cc10 на живом state.json). Отказывать
        они отказывали честно — но без причины, и оператор видел «внутренняя
        ошибка панели» вместо «файл испорчен, ничего не трогаем».

        `public` — ответ тому, кто не вошёл: `/sub/<токен>` читает гость без
        пароля. Отказывать ему надо тем же словом «нет», а не названием
        внутреннего файла: путь и имя state.json наружу не отдаются (тот же
        резон, из-за которого текст исключения в общем 500 не показывается).

        Поток записей той же мерой, что и у миграции: одна строка в час с числом
        подавленных, иначе чужая правка state.json стирает единственный журнал.
        """
        if not _state_unshapable(raw):
            return False
        _audit_throttled("state_read_refused", gap=3600,
                         path=_audit_path(urllib.parse.urlparse(self.path).path),
                         type=type(raw if not isinstance(raw, dict)
                                      else raw.get("inbounds")).__name__)
        self._send(500, {"error": _UNSHAPABLE_ERR_PUB if public else _UNSHAPABLE_ERR})
        return True

    def _api_pay(self, p):
        b = self._body()
        pc = _pay_cfg()
        if p == "/api/pay/settings":
            prov = (b.get("provider") or pc["provider"])
            if prov not in _PAY_PROVIDERS:
                return self._send(400, {"error": "неизвестный провайдер"})
            CFG_CACHE["pay_enabled"] = bool(b.get("enabled"))
            CFG_CACHE["pay_provider"] = prov
            CFG_CACHE["pay_notify"] = bool(b.get("notify", True))
            for key, field in (("pay_secret", "secret"), ("pay_cb_token", "cb_token"),
                               ("pay_yoo_shop", "yoo_shop"), ("pay_yoo_secret", "yoo_secret")):
                v = b.get(field)
                v = v.strip() if isinstance(v, str) else ""
                if v:
                    CFG_CACHE[key] = v[:256]
            _cfg_save()
            _audit("pay_settings", provider=prov, enabled=bool(b.get("enabled")))
            return self._send(200, _pay_summary())
        if p == "/api/pay/plans":
            act = _field(b, 'action').strip()
            try:
                with PAY_LOCK:
                    d = _pay_load()
                    if act in ("add", "edit"):
                        clean = _pay_plan_valid(b.get("plan") or {})
                        pid = str((b.get("plan") or {}).get("id") or "")
                        if act == "add":
                            d["seq"] += 1
                            clean["id"] = "P%d" % d["seq"]
                            d["plans"].append(clean)
                        else:
                            hit = False
                            for i, x in enumerate(d["plans"]):
                                if str(x.get("id")) == pid:
                                    clean["id"] = pid
                                    d["plans"][i] = clean
                                    hit = True
                                    break
                            if not hit:
                                raise LookupError("тариф не найден")
                    elif act == "del":
                        pid = str(b.get("id") or "")
                        d["plans"] = [x for x in d["plans"] if str(x.get("id")) != pid]
                    else:
                        raise ValueError("нужен action: add|edit|del")
                    _pay_save(d)
            except LookupError as e:
                return self._send(404, {"error": str(e)})
            except ValueError as e:
                return self._send(400, {"error": str(e)})
            _audit("pay_plans", action=act)
            return self._send(200, _pay_summary())
        if p == "/api/pay/invoice":
            plan = next((x for x in _pay_load()["plans"]
                         if str(x.get("id")) == str(b.get("plan_id") or "")), None)
            if not plan:
                return self._send(404, {"error": "тариф не найден"})
            try:
                inv = _pay_mkv(str(b.get("sub_token") or ""), plan, src="panel")
            except Exception as e:
                return self._send(400, {"error": str(e)})
            _audit("pay_invoice", inv=inv["id"])
            return self._send(200, {"ok": True, "invoice": inv, "summary": _pay_summary()})
        if p == "/api/pay/confirm":
            iid = str(b.get("invoice_id") or "")
            if not _PAY_IID_RE.fullmatch(iid):
                return self._send(400, {"error": "неверный id счёта"})
            inv = _pay_mark_paid(iid, "panel")
            if not inv:
                return self._send(404, {"error": "счёт не найден"})
            _audit("pay_confirm", inv=iid)
            return self._send(200, {"ok": True, "applied": bool(inv.get("applied")),
                                    "summary": _pay_summary()})
        if p == "/api/pay/check":
            iid = str(b.get("invoice_id") or "")
            if _PAY_IID_RE.fullmatch(iid):
                _pay_check_ext(iid)
            else:
                for v in list(_pay_load()["invoices"].values()):
                    if not v.get("applied") and v.get("provider") in ("cryptobot", "yookassa"):
                        _pay_check_ext(v["id"])
            return self._send(200, _pay_summary())
        return self._send(404, {"error": "not found"})

    def _read_exact(self, n):
        """Прочитать n байт и ЗАПИСАТЬ их в счётчик съеденного тела. Ручки,
        которые дёргают rfile сами (обои, логотип, крупные настройки,
        восстановление из файла), без этого сбивали бы `_drain_body`: он видел
        бы «тело не прочитано» и честно закрывал бы живое соединение."""
        data = b""
        rem = max(0, int(n or 0))
        while rem > 0:
            ch = self.rfile.read(min(rem, 65536))
            if not ch:
                break
            data += ch
            rem -= len(ch)
        self._body_read = int(getattr(self, "_body_read", 0) or 0) + len(data)
        return data

    def _raw_body(self, maxb=8 * 1024 * 1024):
        """Отдать тело запроса байтом. Заголовок Content-Length присылает клиент,
        а браузеры его не шлют вообще ни при каких обстоятельствах: «abc», «-5» и
        «99999999999999» превращали int() в ValueError, и на GET-ветке (do_GET без
        общего try) это рвало соединение без ответа и с трейсбеком в журнале."""
        raw_hdr = self.headers.get("Content-Length")
        try:
            n = int((raw_hdr or "0").strip() or "0")
        except ValueError:
            n = 0
        if n < 0 or n > maxb:
            raise _BodyError("тело запроса слишком большое", 413)
        got = self.rfile.read(n) if n else b""
        self._body_read = int(getattr(self, "_body_read", 0) or 0) + len(got)
        return got

    def _declared_len(self):
        try:
            return max(0, int((self.headers.get("Content-Length") or "0").strip() or "0"))
        except (TypeError, ValueError):
            return 0

    def _drain_body(self, cap=32 * 1024 * 1024):
        """Дочитать и выбросить тело, которое обработчик не забрал.
        Молчаливый возврат из do_POST без чтения тела ломает keep-alive:
        браузер остаётся на том же соединении, а его следующий запрос сервер
        прочитает из хвоста прошлого — то есть ответ уйдёт не тому запросу.
        Именно так «оплата не проходит» и «кнопка срабатывает дважды» выглядят
        для пользователя, тогда как всё, что нужно было, — дочитать байты."""
        n = self._declared_len() - int(getattr(self, "_body_read", 0) or 0)
        if n <= 0:
            return
        if n > cap:
            self.close_connection = True
            return
        try:
            self.rfile.read(n)
            self._body_read = int(getattr(self, "_body_read", 0) or 0) + n
        except Exception:
            self.close_connection = True

    def _reject_chunked(self):
        """chunked панель не раскодует: остаток тела остался бы в сокете и
        следующий запрос этого же соединения читался бы из него. Поэтому —
        отказ и закрытие соединения, а не «как-нибудь обработаем»."""
        te = (self.headers.get("Transfer-Encoding") or "").strip().lower()
        if not te or te == "identity":
            return False
        self.close_connection = True
        self._send(501, {"error": "Transfer-Encoding не поддерживается, нужен Content-Length"})
        return True

    def _body(self, maxb=8 * 1024 * 1024):
        raw = self._raw_body(maxb)
        try:
            d = json.loads(raw or b"{}")
        except Exception as e:
            raise _BodyError("тело запроса — не JSON (" + type(e).__name__ + ")") from e
        if not isinstance(d, dict):
            # 94 ручки читают b.get(...) — на списке или числе они падают в 500
            raise _BodyError("тело запроса — JSON-объект, а не список или число")
        return d

    def _is_cur_pw(self, cur):
        return _pw_match(CFG_CACHE.get("salt", ""), cur, CFG_CACHE.get("pass_hash"))

    # ----.ext: входящий API для внешних панелей/узлов----
    def _ext_get(self, p):
        t = _ext_auth(self)
        if t is None:
            return
        st = _state_view(_load(STATE) or {})
        inbs = st.get("inbounds") or {}
        if p == "/api/ext/status":
            try:
                with open("/proc/uptime") as f:
                    uptime = int(float(f.read().split()[0]))
            except Exception:
                uptime = 0
            today_k = time.strftime("%Y-%m-%d")
            uuids = {c.get("uuid") for inb in inbs.values() for c in inb.get("clients", [])}
            online = 0
            for u in uuids:
                try: online += _online_count(u)
                except Exception: pass
            inb_list = [{"proto": proto, "port": inb.get("port"),
                         "clients": len(inb.get("clients") or [])}
                        for proto, inb in inbs.items()]
            return self._send(200, {
                "version": VERSION, "uptime": uptime,
                "xray": _unit_active("xray"),
                "clients": len(uuids), "online": online,
                "traffic_today": int(_TRAFFIC_DAYS.get(today_k) or 0),
                "caps": EXT_CAPS,
                "inbounds": inb_list})
        if p == "/api/ext/inbounds":
            return self._send(200, {"inbounds": [
                {"proto": proto, "port": inb.get("port"),
                 "clients": len(inb.get("clients") or [])}
                for proto, inb in inbs.items()]})
        if p == "/api/ext/traffic":
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            u = (qs.get("uuid") or [""])[0].strip()
            out = []
            for proto, inb in inbs.items():
                for c in inb.get("clients") or []:
                    if c.get("ext_owner") != t.get("id"):
                        continue
                    if u and c.get("uuid") != u:
                        continue
                    try: on = _online_count(c.get("uuid"))
                    except Exception: on = 0
                    out.append({"uuid": c.get("uuid"), "name": c.get("name"),
                                "proto": proto, "up": _bytes_of(c.get("up")),
                                "down": _bytes_of(c.get("down")),
                                "limit_gb": _gb_of(c.get("limit_gb")),
                                "expiry": _ts_of(c.get("expiry")),
                                "blocked": bool(c.get("blocked")), "online": on})
            if u and not out:
                return self._send(404, {"error": "клиент не найден или не принадлежит токену"})
            return self._send(200, {"clients": out})
        return self._send(404, {"error": "not found"})

    def _ext_post(self, p):
        t = _ext_auth(self, need_write=True)
        if t is None:
            return
        try:
            b = self._body()
        except Exception:
            return self._send(400, {"error": "bad json"})
        tid = t.get("id")
        if p == "/api/ext/clients":
            # Тот же отказ, что и в /api/clients/add (#80): раньше пустое тело значило
            # «заведи подписчика по умолчанию», имя додумывалось, и внешний вызывающий
            # получал 200 с рабочим credential подписчика, которого никто не просил.
            # Порядок важен: выход раньше, чем создан токен, uuid и ключи транспорта.
            if not int(getattr(self, "_body_read", 0) or 0):
                return self._send(400, {"error": "нужно тело запроса: имя подписчика обязательное"})
            name = _client_name_input(b.get("name"))
            proto = _field(b, 'proto').strip()
            st = _load(STATE) or {}
            inb = (st.get("inbounds") or {}).get(proto)
            if not inb:
                return self._send(400, {"error": "inbound не найден; допустимы только существующие"})
            try:
                _lg = float(b.get("limit_gb") or 0)
            except (TypeError, ValueError, OverflowError):
                return self._send(400, {"error": "limit_gb — число гигабайт или 0 (без лимита)"})
            if _lg < 0 or _lg != _lg or _lg == float("inf"):
                return self._send(400, {"error": "limit_gb не может быть отрицательным"})
            limit_gb = _lg or None
            try:
                _edays = int(float(b.get("expiry_days") or 0))
            except (TypeError, ValueError, OverflowError):
                return self._send(400, {"error": "expiry_days — целое число дней или 0 (бессрочно)"})
            if _edays < 0 or _edays > 36500:
                return self._send(400, {"error": "expiry_days от 0 до 36500 суток"})
            expiry = (int(time.time()) + _edays * 86400) if _edays > 0 else 0
            reset_cycle = _field(b, 'reset_cycle').strip().lower()
            try:
                max_devices = max(0, int(b.get("max_devices") or 0))
            except Exception:
                max_devices = 0
            c = _new_client(name, proto, inb, limit_gb=limit_gb, expiry=expiry,
                            reset_cycle=reset_cycle, max_devices=max_devices)
            c["ext_owner"] = tid
            inb.setdefault("clients", []).append(c)
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            panel_port = CFG_CACHE.get("panel_port", 8444)
            _awg_sync(st); _wg_sync(st)
            _apply_state(st)
            link = ""
            try:
                link = _link(inb, host, c, proto)
            except Exception:
                pass
            _audit("ext_client_add", uuid=c["uuid"], name=name, proto=proto, token=t.get("label"))
            return self._send(200, {"client": {
                "uuid": c["uuid"], "name": name, "proto": proto,
                "sub_token": c.get("sub_token"),
                "sub_url": f"{_pb(host, panel_port)}/sub/{c.get('sub_token')}",
                "link": link}})
        if p == "/api/ext/clients/update":
            u = _field(b, 'uuid').strip()
            st = _load(STATE) or {}
            group = _ext_owned_group(st, tid, u)
            if not group:
                return self._send(404, {"error": "клиент не найден или не принадлежит токену"})
            if "limit_gb" in b:
                try: lg = max(0.0, float(b.get("limit_gb") or 0))
                except Exception: return self._send(400, {"error": "limit_gb не число"})
                for c in group:
                    c["limit_gb"] = lg
                    if lg > 0: c["warned_80"] = False
            if "expiry_days" in b:
                try: d = max(0, int(b.get("expiry_days") or 0))
                except Exception: return self._send(400, {"error": "expiry_days не число"})
                exp = (int(time.time()) + d * 86400) if d > 0 else 0
                for c in group:
                    c["expiry"] = exp; c["warned_days"] = []
            if "reset_cycle" in b:
                rc = _field(b, 'reset_cycle').strip().lower()
                if rc not in ("", "day", "week", "month"):
                    return self._send(400, {"error": "reset_cycle: day|week|month или ''"})
                for c in group: c["reset_cycle"] = rc
            if "max_devices" in b:
                try: md = max(0, int(b.get("max_devices") or 0))
                except Exception: return self._send(400, {"error": "max_devices не число"})
                for c in group: c["max_devices"] = md
            _awg_sync(st); _wg_sync(st)
            _apply_state(st)
            _audit("ext_client_update", uuid=u, token=t.get("label"))
            return self._send(200, {"ok": True})
        if p == "/api/ext/clients/delete":
            u = _field(b, 'uuid').strip()
            st = _load(STATE) or {}
            group = _ext_owned_group(st, tid, u)
            if not group:
                return self._send(404, {"error": "клиент не найден или не принадлежит токену"})
            for proto, inb in list((st.get("inbounds") or {}).items()):
                inb["clients"] = [c for c in inb.get("clients") or []
                                  if not (c.get("uuid") == u and c.get("ext_owner") == tid)]
            if st.get("active") not in st.get("inbounds", {}):
                st["active"] = _proto_of(st)
            _awg_sync(st); _wg_sync(st)
            _apply_state(st)
            _audit("ext_client_delete", uuid=u, token=t.get("label"))
            return self._send(200, {"ok": True})
        if p == "/api/ext/restart":
            _restart_xray()
            _audit("ext_restart", token=t.get("label"))
            return self._send(200, {"ok": True})
        return self._send(404, {"error": "not found"})

    # ---- GET ----
    def _cors_origin(self):
        """Тот же хост, что и в Host — иначе CORS превращается в дыру.
        Пустая строка, если Origin не совпал."""
        o = (self.headers.get("Origin") or "").strip()
        if not o:
            return ""
        try:
            oh = (urllib.parse.urlparse(o).hostname or "").lower()
        except Exception:
            return ""
        rh = (self.headers.get("Host") or "").split(":")[0].strip().lower()
        return o if oh and oh == rh else ""

    def do_OPTIONS(self):
        """Preflight браузерного запроса с заголовком X-Sid. Без этого обработчика
        BaseHTTPRequestHandler честно отвечает 501 «Unsupported method», и любой
        api()-вызов в браузере оборачивается в «HTTP 501» — именно так и выглядела
        жалоба на браузерный терминал. Авторизации тут нет намеренно: preflight
        браузер шлёт без cookie, а данных он не отдаёт вообще."""
        o = self._cors_origin()
        if not o:
            self.send_response(403)
            self.send_header("Content-Length", "0")
            self._sec_headers()
            self.end_headers()
            return
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", o)
        self.send_header("Access-Control-Allow-Credentials", "true")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, X-Sid")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Max-Age", "600")
        self.send_header("Vary", "Origin")
        self.send_header("Content-Length", "0")
        self._sec_headers()
        self.end_headers()

    def do_HEAD(self):
        """HEAD тоже должен отвечать: иначе браузер/прокси видит 501."""
        p = urllib.parse.urlparse(self.path).path
        g = _perm_gate(self, p, "GET")
        code = g[0] if g else 200
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8"
                         if code == 200 else "application/json")
        self.send_header("Content-Length", "0")
        self.send_header("Cache-Control", "no-store")
        self._sec_headers()
        o = self._cors_origin()
        if o:
            self.send_header("Access-Control-Allow-Origin", o)
            self.send_header("Access-Control-Allow-Credentials", "true")
            self.send_header("Vary", "Origin")
        self.end_headers()

    def send_response(self, code, message=None):
        # Ни строчки о том, чем написана панель: наружу уходило
        # `Server: BaseHTTP/0.6 Python/3.14.4` — готовый отпечаток для сканеров
        # (замер с чужих машин, P/#48). Дата остаётся: без неё кривой HTTP.
        self.log_request(code)
        self.send_response_only(code, message)
        self.send_header("Date", self.date_time_string())

    def send_response_only(self, code, message=None):
        # Первая строка статуса — единственный честный признак «ответ пошёл».
        # Цепляем именно send_response_only, а не send_response: через него проходит
        # и служебный send_error, так что флаг не врёт ни на одной ветке.
        # Нужен обработчику сбоя в do_GET: дописать 500 в уже открытый поток
        # (скачиваемый конфиг, страница, терминальный `websocket` после 101) — это
        # склейка двух ответов на keep-alive, ровно тот класс дефекта, от
        # которого защищают _drain_body и ka-тесты.
        self._resp_started = True
        super().send_response_only(code, message)

    def do_GET(self):
        # GET с телом юридически возможен (и его шлют сканеры и некоторые
        # прокси). Обработчик его не читает, поэтому тело доедаем здесь —
        # иначе keep-alive склеит хвост с следующим запросом.
        self._body_read = 0
        self._resp_started = False
        if self._reject_chunked():
            return
        try:
            self._do_GET()
        except _BodyError as e:
            # GET-ручки, которые всё-таки читают тело (поиск подписчика, витрина):
            # кривое тело — вина отправителя, честный 400/413 без трейсбека.
            if not self._resp_started:
                self._send(e.code, {"error": str(e)[:200]})
        except _CLIENT_GONE as e:
            # Гость повесил трубку (обрыв на чтении тела, сброс, таймаут,
            # развалившийся TLS) — ответить некому, и это не ошибка панели.
            self.close_connection = True
            _client_gone(urllib.parse.urlparse(self.path).path, e)
        except Exception as e:
            # Сбой обработчика обязан стать ответом, а не обрывом. На выпуске 2.16.5
            # у do_POST такой контракт был, а у do_GET — нет: побитое число в
            # state.json роняло сборщик ответа, и клиент получал закрытое соединение
            # без единого статуса («подписка не обновляется», и в журнале ничего).
            # Текст исключения наружу не отдаём — путь бывает неаутентицированным.
            import traceback
            traceback.print_exc()
            _audit("get_error", path=_audit_path(urllib.parse.urlparse(self.path).path),
                   detail=type(e).__name__ + ": " + _audit_path(str(e))[:200])
            if not self._resp_started:
                try:
                    self._send(500, {"error": "внутренняя ошибка панели"})
                except Exception:
                    pass
        finally:
            self._drain_body()

    def _do_GET(self):
        p = urllib.parse.urlparse(self.path).path
        g = _perm_gate(self, p, "GET")
        if g:
            return self._send(*g)
        if p == "/api/term":
            u = _auth_user(self)
            up = (self.headers.get("Upgrade") or "").lower()
            want_ws = (up == "websocket")
            if not u or not u["owner"]:
                # Браузер при upgrade покажет только «сокет закрылся» — причина живёт
                # здесь, в журнале, иначе владелец гадает, кто же виноват.
                _audit("term_denied", reason=("не владелец" if u else "нет сессии"),
                       ws=want_ws, peer=(self.client_address[0] if getattr(self, "client_address", None) else "?"),
                       login=(u or {}).get("login"))
                return self._send(403, {"error": "только владелец"})
            if want_ws:
                return _term_run(self, u)
            return self._send(200, {"enabled": bool(CFG_CACHE.get("ssh_terminal")),
                                     "active": _term_active, "shell": "/bin/bash"})
        if p == "/api/ssh/port":
            u = _auth_user(self)
            if not u or not u["owner"]:
                return self._send(403, {"error": "только владелец"})
            return self._send(200, _ssh_port_status())
        if p == "/api/node/optimizer":
            u = _auth_user(self)
            if not u or not u["owner"]:
                return self._send(403, {"error": "только владелец"})
            return self._send(200, _node_opt_status())
        if p == "/api/ai":
            u = _auth_user(self)
            if not u or not u["owner"]:
                return self._send(403, {"error": "только владелец"})
            key = (CFG_CACHE.get("ai_key") or "").strip()
            return self._send(200, {"enabled": bool(CFG_CACHE.get("ai_enabled")),
                                    "has_key": bool(key), "key_hint": (key[-4:] if key else ""),
                                    "base": CFG_CACHE.get("ai_base") or "https://api.openai.com/v1",
                                    "model": CFG_CACHE.get("ai_model") or "gpt-4o-mini",
                                    "tools": [t["function"]["name"] for t in _AI_TOOLS],
                                    "providers": AI_PROVIDERS})
        if p == "/api/flux":
            u = _auth_user(self)
            if not u or not u["owner"]:
                return self._send(403, {"error": "только владелец"})
            return self._send(200, _flux_view())
        if p == "/api/me":
            u = _auth_user(self)
            if not u:
                return self._send(401, {"error": "unauthorized"})
            return self._send(200, {"login": u["login"], "owner": bool(u["owner"]),
                                    "perms": ({"*": True} if u["owner"] else u["perms"])})
        if p == "/api/users":
            u = _auth_user(self)
            if not u:
                return self._send(401, {"error": "unauthorized"})
            if not u["owner"]:
                return self._send(403, {"error": "недостаточно прав"})
            us = [{"login": x.get("login"), "perms": x.get("perms") or {},
                   "disabled": bool(x.get("disabled")), "created": x.get("created")}
                  for x in (CFG_CACHE.get("users") or [])]
            return self._send(200, {"users": us, "perm_keys": PERM_KEYS})

        if p == "/api/schedule":
            return self._send(200, _svc_view())

        if p.startswith("/sub/") or p in ("/sub", "/sub/"):
            # Универсальная подписка (/sub) или личная подписка клиента (/sub/<subId>).
            # Как в 3x-ui: возвращается base64-список ссылок на ВСЕ протоколы, где есть клиент,
            # плюс заголовок subscription-userinfo (upload/download/total/expire) для v2rayNG и др.
            if not (p[len("/sub"):].strip("/")):
                # Без токена это «все ссылки всех подписчиков» — наружу так отдавать
                # нельзя: любой, кто знает адрес панели, забирал бы чужие uuid,
                # ключи Reality и готовый рабочий доступ. Соседние ручки (/p/, /sb/)
                # это давно требуют токен; здесь — хотя бы сеанс владельца/оператора.
                u = _auth_user(self)
                if not u:
                    return self._send(401, {"error": "нужен токен подписки"})
                if not u["owner"] and not (u["perms"] or {}).get("clients"):
                    return self._send(403, {"error": "нужен токен подписки"})
            try:
                import base64
                sub_path = p[5:].strip("/") if p.startswith("/sub/") else ""
                raw_st = _load(STATE)
                if self._refuse_unshapable(raw_st, public=True): return
                st = _state_view(raw_st or {})
                host = _hop_pub_host()
                host = host if "://" not in host else urllib.parse.urlparse(host).netloc
                panel_port = CFG_CACHE.get("panel_port", 8444)

                links = []
                seen_uuids = set()
                tg_links = []
                found_client = False
                up = down = total = 0
                expiry = 0
                sub_name = ""

                # Все вхождения клиента по ключу могут быть в нескольких инбаундах —
                # соберём их в один список ссылок (по одному на протокол).
                inb_links = {}
                inc_links = {}
                sb_objs = {}
                _sb_tags = {}
                node_links = {}
                _ensure_identities(st)
                for proto, inb in (st.get("inbounds") or {}).items():
                    for c in inb.get("clients", []):
                        match = (not sub_path) or (c.get("sub_token") == sub_path) or \
                                (c.get("uuid") and c["uuid"] == sub_path)
                        if not match:
                            continue
                        found_client = True
                        sub_name = c.get("name") or sub_name
                        key = c["uuid"]
                        if key not in seen_uuids:
                            seen_uuids.add(key)
                            up += _bytes_of(c.get("up"))
                            down += _bytes_of(c.get("down"))
                            lim = _gb_of(c.get("limit_gb"))
                            if lim > 0:
                                total = max(total, int(lim * 1024 ** 3))
                            ex = _ts_of(c.get("expiry"))
                            if ex:
                                expiry = max(expiry, ex)
                            try:
                                for l in _tg_sub_links(c):
                                    if l not in tg_links:
                                        tg_links.append(l)
                            except Exception:
                                pass
                        if not inb.get("disabled"):
                            try:
                                # Ключ — протокол плюс различник записи (#239): пока
                                # на протокол была одна копия, «одна ссылка на протокол»
                                # была верна. Со второй конфигурацией `wireguard` прежний
                                # ключ-протокол молча выбросил бы её из выдачи — телефон
                                # получил бы один туннель там, где оператор завёл два.
                                # /sub БЕЗ токена обещает «ссылки всех подписчиков»:
                                # там различник — идентификатор человека.
                                lkey = (proto + "|" + _rec_mark(proto, c)) if sub_path \
                                    else proto + "|" + str(c.get("uuid"))
                                if lkey not in inb_links:
                                    inb_links[lkey] = _link(inb, host, c, proto)
                                if lkey not in inc_links:
                                    inc_links[lkey] = _incy_link(proto, inb, c, host)
                                if lkey not in sb_objs:
                                    _ob = _singbox_outbound(proto, inb, c, host)
                                    if _ob:
                                        # метка исходящего — имя+протокол: у двух
                                        # конфигураций одного протокола она обязана
                                        # различаться, иначе `check -c` бракует весь файл
                                        _t0 = str(_ob.get("tag") or "")
                                        if _t0 in _sb_tags:
                                            _sb_tags[_t0] += 1
                                            _ob["tag"] = _t0 + " ·" + str(_sb_tags[_t0])
                                        else:
                                            _sb_tags[_t0] = 1
                                        sb_objs[lkey] = _ob
                            except Exception:
                                continue
                        for h, e in (c.get("nodes") or {}).items():
                            lk = (e or {}).get("link")
                            if lk:
                                node_links[h] = lk

                if sub_path and found_client:
                    # семья: расход — совокупный по хозяйину, лимит/срок — живые его значения
                    rec0 = next((c for inb in (st.get("inbounds") or {}).values()
                                 for c in inb.get("clients", [])
                                 if c.get("sub_token") == sub_path or c["uuid"] == sub_path), None)
                    if rec0 is not None:
                        parent, members = _fam(st, rec0["uuid"])
                        if parent != rec0["uuid"] or members:
                            _, up, down = _fam_ud(st, rec0["uuid"])
                            prec = _fam_parent_record(st, parent)
                            if prec is not None:
                                lim = _gb_of(prec.get("limit_gb"))
                                total = int(lim * 1024 ** 3) if lim > 0 else 0
                                expiry = _ts_of(prec.get("expiry"))

                if sub_path and not found_client:
                    return self._send(404, {"error": "клиент не найден"})
                if not inb_links:
                    return self._send(404, {"error": "нет клиентов"})

                # #110: один порядок на все три формата ответа (INCY, sing-box, base64).
                _ord = _sub_order(inb_links)
                links = [inb_links[k] for k in _ord]
                # Формат ответа:
                #  * INCY — открытые ссылки по одной в строке (в т.ч. wireguard:// и
                #    amneziawg://); базовый тип для Xray-клиентов с их же документации.
                #  * sing-box JSON (массив outbound'ов) — только по явному ?format=sing-box.
                #  * по умолчанию — классический base64 v2ray-список (v2rayNG, NekoBox и др.).
                q = urllib.parse.urlparse(self.path).query
                ua = self.headers.get("User-Agent", "") or ""
                xc = self.headers.get("x-client") or ""
                fmt = (urllib.parse.parse_qs(q).get("format") or [""])[0].lower()
                use_sb = fmt in ("sing-box", "singbox", "sbox", "json")
                force_v2 = fmt in ("v2ray", "base64", "text")
                is_incy = (not use_sb and not force_v2 and sub_path
                           and _is_incy_client(ua, xc))
                if sub_path:
                    _dip = _req_client_ip(self)
                    try:
                        _subdev_note(sub_path, _dip, ua, xc)
                    except Exception:
                        pass
                    _pin = _subdev_pref(sub_path)
                    if _pin == "base64":
                        use_sb = False; is_incy = False
                    elif _pin == "singbox":
                        use_sb = True; is_incy = False
                xprof = None
                _ual = ua.lower()
                if sub_path and not use_sb and \
                        ("incy" in _ual or "happ" in _ual or _is_incy_client(ua, xc)):
                    try:
                        xprof = _routing_profile_b64(
                            _pb(host, CFG_CACHE.get("panel_port", 8444)))
                    except Exception:
                        xprof = None
                if use_sb:
                    payload = json.dumps(_sb_stealth_sort([sb_objs[k] for k in _ord if k in sb_objs]),
                                         ensure_ascii=False).replace(r'\/', '/')
                    b = payload.encode("utf-8")
                    ctype = "application/json; charset=utf-8"
                elif is_incy:
                    # Xray 26.7.11+ наотрез отказывается поднимать outbound
                    # «VLESS без TLS/Reality к публичному адресу» (шифрования
                    # нет — логин ушёл бы открытым текстом). Отдать незашифрованную
                    # vless-ссылку такому ядру нельзя, поэтому в подписку INCY
                    # plaintext-VLESS ноды не попадают: за WebSocket берёт
                    # соседняя нода «VLESS + WebSocket + TLS» (тот же uuid).
                    _nodes = [inc_links[k] for k in _ord
                              if k in inc_links and not (
                                  inc_links[k].startswith("vless://") and
                                  "security=none" in inc_links[k])]
                    payload = "\n".join(_sub_stealth_sort(list(tg_links) + _nodes))
                    if xprof:
                        # Incy понимает routing-профиль только диплинк-формой
                        # incy://routing/onadd/{b64} (схема обязательна, как happ:// у
                        # Happ). Без схемы строку ядро молча игнорировало — потому под
                        # VPN-туннелем Incy и терял MTProto: обходных DirectIp-исключений
                        # не применялось, телефон петлёй уходил на тот же VPS.
                        payload = ("incy://routing/onadd/" + xprof + "\n" + payload)
                    b = payload.encode("utf-8")
                    ctype = "text/plain; charset=utf-8"
                else:
                    # WG/AmneziaWG — однострочными ссылками wireguard:// и amneziawg://
                    # (тот же формат, что для INCY): Shadowrocket, Happ, NekoBox
                    # импортируют их из подписки. Многострочные [Interface]-блоки
                    # клиенты не разбирают и теряли эти протоколы молча.
                    links = [(inc_links.get(p) or inb_links[p])
                             if p.split("|")[0] in ("wireguard", "amneziawg") else inb_links[p]
                             for p in _ord]
                    # ссылки нод, куда клиент размещён мастером — в общий base64-список
                    links = links + list(node_links.values()) + tg_links
                    # Однострочные ссылки сначала, многострочные WG/AmneziaWG-блоки в конец:
                    # парсеры, спотыкающиеся о [Interface], всё равно импортируют остальное.
                    # Внутри однострочной части — от незаметных к заметным (#167): клиент
                    # видит сверху то, что с обычного HTTPS не отличить.
                    one = _sub_stealth_sort([l for l in links if l.startswith(("vless://", "vmess://", "trojan://", "ss://", "hy2://", "tg://"))])
                    links = one + [l for l in links if l not in one]
                    # Happ (Xray-ядро) понимает профиль маршрутизации, приложенный
                    # к подписке строкой happ://routing/onadd/{base64} — тогда
                    # обход РФ включается сам, без «полного конфига» (который Happ
                    # всё равно не импортирует: у него Xray, а не sing-box).
                    # Прочим v2ray-клиентам (Shadowrocket/v2rayNG) строку не даём —
                    # они её не распознают.
                    if xprof and "happ" in _ual:
                        links.insert(0, "happ://routing/onadd/" + xprof)
                    payload = base64.b64encode("\n".join(links).encode()).decode()
                    b = payload.encode()
                    ctype = "text/plain; charset=utf-8"
                self.send_response(200)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(b)))
                self.send_header("Cache-Control", "no-store")
                # subscription-userinfo — клиенты (v2rayNG, Hiddify, NekoBox) показывают трафик и срок
                exp_val = int(expiry)
                if not _expire_seconds_client(ua, xc):
                    exp_val *= 1000  # миллисекунды
                ui = f"upload={up}; download={down}; total={total}; expire={exp_val}"
                self.send_header("subscription-userinfo", ui)
                _pt = ((CFG_CACHE.get("sub_brand") or "").strip() or sub_name)[:25]
                if _pt:
                    pt = "base64:" + base64.b64encode(_pt.encode("utf-8")).decode()
                    self.send_header("profile-title", pt)
                _su = (CFG_CACHE.get("sub_support_url") or "").strip()
                if _su:
                    self.send_header("support-url", _su[:250])
                try:
                    pui = str(max(1, min(168, int(CFG_CACHE.get("sub_update_hours") or 24))))
                except Exception:
                    pui = "24"
                # #169: час после кнопки «обновить сейчас» отдаём единицу — приложения
                # потянут подписку чаще; сохранённый период не тронут, через час всё само
                # вернётся, потому что здесь читается только штамп, а не запись.
                if int(time.time()) - int(CFG_CACHE.get("sub_force_ts") or 0) < 3600:
                    pui = "1"
                self.send_header("profile-update-interval", pui)
                self.send_header("profile-web-page-url",
                                 f"{_pb(host, panel_port)}/p/{sub_path}" if sub_path
                                 else f"{_pb(host, panel_port)}/")
                self.end_headers(); self.wfile.write(b)
                return None
            except Exception as e:
                return self._send(500, {"error": str(e)})


        if p == "/metrics":
            # Prometheus-экспорт. Отключён, если токен не задан (503).
            tok = (CFG_CACHE.get("metrics_token") or "").strip()
            if not tok:
                return self._send(503, {"error": "metrics отключены: задайте токен в настройках"})
            auth = self.headers.get("Authorization", "") or ""
            qt = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            given = auth[7:].strip() if auth.lower().startswith("bearer ") else \
                    (qt.get("token") or [""])[0]
            # compare_digest по строкам падает TypeError на любом не-ASCII символе
            # (владелец вставил кириллицу в токен) — сравниваем байты.
            if not secrets.compare_digest((given or "\x00").encode("utf-8"), tok.encode("utf-8")):
                return self._send(401, {"error": "unauthorized"})
            try:
                body = _metrics_text().encode("utf-8")
            except Exception as e:
                return self._send(500, {"error": str(e)})
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers(); self.wfile.write(body)
            return None

        if p.startswith("/rulesets/"):
            name = os.path.basename(p[len("/rulesets/"):])
            if name not in _RULESET_FILES:
                return self._send(404, {"error": "not found"})
            fp = os.path.join(RULESET_DIR, name)
            try:
                with open(fp, "rb") as f:
                    data = f.read()
            except OSError:
                return self._send(404, {"error": "файлы ещё не загружены"})
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers(); self.wfile.write(data)
            return None

        if p.startswith("/sb/"):
            # Полный standalone-конфиг sing-box (tun + split-tunnel) для подписчика.
            tok = p[4:].strip("/")
            if not tok:
                return self._send(400, {"error": "нужен токен подписки"})
            raw_st = _load(STATE)
            # №64: тот же класс лжи, что у `/p/` и `/sub/`: на испорченном
            # контейнере `_subs_summary` не находит клиента и страница отдавала
            # «не найдено» вместо «недоступно». Конфиг sing-box по пустому списку
            # выдать тем более нельзя — клиент получил бы рабочий файл без единого
            # сервера.
            if self._refuse_unshapable(raw_st, public=True): return
            st = raw_st or {}
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            panel_port = CFG_CACHE.get("panel_port", 8444)
            q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            # ?legacy=1 — прежние формы для клиента на ядре 1.10–1.11, где новых
            # форм нет (замерено 1.11.1: unknown field "type").
            legacy = (q.get("legacy") or [""])[0].strip().lower() in ("1", "true", "yes", "on")
            # ?core=1.14 — формы, которых нет до 1.14 (http_client вместо
            # download_detour, который удалён в 1.16). Просит их тот, кто знает
            # ядро клиента: панель сама его не определяет (замерено #118).
            hc = _sb_core_at_least((q.get("core") or [""])[0])
            if hc:
                legacy = False
            cfgj = _sb_config(st, tok, host, panel_port, legacy, hc)
            if cfgj is None:
                return self._send(404, {"error": "клиент не найден"})
            # Отдаём как файл: браузер сохраняет veil.json (Happ импортирует его),
            # а _send добавил бы в JSON служебный ключ "ok" — конфиг с ним ломается.
            payload = json.dumps(cfgj, ensure_ascii=False, indent=1).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Disposition", 'attachment; filename="veil.json"')
            self.send_header("Content-Length", str(len(payload)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers(); self.wfile.write(payload)
            return None

        if p == "/robots.txt":
            b = b"User-agent: *\nDisallow: /\n"
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(b)))
            self._sec_headers()
            self.end_headers()
            self.wfile.write(b)
            return None

        if p.startswith("/pay/") or p == "/shop":
            return _pay_handle_public(self, p)

        if p.startswith("/p/") and p.endswith("/qr"):
            # QR подписки отдельной картинкой: сканер клиента наводит камеру на
            # неё, а не на адрес в строке браузера. Право — сам токен, ровно как
            # у страницы и аватара; новый доступ ручка не открывает.
            tok = p[3:-len("/qr")].strip("/")
            raw_st = _load(STATE)
            if self._refuse_unshapable(raw_st, public=True): return
            u = next((x for x in _subs_summary(raw_st or {})
                      if x["sub_token"] == tok or x["uuid"] == tok), None)
            if not u:
                return self._send(404, {"error": "подписка не найдена"})
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            svg = _qr_svg("%s/sub/%s" % (_pb(host, CFG_CACHE.get("panel_port", 8444)),
                                         u["sub_token"])).encode("utf-8")
            if not svg:
                return self._send(404, {"error": "QR не собрался"})
            self.send_response(200)
            self.send_header("Content-Type", "image/svg+xml; charset=utf-8")
            self.send_header("Content-Length", str(len(svg)))
            # SVG умеют открывать и как отдельный документ; картинки там делать
            # нечего, и скриптам тоже — этот заголовок так не пускает.
            self.send_header("Content-Security-Policy", "default-src 'none'")
            self.send_header("Cache-Control", "no-store")
            self._sec_headers()
            self.end_headers()
            self.wfile.write(svg)
            return None

        if p.startswith("/p/") and p.endswith("/avatar"):
            # Аватар отдельным GET-файлом (токен = право доступа, как у POST-варианта).
            # Встроенный base64 делал каждую загрузку /p на ~95 КБ тяжелее и
            # гарантированно не кэшировался; здесь — public, max-age=1 день.
            tok = p[3:-len("/avatar")].strip("/")
            st = _load(STATE) or {}
            # Читающая ветка state.json НЕ пишет: её приведением занимается
            # фоновый тик под _STATE_LOCK (см. _limits_loop). Здесь же оставался
            # единственный способ потерять чужую запись: GET читает без замка,
            # а публика страницы подписки (она вообще без авторизации) успевала
            # сохраниться СРАЗУ после того, как морда добавила подписчика, — и
            # новый клиент исчезал из файла, живя в xray дальше.
            if not any(x["sub_token"] == tok or x["uuid"] == tok
                       for x in _subs_summary(st)):
                return self._send(404, {"error": "подписка не найдена"})
            mime, raw = _avatar_serve(tok)
            if raw is None:
                return self._send(404, {"error": "аватара нет"})
            self.send_response(200)
            self.send_header("Content-Type", mime)
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers()
            self.wfile.write(raw)
            return None

        if p.startswith("/p/"):
            # Публичная страница подписки: сюда ведёт profile-web-page-url (кнопка «i»
            # в клиентах). Показывает имя, статус, срок, трафик и способы подключения.
            tok = p[3:].strip("/")
            raw_st = _load(STATE)
            # №64: здесь вранье достается не оператору, а подписчику. `_subs_summary`
            # обходит входы через `_inb_map`, на контейнере-списке он отдаёт пустоту,
            # и личная страница клиента отвечала «подписка не найдена» (404) по живой
            # записи: человек видел, что его подписки «нет», и удалял/создавал её
            # заново, то есть порча файла толкала его к реальным потерям. Отказ
            # честнее, даже без объяснения про state.json.
            if self._refuse_unshapable(raw_st, public=True): return
            st = raw_st or {}
            # Читающая ветка state.json НЕ пишет: её приведением занимается
            # фоновый тик под _STATE_LOCK (см. _limits_loop). Здесь же оставался
            # единственный способ потерять чужую запись: GET читает без замка,
            # а публика страницы подписки (она вообще без авторизации) успевала
            # сохраниться СРАЗУ после того, как морда добавила подписчика, — и
            # новый клиент исчезал из файла, живя в xray дальше.
            u = next((x for x in _subs_summary(st)
                      if x["sub_token"] == tok or x["uuid"] == tok), None)
            if not u:
                return self._send(404, {"error": "подписка не найдена"})
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            panel_port = CFG_CACHE.get("panel_port", 8444)
            sub_url = f"{_pb(host, panel_port)}/sub/{u['sub_token']}"
            _q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query or "")
            _lq = (_q.get("lang") or [""])[0]
            _lck = ""
            for _c in (self.headers.get("Cookie") or "").split(";"):
                _c = _c.strip()
                if _c.startswith("veil_sub_lang="):
                    _lck = _c[len("veil_sub_lang="):]
            lang = _sub_lang_pick(_lq, _lck, self.headers.get("Accept-Language", ""))
            html = _sub_page_html(u, sub_url, host, panel_port,
                                  self.headers.get("User-Agent", "") or "",
                                  devs=_subdev_list(tok), lang=lang,
                                  pact=_protoact_view(tok))
            b = html.encode("utf-8")
            # страница весит ~135 КБ (все ссылки/иконки встроены): по мобильному
            # каналу gzip снимает ~85% трафика и секунды ожидания
            enc = None
            if "gzip" in (self.headers.get("Accept-Encoding") or "").lower():
                b, enc = gzip.compress(b, 6), "gzip"
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("Vary", "Accept-Encoding")
            if enc:
                self.send_header("Content-Encoding", enc)
            if _lq:
                self.send_header("Set-Cookie",
                                 "veil_sub_lang=" + lang + "; Path=/; Max-Age=31536000; SameSite=Lax")
            self.end_headers()
            self.wfile.write(b)
            return None


        if p.startswith("/api/wgconf/") or p.startswith("/api/awgconf/"):
            only_proto = "wireguard" if p.startswith("/api/wgconf/") else "amneziawg"
            tok = p[len("/api/wgconf/"):].strip("/") or p[len("/api/awgconf/"):].strip("/")
            if not tok:
                return self._send(404, {"error": "конфиг не найден"})
            # /api/wgconf/<токен>/<номер> (#239): сколько конфигураций туннеля
            # оператор завёл, столько кнопок скачивания и должно висеть — прежняя
            # выдача молча ограничивалась первой записью.
            tok, _, tail = tok.partition("/")
            try:
                want_no = max(1, int(tail)) if tail else 1
            except ValueError:
                want_no = 1
            st = _load(STATE, {}) or {}
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            conf = ""
            name = "client"
            for proto, inb in (st.get("inbounds") or {}).items():
                if proto != only_proto:
                    continue
                no = 0
                for c in inb.get("clients", []):
                    if c.get("sub_token") == tok or (c.get("uuid") and c["uuid"] == tok):
                        no += 1
                        if no == want_no:
                            conf = _link(inb, host, c, proto)
                            name = c.get("name") or "client"
                            break
                if conf:
                    break
            if not conf:
                return self._send(404, {"error": "конфиг не найден"})
            src_name = (re.sub(r"[^\wа-яёА-ЯЁ -]+", "", name).strip().replace(" ", "_") or "client")
            ascii_name = re.sub(r"[^\x00-\x7f]+", "", src_name) or "client"
            b = conf.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Disposition",
                             'attachment; filename="' + ascii_name + '.conf"; filename*=UTF-8\'\'' + urllib.parse.quote(src_name + ".conf"))
            self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(b)
            return None

        if p.startswith("/appicons/"):
            # Логотипы приложений в каталоге личного кабинета (файлы лежат в BASE/appicons)
            fn = os.path.basename(p)
            if not re.match(r"^[a-z0-9][a-z0-9._-]{0,63}\.(?:jpg|png|webp|ico|svg)$", fn):
                return self._send(404, {"error": "not found"})
            fp = os.path.join(BASE, "appicons", fn)
            try:
                with open(fp, "rb") as f:
                    data = f.read()
            except Exception:
                return self._send(404, {"error": "not found"})
            mime = {"jpg": "image/jpeg", "png": "image/png", "webp": "image/webp",
                    "ico": "image/x-icon", "svg": "image/svg+xml"}[fn.rsplit(".", 1)[1]]
            self.send_response(200)
            self.send_header("Content-Type", mime)
            self.send_header("Cache-Control", "public, max-age=604800")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return None

        if p == "/favicon.ico":
            # Happ и др. тянут логотип подписки из favicon-а домена подписки
            try:
                with open(_LOGO_PNG or os.path.join(BASE, "icon-veil.png"), "rb") as f:
                    data = f.read()
            except Exception:
                return self._send(404, {"error": "not found"})
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Cache-Control", "public, max-age=86400")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return None

        if p == "/logo.png":
            if not _LOGO_PNG:
                return self._send(404, {"error": "logo not found"})
            try:
                with open(_LOGO_PNG, "rb") as f:
                    data = f.read()
            except Exception:
                return self._send(404, {"error": "logo not found"})
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers()
            self.wfile.write(data)
            return None

        if p.startswith("/api/ext/"):
            return self._ext_get(p)
        if p == "/api/metrics":
            # Анониму тут делать нечего: кроме нагрузки машины ручка отдаёт
            # карту портов всех входов (это «здесь VPN») и на каждый запрос
            # поднимает systemctl и перебирает порты — бесплатный усилитель
            # для того, кто просто долбит URL.
            if not _authed(self):
                return self._send(401, {"error": "unauthorized"})
            return self._send(200, get_system_metrics())
        if p == "/api/selftest":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            return self._send(200, run_protocol_self_test())
        if p == "/api/nodes":
            if not _authed(self):
                return self._send(401, {"error": "unauthorized"})
            return self._send(200, _nodes_public())
        if p == "/api/nodes/bootstrap/status":
            if not _authed(self):
                return self._send(401, {"error": "unauthorized"})
            jid = (urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                   .get("id") or [""])[0].strip()[:12]
            with BOOT_LOCK:
                job = BOOT_JOBS.get(jid)
                out = None if not job else {
                    "id": jid, "done": job["done"], "ok": job["ok"], "error": job["error"],
                    "steps": [dict(s) for s in job["steps"]]}
            if out is None:
                return self._send(404, {"error": "задача не найдена (перезапуск панели?)"})
            return self._send(200, out)
        if p == "/api/nodes/tokens":
            if not _authed(self):
                return self._send(401, {"error": "unauthorized"})
            return self._send(200, {"tokens": [
                {"id": t.get("id"), "label": t.get("label"), "scopes": t.get("scopes") or [],
                 "created": t.get("created"), "last_used": t.get("last_used")}
                for t in _node_tokens()]})

        if p in ("/", "/index.html"):
            with open(HTML, "rb") as f:
                content = f.read()
            style = (CFG_CACHE.get("ui_style") or "new").strip().lower()
            content = content.replace(b"__UI_STYLE__", b"classic" if style == "classic" else b"new")
            etag = '"' + hashlib.sha256(content).hexdigest()[:32] + '"'
            if (self.headers.get("If-None-Match") or "").strip() == etag:
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", "no-cache")
                self.send_header("Vary", "Accept-Encoding")
                self._sec_headers()
                self.end_headers()
                return None
            body = content
            enc = None
            if "gzip" in (self.headers.get("Accept-Encoding") or "").lower():
                global _HTML_GZ
                if not (_HTML_GZ and _HTML_GZ[0] == etag):
                    _HTML_GZ = (etag, gzip.compress(content, 6))
                body, enc = _HTML_GZ[1], "gzip"
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("ETag", etag)
            # no-cache = перепроверка по ETag каждый раз: файл ~1 МБ, но отдача
            # 304 или gzip снимает почти весь трафик повторных загрузок.
            self.send_header("Cache-Control", "no-cache")
            if enc: self.send_header("Content-Encoding", enc)
            self.send_header("Vary", "Accept-Encoding")
            self._sec_headers()
            self.end_headers()
            self.wfile.write(body)
            return None
        if p == "/i18n.json":
            try:
                with open(I18N, "rb") as f:
                    content = f.read()
            except OSError:
                return self._send(404, {"error": "not found"})
            etag = '"' + hashlib.sha256(content).hexdigest()[:32] + '"'
            if (self.headers.get("If-None-Match") or "").strip() == etag:
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", "public, max-age=3600")
                self._sec_headers()
                self.end_headers()
                return None
            body = content
            enc = None
            if "gzip" in (self.headers.get("Accept-Encoding") or "").lower():
                global _I18N_GZ
                if not (_I18N_GZ and _I18N_GZ[0] == etag):
                    _I18N_GZ = (etag, gzip.compress(content, 6))
                body, enc = _I18N_GZ[1], "gzip"
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("ETag", etag)
            # Словарь чужих языков не содержит доступов и меняется только с релизом:
            # держим его в кэше браузера час. Русскому он не нужен и не запрашивается.
            self.send_header("Cache-Control", "public, max-age=3600")
            if enc: self.send_header("Content-Encoding", enc)
            self.send_header("Vary", "Accept-Encoding")
            self._sec_headers()
            self.end_headers()
            self.wfile.write(body)
            return None
        if p == "/api/state":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            just_born = _onboard_ensure()
            if just_born:
                _onboard_notify()
            raw_st = _load(STATE)
            # №64: честный отказ №57 дошёл не до всех читающих ручек. Соседи на
            # испорченном состоянии падают в 500 (`/api/dashboard`,
            # `/api/clients`, публичный `/sub`), а эта ручка бережена СВОИХ
            # обращений: `_client_count` и `_proto_of` на контейнере-списке дают 0
            # и «reality», и ответ выходит 200 с `configured: false` — то есть
            # «ничего не настроено» про машину с 17 входами и 119 записями.
            # Морда по этому флагу показывает экран первичной настройки и зовёт
            # создавать подписку заново, а ложь дешевле правды ровно до того
            # момента, пока по лжи не начинают действовать. Пустое состояние — НЕ
            # отказ: это новая машина, ей и положено отвечать «не настроено».
            if self._refuse_unshapable(raw_st): return
            st = _state_view(raw_st)
            running = _unit_active("xray")
            out = {"version": VERSION, "running": running, "login": CFG_CACHE.get("login", ""),
                   "configured": _client_count(st) > 0,
                   "proto": _proto_of(st),
                   "panel_port": CFG_CACHE.get("panel_port", 8443),
                   "ipv6": _my_ipv6(),
                   "onboarding": _onboard_info(),
                   "favorites": st.get("favorites", []) if st else []}
            return self._send(200, out)
        if p == "/api/vpn/protocols":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            # №64: эта ручка падала на контейнере-списке с трейсбеком и отдавала
            # «внутренняя ошибка панели» — формально отказ, но без причины, а
            # морде фронта нечем отличить «файл битый» от «панель сломалась».
            raw_st = _load(STATE)
            if self._refuse_unshapable(raw_st): return
            st = _state_view(raw_st)
            inbs = _inb_map(st)
            def _cap(pid):
                # сколько конфигураций этого протокола может лежать на одном
                # человеке (#239): где различие по ключу — до общего предела,
                # где по адресу входа — сколько адресов узел честно отдаёт
                kind = _proto_dup(pid)
                if kind == "ep":
                    inb = inbs.get(pid)
                    return len(_ep_variants(inb)) if inb and not inb.get("disabled") else 1
                return _ADD_N_MAX if kind else 1
            return self._send(200, {"current": _proto_of(st),
                                    "configured": _client_count(st) > 0,
                                    "protocols": [dict(p, disabled=bool((inbs.get(p["id"]) or {}).get("disabled")),
                                                        has_inbound=bool(inbs.get(p["id"])),
                                                        multi=_proto_multi(p["id"]),
                                                        dup=_proto_dup(p["id"]),
                                                        cap=_cap(p["id"]))
                                                  for p in PROTOCOLS]})
        if p == "/api/inbound/get":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            proto = (urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                     .get("proto") or [""])[0].strip()
            inb = (_load(STATE) or {}).get("inbounds", {}).get(proto)
            if not inb: return self._send(404, {"error": "inbound не найден"})
            return self._send(200, _inbound_public(proto, inb))
        if p == "/api/clients":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            raw_st = _load(STATE)
            if self._refuse_unshapable(raw_st): return
            st = _state_view(raw_st)
            if not st: return self._send(200, {"clients": [], "configured": False})
            # Читающая ветка state.json НЕ пишет: её приведением занимается
            # фоновый тик под _STATE_LOCK (см. _limits_loop). Здесь же оставался
            # единственный способ потерять чужую запись: GET читает без замка,
            # а публика страницы подписки (она вообще без авторизации) успевала
            # сохраниться СРАЗУ после того, как морда добавила подписчика, — и
            # новый клиент исчезал из файла, живя в xray дальше.
            host = _hop_pub_host()
            host = host if "://" not in host else urllib.parse.urlparse(host).netloc
            panel_port = CFG_CACHE.get("panel_port", 8444)
            ipv6 = _my_ipv6()
            out = []
            _ensure_identities(st)
            for proto, inb in (st.get("inbounds") or {}).items():
                for c in inb.get("clients", []):
                    # Мусорную запись вычищает приведение состояния, но читающая
                    # ветка не ждёт тика: окно между чужим сохранением файла и
                    # починкой не должно стоить страницы подписчиков целиком.
                    if not isinstance(c, dict):
                        continue
                    sub_token = c.get("sub_token") or ""
                    sub_url = f"{_pb(host, panel_port)}/sub/{sub_token}"
                    cu = _bytes_of(c.get("up")); cdn = _bytes_of(c.get("down"))
                    try:
                        link = _link(inb, host, c, proto)
                    except Exception as e:
                        link = ""
                        _audit("client_link_error", proto=proto, detail=str(e)[:200])
                    item = {"uuid": c.get("uuid") or "", "name": c.get("name") or "",
                            "link": link,
                            "sub_token": sub_token,
                            "sub_url": sub_url,
                            "sb_url": f"{_pb(host, panel_port)}/sb/{sub_token}",
                            "up": cu, "down": cdn,
                            "limit_gb": _gb_of(c.get("limit_gb")),
                            "expiry": _ts_of(c.get("expiry")),
                            "reset_cycle": c.get("reset_cycle") or "",
                            "tg_proxy": c.get("tg_proxy") or "",
                            "tg_user": c.get("tg_user") or "",
                            "cycle": c.get("cycle") or "lifetime",
                            "max_devices": _cnt_of(c.get("max_devices")),
                            "family_of": c.get("family_of") or "",
                            "fam_name": c.get("fam_name") or "",
                            "used_gb": round((cu + cdn) / (1024**3), 3),
                            "ipv6": ipv6,
                            "proto": proto, "port": inb.get("port") or 0,
                            "proto_label": _proto_meta(proto)["label"],
                            "created": c.get("created", 0)}
                    if c.get("nodes"):
                        item["nodes"] = c["nodes"]
                    if c.get("ext_owner"):
                        item["ext_by"] = next(
                            (t.get("label") for t in _node_tokens() if t.get("id") == c["ext_owner"]),
                            "внешняя панель")
                    if ipv6:
                        item["link6"] = _link(inb, f"[{ipv6}]", c, proto)
                    if proto == "wireguard" and c.get("address"):
                        item["address"] = c["address"]
                        item["link6"] = ""
                        item["conf_url"] = f"{_pb(host, panel_port)}/api/wgconf/{sub_token}"
                    if proto == "amneziawg" and c.get("address"):
                        item["address"] = c["address"]
                        item["link6"] = ""
                        item["conf_url"] = f"{_pb(host, panel_port)}/api/awgconf/{sub_token}"
                    if len(out) < 16:
                        item["online"] = _online_count(c.get("uuid") or "")
                    out.append(item)
            return self._send(200, {"clients": out,
                                    "configured": bool(out),
                                    "active": _proto_of(st),
                                    "ipv6": ipv6})
        if p == "/api/subs":
            # Агрегированный список подписчиков для вкладки «Подписка» (как в 3x-ui).
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            st = _load(STATE)
            if not st: return self._send(200, {"subs": [], "configured": False})
            # №64: та же ленивость, что уже убрана у `/api/state`: `_subs_summary`
            # обходит входы через `_inb_map`, а он на контейнере-списке отдаёт
            # пустоту, и вкладка «Подписка» показала бы «подписчиков нет» на
            # машине, где их 119 записей. Это ровно та страница, по которой
            # судят, цела ли состояние после чужой правки файла.
            if self._refuse_unshapable(st): return
            # Читающая ветка state.json НЕ пишет: её приведением занимается
            # фоновый тик под _STATE_LOCK (см. _limits_loop). Здесь же оставался
            # единственный способ потерять чужую запись: GET читает без замка,
            # а публика страницы подписки (она вообще без авторизации) успевала
            # сохраниться СРАЗУ после того, как морда добавила подписчика, — и
            # новый клиент исчезал из файла, живя в xray дальше.
            subs = _subs_summary(st)
            try:
                _subdev_prune({(u.get("sub_token") or "") for u in subs})
            except Exception:
                pass
            for u in subs:
                tok = u.get("sub_token") or ""
                devs = _subdev_list(tok)
                u["devices"] = devs
                u["fmt"] = _subdev_pref(tok)
                top = devs[0] if devs else {}
                u["client"] = top.get("client", "")
                u["client_version"] = top.get("version", "")
                u["client_os"] = top.get("os", "")
                u["client_device"] = top.get("type", "")
                u["client_old"] = bool(top.get("old"))
                u["last_seen"] = top.get("last_ts", "")
                try:
                    u["usage"] = _protoact_view(tok)
                except Exception:
                    u["usage"] = []
            return self._send(200, {"subs": subs, "configured": bool(subs),
                                    "active": _proto_of(st)})
        if p == "/api/subs/export":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            fmt = ((qs.get("format") or ["json"])[0]).strip().lower()
            raw_st = _load(STATE)
            # №64: пустой экспорт хуже пустого экрана — файл уносят с собой,
            # кладут в отчёт и по нему решают, что терять нечего.
            if self._refuse_unshapable(raw_st): return
            st = raw_st or {}
            # Читающая ветка state.json НЕ пишет: её приведением занимается
            # фоновый тик под _STATE_LOCK (см. _limits_loop). Здесь же оставался
            # единственный способ потерять чужую запись: GET читает без замка,
            # а публика страницы подписки (она вообще без авторизации) успевала
            # сохраниться СРАЗУ после того, как морда добавила подписчика, — и
            # новый клиент исчезал из файла, живя в xray дальше.
            stamp = _ldate("%Y%m%d-%H%M")
            if fmt == "links":
                b = _subs_export_links(st).encode("utf-8")
                ctype, fname = "text/plain; charset=utf-8", "veil-subs-" + stamp + ".txt"
            else:
                b = json.dumps(_subs_export_json(st), ensure_ascii=False, indent=2).encode("utf-8")
                ctype, fname = "application/json; charset=utf-8", "veil-subs-" + stamp + ".json"
            self.send_response(200)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Disposition", 'attachment; filename="' + fname + '"')
            self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(b)
            return None
        if p == "/api/update":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            try:
                return self._send(200, _check_update())
            except urllib.error.HTTPError as e:
                return self._send(502, {"error": f"GitHub API: HTTP {e.code}"})
            except Exception as e:
                return self._send(502, {"error": str(e)})
        if p == "/api/update/job":
            # Опрос фоновой установки. Дешёвый и без замка состояния: журнал живёт
            # в своей памяти, и чтение его не должно ждать чужую замену бинаря.
            jid = (urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                   .get("id") or [""])[0]
            jid = re.fullmatch(r"[0-9a-f]{6,32}", jid or "").group(0) if re.fullmatch(
                r"[0-9a-f]{6,32}", jid or "") else ""
            if not jid:
                return self._send(400, {"error": "нужен id задачи"})
            j = _up_view(jid)
            if not j:
                return self._send(404, {"error": "задача не найдена (журнал живёт час)"})
            return self._send(200, j)
        if p == "/api/update/jobs":
            return self._send(200, {"jobs": _up_list(),
                                    "steps": _UP_STEPS,
                                    "busy": bool(_up_busy())})
        if p == "/api/theme":
            b = json.dumps(_load(THEME, {})).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(b)
            return
        if p == "/api/port/check":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            raw = (qs.get("port") or ["0"])[0]
            try:
                port = int(str(raw).strip() or "0")
            except ValueError:
                return self._send(400, {"error": "порт должен быть числом"})
            if not 1 <= port <= 65535:
                return self._send(400, {"error": "порт вне диапазона 1–65535"})
            st = _load(STATE, {}) or {}
            taken_by = None
            for pr, inb in (st.get("inbounds") or {}).items():
                if inb.get("port") == port and pr != (qs.get("proto") or [""])[0]:
                    taken_by = pr; break
            free = _port_free(port) and taken_by is None
            return self._send(200, {"port": port, "free": free,
                                    "taken_by": taken_by,
                                    "current": (st.get("inbounds") or {}).get((qs.get("proto") or [""])[0], {}).get("port")})
        if p == "/api/xray/info":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            try:
                vp = _xray_versions()
                return self._send(200, {"current": _xray_current_version(),
                                        "versions": vp["versions"], "pre": vp["pre"]})
            except Exception as e:
                return self._send(502, {"error": str(e)})
        if p == "/api/tg/versions":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            try:
                vp = _tg_versions()
                return self._send(200, {"current": _tg_current_version(),
                                        "versions": vp["versions"], "pre": vp["pre"]})
            except Exception as e:
                return self._send(502, {"error": str(e)})
        if p == "/api/versions":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            cur = {"panel": VERSION}
            try: cur["xray"] = _xray_current_version()
            except Exception: cur["xray"] = "unknown"
            try: cur["telemt"] = _tg_current_version()
            except Exception: cur["telemt"] = "unknown"
            return self._send(200, {"panel": _panel_backups(), "xray": _xray_backups(),
                                    "telemt": _tg_backups(), "current": cur})
        if p == "/api/rotate/status":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            try:
                return self._send(200, _rot_status())
            except Exception as e:
                return self._send(502, {"error": str(e)[:200]})
        if p == "/api/dynv6/status":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            conf = _dynv6_conf()
            return self._send(200, {"host": conf["host"], "configured": bool(conf["host"] and conf["token"]),
                                    "updated": _DDNS.get("updated"), "error": _DDNS.get("error"),
                                    "response": _DDNS.get("response"), "ipv4": _DDNS.get("ipv4"),
                                    "ipv6": _DDNS.get("ipv6"), "veil": dict(_VEIL_GUARD)})
        if p == "/api/cert/status":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            return self._send(200, _cert_status())
        if p == "/api/cert/search":
            if not _authed(self): return self._send(401, {"error": "unauthorized"})
            found = []
            roots = [os.path.join(CERT_DIR, "live"), "/etc/letsencrypt/live"]
            for root in roots:
                if not os.path.isdir(root): continue
                try: doms = sorted(os.listdir(root))
                except Exception: continue
                for dom in doms:
                    if "readme" in dom.lower(): continue
                    cert = os.path.join(root, dom, "fullchain.pem")
                    key = os.path.join(root, dom, "privkey.pem")
                    if os.path.isfile(cert) and os.path.isfile(key):
                        exp = _cert_expire(cert)
                        found.append({
                            "domain": dom,
                            "cert": cert, "key": key,
                            "expire": exp - time.time() if exp else None,
                            "days": int((exp - time.time()) / 86400) if exp else None,
                            "current": (os.path.realpath(cert) == os.path.realpath((CFG_CACHE.get("panel_cert_path") or CFG_CACHE.get("cert") or "").strip())
                                        and os.path.realpath(key) == os.path.realpath((CFG_CACHE.get("panel_key_path") or CFG_CACHE.get("cert_key") or "").strip()))})
